def _openapi_yaml_response():
    schema_path = APP_ROOT / "openapi" / "openapi.yaml"
    raw = schema_path.read_text(encoding="utf-8")
    scheme = request.scheme
    host = request.host
    if host.endswith(".ts.net") or host.endswith(".trycloudflare.com"):
        scheme = "https"
    public_base_url = f"{scheme}://{host}"
    body = re.sub(
        r'(?m)^  - url: "https://[^"]+"$',
        f'  - url: "{public_base_url}"',
        raw,
        count=1,
    )
    digest = hashlib.sha256(body.encode("utf-8")).hexdigest()[:12]
    response = make_response(body)
    response.mimetype = "application/yaml"
    response.headers["Content-Disposition"] = "inline; filename=openapi.yaml"
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    response.headers["X-LIVA-OpenAPI-Sha"] = digest
    return response


@app.get("/openapi.yaml")
@app.get("/.well-known/openapi.yaml")
def openapi_yaml():
    return _openapi_yaml_response()


