REMOTE_PC_CONTROL_PORT = max(1, min(65535, REMOTE_PC_CONTROL_PORT))
REMOTE_PC_HTTP_TOKEN = (os.getenv("LIVA_REMOTE_PC_HTTP_TOKEN") or "").strip()
REMOTE_PC_CONTROL_SCHEME = (os.getenv("LIVA_REMOTE_PC_CONTROL_SCHEME") or "http").strip().lower() or "http"
REMOTE_PC_WAKE_COMMAND = ["sudo", "etherwake", "-i", REMOTE_PC_WAKE_INTERFACE, REMOTE_PC_WAKE_MAC]
REMOTE_APP_DEEPLINK_ENABLED = (os.getenv("LIVA_REMOTE_APP_DEEPLINK_ENABLED") or "0").strip().lower() in {"1", "true", "yes", "on"}
