REMOTE_SHORTCUT_URL = (os.getenv("LIVA_REMOTE_SHORTCUT_URL") or "").strip()
try:
    REMOTE_SESSION_TTL_SECONDS = int((os.getenv("LIVA_REMOTE_SESSION_TTL_SECONDS") or "900").strip())
except Exception:
    REMOTE_SESSION_TTL_SECONDS = 900
REMOTE_SESSION_TTL_SECONDS = max(120, min(86_400, REMOTE_SESSION_TTL_SECONDS))

_remote_state_lock = threading.Lock()
_remote_state: dict[str, datetime | None] = {
    "last_wake_attempt": None,
    "last_ready_seen": None,
}
_remote_sessions_lock = threading.Lock()
_remote_sessions: dict[str, dict[str, Any]] = {}
_remote_devices_lock = threading.Lock()
_remote_devices_state: dict[str, dict[str, Any]] = {}
_remote_devices_state_path = Path("/opt/liva/smart_home/data/remote_devices_state.json")


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso_utc(dt: datetime | None) -> str | None:
    if dt is None:
        return None
    return dt.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _remote_mark_wake_attempt() -> datetime:
    now = _utc_now()
    with _remote_state_lock:
        _remote_state["last_wake_attempt"] = now
    return now


def _remote_last_wake_attempt() -> datetime | None:
    with _remote_state_lock:
        value = _remote_state.get("last_wake_attempt")
    return value if isinstance(value, datetime) else None


def _remote_mark_ready_seen(now: datetime | None = None) -> datetime:
    ready_ts = now or _utc_now()
    with _remote_state_lock:
        _remote_state["last_ready_seen"] = ready_ts
    return ready_ts


def _remote_last_ready_seen() -> datetime | None:
    with _remote_state_lock:
        value = _remote_state.get("last_ready_seen")
    return value if isinstance(value, datetime) else None


def _remote_recent_wake(window_seconds: int = REMOTE_BOOTING_WINDOW_SECONDS) -> bool:
    last = _remote_last_wake_attempt()
    if last is None:
        return False
    return (_utc_now() - last).total_seconds() <= max(1, int(window_seconds))


def _remote_listener_log_url(path: str) -> str:
    return _remote_listener_url(path, token="***")


def _remote_status_from_automation_state(automation_state: dict[str, Any]) -> str:
    state_name = str((automation_state or {}).get("state") or "").strip().upper()
    if state_name == "PC_ON":
        return "ready"
    if state_name in {"PC_MAYBE_OFF", "OFF_TIMER_RUNNING"}:
        return "booting"
    if state_name == "PC_CONFIRMED_OFF":
        return "offline"
    return "offline"


def _remote_pc_status_payload() -> dict[str, Any]:
    checked_at = _utc_now()
    automation_state = read_automation_state()
    evaluation = automation_state.get("last_evaluation") if isinstance(automation_state.get("last_evaluation"), dict) else {}
    checks = evaluation.get("checks") if isinstance(evaluation.get("checks"), list) else []
    status = _remote_status_from_automation_state(automation_state)
    rdp_port_open = any(
        isinstance(check, dict)
        and str(check.get("name") or "") == f"tcp:{REMOTE_PC_RDP_PORT}"
        and bool(check.get("ok"))
        for check in checks
    )
    listener_ping = next(
        (
            bool(check.get("ok"))
            for check in checks
            if isinstance(check, dict) and str(check.get("name") or "") == "listener_ping"
        ),
        None,
    )
    host_reachable = bool(automation_state.get("is_online")) or bool(rdp_port_open)
    if status == "ready":
        _remote_mark_ready_seen(checked_at)
    last_wake_attempt = _remote_last_wake_attempt()
    last_ready_seen = _remote_last_ready_seen()
    return {
        "ok": True,
        "status": status,
        "host": REMOTE_PC_HOST,
        "rdp_port": REMOTE_PC_RDP_PORT,
        "wake_interface": REMOTE_PC_WAKE_INTERFACE,
        "rdp_port_open": bool(rdp_port_open),
        "host_reachable": bool(host_reachable),
        "listener_ping": listener_ping,
        "last_wake_attempt": _iso_utc(last_wake_attempt),
        "last_ready_seen": _iso_utc(last_ready_seen),
        "automation_state": automation_state,
        "checked_at": _iso_utc(checked_at),
    }


def _remote_listener_url(path: str, token: str | None = None) -> str:
    clean_path = "/" + str(path or "").lstrip("/")
    final_token = (token or REMOTE_PC_HTTP_TOKEN or "").strip()
    query = f"?token={urllib_parse.quote(final_token, safe='')}" if final_token else ""
    return f"{REMOTE_PC_CONTROL_SCHEME}://{REMOTE_PC_HOST}:{REMOTE_PC_CONTROL_PORT}{clean_path}{query}"


def _remote_listener_call(path: str, timeout_seconds: float = 2.0) -> tuple[bool, int | None, str]:
    if not REMOTE_PC_HTTP_TOKEN:
        app.logger.warning(
            "REMOTE shutdown/listener skipped: token missing (path=%s host=%s port=%s)",
            path,
            REMOTE_PC_HOST,
            REMOTE_PC_CONTROL_PORT,
        )
        return False, None, "token_missing"

    url = _remote_listener_url(path, token=REMOTE_PC_HTTP_TOKEN)
    req = urllib_request.Request(url, method="GET")
    try:
        with urllib_request.urlopen(req, timeout=max(0.2, float(timeout_seconds))) as resp:
            code = int(getattr(resp, "status", 200))
            body_bytes = resp.read()
            body_text = body_bytes.decode("utf-8", errors="replace").strip()
            app.logger.info(
                "REMOTE listener call ok: url=%s status=%s body=%s",
                _remote_listener_log_url(path),
                code,
                body_text[:240],
            )
            return True, code, body_text
    except urllib_error.URLError as exc:
        reason = str(getattr(exc, "reason", "") or exc).strip() or "listener_unreachable"
        app.logger.warning(
            "REMOTE listener call failed: url=%s error=%s",
            _remote_listener_log_url(path),
            reason,
        )
        return False, None, reason
    except TimeoutError as exc:
        reason = str(exc).strip() or "listener_timeout"
        app.logger.warning(
            "REMOTE listener timeout: url=%s error=%s",
            _remote_listener_log_url(path),
            reason,
        )
        return False, None, reason
    except Exception as exc:
        reason = str(exc).strip() or "listener_unreachable"
        app.logger.exception(
            "REMOTE listener call exception: url=%s error=%s",
            _remote_listener_log_url(path),
            reason,
        )
        return False, None, reason


def _remote_shortcut_url() -> str:
    if REMOTE_SHORTCUT_URL:
        return REMOTE_SHORTCUT_URL
    if not REMOTE_SHORTCUT_NAME:
        return ""
    return f"shortcuts://run-shortcut?name={urllib_parse.quote(REMOTE_SHORTCUT_NAME, safe='')}"


def _remote_send_wake() -> tuple[bool, str | None]:
    cmd_display = shlex.join(REMOTE_PC_WAKE_COMMAND)
    app.logger.info("REMOTE wake start: command=%s", cmd_display)
    try:
        proc = subprocess.run(
            REMOTE_PC_WAKE_COMMAND,
            capture_output=True,
            text=True,
            check=False,
            timeout=8,
        )
    except subprocess.TimeoutExpired:
        app.logger.warning("REMOTE wake timeout: command=%s", cmd_display)
        return False, "wake_timeout"
    except Exception as exc:
        app.logger.exception("REMOTE wake exception: command=%s error=%s", cmd_display, exc)
        return False, str(exc).strip() or "wake_failed"
    if proc.returncode != 0:
        detail = (proc.stderr or proc.stdout or "").strip() or "wake_failed"
        app.logger.warning(
            "REMOTE wake failed: command=%s returncode=%s stdout=%s stderr=%s",
            cmd_display,
            proc.returncode,
            (proc.stdout or "").strip()[:240],
            (proc.stderr or "").strip()[:240],
        )
        return False, detail
    app.logger.info(
        "REMOTE wake ok: command=%s returncode=%s stdout=%s stderr=%s",
        cmd_display,
        proc.returncode,
        (proc.stdout or "").strip()[:240],
        (proc.stderr or "").strip()[:240],
    )
    return True, None


def _remote_sessions_cleanup(now: datetime | None = None) -> None:
    ts = now or _utc_now()
    with _remote_sessions_lock:
        stale_ids = []
        for sid, row in _remote_sessions.items():
            created = row.get("created_at")
            if not isinstance(created, datetime):
                stale_ids.append(sid)
                continue
            age = (ts - created).total_seconds()
            if age > REMOTE_SESSION_TTL_SECONDS:
                stale_ids.append(sid)
        for sid in stale_ids:
            _remote_sessions.pop(sid, None)


def _remote_session_get(session_id: str) -> dict[str, Any] | None:
    _remote_sessions_cleanup()
    with _remote_sessions_lock:
        row = _remote_sessions.get(session_id)
        return dict(row) if isinstance(row, dict) else None


def _remote_access_allowed() -> bool:
    if get_current_role() == "master":
        return True
    client_ip = str(getattr(g, "client_ip", "") or "")
    return bool(client_ip and is_tailscale_ip(client_ip))


def _remote_device_set_cached_state(device_id: str, is_on: bool | None, reachable: bool, error: str | None = None) -> None:
    did = str(device_id or "").strip()
    if not did:
        return
    row = {
        "is_on": is_on if isinstance(is_on, bool) else None,
        "reachable": bool(reachable),
        "error": str(error or "").strip() or None,
        "updated_at": _iso_utc(_utc_now()),
    }
    with _remote_devices_lock:
        _remote_devices_state[did] = row
        existing: dict[str, Any] = {}
        try:
            if _remote_devices_state_path.exists():
                existing_raw = json.loads(_remote_devices_state_path.read_text(encoding="utf-8"))
                if isinstance(existing_raw, dict):
                    existing = dict(existing_raw)
        except Exception:
            existing = {}
        existing[did] = row
        _remote_devices_state_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = _remote_devices_state_path.with_name(
            f"{_remote_devices_state_path.name}.tmp.{os.getpid()}.{threading.get_ident()}"
        )
        tmp_path.write_text(json.dumps(existing, ensure_ascii=False), encoding="utf-8")
        tmp_path.replace(_remote_devices_state_path)


def _remote_device_set_cached_extras(device_id: str, extras: dict[str, Any]) -> None:
    did = str(device_id or "").strip()
    if not did or not isinstance(extras, dict):
        return
    with _remote_devices_lock:
        existing: dict[str, Any] = {}
        try:
            if _remote_devices_state_path.exists():
                existing_raw = json.loads(_remote_devices_state_path.read_text(encoding="utf-8"))
                if isinstance(existing_raw, dict):
                    existing = dict(existing_raw)
        except Exception:
            existing = {}

        row = existing.get(did)
        if not isinstance(row, dict):
            row = dict(_remote_devices_state.get(did) or {})
        if not isinstance(row, dict):
            row = {}

        for key, value in extras.items():
            if value is None:
                row.pop(str(key), None)
            else:
                row[str(key)] = value
        row["updated_at"] = _iso_utc(_utc_now())

        _remote_devices_state[did] = row
        existing[did] = row
        _remote_devices_state_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = _remote_devices_state_path.with_name(
            f"{_remote_devices_state_path.name}.tmp.{os.getpid()}.{threading.get_ident()}"
        )
        tmp_path.write_text(json.dumps(existing, ensure_ascii=False), encoding="utf-8")
        tmp_path.replace(_remote_devices_state_path)


def _remote_device_get_cached_state(device_id: str) -> dict[str, Any] | None:
    did = str(device_id or "").strip()
    if not did:
        return None
    with _remote_devices_lock:
        row = _remote_devices_state.get(did)
        if isinstance(row, dict):
            return dict(row)
        try:
            if _remote_devices_state_path.exists():
                payload = json.loads(_remote_devices_state_path.read_text(encoding="utf-8"))
                if isinstance(payload, dict):
                    from_file = payload.get(did)
                    if isinstance(from_file, dict):
                        _remote_devices_state[did] = dict(from_file)
                        return dict(from_file)
        except Exception:
            return None
        return None


def _remote_device_live_is_on(payload: Any) -> bool | None:
    if not isinstance(payload, dict):
        return None
    is_on = payload.get("is_on")
    if isinstance(is_on, bool):
        return is_on
    state = payload.get("state")
    if isinstance(state, bool):
        return state
    return None


def _remote_fetch_live_device_state(device_name: str, driver: str) -> dict[str, Any] | None:
    try:
        if driver == "tapo":
            from smart_home.service import get_state as tapo_get_state

            live = tapo_get_state(device_name, retries=1, delay=0.0, timeout=1.6)
        elif driver == "govee":
            from smart_home.config import is_govee_enabled
            if not is_govee_enabled():
                return None
            from smart_home.govee import get_state as govee_get_state

            live = govee_get_state(device_name, timeout=0.5)
        else:
            return None
    except Exception:
        return None

    if isinstance(live, dict) and live.get("ok"):
        return live
    return None


def _remote_fetch_live_device_states(device_specs: list[tuple[str, str]]) -> dict[str, dict[str, Any] | None]:
    if not device_specs:
        return {}

    results: dict[str, dict[str, Any] | None] = {}
    max_workers = max(1, min(len(device_specs), 6))
    with ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix="remote-device-state") as executor:
        futures = {
            executor.submit(_remote_fetch_live_device_state, device_name, driver): device_name
            for device_name, driver in device_specs
        }
        for future in as_completed(futures):
            device_name = futures[future]
            try:
                results[device_name] = future.result()
            except Exception:
                results[device_name] = None
    return results


def require_remote_access(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if _remote_access_allowed() or (
            get_current_role() == "key" and request.method in {"GET", "HEAD", "OPTIONS"}
        ):
            return fn(*args, **kwargs)
        if request.path.startswith("/api/"):
            return jsonify(
                {
                    "ok": False,
                    "error": "forbidden",
                    "detail": "Remote nur über Tailscale-IP oder Master-Rolle verfügbar.",
                }
            ), 403
        return make_response("Remote nur über Tailscale-IP oder Master-Rolle verfügbar.", 403)

    return wrapper


