@app.before_request
def _security_layer():
    g.core_request_started_at = time()
    g.request_id = uuid.uuid4().hex[:12]
    init_request_timing()
    test_ctx = _test_ui_context_from_request()
    g.test_mode = bool(test_ctx["enabled"])
    g.test_mode_role = str(session.get("role") or "")
    resp = enforce_private_access()
    if resp is not None:
        return resp
    resp = enforce_key_read_only()
    if resp is not None:
        return resp
    enforce_ip_whitelist()
    if getattr(g, "test_mode", False) and request.method in _TEST_UI_WRITE_METHODS:
        return _test_ui_blocked_write_response()
    return enforce_write_protection()


@app.after_request
def _auth_logging_layer(response):
    total_ms = None
    try:
        started = float(getattr(g, "core_request_started_at", time()))
        latency_ms = max(0, int((time() - started) * 1000))
        total_ms = max(0.0, (time() - started) * 1000.0)
        response = capture_http_event(request, response, latency_ms)
    except Exception:
        pass
    try:
        flush_request_timing(getattr(response, "status_code", None))
    except Exception:
        pass
    try:
        if total_ms is not None:
            response.headers["Server-Timing"] = f"app;dur={total_ms:.1f}"
            response.headers["X-Render-Time-Ms"] = f"{total_ms:.1f}"
            response.headers["X-Request-Id"] = str(getattr(g, "request_id", "") or "")
    except Exception:
        pass
    try:
        path = request.path or ""
        if path.startswith("/static/"):
            # Aggressive caching for fingerprinted static assets (?v=...), conservative otherwise.
            if request.args.get("v"):
                response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
            else:
                response.headers["Cache-Control"] = f"public, max-age={_static_max_age}"
        elif response.content_type and "text/html" in response.content_type.lower():
            # Preserve revalidation while allowing mobile browsers to reuse page state.
            response.headers["Cache-Control"] = "private, no-cache, max-age=0, must-revalidate"
            response.headers["Vary"] = "Cookie"
    except Exception:
        pass
    return log_key_activity(response)

