def _to_float(x):
    if x is None:
        return 0.0
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return 0.0
        s = s.replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0
    return 0.0


def _parse_float_or_none(val):
    if val is None:
        return None
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        s = val.strip()
        if not s:
            return None
        s = re.sub(r"[^0-9,.\-+]", "", s.replace(" ", ""))
        if not s:
            return None
        sign = -1 if s.startswith("-") else 1
        s = s.lstrip("+-")
        if "," in s and "." in s:
            if s.rfind(".") > s.rfind(","):
                s = s.replace(",", "")
            else:
                s = s.replace(".", "").replace(",", ".")
        elif "," in s:
            if s.count(",") > 1:
                s = s.replace(",", "")
            else:
                head, tail = s.split(",", 1)
                if len(tail) == 3 and len(head) > 0:
                    s = head + tail
                else:
                    s = head + "." + tail
        elif "." in s:
            if s.count(".") > 1:
                s = s.replace(".", "")
            else:
                head, tail = s.split(".", 1)
                if len(tail) == 3 and len(head) > 0:
                    s = head + tail
                else:
                    s = head + "." + tail
        try:
            return sign * float(s)
        except Exception:
            return None
    return None

def _dashboard_range_window(raw_days: str | None, offset_raw: str | None = "0", default_days: int = 7):
    raw = (raw_days or str(default_days)).strip().lower()
    if raw == "all":
        days = 3650
        days_out = "all"
    else:
        days = _clamp_int(raw, 1, 3650, default_days)
        days_out = days
    offset_days = _clamp_int((offset_raw or "0").strip(), 0, 3650, 0)
    today = date.today()
    target_end = today - timedelta(days=offset_days)
    start = target_end - timedelta(days=days - 1)
    return {
        "days": days,
        "days_out": days_out,
        "offset_days": offset_days,
        "start_iso": start.isoformat(),
        "end_iso": target_end.isoformat(),
    }

def _clamp_int(v, lo, hi, default):
    try:
        v = int(v)
        return max(lo, min(hi, v))
    except Exception:
        return default

def _date_from_for_range(days, default_days: int = 365):
    if isinstance(days, str) and days.strip().lower() == "all":
        return None
    window_days = _clamp_int(days, 1, 3650, default_days)
    cutoff = date.today() - timedelta(days=window_days - 1)
    return cutoff.isoformat()

def _parse_iso(s: str | None):
    if not s:
        return None
    try:
        return datetime.strptime(s.strip(), "%Y-%m-%d").date()
    except Exception:
        return None

def touch_last_update():
    global _LAST_UPDATE_CACHE_TS, _LAST_UPDATE_CACHE_VALUE
    conn = get_training_db()
    conn.execute(
        "UPDATE meta SET value=? WHERE key='last_update'",
        (str(time()),)
    )
    conn.commit()
    conn.close()
    _LAST_UPDATE_CACHE_TS = 0.0
    _LAST_UPDATE_CACHE_VALUE = 0.0

def _safe_mtime(path: Path) -> float:
    try:
        return path.stat().st_mtime
    except Exception:
        return 0.0


_LAST_UPDATE_CACHE_TS = 0.0
_LAST_UPDATE_CACHE_VALUE = 0.0
_LAST_UPDATE_CACHE_TTL_SECONDS = 2.0


def _compute_last_update_ts() -> float:
    """
    Single timestamp for "something in the data changed".
    We combine:
      - meta.last_update (for writes done through the Flask app)
      - filesystem mtimes of all SQLite DBs (+ WAL/SHM), so background jobs also trigger live refresh.
    """
    global _LAST_UPDATE_CACHE_TS, _LAST_UPDATE_CACHE_VALUE
    now_ts = time()
    if (now_ts - _LAST_UPDATE_CACHE_TS) < _LAST_UPDATE_CACHE_TTL_SECONDS:
        return _LAST_UPDATE_CACHE_VALUE

    # 1) app-triggered writes
    meta_ts = 0.0
    try:
        conn = get_training_db()
        cur = conn.cursor()
        cur.execute("SELECT value FROM meta WHERE key='last_update'")
        row = cur.fetchone()
        conn.close()
        if row and row[0] is not None:
            meta_ts = float(row[0])
    except Exception:
        meta_ts = 0.0

    # 2) background jobs / other db files
    base_dir = Path(__file__).resolve().parent
    db_dir = base_dir / "database"
    db_names = [
        "training.sqlite3",
        "ernaehrung.sqlite3",
        "hrv.sqlite3",
        "runs.sqlite3",
        "plans.sqlite3",
    ]
    file_ts = 0.0
    for name in db_names:
        p = db_dir / name
        file_ts = max(file_ts, _safe_mtime(p))
        # SQLite WAL mode: writes may only touch -wal / -shm for a while
        file_ts = max(file_ts, _safe_mtime(Path(str(p) + "-wal")))
        file_ts = max(file_ts, _safe_mtime(Path(str(p) + "-shm")))

    out = max(meta_ts, file_ts)
    _LAST_UPDATE_CACHE_TS = now_ts
    _LAST_UPDATE_CACHE_VALUE = out
    return out


def safe_num(v):
    try:
        return float(v)
    except Exception:
        return 0.0


def safe_round(v, digits=0):
    return round(v, digits) if v is not None else None


# ============================================================
#   PLANUNG / PERIODISIERUNG – DATEN & DB
#   Kurz-Doku:
#   - Tabelle plans: name, payload_json (base_week + weeks + meta), block_length, is_active, timestamps
#   - Tabelle exercise_muscle_map: user overrides für Muskel-Zuordnung (JSON gewichtete Anteile)
#   - Tabelle plan_cache: Cache für Coach-Panel pro Plan+Week (cache_key = Hash aus Plan+Mapping)
#   Best-Range/Progress:
#   - Wochenweise Aggregation historischer Sets aus training.sqlite3 (nur Arbeitssätze)
#   - e1RM-Improvement pro Übung (Lag +1 Woche) -> progress_score pro Muskel/Woche
#   - Best-Range per Muskel: Bins über Sets, gefiltert nach ähnlichen Wochen (Strength-Frequenz ±1, Run-Load Kategorie)
#   - Confidence abhängig von Datenmenge/Klarheit; Fallback konservativ falls zu wenig Daten
# ============================================================


def ensure_plans_schema():
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("""
        CREATE TABLE IF NOT EXISTS plans (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            data TEXT NOT NULL,
            block_length INTEGER NOT NULL DEFAULT 4,
            is_active INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
    """)
    if not _column_exists(cur, "plans", "start_date"):
        cur.execute("ALTER TABLE plans ADD COLUMN start_date TEXT NULL")
    if not _column_exists(cur, "plans", "total_weeks"):
        cur.execute("ALTER TABLE plans ADD COLUMN total_weeks INTEGER NOT NULL DEFAULT 8")
    if not _column_exists(cur, "plans", "week_override"):
        cur.execute("ALTER TABLE plans ADD COLUMN week_override INTEGER NULL")
    if not _column_exists(cur, "plans", "week_types"):
        cur.execute("ALTER TABLE plans ADD COLUMN week_types TEXT NULL")
    cur.execute("""
        CREATE TABLE IF NOT EXISTS exercise_muscle_map (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            mapping_json TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS plan_cache (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            plan_id INTEGER NOT NULL,
            week_index INTEGER NOT NULL,
            cache_key TEXT NOT NULL,
            payload TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(plan_id, week_index, cache_key)
        )
    """)

    # Default Split, falls leer
    count = cur.execute("SELECT COUNT(*) FROM plans").fetchone()[0]
    if count == 0:
        default_plan = build_default_plan()
        now = datetime.utcnow().isoformat()
        cur.execute("""
            INSERT INTO plans (name, data, block_length, is_active, created_at, updated_at)
            VALUES (?, ?, ?, 1, ?, ?)
        """, (
            default_plan["name"],
            json.dumps(default_plan),
            default_plan["block_length"],
            now,
            now
        ))
    conn.commit()
    conn.close()


def ensure_gym_plans_schema():
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS gym_plans (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            focus TEXT NOT NULL DEFAULT '',
            plan_json TEXT NOT NULL,
            rules_json TEXT NOT NULL DEFAULT '{}',
            blocks_json TEXT NOT NULL DEFAULT '{}',
            is_active INTEGER NOT NULL DEFAULT 0,
            is_archived INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_gym_plans_active_updated ON gym_plans (is_active DESC, updated_at DESC)"
    )
    if not _column_exists(cur, "gym_plans", "focus"):
        cur.execute("ALTER TABLE gym_plans ADD COLUMN focus TEXT NOT NULL DEFAULT ''")
    if not _column_exists(cur, "gym_plans", "rules_json"):
        cur.execute("ALTER TABLE gym_plans ADD COLUMN rules_json TEXT NOT NULL DEFAULT '{}'")
    if not _column_exists(cur, "gym_plans", "blocks_json"):
        cur.execute("ALTER TABLE gym_plans ADD COLUMN blocks_json TEXT NOT NULL DEFAULT '{}'")

    count = cur.execute("SELECT COUNT(*) AS c FROM gym_plans").fetchone()["c"]
    if count == 0:
        now = datetime.utcnow().isoformat()
        plan_json = default_gym_plan_json()
        rules_json = default_rules_json(int(plan_json.get("weeks") or 8))
        blocks_json = default_blocks_json()
        cur.execute(
            """
            INSERT INTO gym_plans (title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, 1, 0, ?, ?)
            """,
            (
                plan_json["meta"]["title"],
                plan_json["meta"]["focus"],
                json.dumps(plan_json, ensure_ascii=False),
                json.dumps(rules_json, ensure_ascii=False),
                json.dumps(blocks_json, ensure_ascii=False),
                now,
                now,
            ),
        )
    conn.commit()
    conn.close()


