def _column_exists(cur: sqlite3.Cursor, table: str, col: str) -> bool:
    cur.execute(f"PRAGMA table_info({table})")
    return any(r["name"] == col for r in cur.fetchall())


def ensure_sets_workout_id_schema():
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sets'")
    if cur.fetchone() is None:
        conn.close()
        return

    has_workout_id = _column_exists(cur, "sets", "workout_id")
    if not has_workout_id:
        cur.execute("ALTER TABLE sets ADD COLUMN workout_id INTEGER")
        cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='exercises'")
        if cur.fetchone() is not None:
            cur.execute("""
                UPDATE sets
                SET workout_id = (
                    SELECT workout_id
                    FROM exercises
                    WHERE exercises.id = sets.exercise_id
                )
                WHERE workout_id IS NULL
            """)

    cur.execute("CREATE INDEX IF NOT EXISTS idx_sets_workout_id ON sets(workout_id)")

    schema_row = cur.execute("""
        SELECT sql FROM sqlite_master
        WHERE type='table' AND name='sets'
    """).fetchone()
    schema_sql = (schema_row["sql"] or "").lower() if schema_row else ""
    has_fk = "workout_id" in schema_sql and "references workouts" in schema_sql
    has_not_null = "workout_id" in schema_sql and "workout_id integer not null" in schema_sql

    null_count = cur.execute("SELECT COUNT(*) AS c FROM sets WHERE workout_id IS NULL").fetchone()["c"]
    if null_count == 0 and (not has_fk or not has_not_null):
        cur.execute("PRAGMA foreign_keys=OFF")
        cur.execute("""
            CREATE TABLE sets_new (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                exercise_id INTEGER NOT NULL,
                workout_id INTEGER NOT NULL,
                set_number INTEGER,
                weight REAL,
                reps INTEGER,
                rpe REAL,
                created_at TEXT NOT NULL,
                FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE,
                FOREIGN KEY (workout_id) REFERENCES workouts(id) ON DELETE CASCADE
            )
        """)
        cur.execute("""
            INSERT INTO sets_new (
                id, exercise_id, workout_id, set_number, weight, reps, rpe, created_at
            )
            SELECT id, exercise_id, workout_id, set_number, weight, reps, rpe, created_at
            FROM sets
        """)
        cur.execute("DROP TABLE sets")
        cur.execute("ALTER TABLE sets_new RENAME TO sets")
        cur.execute("CREATE INDEX IF NOT EXISTS idx_sets_workout_id ON sets(workout_id)")
        cur.execute("PRAGMA foreign_keys=ON")

    conn.commit()
    conn.close()


