def ensure_progression_v5_schema():
    """Add deterministic V5 identity, slot, and technical exclusion fields."""
    conn = get_training_db()
    cur = conn.cursor()
    migrations = {
        "exercises": {
            "canonical_exercise_id": "ALTER TABLE exercises ADD COLUMN canonical_exercise_id TEXT",
            "variation_id": "ALTER TABLE exercises ADD COLUMN variation_id TEXT",
            "execution_mode": "ALTER TABLE exercises ADD COLUMN execution_mode TEXT NOT NULL DEFAULT ''",
            "notes": "ALTER TABLE exercises ADD COLUMN notes TEXT NOT NULL DEFAULT ''",
        },
        "sets": {
            "set_slot": "ALTER TABLE sets ADD COLUMN set_slot TEXT",
            "is_warmup": "ALTER TABLE sets ADD COLUMN is_warmup INTEGER",
            "is_working_set": "ALTER TABLE sets ADD COLUMN is_working_set INTEGER",
            "intentional_deload": "ALTER TABLE sets ADD COLUMN intentional_deload INTEGER NOT NULL DEFAULT 0",
            "technique_set": "ALTER TABLE sets ADD COLUMN technique_set INTEGER NOT NULL DEFAULT 0",
        },
    }
    for table, columns in migrations.items():
        cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,))
        if cur.fetchone() is None:
            continue
        for column, sql in columns.items():
            if not _column_exists(cur, table, column):
                cur.execute(sql)
    cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sets'")
    if cur.fetchone() is not None and _column_exists(cur, "sets", "exercise_id") and _column_exists(cur, "sets", "set_slot"):
        cur.execute("CREATE INDEX IF NOT EXISTS idx_sets_set_slot ON sets(exercise_id, set_slot)")
    conn.commit()
    conn.close()


