EXERCISE_NAME_ALIASES = {
    "hammer curls": "hammers",
    "hammers": "hammers",
}


def normalize_ex_name(name: str):
    raw = (name or "").strip().lower()
    if not raw:
        return raw
    return EXERCISE_NAME_ALIASES.get(raw, raw)


def get_user_mapping():
    conn = get_plans_db()
    rows = conn.execute(
        "SELECT name, mapping_json FROM exercise_muscle_map ORDER BY updated_at ASC, id ASC"
    ).fetchall()
    conn.close()
    mapping = {}
    for r in rows:
        try:
            mapping[normalize_ex_name(r["name"])] = json.loads(r["mapping_json"])
        except Exception:
            continue
    return mapping


def dynamic_muscle_map():
    """
    Baut ein Mapping aus der Trainingshistorie:
    - nimmt muscle_primary / muscle_secondary aus training.sqlite3, falls vorhanden
    - primary -> 1.0, secondary -> 0.5
    """
    try:
        conn = get_training_db()
        rows = conn.execute("""
            SELECT DISTINCT TRIM(name) AS name,
                   LOWER(TRIM(muscle_primary)) AS mp,
                   LOWER(TRIM(muscle_secondary)) AS ms
            FROM exercises
            WHERE name IS NOT NULL AND TRIM(name) != ''
        """).fetchall()
        conn.close()
    except Exception:
        return {}

    mapping: dict[str, dict[str, float]] = {}
    for r in rows:
        ex = normalize_ex_name(r["name"])
        if not ex:
            continue
        mp = r["mp"]
        ms = r["ms"]
        mus = {}
        if mp:
            mus[mp] = 1.0
        if ms:
            mus[ms] = mus.get(ms, 0) + 0.5
        if mus:
            mapping[ex] = mus
    return mapping


def combined_mapping():
    user_map = get_user_mapping()
    dynamic_map = dynamic_muscle_map()
    merged = DEFAULT_MUSCLE_MAP.copy()
    merged.update(dynamic_map)
    merged.update(user_map)
    return merged


def resolve_muscles(exercise_name: str, variation: str = "", primary: str | None = None, secondary: str | None = None):
    name = normalize_ex_name(exercise_name)
    base = combined_mapping()
    if name in base:
        return base[name]

    # try combination with variation/device words appended
    if variation:
        vname = normalize_ex_name(f"{name} {variation}")
        if vname in base:
            return base[vname]

    coarse = classify_pattern(exercise_name or "", variation or "")
    if coarse and coarse in PATTERN_TO_MUSCLES:
        return PATTERN_TO_MUSCLES[coarse]

    muscles = {}
    if primary:
        muscles[normalize_ex_name(primary)] = 1.0
    if secondary:
        muscles[normalize_ex_name(secondary)] = 0.5
    return muscles if muscles else {"other": 1.0}


def canonicalize_sets(raw: dict) -> dict:
    """Map ähnliche Muskel-Bezeichner auf die festen Kategorien für das Coach-Panel."""
    mapping = {
        "upper_back": "back_horizontal",
        "traps": "back_horizontal",
        "lats": "back_vertical",
        "forearms": "biceps",
    }
    out = defaultdict(float)
    for k, v in raw.items():
        key = mapping.get(k, k)
        out[key] += float(v)
    return dict(out)


