def ensure_row_ids(plan: dict):
    changed = False
    for day in plan.get("base_week", []):
        for row in day.get("strength_exercises", []):
            if "uid" not in row:
                row["uid"] = uuid.uuid4().hex[:8]
                changed = True
        for run in day.get("run_sessions", []):
            if "uid" not in run:
                run["uid"] = uuid.uuid4().hex[:8]
                changed = True
    if changed and plan.get("id"):
        invalidate_plan_cache(plan["id"])
    return plan


def summarize_plan(plan: dict):
    base_week = plan.get("base_week", []) or []

    strength_days = sum(1 for d in base_week if (d.get("strength_exercises") or []))
    run_days = sum(1 for d in base_week if (d.get("run_sessions") or []))

    runs_total = 0.0
    for d in base_week:
        for r in (d.get("run_sessions") or []):
            runs_total += _to_float(r.get("amount_value"))

    return {
        "strength_days": strength_days,
        "run_days": run_days,
        "runs_total": runs_total
    }




def week_key_from_date(d: date):
    iso = d.isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


def pick_run_category(distance_km: float | None, minutes: float | None):
    dist = distance_km or 0.0
    if dist == 0 and minutes:
        dist = minutes / 6.0  # grobe Umrechnung
    if dist >= 45:
        return "high"
    if dist >= 25:
        return "med"
    if dist > 0:
        return "low"
    return "none"


def bin_for_sets(sets: float):
    bins = [
        (0, 4),
        (5, 7),
        (8, 10),
        (11, 13),
        (14, 16),
        (17, 20),
    ]
    for lo, hi in bins:
        if sets <= hi:
            return (lo, hi)
    return (21, 24)  # 20+


def collect_run_history():
    weekly = defaultdict(lambda: {"distance": 0.0, "minutes": 0.0, "quality": 0})

    tr_conn = get_training_db()
    tr_rows = tr_conn.execute("SELECT date_iso, km, minutes FROM runs").fetchall()
    tr_conn.close()

    for r in tr_rows:
        if not r["date_iso"]:
            continue
        try:
            d = datetime.strptime(r["date_iso"], "%Y-%m-%d").date()
        except Exception:
            continue
        wk = week_key_from_date(d)
        km = r["km"] or 0.0
        minutes = r["minutes"] or 0.0
        weekly[wk]["distance"] += km
        weekly[wk]["minutes"] += minutes
        pace = None
        if km and minutes:
            pace = minutes / km
        run_type = classify_run(km, pace) if km and pace else "Unknown"
        if run_type in ("Tempo", "Threshold", "Interval"):
            weekly[wk]["quality"] += 1

    runs_conn = get_runs_db()
    runs_rows = runs_conn.execute("SELECT date, distance, moving_time, pace FROM runs").fetchall()
    runs_conn.close()

    for r in runs_rows:
        date_raw = r["date"]
        if not date_raw:
            continue
        try:
            d = datetime.strptime(date_raw.split("T")[0], "%Y-%m-%d").date()
        except Exception:
            continue
        wk = week_key_from_date(d)
        km = r["distance"] or 0.0
        minutes = None
        if r["moving_time"]:
            minutes = (r["moving_time"] or 0) / 60.0
        weekly[wk]["distance"] += km
        if minutes:
            weekly[wk]["minutes"] += minutes
        pace = None
        if km and minutes:
            pace = minutes / km
        run_type = classify_run(km, pace) if km and pace else "Unknown"
        if run_type in ("Tempo", "Threshold", "Interval"):
            weekly[wk]["quality"] += 1

    return weekly


def load_training_history():
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    rows = conn.execute("""
        SELECT
            w.date_iso,
            e.name,
            e.variation,
            e.device,
            e.muscle_primary,
            e.muscle_secondary,
            s.weight,
            s.reps,
            s.rpe
        FROM sets s
        JOIN exercises e ON s.exercise_id = e.id
        JOIN workouts w ON e.workout_id = w.id
        WHERE w.date_iso IS NOT NULL
        ORDER BY w.date_iso ASC, w.id ASC, e.id ASC, COALESCE(s.set_number, 0) ASC, s.id ASC
    """).fetchall()
    conn.close()

    weekly_sets = defaultdict(lambda: defaultdict(float))
    strength_days = defaultdict(set)
    session_best = {}

    for r in rows:
        date_iso = r["date_iso"]
        try:
            d = datetime.strptime(date_iso, "%Y-%m-%d").date()
        except Exception:
            continue
        wk = week_key_from_date(d)
        muscles = resolve_muscles(r["name"], r["variation"], r["muscle_primary"], r["muscle_secondary"])
        # set counting (arbeitssatz)
        for m, wgt in muscles.items():
            weekly_sets[wk][m] += 1 * float(wgt)
        strength_days[wk].add(date_iso)

        key = (
            date_iso,
            normalize_ex_name(r["name"]),
            normalize_ex_name(r["device"]),
            normalize_ex_name(r["variation"]),
        )
        e1rm = None
        if r["weight"] is not None and r["reps"] is not None and r["weight"] > 0 and r["reps"] > 0:
            e1rm = float(r["weight"]) * (1 + float(r["reps"]) / 30.0)
        if e1rm:
            existing = session_best.get(key)
            if not existing or e1rm > existing["e1rm"]:
                session_best[key] = {
                    "date": d,
                    "e1rm": e1rm,
                    "muscles": muscles,
                    "ex_key": (normalize_ex_name(r["name"]), normalize_ex_name(r["variation"]), normalize_ex_name(r["device"]))
                }

    exposures = defaultdict(lambda: defaultdict(float))
    for sess in session_best.values():
        wk = week_key_from_date(sess["date"])
        for m, wgt in sess["muscles"].items():
            exposures[wk][m] += float(wgt)

    improved = defaultdict(lambda: defaultdict(float))
    delta_pct = defaultdict(lambda: defaultdict(list))
    last_e1rm = {}
    for sess in sorted(session_best.values(), key=lambda x: x["date"]):
        key = sess["ex_key"]
        prev = last_e1rm.get(key)
        if prev and sess["e1rm"] > prev * 1.0075:
            target = sess["date"] + timedelta(days=7)
            wk = week_key_from_date(target)
            for m, wgt in sess["muscles"].items():
                improved[wk][m] += float(wgt)
                delta_pct[wk][m].append((sess["e1rm"] - prev) / prev)
        last_e1rm[key] = sess["e1rm"]

    weekly = {}
    run_history = collect_run_history()

    # Deload Erkennung über Median der letzten 4 Wochen
    ordered_weeks = sorted(weekly_sets.keys())
    totals = []
    for wk in ordered_weeks:
        totals.append(sum(weekly_sets[wk].values()))
    median_cache = {}
    for idx, wk in enumerate(ordered_weeks):
        prev = totals[max(0, idx - 4):idx]
        median_val = 0
        if prev:
            sorted_prev = sorted(prev)
            mid = len(sorted_prev) // 2
            if len(sorted_prev) % 2 == 0:
                median_val = (sorted_prev[mid - 1] + sorted_prev[mid]) / 2
            else:
                median_val = sorted_prev[mid]
        median_cache[wk] = median_val

    for wk in ordered_weeks:
        run_info = run_history.get(wk, {"distance": 0.0, "minutes": 0.0, "quality": 0})
        weekly[wk] = {
            "muscle_sets": canonicalize_sets(weekly_sets[wk]),
            "strength_days": len(strength_days[wk]),
            "run_distance": run_info["distance"],
            "run_minutes": run_info["minutes"],
            "quality_runs": run_info["quality"],
            "run_category": pick_run_category(run_info["distance"], run_info["minutes"]),
            "exposures": canonicalize_sets(exposures.get(wk, {})),
            "improved": canonicalize_sets(improved.get(wk, {})),
            "progress_score": {},
            "progress_delta": delta_pct.get(wk, {}),
            "deload": False
        }
        median_val = median_cache.get(wk, 0)
        total_sets = sum(weekly_sets[wk].values())
        if median_val and total_sets < median_val * 0.7:
            weekly[wk]["deload"] = True

    for wk, data in weekly.items():
        for m, exp in data["exposures"].items():
            imp = data["improved"].get(m, 0.0)
            score = 0.0
            if exp > 0:
                score = min(1.5, imp / exp)
            data["progress_score"][m] = score
            deltas = data["progress_delta"].get(m, [])
            if deltas:
                data["progress_delta"][m] = sum(deltas) / len(deltas)
            else:
                data["progress_delta"][m] = 0.0

    return weekly


def compute_planned_week(plan: dict, week_index: int):
    weeks = plan.get("weeks") or []
    base_week = plan.get("base_week") or []

    # clamp
    if week_index < 0:
        week_index = 0
    if weeks and week_index >= len(weeks):
        week_index = len(weeks) - 1

    week_meta = weeks[week_index] if week_index < len(weeks) else {
        "week": week_index + 1,
        "strength_volume_factor": 1.0,
        "run_volume_factor": 1.0,
        "deload": False,
        "rpe_cap": None,
        "week_note": ""
    }

    strength_factor = float(week_meta.get("strength_volume_factor", 1.0) or 1.0)
    run_factor = float(week_meta.get("run_volume_factor", 1.0) or 1.0)

    muscle_sets = defaultdict(float)
    day_details = []
    total_run_km_est = 0.0
    total_run_minutes = 0.0
    quality_runs = 0

    for idx, day in enumerate(base_week):
        day = day or {}
        day_muscles = defaultdict(float)

        rows = []
        for row in (day.get("strength_exercises") or []):
            row = row or {}

            # robust: akzeptiere verschiedene Key-Namen (falls Frontend/AI mal anders schreibt)
            ex_name = row.get("exercise_name") or row.get("name") or row.get("exercise") or ""
            device  = row.get("device") or row.get("variation") or ""

            base_sets = _to_float(row.get("sets"))
            scaled_sets = max(0, int(round(base_sets * strength_factor)))

            muscles = resolve_muscles(ex_name, device)

            for m, wgt in (muscles or {}).items():
                val = scaled_sets * float(wgt)
                day_muscles[m] += val
                muscle_sets[m] += val

            rows.append({
                "uid": row.get("uid"),
                "exercise_name": ex_name,
                "device": device,
                "sets": scaled_sets,
                "reps_min": row.get("reps_min"),
                "reps_max": row.get("reps_max"),
                "rpe_min": row.get("rpe_min"),
                "rpe_max": row.get("rpe_max"),
                "notes": row.get("notes"),
                "muscles": muscles,
            })

        runs = []
        day_run_amount = 0.0
        for run in (day.get("run_sessions") or []):
            run = run or {}
            amount_value = _to_float(run.get("amount_value"))
            amount = amount_value * run_factor
            day_run_amount += amount

            unit = (run.get("amount_unit") or "km").lower()
            if unit.startswith("min"):
                total_run_minutes += amount
                total_run_km_est += amount / 6.0
            else:
                total_run_km_est += amount
                total_run_minutes += amount * 6.0

            run_type = run.get("run_type") or "Easy"
            if run_type in ("Tempo", "Intervals", "Threshold"):
                quality_runs += 1

            runs.append({
                "uid": run.get("uid"),
                "run_type": run_type,
                "amount_value": amount,
                "amount_unit": run.get("amount_unit") or "km",
                "notes": run.get("notes"),
                "pace": run.get("pace"),
            })

        day_details.append({
            "day_index": idx,
            "label": day.get("day") or idx,
            "session_name": day.get("session_name") or "",
            "muscle_sets": canonicalize_sets(day_muscles),
            "strength_rows": rows,
            "runs": runs,
            "day_run_amount": day_run_amount
        })

    run_category = pick_run_category(total_run_km_est, total_run_minutes)

    return {
        "muscle_sets": canonicalize_sets(muscle_sets),
        "day_details": day_details,
        "week_meta": week_meta,
        "strength_factor": strength_factor,
        "run_factor": run_factor,
        "run_summary": {
            "km_estimate": round(total_run_km_est, 1),
            "minutes": round(total_run_minutes, 1),
            "quality_runs": quality_runs,
            "category": run_category
        }
    }



def similar_week_keys(history: dict, target_strength_days: int, target_run_cat: str):
    scored = []
    for wk, data in history.items():
        score = abs(data.get("strength_days", 0) - target_strength_days)
        if data.get("run_category") != target_run_cat:
            score += 1.2
        if data.get("deload"):
            score += 0.3
        scored.append((score, wk))
    return [wk for score, wk in sorted(scored)]


def derive_muscle_recs(planned_sets: dict, history: dict, similar_keys: list[str]):
    unassigned = planned_sets.get("unassigned", 0.0) + planned_sets.get("other", 0.0)
    muscles = set(k for k in planned_sets.keys() if k not in ("unassigned", "other"))
    for wk in similar_keys:
        muscles.update(k for k in (history.get(wk, {}).get("muscle_sets", {}).keys()) if k not in ("unassigned", "other"))

    recs = []
    for muscle in sorted(muscles):
        planned = planned_sets.get(muscle, 0.0)
        if planned <= 0:
            # nichts geplant -> aktuell keine Empfehlung
            continue
        bin_stats = {}
        raw_sets: list[float] = []
        for wk in similar_keys:
            data = history.get(wk)
            if not data:
                continue
            sets = data["muscle_sets"].get(muscle, 0.0)
            if sets <= 0:
                continue
            raw_sets.append(sets)
            score = data["progress_score"].get(muscle, 0.0)
            bin_range = bin_for_sets(sets)
            key = f"{bin_range[0]}-{bin_range[1]}"
            stat = bin_stats.setdefault(key, {"score": 0.0, "n": 0, "range": bin_range})
            stat["score"] += score
            stat["n"] += 1

        best_range = None
        confidence = "niedrig"
        default_range = DEFAULT_SET_RANGES.get(muscle, (8, 12))
        if bin_stats:
            for v in bin_stats.values():
                v["avg"] = v["score"] / max(1, v["n"])
            sorted_bins = sorted(bin_stats.values(), key=lambda x: (x["avg"], x["n"]), reverse=True)
            best = sorted_bins[0]
            if best["n"] >= 3:
                best_range = best["range"]
                second_avg = sorted_bins[1]["avg"] if len(sorted_bins) > 1 else 0
                confidence = "hoch" if best["n"] >= 8 and best["avg"] >= second_avg + 0.1 else "mittel" if best["n"] >= 4 else "niedrig"
        # fallback: nutze Median/IQR aus Rohdaten, wenn vorhanden
        if not best_range and raw_sets:
            sorted_sets = sorted(raw_sets)
            n = len(sorted_sets)
            median = sorted_sets[n // 2] if n % 2 == 1 else (sorted_sets[n // 2 - 1] + sorted_sets[n // 2]) / 2
            q1 = sorted_sets[max(0, n // 4 - 1)]
            q3 = sorted_sets[min(n - 1, (3 * n) // 4)]
            lo = max(1, round(q1 if n >= 4 else median * 0.8))
            hi = round(q3 if n >= 4 else median * 1.2 + 1)
            if hi < lo + 1:
                hi = lo + 2
            best_range = (lo, hi)
            confidence = "mittel" if n >= 3 else "niedrig"
        # falls historische Range unrealistisch niedrig, clamp auf Default
        if best_range and best_range[1] < default_range[0]:
            best_range = default_range
            confidence = "niedrig"

        status = "grey"
        recommendation = "Zu wenig Daten"
        if best_range:
            status = "green"
            recommendation = "passen lassen"
            if planned < best_range[0]:
                status = "orange"
                recommendation = "+2 Sätze/Woche (verteilen: +1 Haupt, +1 Accessory)"
            elif planned > best_range[1]:
                status = "red"
                overshoot = planned - best_range[1]
                step = 2 if overshoot <= 3 else 4
                recommendation = f"-{step} Sätze/Woche, reduziere auf zwei Tage"
        else:
            # Fallback auf heuristische Ranges
            fallback = DEFAULT_SET_RANGES.get(muscle, (8, 12))
            best_range = fallback
            recommendation = "Schätzung basierend auf ähnlichen Muskeln"
            status = "grey"

        why = []
        for wk in similar_keys:
            data = history.get(wk)
            if not data:
                continue
            sets = data["muscle_sets"].get(muscle, 0.0)
            score = data["progress_score"].get(muscle, 0.0)
            if sets <= 0:
                continue
            why.append({
                "week": wk,
                "sets": round(sets, 1),
                "progress": round(score, 3)
            })
        why = sorted(why, key=lambda x: x["progress"], reverse=True)[:3]

        recs.append({
            "muscle": muscle,
            "planned_sets": round(planned, 1),
            "best_range": best_range,
            "confidence": confidence,
            "status": status,
            "recommendation": recommendation,
            "why": why,
            "data_points": sum(v["n"] for v in bin_stats.values()) if bin_stats else 0
        })
    return recs, unassigned


def derive_run_rec(planned_run: dict, history: dict, similar_keys: list[str]):
    planned_km = planned_run.get("km_estimate") or 0.0
    distances = []
    for wk in similar_keys:
        data = history.get(wk)
        if not data:
            continue
        km = data.get("run_distance", 0.0) or 0.0
        if km <= 0:
            continue
        distances.append(km)

    best_range = None
    confidence = "niedrig"
    if distances:
        distances.sort()
        n = len(distances)
        median = distances[n // 2] if n % 2 == 1 else (distances[n // 2 - 1] + distances[n // 2]) / 2
        q1 = distances[max(0, n // 4 - 1)]
        q3 = distances[min(n - 1, (3 * n) // 4)]
        lo = max(10, round(q1 if n >= 4 else median * 0.8))
        hi = round(q3 if n >= 4 else median * 1.2 + 2)
        if hi < lo + 5:
            hi = lo + 8
        best_range = (lo, hi)
        confidence = "hoch" if n >= 12 else "mittel" if n >= 6 else "niedrig"
    else:
        best_range = None
        confidence = "niedrig"

    status = "grey"
    recommendation = "Keine Empfehlung, Laufdaten prüfen"
    if best_range:
        status = "green"
        recommendation = "passen lassen"
        if planned_km < best_range[0]:
            status = "orange"
            recommendation = "+1 moderater Lauf, Gesamt +2–4 km"
        elif planned_km > best_range[1]:
            status = "red"
            recommendation = "-1 Qualität oder Umfang drosseln (-10–20%)"
        elif planned_km == 0:
            status = "grey"
            recommendation = "Plane min. 1 Easy Run, damit Daten entstehen"

    return {
        "planned_km": round(planned_km, 1),
        "best_range": best_range,
        "confidence": confidence,
        "status": status,
        "recommendation": recommendation
    }


def build_warnings(planned_week: dict):
    warnings = []
    days = planned_week.get("day_details", [])
    total_muscle_sets = {k: v for k, v in planned_week.get("muscle_sets", {}).items() if k not in ("unassigned", "other")}

    uid_lookup = {}
    for d in days:
        for row in d.get("strength_rows", []):
            uid_lookup[row.get("uid")] = {
                "day": d.get("label", d.get("day_index")),
                "name": row.get("exercise_name") or "Übung"
            }

    lower_keys = ("quads", "hamstrings", "glutes")
    pull_keys = ("back_horizontal", "back_vertical", "rear_delts", "biceps")
    push_keys = ("chest", "front_delts", "side_delts", "triceps")

    lower_by_day = []
    unassigned_rows = []
    for d in days:
        lower_sum = sum(d["muscle_sets"].get(k, 0.0) for k in lower_keys)
        lower_by_day.append(lower_sum)
        for row in d.get("strength_rows", []):
            if any(k in ("unassigned", "other") for k in (row.get("muscles") or {})):
                unassigned_rows.append({"day": d["day_index"], "uid": row.get("uid")})

    for idx, d in enumerate(days):
        for run in d.get("runs", []):
            rt = run.get("run_type")
            if rt in ("Intervals", "Tempo", "Threshold"):
                if idx + 1 < len(lower_by_day) and lower_by_day[idx + 1] >= 12:
                    warnings.append({
                        "level": "red",
                        "title": "Intervals nah an schwerem Lower",
                        "action": "Verschiebe Intervalle 1 Tag früher oder senke Unterkörperstress",
                        "targets": [{"day": idx + 1}, {"day": idx, "run_uid": run.get("uid")}]
                    })
            if rt == "Long" and idx > 0 and lower_by_day[idx - 1] >= 10:
                warnings.append({
                    "level": "orange",
                    "title": "Long Run direkt nach heavy Hinge",
                    "action": "Lege Long Run 48h nach schwerem Hinge oder entzerre Beinvolumen",
                    "targets": [{"day": idx - 1}, {"day": idx, "run_uid": run.get("uid")}]
                })

    planned_km = planned_week.get("run_summary", {}).get("km_estimate", 0.0)
    quality_runs = planned_week.get("run_summary", {}).get("quality_runs", 0)
    if quality_runs > 2:
        warnings.append({
            "level": "orange",
            "title": "Zu viele Quality Runs",
            "action": "Max 2 Quality-Runs/Woche; mach einen zum Easy/Steady",
            "targets": []
        })

    push = sum(total_muscle_sets.get(k, 0.0) for k in push_keys)
    pull = sum(total_muscle_sets.get(k, 0.0) for k in pull_keys)
    if pull < push * 0.6 and (pull + push) > 0:
        warnings.append({
            "level": "orange",
            "title": "Pull deutlich unter Push",
            "action": "Füge 2–3 Sätze Rücken/Bizeps hinzu",
            "targets": []
        })

    for muscle, sets in total_muscle_sets.items():
        for d in days:
            d_sets = d["muscle_sets"].get(muscle, 0.0)
            if sets > 0 and d_sets > sets * 0.6 and sets >= 8:
                warnings.append({
                    "level": "grey",
                    "title": f"{muscle}: Volumen konzentriert",
                    "action": "Verteile Sätze auf zwei Tage",
                    "targets": [{"day": d["day_index"]}]
                })
                break

    if planned_km > 45 and any(v > 16 for v in lower_by_day):
        warnings.append({
            "level": "orange",
            "title": "High Run Load + hoher Lower-Stress",
            "action": "Reduziere Beinvolumen in Lauf-Spitzenwochen um 10–20%",
            "targets": []
        })

    if unassigned_rows:
        details = []
        for r in unassigned_rows:
            info = uid_lookup.get(r.get("uid"), {})
            details.append(f"{info.get('day')}: {info.get('name')}")
        warn_text = "Fehlend: " + ", ".join(details) if details else "Mapping ergänzen."
        warnings.append({
            "level": "grey",
            "title": "Muskel-Zuordnung fehlt",
            "action": warn_text,
            "targets": unassigned_rows
        })

    return warnings


def coach_payload(plan: dict, week_index: int):
    plan = ensure_row_ids(plan)
    planned = compute_planned_week(plan, week_index)
    history = load_training_history()
    target_strength_days = sum(1 for d in plan.get("base_week", []) if d.get("strength_exercises"))
    similar_keys = similar_week_keys(history, target_strength_days, planned["run_summary"]["category"])
    similar_keys = similar_keys[:30]

    # unmapped exercises aus Plan sammeln
    unmapped = []
    for day in plan.get("base_week", []):
        for row in day.get("strength_exercises", []):
            muscles = resolve_muscles(row.get("exercise_name"), None)
            if "other" in muscles or "unassigned" in muscles:
                unmapped.append(row.get("exercise_name") or "Übung")

    muscle_recs, unassigned_sets = derive_muscle_recs(planned["muscle_sets"], history, similar_keys)
    run_rec = derive_run_rec(planned["run_summary"], history, similar_keys)
    warnings = build_warnings(planned)

    payload = {
        "week": week_index + 1,
        "strength_factor": planned["strength_factor"],
        "run_factor": planned["run_factor"],
        "muscles": muscle_recs,
        "run": run_rec,
        "warnings": warnings,
        "unassigned_sets": round(unassigned_sets, 1) if unassigned_sets else 0,
        "unmapped_exercises": unmapped,
    }

    return payload


