def get_weight_logs(
    limit: int | None = None,
    offset: int = 0,
    include_weight_only: bool = True,
    date_from: str | None = None,
    date_to: str | None = None,
):
    conn = get_nutrition_db()
    _ensure_nutrition_daily_view(conn)
    cur = conn.cursor()

    filters = []
    params: list[str | int] = []
    if not include_weight_only:
        filters.append("(kcal IS NOT NULL OR protein IS NOT NULL OR carbs IS NOT NULL OR fat IS NOT NULL OR sugar IS NOT NULL)")
    if date_from:
        filters.append("date_iso >= ?")
        params.append(date_from)
    if date_to:
        filters.append("date_iso <= ?")
        params.append(date_to)
    where_clause = f"WHERE {' AND '.join(filters)}" if filters else ""

    base_query = f"""
        WITH filtered AS (
            SELECT id, date, weight_kg, kcal, protein, carbs, fat, sugar, date_iso, created_at, raw_json
            FROM weight_logs
            {where_clause}
        ),
        latest_per_day AS (
            SELECT COALESCE(date_iso, date) AS day_key, MAX(id) AS latest_id
            FROM filtered
            GROUP BY COALESCE(date_iso, date)
        )
        SELECT f.id, f.date, f.weight_kg, f.kcal, f.protein, f.carbs, f.fat, f.sugar, f.date_iso, f.created_at, f.raw_json
        FROM filtered f
        JOIN latest_per_day l ON COALESCE(f.date_iso, f.date) = l.day_key AND f.id = l.latest_id
        ORDER BY f.date_iso DESC
    """

    if limit is not None:
        base_query += " LIMIT ? OFFSET ?"
        params.extend([limit, offset])
    elif offset:
        base_query += " LIMIT -1 OFFSET ?"
        params.append(offset)

    cur.execute(base_query, tuple(params))
    rows = cur.fetchall()
    conn.close()
    return rows


def _ensure_nutrition_settings(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS nutrition_settings (
            key TEXT PRIMARY KEY,
            value TEXT
        )
    """)


def _load_nutrition_settings():
    conn = get_nutrition_db()
    _ensure_nutrition_settings(conn)
    cur = conn.cursor()
    cur.execute("SELECT key, value FROM nutrition_settings")
    rows = cur.fetchall()
    conn.close()
    settings = {row["key"]: row["value"] for row in rows}

    def parse_value(key):
        return _parse_float_or_none(settings.get(key))

    def default_tolerances():
        return {"green_tol": 150.0, "yellow_tol": 300.0}

    modes = {}
    for mode in ("cut", "lean_bulk", "maintenance", "custom"):
        target_key = f"mode_{mode}_target"
        protein_key = f"mode_{mode}_protein_target"
        carbs_key = f"mode_{mode}_carbs_target"
        fat_key = f"mode_{mode}_fat_target"
        green_key = f"mode_{mode}_green_tol"
        yellow_key = f"mode_{mode}_yellow_tol"
        green_low_key = f"mode_{mode}_green_low"
        green_high_key = f"mode_{mode}_green_high"
        yellow_low_key = f"mode_{mode}_yellow_low"
        yellow_high_key = f"mode_{mode}_yellow_high"
        target = parse_value(target_key)
        protein_target = parse_value(protein_key)
        carbs_target = parse_value(carbs_key)
        fat_target = parse_value(fat_key)
        green_tol = parse_value(green_key)
        yellow_tol = parse_value(yellow_key)
        green_low = parse_value(green_low_key)
        green_high = parse_value(green_high_key)
        yellow_low = parse_value(yellow_low_key)
        yellow_high = parse_value(yellow_high_key)

        # Backwards compatibility: if bounds are missing but we have target + tolerances, derive bounds.
        if target is not None:
            if green_low is None and green_tol is not None:
                green_low = target - green_tol
            if green_high is None and green_tol is not None:
                green_high = target + green_tol
            if yellow_low is None and yellow_tol is not None:
                yellow_low = target - yellow_tol
            if yellow_high is None and yellow_tol is not None:
                yellow_high = target + yellow_tol

        # If bounds exist but tolerances are missing, derive a conservative "effective tolerance"
        # so older clients don't fall back to unrelated defaults.
        if target is not None and green_low is not None and green_high is not None and green_tol is None:
            green_tol = max(target - green_low, green_high - target)
        if target is not None and yellow_low is not None and yellow_high is not None and yellow_tol is None:
            yellow_tol = max(target - yellow_low, yellow_high - target)

        # Final fallback: if we still have no tolerances, use defaults.
        if green_tol is None or yellow_tol is None:
            defaults = default_tolerances()
            green_tol = green_tol if green_tol is not None else defaults["green_tol"]
            yellow_tol = yellow_tol if yellow_tol is not None else defaults["yellow_tol"]

        modes[mode] = {
            "kcal_target": target,
            "protein_target": protein_target,
            "carbs_target": carbs_target,
            "fat_target": fat_target,
            "green_tol": green_tol,
            "yellow_tol": yellow_tol,
            "green_low": green_low,
            "green_high": green_high,
            "yellow_low": yellow_low,
            "yellow_high": yellow_high,
            "updated_at": settings.get(f"mode_{mode}_updated_at"),
        }

    # Backwards compatibility with existing presets/targets.
    target_kcal = parse_value("target_kcal")
    presets = {
        "cut": parse_value("target_cut"),
        "lean_bulk": parse_value("target_lean_bulk"),
        "maintenance": parse_value("target_maintenance"),
    }
    if modes["custom"]["kcal_target"] is None and target_kcal is not None:
        modes["custom"]["kcal_target"] = target_kcal
    if modes["cut"]["kcal_target"] is None and presets["cut"] is not None:
        modes["cut"]["kcal_target"] = presets["cut"]
    if modes["lean_bulk"]["kcal_target"] is None and presets["lean_bulk"] is not None:
        modes["lean_bulk"]["kcal_target"] = presets["lean_bulk"]
    if modes["maintenance"]["kcal_target"] is None and presets["maintenance"] is not None:
        modes["maintenance"]["kcal_target"] = presets["maintenance"]

    active_mode = settings.get("active_mode") or settings.get("selected_mode") or "maintenance"

    return {
        "target_kcal": target_kcal,
        "presets": presets,
        "selected_mode": settings.get("selected_mode") or active_mode,
        "active_mode": active_mode,
        "modes": modes,
    }


def _extract_nutrition_meta(raw_json):
    if not raw_json:
        return {"source": None, "note": None}
    try:
        payload = json.loads(raw_json)
    except Exception:
        return {"source": None, "note": None}
    return {
        "source": payload.get("source") or payload.get("app") or payload.get("provider"),
        "note": payload.get("note"),
    }


def _extract_logged_macro_target(raw_json):
    if not raw_json:
        return None
    try:
        payload = json.loads(raw_json)
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None

    candidates = [
        payload.get("target"),
        payload.get("targets"),
        payload.get("macro_target"),
        payload.get("macro_targets"),
        payload.get("nutrition_target"),
        payload.get("nutrition_targets"),
        payload.get("goal"),
        payload.get("goals"),
    ]
    for candidate in candidates:
        if isinstance(candidate, dict):
            target = _parse_float_or_none(
                candidate.get("kcal")
                if candidate.get("kcal") is not None
                else candidate.get("target_kcal")
            )
            if target is not None:
                return {
                    "target_kcal": target,
                    "green_low": _parse_float_or_none(candidate.get("green_low")),
                    "green_high": _parse_float_or_none(candidate.get("green_high")),
                    "yellow_low": _parse_float_or_none(candidate.get("yellow_low")),
                    "yellow_high": _parse_float_or_none(candidate.get("yellow_high")),
                    "mode": (str(candidate.get("mode") or "").strip().lower() or None),
                    "template_title": candidate.get("template_title") or candidate.get("title"),
                    "source": "logged_target",
                }
    return None


_NUTRITION_DAILY_VIEW_READY = False
_NUTRITION_INDEXES_READY = False


def _ensure_weight_log_indexes(conn):
    global _NUTRITION_INDEXES_READY
    if _NUTRITION_INDEXES_READY:
        return
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_weight_logs_date_iso ON weight_logs(date_iso)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_weight_logs_date_iso_id ON weight_logs(date_iso, id)")
        _NUTRITION_INDEXES_READY = True
    except Exception:
        # Keep requests serving even if indexing fails.
        return


def _ensure_nutrition_daily_view(conn):
    global _NUTRITION_DAILY_VIEW_READY
    if _NUTRITION_DAILY_VIEW_READY:
        return
    try:
        row = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='weight_logs' LIMIT 1"
        ).fetchone()
    except Exception:
        row = None
    if not row:
        return
    _ensure_weight_log_indexes(conn)
    try:
        conn.execute(
            """
            CREATE VIEW IF NOT EXISTS nutrition_daily AS
            SELECT date, date_iso, weight_kg, kcal, protein, carbs, fat, sugar, created_at, raw_json
            FROM weight_logs
            """
        )
        _NUTRITION_DAILY_VIEW_READY = True
    except Exception:
        # If view creation fails, fall back to direct table queries in callers.
        return


def _load_nutrition_series(*, days=None, start_iso=None, end_iso=None, source=None):
    conn = get_nutrition_db()
    _ensure_nutrition_daily_view(conn)
    cur = conn.cursor()

    if start_iso and end_iso:
        cur.execute(
            """
            SELECT date, date_iso, weight_kg, kcal, protein, carbs, fat, sugar, raw_json
            FROM nutrition_daily
            WHERE date_iso BETWEEN ? AND ?
            ORDER BY date_iso ASC
            """,
            (start_iso, end_iso),
        )
        rows = cur.fetchall()
    elif days == "all":
        cur.execute(
            """
            SELECT date, date_iso, weight_kg, kcal, protein, carbs, fat, sugar, raw_json
            FROM nutrition_daily
            ORDER BY date_iso ASC
            """
        )
        rows = cur.fetchall()
    else:
        days = _clamp_int(str(days or 30), 1, 3650, 30)
        cur.execute(
            """
            SELECT date, date_iso, weight_kg, kcal, protein, carbs, fat, sugar, raw_json
            FROM nutrition_daily
            WHERE date_iso >= date('now', ?)
            ORDER BY date_iso ASC
            """,
            (f"-{days} days",),
        )
        rows = cur.fetchall()

    conn.close()

    data = []
    for row in rows:
        meta = _extract_nutrition_meta(row["raw_json"])
        if source and source.lower() != "any":
            if (meta["source"] or "").strip() != source:
                continue
        calories = _parse_float_or_none(row["kcal"])
        protein = _parse_float_or_none(row["protein"])
        carbs = _parse_float_or_none(row["carbs"])
        fat = _parse_float_or_none(row["fat"])
        sugar = _parse_float_or_none(row["sugar"])
        bodyweight = _parse_float_or_none(row["weight_kg"])
        data.append({
            "date": row["date"],
            "date_iso": row["date_iso"],
            "calories": calories,
            "protein_g": protein,
            "carbs_g": carbs,
            "fat_g": fat,
            "sugar_g": sugar,
            "bodyweight_kg": bodyweight,
            "source": meta["source"],
            "note": meta["note"],
        })
    return data


def _load_logging_streaks():
    conn = get_nutrition_db()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT DISTINCT date_iso
            FROM weight_logs
            WHERE date_iso IS NOT NULL
              AND (
                kcal IS NOT NULL
                OR protein IS NOT NULL
                OR carbs IS NOT NULL
                OR fat IS NOT NULL
                OR sugar IS NOT NULL
              )
            ORDER BY date_iso ASC
            """
        )
        rows = [row["date_iso"] for row in cur.fetchall() if row["date_iso"]]
    finally:
        conn.close()

    parsed_dates = []
    for iso in rows:
        try:
            parsed_dates.append(date.fromisoformat(iso))
        except Exception:
            continue

    parsed_dates = sorted(set(parsed_dates))
    if not parsed_dates:
        return {
            "current_streak_days": 0,
            "longest_streak_days": 0,
            "total_logged_days": 0,
        }

    total_logged_days = len(parsed_dates)
    longest = 0
    current_run = 0
    prev_date = None
    for log_date in parsed_dates:
        if prev_date and log_date == prev_date + timedelta(days=1):
            current_run += 1
        else:
            current_run = 1
        longest = max(longest, current_run)
        prev_date = log_date

    today = datetime.now(ZoneInfo("Europe/Berlin")).date()
    logged_set = set(parsed_dates)
    current_streak = 0

    # Count the active streak through today when today's entry exists.
    # If today is not logged yet, allow the streak to still be "current"
    # when yesterday was logged and there is no gap before that.
    if today in logged_set:
        check_day = today
    elif (today - timedelta(days=1)) in logged_set:
        check_day = today - timedelta(days=1)
    else:
        check_day = None

    while check_day and check_day in logged_set:
        current_streak += 1
        check_day -= timedelta(days=1)

    return {
        "current_streak_days": current_streak,
        "longest_streak_days": longest,
        "total_logged_days": total_logged_days,
    }


def _write_nutrition_settings(payload: dict):
    conn = get_nutrition_db()
    _ensure_nutrition_settings(conn)
    cur = conn.cursor()

    def upsert(key, value):
        if value is None:
            cur.execute("DELETE FROM nutrition_settings WHERE key=?", (key,))
            return
        cur.execute(
            """
            INSERT INTO nutrition_settings (key, value)
            VALUES (?, ?)
            ON CONFLICT(key) DO UPDATE SET value=excluded.value
            """,
            (key, str(value)),
        )

    if "target_kcal" in payload:
        upsert("target_kcal", _parse_float_or_none(payload.get("target_kcal")))
    if "presets" in payload:
        presets = payload.get("presets") or {}
        if "cut" in presets:
            upsert("target_cut", _parse_float_or_none(presets.get("cut")))
        if "lean_bulk" in presets:
            upsert("target_lean_bulk", _parse_float_or_none(presets.get("lean_bulk")))
        if "maintenance" in presets:
            upsert("target_maintenance", _parse_float_or_none(presets.get("maintenance")))
    if "selected_mode" in payload:
        selected = payload.get("selected_mode")
        selected_value = selected if selected is not None else None
        upsert("selected_mode", selected_value)
    if "active_mode" in payload:
        active = payload.get("active_mode")
        active_value = active if active is not None else None
        upsert("active_mode", active_value)
        upsert("selected_mode", active_value)
    if "modes" in payload:
        modes = payload.get("modes") or {}
        now_stamp = datetime.utcnow().isoformat()
        for mode, values in modes.items():
            if mode not in ("cut", "lean_bulk", "maintenance", "custom"):
                continue
            if not isinstance(values, dict):
                continue
            target = _parse_float_or_none(values.get("kcal_target"))
            protein_target = _parse_float_or_none(values.get("protein_target"))
            carbs_target = _parse_float_or_none(values.get("carbs_target"))
            fat_target = _parse_float_or_none(values.get("fat_target"))
            green_tol = _parse_float_or_none(values.get("green_tol"))
            yellow_tol = _parse_float_or_none(values.get("yellow_tol"))
            green_low = _parse_float_or_none(values.get("green_low"))
            green_high = _parse_float_or_none(values.get("green_high"))
            yellow_low = _parse_float_or_none(values.get("yellow_low"))
            yellow_high = _parse_float_or_none(values.get("yellow_high"))

            # Backwards compatibility: if only tolerances are provided, derive bounds from target.
            if target is not None and (green_low is None or green_high is None) and green_tol is not None:
                green_low = target - green_tol
                green_high = target + green_tol
            if target is not None and (yellow_low is None or yellow_high is None) and yellow_tol is not None:
                yellow_low = target - yellow_tol
                yellow_high = target + yellow_tol

            # If bounds are provided but tolerances are missing, persist derived tolerances for older clients.
            if target is not None and green_low is not None and green_high is not None and green_tol is None:
                green_tol = max(target - green_low, green_high - target)
            if target is not None and yellow_low is not None and yellow_high is not None and yellow_tol is None:
                yellow_tol = max(target - yellow_low, yellow_high - target)

            upsert(f"mode_{mode}_target", target)
            upsert(f"mode_{mode}_protein_target", protein_target)
            upsert(f"mode_{mode}_carbs_target", carbs_target)
            upsert(f"mode_{mode}_fat_target", fat_target)
            upsert(f"mode_{mode}_green_tol", green_tol)
            upsert(f"mode_{mode}_yellow_tol", yellow_tol)
            upsert(f"mode_{mode}_green_low", green_low)
            upsert(f"mode_{mode}_green_high", green_high)
            upsert(f"mode_{mode}_yellow_low", yellow_low)
            upsert(f"mode_{mode}_yellow_high", yellow_high)
            upsert(f"mode_{mode}_updated_at", values.get("updated_at") or now_stamp)
            if mode == "custom":
                upsert("target_kcal", target)
            if mode == "cut":
                upsert("target_cut", target)
            if mode == "lean_bulk":
                upsert("target_lean_bulk", target)
            if mode == "maintenance":
                upsert("target_maintenance", target)

    conn.commit()
    conn.close()


def _ensure_autopilot_schema(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS settings_kv (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL,
            updated_ts INTEGER
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS autopilot_day (
            date TEXT PRIMARY KEY,
            mode TEXT NOT NULL,
            output_json TEXT NOT NULL,
            reason_codes_json TEXT,
            created_ts INTEGER NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS autopilot_week (
            week_start TEXT PRIMARY KEY,
            plan_id INTEGER,
            data_json TEXT,
            planned_json TEXT,
            shifted_json TEXT,
            reason_codes_json TEXT,
            created_ts INTEGER NOT NULL,
            last_updated_ts INTEGER NOT NULL
        )
    """)
    # Migrations for older tables
    try:
        cur = conn.cursor()
        cols = [row["name"] for row in cur.execute("PRAGMA table_info(autopilot_week);").fetchall()]
        if "planned_json" not in cols:
            cur.execute("ALTER TABLE autopilot_week ADD COLUMN planned_json TEXT")
        if "shifted_json" not in cols:
            cur.execute("ALTER TABLE autopilot_week ADD COLUMN shifted_json TEXT")
        if "reason_codes_json" not in cols:
            cur.execute("ALTER TABLE autopilot_week ADD COLUMN reason_codes_json TEXT")
        if "plan_id" not in cols:
            cur.execute("ALTER TABLE autopilot_week ADD COLUMN plan_id INTEGER")
    except Exception:
        pass
    conn.execute("""
        CREATE TABLE IF NOT EXISTS override_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts INTEGER NOT NULL,
            decision_type TEXT NOT NULL,
            proposed_json TEXT,
            applied_json TEXT,
            user_override_bool INTEGER DEFAULT 0,
            context_json TEXT
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS movement_library (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movement_key TEXT NOT NULL,
            label TEXT NOT NULL,
            muscle_group TEXT,
            metadata_json TEXT
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS swap_groups (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_key TEXT NOT NULL,
            movement_key TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS pain_flags (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts INTEGER NOT NULL,
            movement_key TEXT,
            note TEXT
        )
    """)


def _get_setting(conn, key: str, default: str | None = None) -> str | None:
    _ensure_autopilot_schema(conn)
    cur = conn.cursor()
    row = cur.execute("SELECT value FROM settings_kv WHERE key=? LIMIT 1", (key,)).fetchone()
    if row and row["value"] is not None:
        return row["value"]
    if default is not None:
        cur.execute(
            "INSERT OR REPLACE INTO settings_kv (key, value, updated_ts) VALUES (?, ?, ?)",
            (key, str(default), int(time())),
        )
        conn.commit()
    return default


def _set_setting(conn, key: str, value: str | None) -> None:
    _ensure_autopilot_schema(conn)
    cur = conn.cursor()
    if value is None:
        cur.execute("DELETE FROM settings_kv WHERE key=?", (key,))
    else:
        cur.execute(
            "INSERT OR REPLACE INTO settings_kv (key, value, updated_ts) VALUES (?, ?, ?)",
            (key, str(value), int(time())),
        )
    conn.commit()


def _autopilot_clear_week_cache() -> None:
    conn = get_training_db()
    try:
        _ensure_autopilot_schema(conn)
        conn.execute("DELETE FROM autopilot_week")
        conn.commit()
    finally:
        conn.close()






def _get_core_mode_enabled() -> bool:
    return True


def _set_core_mode_enabled(enabled: bool) -> None:
    conn = get_training_db()
    try:
        # CORE is no longer user-toggleable. Keep legacy keys pinned on so
        # old clients/settings payloads cannot silently disable CORE.
        _set_setting(conn, "core_mode_enabled", "1")
        _set_setting(conn, "autopilot_enabled", "1")
    finally:
        conn.close()


def _core_prediction_active(pred: dict | None, min_conf: float = 0.55) -> bool:
    if not isinstance(pred, dict):
        return False
    if str(pred.get("answer") or "").strip().lower() != "yes":
        return False
    try:
        return float(pred.get("confidence") or 0.0) >= float(min_conf)
    except Exception:
        return False


def _build_core_mode_overlay(state_snapshot: dict | None = None) -> dict:
    if not _get_core_mode_enabled():
        return {"enabled": False}
    try:
        feature_payload = load_latest_features()
    except Exception:
        return {"enabled": True, "available": False, "features": {}, "summaries": {}, "predictions": {}, "actions": {}}

    state_snapshot = state_snapshot if isinstance(state_snapshot, dict) else {}
    features = dict(feature_payload.get("features") or {})
    summaries = dict(feature_payload.get("summaries") or {})
    subjective = state_snapshot.get("subjective") if isinstance(state_snapshot.get("subjective"), dict) else {}
    if subjective:
        features.update({
            "subjective_motivation": str(subjective.get("motivation_state") or "missing"),
            "subjective_sleep": str(subjective.get("sleep_state") or "missing"),
            "subjective_fatigue": str(subjective.get("fatigue_state") or "missing"),
            "subjective_readiness": str(subjective.get("readiness_state") or "missing"),
        })
        summaries["subjective"] = subjective
    topics = [
        "volume_vs_intensity",
        "proximity_to_failure",
        "progression_discipline",
        "deload_philosophy",
        "consistency_frequency",
        "interference_run_gym",
        "nutrition_as_limiter",
        "signal_weighting",
    ]
    predictions = {}
    for topic in topics:
        try:
            predictions[topic] = predict_topic(topic, features)
        except Exception:
            predictions[topic] = {"answer": "no", "probability": 0.5, "confidence": 0.0, "bar_position": 0.5}

    recovery_state = str(features.get("recovery_state") or "missing")
    strength_trend = str(features.get("strength_trend") or "missing")
    nutrition_state = str(features.get("nutrition_adherence") or "missing")
    run_load = str(features.get("run_load") or "missing")
    run_consistency = str(features.get("run_consistency") or "missing")
    warning_load = str(features.get("warning_load") or "missing")
    session_gap = str(features.get("session_gap") or "missing")
    gym_frequency = str(features.get("gym_frequency") or "missing")
    proximity = str(features.get("proximity_to_failure") or "missing")

    actions = {
        "nutrition_guard": nutrition_state == "low" and _core_prediction_active(predictions.get("nutrition_as_limiter"), 0.52),
        "deload_guard": warning_load in {"ok", "high"} and _core_prediction_active(predictions.get("deload_philosophy"), 0.55),
        "interference_guard": run_load == "high" and _core_prediction_active(predictions.get("interference_run_gym"), 0.52),
        "consistency_guard": (gym_frequency == "low" or session_gap == "long" or run_consistency == "low") and _core_prediction_active(predictions.get("consistency_frequency"), 0.52),
        "rpe_guard": proximity == "high" and _core_prediction_active(predictions.get("proximity_to_failure"), 0.55),
        "progression_push": (
            recovery_state == "high"
            and strength_trend in {"flat", "up"}
            and _core_prediction_active(predictions.get("progression_discipline"), 0.55)
        ),
        "signal_guard": (
            (recovery_state == "low" or warning_load == "high")
            and _core_prediction_active(predictions.get("signal_weighting"), 0.52)
        ),
    }

    why_lines = []
    if actions["nutrition_guard"]:
        why_lines.append("CORE wertet die Ernährung gerade als Limit und hält die Steuerung stabil.")
    if actions["deload_guard"]:
        why_lines.append("CORE reagiert früher auf Warnsignale und nimmt Tempo raus.")
    if actions["interference_guard"]:
        why_lines.append("CORE schützt Kraft und Laufen stärker gegeneinander.")
    if actions["consistency_guard"]:
        why_lines.append("CORE priorisiert gerade Wiederholbarkeit vor maximalem Druck.")
    if actions["rpe_guard"]:
        why_lines.append("CORE will aktuell früher bremsen, wenn Sätze zu nah ans Limit laufen.")
    if actions["progression_push"]:
        why_lines.append("CORE sieht ein gutes Progressionsfenster und blockt unnötige Vorsicht.")
    if actions["signal_guard"]:
        why_lines.append("CORE nimmt Warnsignale ernster als einen einzelnen guten Marker.")

    return {
        "enabled": True,
        "available": True,
        "features": features,
        "summaries": summaries,
        "predictions": predictions,
        "actions": actions,
        "why_lines": why_lines,
    }


def _apply_core_overlay_to_decision(
    decision: dict,
    state_snapshot: dict,
    core_overlay: dict,
    planned_slot: dict | None = None,
    week_layer: dict | None = None,
    is_today: bool = False,
    is_tomorrow: bool = False,
) -> dict:
    if not isinstance(decision, dict) or not core_overlay.get("enabled") or not core_overlay.get("available", True):
        return decision

    features = core_overlay.get("features") or {}
    actions = core_overlay.get("actions") or {}
    week_layer = week_layer if isinstance(week_layer, dict) else {}
    principle_scores = get_core_principle_scores() if callable(get_core_principle_scores) else {}
    used_principles = []

    def _risk(topic: str) -> int:
        item = principle_scores.get(topic) if isinstance(principle_scores, dict) else {}
        try:
            return int((item or {}).get("risk") or 0)
        except Exception:
            return 0

    def _strength(topic: str) -> int:
        item = principle_scores.get(topic) if isinstance(principle_scores, dict) else {}
        try:
            return int((item or {}).get("strength") or 0)
        except Exception:
            return 0

    def _use_principle(topic: str, effect: str, mode: str = "risk") -> None:
        item = principle_scores.get(topic) if isinstance(principle_scores, dict) else {}
        if not isinstance(item, dict):
            return
        used_principles.append(
            {
                "topic": topic,
                "label": str(item.get("label") or topic),
                "strength": int(item.get("strength") or 0),
                "risk": int(item.get("risk") or 0),
                "mode": mode,
                "effect": effect,
            }
        )

    if _risk("rpe_honesty") >= 56:
        actions["rpe_guard"] = True
        _use_principle("rpe_honesty", "RPE wird vorsichtiger gelesen")
    if _risk("logging_quality") >= 56:
        actions["signal_guard"] = True
        _use_principle("logging_quality", "Datenlage wird konservativer bewertet")
    if _risk("nutrition_discipline") >= 56:
        actions["nutrition_guard"] = True
        _use_principle("nutrition_discipline", "Ernährung wird robuster und einfacher gehalten")
    if _risk("regeneration_honesty") >= 56:
        actions["signal_guard"] = True
        _use_principle("regeneration_honesty", "Erholung bekommt früher Vorrang")
    if _risk("run_quality") >= 56:
        actions["interference_guard"] = True
        _use_principle("run_quality", "Qualitätsläufe werden früher abgesichert")
    if _risk("regression_response") >= 56:
        actions["consistency_guard"] = True
        _use_principle("regression_response", "Plateaus werden früher als echter Wechsel behandelt")
    if _strength("plan_first") >= 64:
        actions["plan_anchor"] = True
        _use_principle("plan_first", "CORE bleibt näher am Plan", mode="strength")

    if not any(bool(v) for v in actions.values()):
        return decision

    adjusted = dict(decision)
    reason_codes = list(adjusted.get("reason_codes") or [])
    badges = list(adjusted.get("badges") or [])
    decision_meta = dict(adjusted.get("decision_meta") or {})
    decision_meta["core_overlay"] = {
        "enabled": True,
        "features": features,
        "actions": actions,
        "why_lines": list(core_overlay.get("why_lines") or []),
        "principles": used_principles,
    }
    if "CORE" not in badges:
        badges.append("CORE")

    kind = str(adjusted.get("kind") or "").strip().lower()
    planned_kind = str((planned_slot or {}).get("kind") or "").strip().lower()
    planned_run_kind = str((planned_slot or {}).get("run_kind") or "").strip().lower()
    flags = state_snapshot.get("flags") or {}
    local = flags.get("local_fatigue") or {}
    subjective = state_snapshot.get("subjective") if isinstance(state_snapshot.get("subjective"), dict) else {}
    recovery = state_snapshot.get("recovery") if isinstance(state_snapshot.get("recovery"), dict) else {}
    session_category = _slot_session_category(
        {
            "category": adjusted.get("category") or (planned_slot or {}).get("category"),
            "session_name": adjusted.get("session_name") or (planned_slot or {}).get("session_name"),
            "label": adjusted.get("session_name") or (planned_slot or {}).get("label"),
        }
    )
    matched_local_fatigue = bool(
        (session_category == "legs" and local.get("legs"))
        or (session_category == "push" and local.get("push"))
        or (session_category == "pull" and local.get("pull"))
    )
    systemic_fatigue = bool(flags.get("zns_fatigue") or flags.get("sick") or flags.get("alcohol"))
    severe_guard = bool(actions.get("nutrition_guard") or actions.get("deload_guard") or actions.get("signal_guard"))
    recovery_state = str(features.get("recovery_state") or "missing").strip().lower()
    hrv_ratio = _to_optional_float(recovery.get("hrv_ratio"))
    rhr_ratio = _to_optional_float(recovery.get("rhr_ratio"))
    readiness_state = str(subjective.get("readiness_state") or "missing").strip().lower()
    fatigue_state = str(subjective.get("fatigue_state") or "missing").strip().lower()
    motivation_state = str(subjective.get("motivation_state") or "missing").strip().lower()
    sleep_state = str(subjective.get("sleep_state") or "missing").strip().lower()
    week_type = str(week_layer.get("week_type") or "build").strip().lower()
    strength_factor = _to_optional_float(week_layer.get("strength_factor")) or 1.0
    run_factor = _to_optional_float(week_layer.get("run_factor")) or 1.0

    system_red = bool(
        flags.get("sick")
        or flags.get("alcohol")
        or (hrv_ratio is not None and hrv_ratio <= 0.88)
        or (rhr_ratio is not None and rhr_ratio >= 1.08)
        or recovery_state == "low"
    )
    system_yellow = bool(
        (not system_red)
        and (
            (hrv_ratio is not None and hrv_ratio <= 0.95)
            or (rhr_ratio is not None and rhr_ratio >= 1.03)
            or recovery_state == "ok"
        )
    )
    subjective_red = bool(
        fatigue_state == "high"
        or (sleep_state == "low" and motivation_state == "low")
    )
    subjective_green = bool(
        fatigue_state in {"low", "ok", "missing"}
        and sleep_state != "low"
        and readiness_state in {"ok", "high", "missing"}
    )
    build_push_window = bool(
        week_type in {"build", "overreach"}
        and (
            (kind in {"plan", "rest"} and strength_factor >= 1.05)
            or (kind == "run" and run_factor >= 1.02)
        )
    )
    aggressive_window = bool(
        (not system_red)
        and (not matched_local_fatigue)
        and (not subjective_red)
        and subjective_green
        and build_push_window
    )
    hierarchy_band = "normal"
    if system_red:
        hierarchy_band = "protect"
    elif matched_local_fatigue:
        hierarchy_band = "local_guard"
    elif system_yellow and subjective_red:
        hierarchy_band = "light"
    elif aggressive_window or actions.get("progression_push"):
        hierarchy_band = "push"

    if used_principles:
        why_lines = decision_meta["core_overlay"]["why_lines"]
        for item in used_principles[:3]:
            effect = str(item.get("effect") or "").strip()
            if effect and effect not in why_lines:
                why_lines.append(effect)

    if kind == "plan" and session_category != "legs":
        reason_codes = [code for code in reason_codes if code != "LEGS_FATIGUE"]

    core_execution = {
        "band": hierarchy_band,
        "week_type": week_type,
        "strength_factor": round(float(strength_factor), 3),
        "run_factor": round(float(run_factor), 3),
        "system_red": bool(system_red),
        "system_yellow": bool(system_yellow),
        "matched_local_fatigue": bool(matched_local_fatigue),
        "subjective_red": bool(subjective_red),
        "subjective_green": bool(subjective_green),
        "gym_mode": "heavy" if hierarchy_band == "push" and kind in {"plan", "rest"} else ("light" if hierarchy_band in {"protect", "local_guard", "light"} else "normal"),
        "run_mode": "push" if hierarchy_band == "push" and kind in {"run", "rest"} else ("light" if hierarchy_band in {"protect", "local_guard", "light"} else "normal"),
    }
    decision_meta["core_overlay"]["execution"] = core_execution
    why_lines = decision_meta["core_overlay"]["why_lines"]
    if hierarchy_band == "push":
        push_line = "CORE priorisiert heute die harten Marker und gibt bei guter Lage bewusst Druck frei."
        if push_line not in why_lines:
            why_lines.append(push_line)
    elif hierarchy_band in {"protect", "local_guard", "light"}:
        light_line = "CORE priorisiert heute erst System- und Fatigue-Signale, danach erst Motivation und Wollen."
        if light_line not in why_lines:
            why_lines.append(light_line)

    if kind == "run":
        run_kind = str(adjusted.get("run_kind") or "z2").strip().lower()
        duration = int(adjusted.get("run_duration_min") or (45 if run_kind == "z2" else 30))
        if hierarchy_band in {"protect", "light", "local_guard"} and run_kind == "threshold":
            adjusted["run_kind"] = "z2"
            adjusted["run_duration_min"] = max(20, min(30, duration))
            reason_codes.append("CORE_DOWN_SHIFT_RUN")
        elif hierarchy_band == "protect" and run_kind == "z2":
            adjusted["run_duration_min"] = max(20, min(35, int(round(duration * 0.85))))
            reason_codes.append("CORE_STABLE_RUN")
        elif actions.get("consistency_guard") and run_kind == "threshold" and hierarchy_band != "push":
            adjusted["run_kind"] = "z2"
            adjusted["run_duration_min"] = max(20, min(35, duration))
            reason_codes.append("CORE_REPEATABLE_RUN")
        elif actions.get("consistency_guard") and run_kind == "z2" and hierarchy_band == "normal":
            adjusted["run_duration_min"] = max(30, min(40, int(round(duration / 5.0) * 5)))
            reason_codes.append("CORE_REPEATABLE_RUN")
        elif hierarchy_band == "push":
            if planned_run_kind == "threshold":
                adjusted["run_kind"] = "threshold"
                adjusted["run_duration_min"] = max(25, duration)
            else:
                adjusted["run_duration_min"] = min(60, int(round(duration * 1.1 / 5.0) * 5))
            reason_codes.append("CORE_PUSH_RUN")
        elif actions.get("progression_push") and run_kind == "z2" and not local.get("legs"):
            adjusted["run_duration_min"] = min(60, int(round(duration * 1.1 / 5.0) * 5))
            reason_codes.append("CORE_PROGRESS_WINDOW")

    elif kind == "plan":
        should_light_plan = False
        if hierarchy_band in {"protect", "local_guard", "light"}:
            should_light_plan = True
        elif actions.get("interference_guard") and (session_category == "legs" or systemic_fatigue) and hierarchy_band != "push":
            should_light_plan = True
        elif actions.get("consistency_guard") and (matched_local_fatigue or systemic_fatigue) and hierarchy_band != "push":
            should_light_plan = True

        if should_light_plan:
            adjusted["minimal_gym"] = True
            reason_codes.append("CORE_LIGHT_GYM")
        elif hierarchy_band == "push":
            adjusted["minimal_gym"] = False
            reason_codes = [code for code in reason_codes if code != "CORE_LIGHT_GYM"]
            reason_codes.append("CORE_PUSH_GYM")
        elif actions.get("plan_anchor") and not severe_guard:
            adjusted["minimal_gym"] = False
            reason_codes.append("CORE_PLAN_ANCHOR")
        elif actions.get("progression_push"):
            adjusted["minimal_gym"] = False
            reason_codes.append("CORE_PROGRESS_WINDOW")

    elif kind == "rest":
        if hierarchy_band == "push" and planned_kind == "plan" and not system_red:
            adjusted.update({
                "kind": "plan",
                "session_key": (planned_slot or {}).get("session_key"),
                "session_name": (planned_slot or {}).get("session_name") or (planned_slot or {}).get("label"),
                "minimal_gym": False,
            })
            reason_codes.append("CORE_PUSH_GYM")
        elif hierarchy_band == "push" and planned_kind == "run" and not system_red:
            adjusted.update({
                "kind": "run",
                "run_kind": "threshold" if planned_run_kind == "threshold" else "z2",
                "run_duration_min": 30 if planned_run_kind == "threshold" else 45,
                "minimal_gym": False,
            })
            reason_codes.append("CORE_PUSH_RUN")
        elif actions.get("plan_anchor") and planned_kind == "plan" and not severe_guard and not flags.get("sick"):
            adjusted.update({
                "kind": "plan",
                "session_key": (planned_slot or {}).get("session_key"),
                "session_name": (planned_slot or {}).get("session_name") or (planned_slot or {}).get("label"),
                "minimal_gym": True,
            })
            reason_codes.append("CORE_PLAN_ANCHOR")
        elif actions.get("plan_anchor") and planned_kind == "run" and not severe_guard and not flags.get("sick"):
            adjusted.update({"kind": "run", "run_kind": "z2", "run_duration_min": 25, "minimal_gym": False})
            reason_codes.append("CORE_PLAN_ANCHOR")
        elif actions.get("consistency_guard") and not flags.get("sick") and features.get("recovery_state") in {"ok", "high"}:
            if planned_kind == "run":
                adjusted.update({"kind": "run", "run_kind": "z2", "run_duration_min": 25, "minimal_gym": False})
                reason_codes.append("CORE_REENTRY_RUN")
            elif planned_kind == "plan":
                adjusted.update({
                    "kind": "plan",
                    "session_key": (planned_slot or {}).get("session_key"),
                    "session_name": (planned_slot or {}).get("session_name") or (planned_slot or {}).get("label"),
                    "minimal_gym": True,
                })
                reason_codes.append("CORE_REENTRY_GYM")

    adjusted["reason_codes"] = list(dict.fromkeys(reason_codes))
    adjusted["badges"] = list(dict.fromkeys(badges))
    adjusted["decision_meta"] = decision_meta
    return adjusted


def _core_energy_context(day_iso: str | None, lookback_days: int = 35) -> dict[str, Any]:
    fallback = {
        "available": False,
        "mode": None,
        "daily_status": "neutral",
        "momentum": None,
        "target_kcal": None,
        "daily_delta": None,
        "intraday_pending": False,
    }
    try:
        conn = get_nutrition_db()
        _ensure_nutrition_daily_view(conn)
        settings = _load_nutrition_settings()
        timeline = _load_nutrition_mode_timeline(conn, settings)
        rows = _load_nutrition_series(days=max(21, int(lookback_days)))
        conn.close()
        daily = _build_energy_daily(rows, settings, timeline)
        if not daily:
            return fallback
        momentum = _compute_energy_momentum(daily)
        date_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
        entry = next((row for row in daily if row.get("date_iso") == date_key), None)
        if entry is None:
            entry = daily[-1]
        intraday_pending = False
        today_iso = datetime.now(ZoneInfo("Europe/Berlin")).date().isoformat()
        now_hour = datetime.now(ZoneInfo("Europe/Berlin")).hour
        # Intraday guard: early-day intake must not bias CORE as "nutrition is weak".
        # Until evening, ignore today's absolute kcal position and use momentum without today's partial day.
        if date_key == today_iso and now_hour < 20:
            intraday_pending = True
            hist_daily = [row for row in daily if str(row.get("date_iso") or "") < today_iso]
            if hist_daily:
                hist_momentum = _compute_energy_momentum(hist_daily)
                if isinstance(hist_momentum, dict):
                    momentum = hist_momentum
        return {
            "available": True,
            "mode": entry.get("mode"),
            "daily_status": ("neutral" if intraday_pending else (entry.get("daily_status") or "neutral")),
            "momentum": momentum.get("momentum") if isinstance(momentum, dict) else None,
            "target_kcal": entry.get("daily_target_kcal"),
            "daily_delta": (None if intraday_pending else entry.get("daily_delta")),
            "intraday_pending": intraday_pending,
        }
    except Exception:
        try:
            conn.close()
        except Exception:
            pass
        return fallback


def _core_memory_learning_map(day_iso: str | None = None) -> dict[str, dict[str, Any]]:
    try:
        payload = _dashboard_autopilot_memory_payload(day_iso=day_iso, lookback_days=84)
    except Exception:
        payload = {}
    learnings = payload.get("learnings") if isinstance(payload, dict) else []
    out: dict[str, dict[str, Any]] = {}
    for item in learnings or []:
        if not isinstance(item, dict):
            continue
        key = str(item.get("id") or "").strip()
        if key:
            out[key] = item
    return out


def _core_exercise_regions(name: str, session_category: str | None = None) -> set[str]:
    nm = _norm_text(name)
    if not nm:
        return {str(session_category or "general")}
    regions: set[str] = set()
    mapping = {
        "chest": ["bank", "bench", "incline", "chest", "fly", "brust"],
        "shoulders": ["ohp", "overhead", "shoulder", "schulter", "seitheben", "lateral"],
        "triceps": ["pushdown", "trizeps", "katana", "dip", "extension"],
        "back": ["row", "rudern", "lat", "pull", "pulldown", "pullover", "rear delt", "face pull"],
        "biceps": ["curl", "bizeps", "hammer"],
        "quads": ["squat", "hack", "beinstrecker", "leg press", "lunge", "split squat"],
        "hamstrings": ["rdl", "deadlift", "kreuzheben", "beinbeuger", "leg curl", "nordic"],
        "glutes": ["hip thrust", "glute", "split squat", "rdl", "squat"],
        "calves": ["waden", "calf"],
        "core": ["crunch", "plank", "hanging knee", "cable crunch", "core"],
    }
    for region, keywords in mapping.items():
        if any(word in nm for word in keywords):
            regions.add(region)
    if not regions:
        if session_category == "push":
            regions.update({"chest", "shoulders", "triceps"})
        elif session_category == "pull":
            regions.update({"back", "biceps"})
        elif session_category == "legs":
            regions.update({"quads", "hamstrings", "glutes"})
        else:
            regions.add("general")
    return regions


def _core_item_local_penalty(
    item: dict,
    session_category: str,
    state_snapshot: dict,
    pain_keys: set[str] | None = None,
) -> dict[str, Any]:
    planned = item.get("planned") if isinstance(item.get("planned"), dict) else {}
    title = str(item.get("title") or "")
    regions = _core_exercise_regions(title, session_category)
    flags = state_snapshot.get("flags") if isinstance(state_snapshot.get("flags"), dict) else {}
    local = flags.get("local_fatigue") if isinstance(flags.get("local_fatigue"), dict) else {}
    pain_keys = pain_keys if isinstance(pain_keys, set) else set()
    penalty = 0.0
    notes: list[str] = []
    if session_category == "legs" and local.get("legs"):
        penalty += 1.4
        notes.append("lokale Beinmüdigkeit")
    if session_category == "push" and local.get("push"):
        penalty += 1.2
        notes.append("lokale Push-Müdigkeit")
    if session_category == "pull" and local.get("pull"):
        penalty += 1.2
        notes.append("lokale Pull-Müdigkeit")
    title_key = _replacement_key(title)
    if title_key and any(title_key in _replacement_key(key) or _replacement_key(key) in title_key for key in pain_keys):
        penalty += 1.8
        notes.append("Pain-Flag auf Bewegung")
    if "shoulders" in regions and local.get("push"):
        penalty += 0.3
    if ("quads" in regions or "hamstrings" in regions or "glutes" in regions) and local.get("legs"):
        penalty += 0.5
    if planned.get("device") and str(planned.get("device")).strip().lower() in {"barbell", "langhantel"} and penalty > 0:
        penalty += 0.2
    return {
        "penalty": round(penalty, 2),
        "regions": sorted(regions),
        "notes": notes,
    }


def _core_horizon_context(
    selected_day_id: str,
    week_days: list[dict],
    session_category: str,
    state_snapshot: dict,
    learning_map: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    entries = sorted(
        [d for d in (week_days or []) if d.get("day_id")],
        key=lambda row: str(row.get("day_id") or ""),
    )
    idx = next((i for i, row in enumerate(entries) if row.get("day_id") == selected_day_id), None)
    next_days = entries[idx + 1: idx + 3] if idx is not None else []
    prev_hard = int(((state_snapshot.get("gym") or {}).get("hi_exposures_3d") or 0))
    next_run_quality = any(str(row.get("final_label") or row.get("planned_label") or "").lower().find("threshold") >= 0 for row in next_days)
    next_lower = any("lower" in str(row.get("final_label") or row.get("planned_label") or "").lower() for row in next_days)
    next_upper = any(
        any(key in str(row.get("final_label") or row.get("planned_label") or "").lower() for key in ["push", "pull", "upper"])
        for row in next_days
    )
    risk = 0.0
    notes: list[str] = []
    if session_category == "legs" and next_run_quality:
        risk += 1.3
        notes.append("Qualitätslauf im 48h-Horizont")
        if "lower_to_run_interference" in learning_map:
            risk += 0.8
            notes.append("Memory: lower_to_run_interference")
    if session_category in {"push", "pull"} and next_upper:
        risk += 0.3
    if prev_hard >= 2:
        risk += 1.0
        notes.append("zuletzt schon hohe Härte")
        if "stacked_hard_days" in learning_map:
            risk += 0.7
            notes.append("Memory: stacked_hard_days")
    if session_category == "run" and next_lower:
        risk += 0.4
    return {
        "risk": round(risk, 2),
        "prev_hard_days": prev_hard,
        "next_days": [
            {
                "day_id": row.get("day_id"),
                "label": row.get("final_label") or row.get("planned_label"),
                "kind": row.get("kind"),
            }
            for row in next_days
        ],
        "notes": notes,
    }


def _build_core_execution_profile(
    *,
    selected_day_id: str,
    decision: dict,
    state_snapshot: dict,
    core_overlay: dict,
    week_layer: dict,
    planned_slot: dict | None,
    week_days: list[dict],
    items: list[dict] | None = None,
    pain_keys: set[str] | None = None,
) -> dict[str, Any]:
    items = items if isinstance(items, list) else []
    core_execution = {}
    if isinstance(decision.get("decision_meta"), dict):
        overlay = decision["decision_meta"].get("core_overlay")
        if isinstance(overlay, dict):
            core_execution = overlay.get("execution") if isinstance(overlay.get("execution"), dict) else {}

    kind = str(decision.get("kind") or "").strip().lower()
    features = core_overlay.get("features") if isinstance(core_overlay, dict) else {}
    actions = core_overlay.get("actions") if isinstance(core_overlay, dict) else {}
    session_category = _slot_session_category(
        {
            "category": decision.get("category") or (planned_slot or {}).get("category"),
            "session_name": decision.get("session_name") or (planned_slot or {}).get("session_name"),
            "label": decision.get("session_name") or (planned_slot or {}).get("label"),
        }
    )
    learning_map = _core_memory_learning_map(selected_day_id)
    energy = _core_energy_context(selected_day_id)
    horizon = _core_horizon_context(selected_day_id, week_days, session_category, state_snapshot, learning_map)
    plan_ctx = _autopilot_plan_context_for_day(selected_day_id, planned_slot=planned_slot)

    week_type = str(week_layer.get("week_type") or "build").strip().lower()
    strength_factor = _to_optional_float(week_layer.get("strength_factor")) or 1.0
    run_factor = _to_optional_float(week_layer.get("run_factor")) or 1.0
    base_rpe_cap = _to_optional_float(week_layer.get("rpe_cap"))
    strength_trend = str((features or {}).get("strength_trend") or "missing").strip().lower()
    nutrition_state = str((features or {}).get("nutrition_adherence") or "missing").strip().lower()
    readiness_state = str(((state_snapshot.get("subjective") or {}).get("readiness_state")) or "missing").strip().lower()
    sleep_state = str(((state_snapshot.get("subjective") or {}).get("sleep_state")) or "missing").strip().lower()
    fatigue_state = str(((state_snapshot.get("subjective") or {}).get("fatigue_state")) or "missing").strip().lower()
    execution_band = str((core_execution or {}).get("band") or "normal").strip().lower()

    score = 0.0
    reasons: list[str] = []
    if execution_band == "push":
        score += 1.8
        reasons.append("CORE-Band heavy")
    elif execution_band in {"light", "local_guard", "protect"}:
        score -= 1.8
        reasons.append("CORE-Band vorsichtig")

    if strength_trend == "up":
        score += 0.8
        reasons.append("Strength-Trend aufwärts")
    elif strength_trend == "flat":
        score += 0.3
    elif strength_trend == "down":
        score -= 0.8
        reasons.append("Strength-Trend rückläufig")

    if energy.get("available"):
        momentum = _to_optional_float(energy.get("momentum"))
        if momentum is not None and momentum <= -220:
            score -= 0.9
            reasons.append("Kalorien-Momentum negativ")
        elif momentum is not None and momentum >= 120:
            score += 0.5
            reasons.append("Kalorien-Momentum positiv")
        if energy.get("daily_status") == "red":
            score -= 0.7
            reasons.append("heute Energie außerhalb Band")
        elif energy.get("daily_status") == "green":
            score += 0.3

    if nutrition_state == "low":
        score -= 0.8
    if readiness_state == "high":
        score += 0.4
    if sleep_state == "low":
        score -= 0.6
        if "sleep_to_rpe_drift" in learning_map:
            score -= 0.4
            reasons.append("Memory: sleep_to_rpe_drift")
    if fatigue_state == "high":
        score -= 0.9
    if week_type == "build" and strength_factor >= 1.05:
        score += 0.5
    if week_type == "overreach" and strength_factor >= 1.0:
        score += 0.3
    if week_type == "deload":
        score -= 1.6
        reasons.append("Deload-Woche")

    days_to_deload = _clean_int(plan_ctx.get("days_to_deload"))
    if days_to_deload is not None and days_to_deload <= 2 and week_type != "deload":
        score -= 0.2
    if days_to_deload is not None and days_to_deload > 2 and week_type in {"build", "overreach"} and execution_band == "push":
        score += 0.2

    score -= float(horizon.get("risk") or 0.0) * 0.45
    if horizon.get("notes"):
        reasons.extend(list(horizon.get("notes") or [])[:2])

    gym_mode = "heavy" if _core_canonical_gym_mode((core_execution or {}).get("gym_mode") or "", default="") == "HEAVY" else "normal"
    run_mode = "push" if str((core_execution or {}).get("run_mode") or "").strip().lower() == "push" else "normal"
    if kind in {"plan", "rest"}:
        if score <= -0.7:
            gym_mode = "light"
        elif score < 0.8 and gym_mode == "heavy":
            gym_mode = "normal"
        elif score >= 1.4:
            gym_mode = "heavy"
    if kind in {"run", "rest"}:
        if score <= -0.7:
            run_mode = "light"
        elif score < 0.8 and run_mode == "push":
            run_mode = "normal"
        elif score >= 1.2 and run_factor >= 1.0:
            run_mode = "push"

    volume_factor = 1.0
    weight_factor = 1.0
    rpe_shift = 0.0
    set_bonus_compounds = 0
    if gym_mode == "heavy":
        volume_factor = 1.08 if session_category != "legs" else 1.04
        weight_factor = 1.025 if strength_trend != "down" else 1.0
        rpe_shift = 0.4
        set_bonus_compounds = 1 if horizon.get("risk", 0) < 1.0 else 0
    elif gym_mode == "light":
        volume_factor = 0.82
        weight_factor = 0.95
        rpe_shift = -0.8
        set_bonus_compounds = -1

    if week_type == "deload":
        volume_factor = min(volume_factor, 0.75)
        weight_factor = min(weight_factor, 0.93)
        rpe_shift = min(rpe_shift, -1.0)
        set_bonus_compounds = min(set_bonus_compounds, -1)

    if kind == "run":
        volume_factor = 1.1 if run_mode == "push" else (0.85 if run_mode == "light" else 1.0)

    item_profiles = []
    for item in items:
        local_info = _core_item_local_penalty(item, session_category, state_snapshot, pain_keys)
        penalty = float(local_info.get("penalty") or 0.0)
        item_shift = rpe_shift - min(1.0, penalty * 0.5)
        item_weight_factor = max(0.88, weight_factor - min(0.08, penalty * 0.03))
        item_set_delta = set_bonus_compounds
        title = str(item.get("title") or "")
        is_compound = any(key in _norm_text(title) for key in ["squat", "deadlift", "bank", "bench", "ohp", "press", "row", "rudern", "latzug", "pull"])
        if not is_compound:
            item_set_delta = min(0, item_set_delta)
        if penalty >= 1.4:
            item_set_delta = min(item_set_delta, -1)
        item_profiles.append(
            {
                "title": title,
                "regions": local_info.get("regions") or [],
                "notes": local_info.get("notes") or [],
                "rpe_shift": round(item_shift, 2),
                "weight_factor": round(item_weight_factor, 3),
                "set_delta": int(item_set_delta),
                "is_compound": bool(is_compound),
                "replacement_candidates": _replacement_candidates(title)[:3] if penalty >= 1.8 else [],
            }
        )

    return {
        "score": round(score, 2),
        "session_category": session_category,
        "gym_mode": gym_mode,
        "run_mode": run_mode,
        "volume_factor": round(volume_factor, 3),
        "weight_factor": round(weight_factor, 3),
        "rpe_shift": round(rpe_shift, 2),
        "rpe_cap": base_rpe_cap,
        "set_bonus_compounds": int(set_bonus_compounds),
        "energy": energy,
        "horizon": horizon,
        "learning_keys": sorted(learning_map.keys()),
        "days_to_deload": days_to_deload,
        "item_profiles": item_profiles,
        "reasons": list(dict.fromkeys([r for r in reasons if r]))[:6],
        "actions": actions if isinstance(actions, dict) else {},
    }


def _apply_core_execution_profile_to_items(items: list[dict], profile: dict | None) -> list[dict]:
    if not isinstance(profile, dict) or not isinstance(items, list):
        return items

    def _round_sets(raw_sets: Any, delta: int, factor: float) -> int:
        base = _clean_int(raw_sets) or 0
        if base <= 0:
            return base
        scaled = int(round(base * factor)) + int(delta)
        return max(1, scaled)

    def _safe_num(v: Any) -> float | None:
        try:
            return float(v)
        except Exception:
            return None

    item_profiles = {str(item.get("title") or ""): item for item in (profile.get("item_profiles") or []) if isinstance(item, dict)}
    for item in items:
        title = str(item.get("title") or "")
        per_item = item_profiles.get(title, {})
        planned = item.get("planned") if isinstance(item.get("planned"), dict) else {}
        structured = item.get("structured") if isinstance(item.get("structured"), dict) else {}
        weight_factor = float(per_item.get("weight_factor") or profile.get("weight_factor") or 1.0)
        rpe_shift = float(per_item.get("rpe_shift") or profile.get("rpe_shift") or 0.0)
        set_delta = int(per_item.get("set_delta") or 0)
        volume_factor = float(profile.get("volume_factor") or 1.0)

        old_sets = _clean_int(planned.get("sets"))
        if old_sets:
            planned["sets"] = _round_sets(old_sets, set_delta, volume_factor)

        rpe_values = planned.get("rpe_values") if isinstance(planned.get("rpe_values"), list) else []
        if rpe_values:
            shifted = []
            for raw in rpe_values:
                val = _safe_num(raw)
                if val is None:
                    continue
                shifted.append(max(5.0, min(10.0, round(val + rpe_shift, 1))))
            if shifted:
                planned["rpe_values"] = shifted
                planned["rpe_min"] = min(shifted)
                planned["rpe_max"] = max(shifted)
                planned["display_rpe"] = _format_rpe_targets(shifted) or _format_rpe_range(planned["rpe_min"], planned["rpe_max"])
        else:
            for key in ("rpe_min", "rpe_max"):
                val = _safe_num(planned.get(key))
                if val is not None:
                    planned[key] = max(5.0, min(10.0, round(val + rpe_shift, 1)))
            planned["display_rpe"] = _format_rpe_targets(planned.get("rpe_values")) or _format_rpe_range(
                _clean_float(planned.get("rpe_min")),
                _clean_float(planned.get("rpe_max")),
            )

        for key in ("weight_suggestion",):
            val = _safe_num(planned.get(key))
            if val is not None:
                device_type = _detect_device_type(title, str(planned.get("device") or ""))
                planned[key] = _round_to_step(max(0.0, val * weight_factor), _step_for_device_type(device_type))

        ww = _safe_num(structured.get("working_weight"))
        if ww is not None:
            device_type = _detect_device_type(title, str(planned.get("device") or ""))
            structured["working_weight"] = _round_to_step(max(0.0, ww * weight_factor), _step_for_device_type(device_type))
        new_weights = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
        if new_weights:
            device_type = _detect_device_type(title, str(planned.get("device") or ""))
            step = _step_for_device_type(device_type)
            structured["new_weights"] = [
                _round_to_step(max(0.0, float(v) * weight_factor), step) if _safe_num(v) is not None else v
                for v in new_weights
            ]

        core_note_parts = []
        if per_item.get("notes"):
            core_note_parts.append(", ".join(per_item.get("notes") or []))
        if per_item.get("replacement_candidates"):
            core_note_parts.append("Alt: " + ", ".join(per_item.get("replacement_candidates") or []))
        if core_note_parts:
            item["core_note"] = " | ".join(core_note_parts)
        item["planned"] = planned
        if structured:
            item["structured"] = structured
    return items


def _apply_core_execution_profile_to_run_payload(payload: dict, profile: dict | None) -> dict:
    if not isinstance(payload, dict) or not isinstance(profile, dict):
        return payload
    items = payload.get("items") if isinstance(payload.get("items"), list) else []
    if not items:
        return payload
    run_mode = str(profile.get("run_mode") or "normal").strip().lower()
    factor = float(profile.get("volume_factor") or 1.0)
    for item in items:
        planned = item.get("planned") if isinstance(item.get("planned"), dict) else {}
        run_block = planned.get("run") if isinstance(planned.get("run"), dict) else {}
        duration = _clean_int(run_block.get("duration_min"))
        if duration:
            run_block["duration_min"] = max(20, min(70, int(round((duration * factor) / 5.0) * 5)))
        if run_mode == "light":
            item["core_note"] = "CORE hält den Lauf heute repeatable und schützt den 48h-Horizont."
        elif run_mode == "push":
            item["core_note"] = "CORE sieht heute ein sauberes Qualitätsfenster für den Lauf."
        planned["run"] = run_block
        item["planned"] = planned
    return payload


TELEGRAM_PUSH_MUTE_FOREVER_TS = 253402300799  # 9999-12-31T23:59:59Z
TELEGRAM_MEAL_PUSH_MIN_INDEX = 1
TELEGRAM_MEAL_PUSH_MAX_INDEX = 8


def _parse_setting_bool(raw: str | None, default: bool = True) -> bool:
    if raw is None:
        return default
    text = str(raw).strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    return default


def _telegram_meal_push_key(meal_index: int) -> str:
    return f"telegram_push_meal_{int(meal_index)}_enabled"




def _set_telegram_meal_push_enabled(meal_index: int, enabled: bool) -> None:
    idx = int(meal_index)
    if idx < TELEGRAM_MEAL_PUSH_MIN_INDEX or idx > TELEGRAM_MEAL_PUSH_MAX_INDEX:
        return
    conn = get_training_db()
    try:
        _set_setting(conn, _telegram_meal_push_key(idx), "1" if enabled else "0")
    finally:
        conn.close()


def _get_telegram_meal_push_settings() -> dict[str, int]:
    out: dict[str, int] = {}
    conn = get_training_db()
    try:
        for idx in range(TELEGRAM_MEAL_PUSH_MIN_INDEX, TELEGRAM_MEAL_PUSH_MAX_INDEX + 1):
            raw = _get_setting(conn, _telegram_meal_push_key(idx), "1")
            out[str(idx)] = 1 if _parse_setting_bool(raw, default=True) else 0
    finally:
        conn.close()
    return out


def _get_telegram_push_until_ts(key: str) -> int | None:
    conn = get_training_db()
    try:
        raw = _get_setting(conn, key, None)
    finally:
        conn.close()
    if raw in (None, ""):
        return None
    try:
        value = int(str(raw).strip())
    except Exception:
        return None
    return value if value > 0 else None


def _set_telegram_push_until_ts(key: str, until_ts: int | None) -> None:
    conn = get_training_db()
    try:
        if until_ts is None:
            _set_setting(conn, key, None)
        else:
            _set_setting(conn, key, str(int(until_ts)))
    finally:
        conn.close()


def _get_telegram_pause_kind() -> str:
    conn = get_training_db()
    try:
        raw = _get_setting(conn, "telegram_push_last_pause_kind", "")
    finally:
        conn.close()
    return str(raw or "").strip().lower()


def _set_telegram_pause_kind(kind: str | None) -> None:
    conn = get_training_db()
    try:
        value = (kind or "").strip().lower() or None
        _set_setting(conn, "telegram_push_last_pause_kind", value)
    finally:
        conn.close()


def _effective_telegram_push_state(now_ts: int | None = None) -> dict:
    ts = int(now_ts if now_ts is not None else time())
    muted_until = _get_telegram_push_until_ts("telegram_push_muted_until_ts")
    unmuted_until = _get_telegram_push_until_ts("telegram_push_unmuted_until_ts")
    muted_active = bool(muted_until and muted_until >= ts)
    unmuted_active = bool(unmuted_until and unmuted_until >= ts)
    effective_muted = muted_active and not unmuted_active
    return {
        "muted": effective_muted,
        "active": not effective_muted,
        "muted_until_ts": muted_until if muted_active else None,
        "unmuted_until_ts": unmuted_until if unmuted_active else None,
        "muted_forever": bool(muted_active and muted_until and muted_until >= TELEGRAM_PUSH_MUTE_FOREVER_TS),
        "unmuted_forever": bool(unmuted_active and unmuted_until and unmuted_until >= TELEGRAM_PUSH_MUTE_FOREVER_TS),
    }


def _send_telegram_system_notice(message: str) -> bool:
    try:
        return bool(send_domain_message("system", message, respect_push_settings=False).get("ok"))
    except Exception:
        app.logger.exception("telegram system notice failed")
        return False


def _apply_telegram_push_action(action: str) -> None:
    prev = _effective_telegram_push_state()
    prev_pause_kind = _get_telegram_pause_kind()
    now_berlin = datetime.now(ZoneInfo("Europe/Berlin"))
    end_of_today_ts = int(now_berlin.replace(hour=23, minute=59, second=59, microsecond=0).timestamp())
    seven_days_ts = int((now_berlin + timedelta(days=7)).timestamp())
    action = (action or "").strip().lower()
    if action == "mute_today":
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", end_of_today_ts)
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", None)
        _set_telegram_pause_kind("today")
    elif action == "mute_7d":
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", seven_days_ts)
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", None)
        _set_telegram_pause_kind("7d")
        _send_telegram_system_notice("Mealplan-Benachrichtigungen sind ab jetzt pausiert (7 Tage).")
    elif action == "mute_forever":
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", TELEGRAM_PUSH_MUTE_FOREVER_TS)
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", None)
        _set_telegram_pause_kind("forever")
        _send_telegram_system_notice("Mealplan-Benachrichtigungen sind ab jetzt pausiert (dauerhaft).")
    elif action == "unmute_today":
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", end_of_today_ts)
    elif action == "unmute_7d":
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", seven_days_ts)
    elif action == "unmute_forever":
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", TELEGRAM_PUSH_MUTE_FOREVER_TS)
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", None)
        if prev.get("muted") and prev_pause_kind in {"7d", "forever"}:
            _send_telegram_system_notice("Mealplan-Benachrichtigungen sind ab jetzt wieder aktiv.")
        _set_telegram_pause_kind(None)
    elif action in {"unmute", "on"}:
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", None)
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", None)
        if prev.get("muted") and prev_pause_kind in {"7d", "forever"}:
            _send_telegram_system_notice("Mealplan-Benachrichtigungen sind ab jetzt wieder aktiv.")
        _set_telegram_pause_kind(None)
    elif action in {"mute", "off"}:
        _set_telegram_push_until_ts("telegram_push_muted_until_ts", TELEGRAM_PUSH_MUTE_FOREVER_TS)
        _set_telegram_push_until_ts("telegram_push_unmuted_until_ts", None)
        _set_telegram_pause_kind("forever")
        _send_telegram_system_notice("Mealplan-Benachrichtigungen sind ab jetzt pausiert (dauerhaft).")


def _settings_payload() -> dict:
    tg = _effective_telegram_push_state()
    return {
        "autopilot_enabled": 1 if _get_core_mode_enabled() else 0,
        "core_mode_enabled": 1 if _get_core_mode_enabled() else 0,
        "autopilot_base_enabled": 1,
        "telegram_push_muted": 1 if tg["muted"] else 0,
        "telegram_push_active": 1 if tg["active"] else 0,
        "telegram_push_muted_until_ts": tg["muted_until_ts"],
        "telegram_push_unmuted_until_ts": tg["unmuted_until_ts"],
        "telegram_push_muted_forever": tg["muted_forever"],
        "telegram_push_unmuted_forever": tg["unmuted_forever"],
        "telegram_meal_push_enabled": _get_telegram_meal_push_settings(),
    }


def _get_autopilot_rpe_hardcap() -> float:
    conn = get_training_db()
    try:
        raw = _get_setting(conn, "rpe_hardcap", "9.0")
    finally:
        conn.close()
    try:
        return float(raw)
    except Exception:
        return 9.0




def _get_run_zones() -> dict | None:
    conn = get_training_db()
    try:
        z2_min = _get_setting(conn, "run_zone_z2_min", None)
        z2_max = _get_setting(conn, "run_zone_z2_max", None)
        thr_min = _get_setting(conn, "run_zone_thr_min", None)
        thr_max = _get_setting(conn, "run_zone_thr_max", None)
    finally:
        conn.close()
    try:
        z2_min_v = int(float(z2_min)) if z2_min is not None else None
        z2_max_v = int(float(z2_max)) if z2_max is not None else None
        thr_min_v = int(float(thr_min)) if thr_min is not None else None
        thr_max_v = int(float(thr_max)) if thr_max is not None else None
    except Exception:
        return None
    if z2_min_v is None or z2_max_v is None:
        return None
    if thr_min_v is None or thr_max_v is None:
        return None
    return {
        "z2": [z2_min_v, z2_max_v],
        "threshold": [thr_min_v, thr_max_v],
    }


def _load_hrv_daily_summary(days: int = 60):
    try:
        conn = get_hrv_db()
    except Exception:
        return []
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT
                substr(COALESCE(date_utc, ts_measurement), 1, 10) AS day,
                AVG(rmssd) AS rmssd_avg,
                AVG(hr) AS hr_avg,
                AVG(signal_quality) AS signal_quality
            FROM hrv_measurements
            WHERE rmssd IS NOT NULL
              AND substr(COALESCE(date_utc, ts_measurement), 1, 10) >= date('now', ?)
            GROUP BY day
            ORDER BY day DESC
            """,
            (f"-{int(days)} days",),
        )
        rows = cur.fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()
    out = []
    for row in rows:
        if not row["day"]:
            continue
        out.append({
            "day": row["day"],
            "rmssd_avg": row["rmssd_avg"],
            "hr_avg": row["hr_avg"],
            "signal_quality": row["signal_quality"],
        })
    return out


def _load_today_hrv() -> tuple[float | None, float | None]:
    try:
        conn = get_hrv_db()
    except Exception:
        return None, None
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        rows = cur.execute(
            """
            SELECT
                rmssd,
                hr,
                signal_quality,
                COALESCE(date_utc, ts_measurement) AS ts
            FROM hrv_measurements
            WHERE substr(COALESCE(date_utc, ts_measurement), 1, 10) = date('now')
            ORDER BY COALESCE(signal_quality, 0) DESC, ts ASC
            LIMIT 1
            """
        ).fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()
    if not rows:
        return None, None
    row = rows[0]
    rmssd = _to_optional_float(row["rmssd"] if "rmssd" in row.keys() else None)
    rhr = _to_optional_float(row["hr"] if "hr" in row.keys() else None)
    return rmssd, rhr




def _compute_recovery_snapshot(days: int = 28) -> dict:
    try:
        conn = get_hrv_db()
    except Exception:
        return {
            "rmssd_7d": None,
            "rmssd_28d": None,
            "rhr_7d": None,
            "rhr_28d": None,
            "recovery_today_missing": True,
            "recovery_history_available": False,
            "recovery_data_missing": True,
        }

    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        rows = cur.execute(
            """
            SELECT
                substr(COALESCE(date_utc, ts_measurement), 1, 10) AS day,
                rmssd,
                hr
            FROM hrv_measurements
            WHERE substr(COALESCE(date_utc, ts_measurement), 1, 10) >= date('now', ?)
            ORDER BY day DESC
            """,
            (f"-{int(days)} days",),
        ).fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()

    daily = {}
    for row in rows:
        day = row["day"] if "day" in row.keys() else None
        if not day:
            continue
        rmssd = _to_optional_float(row["rmssd"] if "rmssd" in row.keys() else None)
        rhr = _to_optional_float(row["hr"] if "hr" in row.keys() else None)
        if day not in daily:
            daily[day] = {"rmssd": [], "rhr": []}
        if rmssd is not None:
            daily[day]["rmssd"].append(rmssd)
        if rhr is not None:
            daily[day]["rhr"].append(rhr)

    def avg_for_window(days_back: int, min_days: int):
        today = date.today()
        cutoff = today - timedelta(days=days_back - 1)
        vals_rmssd = []
        vals_rhr = []
        for d_iso, vals in daily.items():
            try:
                d = date.fromisoformat(d_iso)
            except Exception:
                continue
            if d < cutoff:
                continue
            if vals["rmssd"]:
                vals_rmssd.append(sum(vals["rmssd"]) / len(vals["rmssd"]))
            if vals["rhr"]:
                vals_rhr.append(sum(vals["rhr"]) / len(vals["rhr"]))
        if len(vals_rmssd) < min_days:
            rmssd_avg = None
        else:
            rmssd_avg = sum(vals_rmssd) / len(vals_rmssd)
        if len(vals_rhr) < min_days:
            rhr_avg = None
        else:
            rhr_avg = sum(vals_rhr) / len(vals_rhr)
        return rmssd_avg, rhr_avg

    rmssd_7d, rhr_7d = avg_for_window(7, 4)
    if rmssd_7d is None or rhr_7d is None:
        fallback_rmssd, fallback_rhr = avg_for_window(14, 4)
        rmssd_7d = rmssd_7d if rmssd_7d is not None else fallback_rmssd
        rhr_7d = rhr_7d if rhr_7d is not None else fallback_rhr

    rmssd_28d, rhr_28d = avg_for_window(28, 8)

    rmssd_today, rhr_today = _load_today_hrv()
    recovery_today_missing = rmssd_today is None or rhr_today is None
    recovery_history_available = ((rmssd_7d is not None and rmssd_28d is not None) or (rhr_7d is not None and rhr_28d is not None))
    recovery_data_missing = bool(recovery_today_missing and not recovery_history_available)

    return {
        "rmssd_today": rmssd_today,
        "rhr_today": rhr_today,
        "rmssd_7d": rmssd_7d,
        "rmssd_28d": rmssd_28d,
        "rhr_7d": rhr_7d,
        "rhr_28d": rhr_28d,
        "recovery_today_missing": recovery_today_missing,
        "recovery_history_available": recovery_history_available,
        "recovery_data_missing": recovery_data_missing,
    }


def _hrv_signal_quality_low_days(hrv_rows: list[dict], threshold: float = 2.0, max_days: int = 3) -> int:
    if not hrv_rows:
        return 0
    recent = []
    for row in hrv_rows:
        if len(recent) >= max_days:
            break
        recent.append(row)
    low = 0
    for row in recent:
        sq = _to_optional_float(row.get("signal_quality"))
        if sq is None:
            continue
        if sq <= threshold:
            low += 1
    return low


def _load_hrv_flags(days: int = 7) -> dict:
    try:
        conn = get_hrv_db()
    except Exception:
        return {"sickness": False, "alcohol": False}
    try:
        cur = conn.cursor()
        cols = [row["name"] for row in cur.execute("PRAGMA table_info(hrv_measurements);").fetchall()]
        has_sickness_bool = "sickness_bool" in cols
        has_alcohol_bool = "alcohol_bool" in cols
        has_alcohol_text = "alcohol" in cols
        has_sickness_text = "sickness" in cols

        sickness_expr = "sickness_bool" if has_sickness_bool else "0 AS sickness_bool"
        alcohol_expr = "alcohol_bool" if has_alcohol_bool else "0 AS alcohol_bool"
        alcohol_text_expr = "alcohol" if has_alcohol_text else "NULL AS alcohol"
        sickness_text_expr = "sickness" if has_sickness_text else "NULL AS sickness"

        rows = cur.execute(
            f"""
            SELECT
                substr(COALESCE(date_utc, ts_measurement), 1, 10) AS day,
                COALESCE(ts_measurement, date_utc) AS ts_ref,
                {sickness_expr},
                {alcohol_expr},
                {alcohol_text_expr},
                {sickness_text_expr}
            FROM hrv_measurements
            WHERE substr(COALESCE(date_utc, ts_measurement), 1, 10) >= date('now', ?)
            """,
            (f"-{int(days)} days",),
        ).fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()

    sickness_any = False
    latest_sickness_ts: datetime | None = None
    alcohol = False
    def _to_text(val):
        if val is None:
            return ""
        if isinstance(val, (int, float)):
            return str(int(val))
        return str(val)
    for row in rows:
        sickness_bool = row["sickness_bool"] if "sickness_bool" in row.keys() else 0
        alcohol_bool = row["alcohol_bool"] if "alcohol_bool" in row.keys() else 0
        sickness_val = row["sickness"] if "sickness" in row.keys() else None
        alcohol_val = row["alcohol"] if "alcohol" in row.keys() else None
        if sickness_bool in (1, True):
            sickness_any = True
        sickness_txt = _to_text(sickness_val).strip().lower()
        if sickness_txt and sickness_txt not in {"no", "0", "false"}:
            sickness_any = True
        if sickness_bool in (1, True) or (sickness_txt and sickness_txt not in {"no", "0", "false"}):
            ts_txt = _to_text(row["ts_ref"] if "ts_ref" in row.keys() else None).strip()
            if ts_txt:
                if ts_txt.endswith("Z"):
                    ts_txt = ts_txt[:-1] + "+00:00"
                try:
                    ts_val = datetime.fromisoformat(ts_txt)
                except Exception:
                    ts_val = None
                if ts_val is not None and (latest_sickness_ts is None or ts_val > latest_sickness_ts):
                    latest_sickness_ts = ts_val
        if alcohol_bool in (1, True):
            alcohol = True
        alcohol_txt = _to_text(alcohol_val).strip().lower()
        if alcohol_txt and alcohol_txt not in {"no", "0", "false"}:
            alcohol = True
    sickness_active = False
    if sickness_any and latest_sickness_ts is not None:
        now_ref = datetime.now(latest_sickness_ts.tzinfo) if latest_sickness_ts.tzinfo else datetime.now()
        hours_since = (now_ref - latest_sickness_ts).total_seconds() / 3600.0
        sickness_active = 0.0 <= hours_since <= 24.0
    # If sickness is marked but no valid timestamp exists, do not keep it active forever.
    return {"sickness": bool(sickness_active), "alcohol": alcohol}


def _load_hrv_subjective_snapshot(lookback_days: int = 35) -> dict:
    fallback = {
        "motivation_today": None,
        "motivation_baseline": None,
        "motivation_state": "missing",
        "sleep_today": None,
        "sleep_baseline": None,
        "sleep_state": "missing",
        "fatigue_today": None,
        "fatigue_baseline": None,
        "fatigue_state": "missing",
        "readiness_score": None,
        "readiness_baseline": None,
        "readiness_state": "missing",
        "available": False,
    }
    try:
        conn = get_hrv_db()
    except Exception:
        return fallback
    try:
        cur = conn.cursor()
        rows = cur.execute(
            """
            SELECT
                ts_measurement,
                date_utc,
                training_motivation,
                sleep_quality,
                fatigue,
                rmssd,
                hr,
                sdnn
            FROM hrv_measurements
            WHERE substr(COALESCE(date_utc, ts_measurement), 1, 10) >= date('now', ?)
            ORDER BY COALESCE(date_utc, ts_measurement) DESC
            """,
            (f"-{int(max(7, lookback_days))} days",),
        ).fetchall()
        readiness_map = _load_hrv_readiness_map(conn)
    except Exception:
        rows = []
        readiness_map = {}
    finally:
        conn.close()

    if not rows:
        return fallback

    latest = rows[0]
    refs = rows[1:29]

    def _f(row, key):
        try:
            return _to_optional_float(row[key])
        except Exception:
            return None

    def _mean_clean(values):
        clean = [float(v) for v in values if v is not None]
        return _mean(clean)

    def _state(today, baseline, *, higher_is_better: bool, margin: float) -> str:
        if today is None:
            return "missing"
        if baseline is None:
            return "ok"
        delta = float(today) - float(baseline)
        if higher_is_better:
            if delta <= -margin:
                return "low"
            if delta >= margin:
                return "high"
        else:
            if delta >= margin:
                return "high"
            if delta <= -margin:
                return "low"
        return "ok"

    motivation_today = _f(latest, "training_motivation")
    sleep_today = _f(latest, "sleep_quality")
    fatigue_today = _f(latest, "fatigue")
    readiness_today = _to_optional_float(readiness_map.get(latest["ts_measurement"]))

    motivation_base = _mean_clean([_f(r, "training_motivation") for r in refs])
    sleep_base = _mean_clean([_f(r, "sleep_quality") for r in refs])
    fatigue_base = _mean_clean([_f(r, "fatigue") for r in refs])
    readiness_base = _mean_clean([_to_optional_float(readiness_map.get(r["ts_measurement"])) for r in refs])

    return {
        "motivation_today": motivation_today,
        "motivation_baseline": motivation_base,
        "motivation_state": _state(motivation_today, motivation_base, higher_is_better=True, margin=0.75),
        "sleep_today": sleep_today,
        "sleep_baseline": sleep_base,
        "sleep_state": _state(sleep_today, sleep_base, higher_is_better=True, margin=0.6),
        "fatigue_today": fatigue_today,
        "fatigue_baseline": fatigue_base,
        "fatigue_state": _state(fatigue_today, fatigue_base, higher_is_better=False, margin=0.75),
        "readiness_score": readiness_today,
        "readiness_baseline": readiness_base,
        "readiness_state": _state(readiness_today, readiness_base, higher_is_better=True, margin=8.0),
        "available": any(v is not None for v in (motivation_today, sleep_today, fatigue_today, readiness_today)),
    }


def _compute_gym_load(days: int = 28) -> dict:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    rows = cur.execute(
        """
        SELECT w.date_iso AS day, e.name, e.variation, s.rpe
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE w.date_iso IS NOT NULL
          AND w.date_iso >= date('now', ?)
        ORDER BY w.date_iso DESC
        """,
        (f"-{int(days)} days",),
    ).fetchall()

    today = date.today()
    hi_days_3d = set()
    hi_days_7d = set()
    hi_days_14d = set()
    hi_yesterday = False

    counts_7d = {"push": 0, "pull": 0, "legs": 0}
    counts_28d = {"push": 0, "pull": 0, "legs": 0}
    # Local fatigue should be muscle-group specific (push/pull/legs),
    # based on hard work in those groups with time decay.
    day_group_stats: dict[tuple[str, str], dict[str, float]] = {}

    for row in rows:
        d_iso = row["day"]
        try:
            d = date.fromisoformat(d_iso)
        except Exception:
            continue
        rpe = _to_optional_float(row["rpe"])
        if rpe is not None and rpe >= 8.0:
            if d >= today - timedelta(days=2):
                hi_days_3d.add(d_iso)
            if d >= today - timedelta(days=6):
                hi_days_7d.add(d_iso)
            if d >= today - timedelta(days=13):
                hi_days_14d.add(d_iso)
            if d == today - timedelta(days=1):
                hi_yesterday = True

        pattern = classify_pattern(row["name"] or "", row["variation"] or "")
        group = None
        if pattern in {"chest", "shoulders_arms"}:
            group = "push"
        elif pattern in {"back"}:
            group = "pull"
        elif pattern in {"legs"}:
            group = "legs"
        if group:
            counts_28d[group] += 1
            if d >= today - timedelta(days=6):
                counts_7d[group] += 1
            key = (group, d_iso)
            snap = day_group_stats.get(key)
            if snap is None:
                snap = {"max_rpe": 0.0, "sets": 0.0}
                day_group_stats[key] = snap
            snap["sets"] += 1.0
            if rpe is not None and rpe > snap["max_rpe"]:
                snap["max_rpe"] = float(rpe)

    pain_flags = {"push": False, "pull": False, "legs": False}
    try:
        pain_rows = cur.execute(
            "SELECT movement_key, note, ts FROM pain_flags WHERE ts >= ?",
            (int(time()) - 14 * 86400,),
        ).fetchall()
    except Exception:
        pain_rows = []

    for row in pain_rows:
        movement_key = row["movement_key"] if "movement_key" in row.keys() else ""
        note = row["note"] if "note" in row.keys() else ""
        text = f"{movement_key or ''} {note or ''}".lower()
        if any(k in text for k in ["elbow", "shoulder", "bench", "press", "dip"]):
            pain_flags["push"] = True
        if any(k in text for k in ["row", "pull", "lat", "chin", "biceps"]):
            pain_flags["pull"] = True
        if any(k in text for k in ["knee", "squat", "deadlift", "leg", "hip"]):
            pain_flags["legs"] = True

    conn.close()

    baseline_7d = {
        k: (counts_28d[k] / 4.0) if counts_28d[k] else 0.0 for k in counts_28d
    }

    # Group-specific half-life (in days): legs recover a bit slower than upper body.
    half_life_days = {"push": 2.0, "pull": 1.9, "legs": 2.6}

    local_scores: dict[str, float] = {"push": 0.0, "pull": 0.0, "legs": 0.0}
    days_since_hard: dict[str, int | None] = {"push": None, "pull": None, "legs": None}

    for (group, day_iso), stats in day_group_stats.items():
        try:
            d = date.fromisoformat(day_iso)
        except Exception:
            continue
        days_ago = max(0, (today - d).days)
        max_rpe = float(stats.get("max_rpe") or 0.0)
        sets_cnt = float(stats.get("sets") or 0.0)

        # Only meaningful local fatigue from sufficiently hard local work.
        if max_rpe < 7.8:
            continue

        # Session load in [0..1], combining intensity and volume.
        intensity_component = max(0.0, min(1.0, (max_rpe - 7.6) / 1.8))
        volume_component = max(0.0, min(1.0, sets_cnt / 12.0))
        day_load = min(1.0, (intensity_component * 0.72) + (volume_component * 0.28))

        hl = max(1.2, float(half_life_days.get(group, 2.0)))
        decay = math.pow(0.5, float(days_ago) / hl)
        local_scores[group] += day_load * decay

        if max_rpe >= 8.0:
            prev = days_since_hard.get(group)
            if prev is None or days_ago < prev:
                days_since_hard[group] = days_ago

    for g in local_scores:
        local_scores[g] = float(max(0.0, min(1.0, local_scores[g])))

    # Small anti-stickiness guard after two full rest days.
    if len(hi_days_3d) == 0:
        for g in local_scores:
            local_scores[g] = min(local_scores[g], 0.45)

    fatigue_flags = {
        "push_fatigue_high": bool(pain_flags["push"] or local_scores["push"] >= 0.58),
        "pull_fatigue_high": bool(pain_flags["pull"] or local_scores["pull"] >= 0.58),
        "legs_fatigue_high": bool(pain_flags["legs"] or local_scores["legs"] >= 0.58),
    }

    return {
        "hi_exposures_3d": len(hi_days_3d),
        "hi_exposures_7d": len(hi_days_7d),
        "hi_exposures_14d": len(hi_days_14d),
        "hi_yesterday": hi_yesterday,
        "stimulus_7d": counts_7d,
        "baseline_28d_7d": baseline_7d,
        "local_fatigue_score": {
            "push": round(local_scores["push"], 3),
            "pull": round(local_scores["pull"], 3),
            "legs": round(local_scores["legs"], 3),
        },
        "local_days_since_hard": {
            "push": days_since_hard["push"],
            "pull": days_since_hard["pull"],
            "legs": days_since_hard["legs"],
        },
        **fatigue_flags,
    }


def _compute_run_load() -> dict:
    stats = compute_run_stats(days=60)
    hi_yesterday = False
    conn = None
    try:
        conn = get_runs_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        rows = cur.execute(
            """
            SELECT date, distance, moving_time, pace, avg_hr
            FROM runs
            WHERE date IS NOT NULL
              AND date >= date('now', '-2 days')
            ORDER BY date DESC
            """
        ).fetchall()
    except Exception:
        rows = []
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

    for row in rows:
        d = (row["date"] or "").split("T")[0]
        if d != (date.today() - timedelta(days=1)).isoformat():
            continue
        dist_m = row["distance"] or 0.0
        km = dist_m / 1000.0 if dist_m else None
        pace_s = row["pace"]
        pace_min = (float(pace_s) / 60.0) if pace_s else None
        label = classify_run(km, pace_min, row["avg_hr"]) if km and pace_min else "Unknown"
        if label in {"Tempo", "Threshold", "Interval"}:
            hi_yesterday = True
            break

    stats["hi_yesterday"] = hi_yesterday
    return stats


_OVERRIDE_WHITELIST_TYPES = {
    "manual_override",
    "autopilot_override",
    "target_override",
    "volume_intensity_override",
    "skip_rest_override",
}


def _planned_slots_last_7d(plan: dict | None, today: date) -> tuple[list[date], int]:
    gym_dates: list[date] = []
    planned_runs = 0
    base_week = (plan or {}).get("base_week") or []
    if not isinstance(base_week, list) or not base_week:
        return gym_dates, planned_runs
    for offset in range(6, -1, -1):
        d = today - timedelta(days=offset)
        day_tpl = base_week[d.weekday()] if d.weekday() < len(base_week) else {}
        if not isinstance(day_tpl, dict):
            continue
        if day_tpl.get("strength_exercises"):
            gym_dates.append(d)
        run_sessions = day_tpl.get("run_sessions") or []
        if isinstance(run_sessions, list):
            planned_runs += len([rs for rs in run_sessions if isinstance(rs, dict)])
    return gym_dates, planned_runs


def _compute_adherence_from_context(
    plan: dict | None,
    *,
    today: date,
    now_dt: datetime,
    logged_gym_dates: set[str],
    performed_runs_7d: int,
    override_types_7d: list[str],
    days_since_last_run: int | None,
    late_logging_window_hours: int = 36,
    late_logging_window_days: int = 2,
) -> dict:
    gym_plan_dates, planned_runs_7d = _planned_slots_last_7d(plan, today)
    expected_gym_7d = len(gym_plan_dates)
    expected_7d = expected_gym_7d + planned_runs_7d

    logged_done_7d = 0
    assumed_done_7d = 0
    skipped_gym_7d = 0

    for d in gym_plan_dates:
        d_iso = d.isoformat()
        if d_iso in logged_gym_dates:
            logged_done_7d += 1
            continue
        age_hours = (now_dt - datetime.combine(d, datetime.min.time())).total_seconds() / 3600.0
        within_late_window = (age_hours <= float(late_logging_window_hours)) or ((today - d).days <= int(late_logging_window_days))
        if within_late_window:
            assumed_done_7d += 1
        else:
            skipped_gym_7d += 1

    skipped_runs_7d = max(0, int(planned_runs_7d) - int(performed_runs_7d or 0))
    actual_7d = int(logged_done_7d + assumed_done_7d + int(performed_runs_7d or 0))
    skipped_7d = int(skipped_gym_7d + skipped_runs_7d)

    override_counts: dict[str, int] = {}
    for raw in override_types_7d or []:
        dt = str(raw or "").strip().lower()
        if dt in _OVERRIDE_WHITELIST_TYPES:
            override_counts[dt] = int(override_counts.get(dt, 0) or 0) + 1
    override_count = int(sum(override_counts.values()))
    override_types_compact = sorted(override_counts.keys())[:10]

    return {
        "expected_7d": expected_7d,
        "expected_gym_7d": expected_gym_7d,
        "expected_runs_7d": int(planned_runs_7d),
        "logged_done_7d": int(logged_done_7d),
        "assumed_done_7d": int(assumed_done_7d),
        "actual_7d": actual_7d,
        "skipped_7d": skipped_7d,
        "skipped_gym_7d": int(skipped_gym_7d),
        "skipped_runs_7d": int(skipped_runs_7d),
        "late_window_hours": int(late_logging_window_hours),
        "late_window_days": int(late_logging_window_days),
        "performed_runs_last_3_weeks": None,
        "planned_runs_last_3_weeks": None,
        "days_since_last_run": days_since_last_run,
        "override_count_7d": override_count,
        "override_count_7d_whitelisted": override_count,
        "override_types_7d": override_types_compact,
        "low": skipped_7d >= 2 or override_count >= 3,
    }


def _compute_adherence(
    plan: dict | None,
    *,
    today: date | None = None,
    now_dt: datetime | None = None,
    late_logging_window_hours: int = 36,
    late_logging_window_days: int = 2,
) -> dict:
    ref_today = today or date.today()
    ref_now = now_dt or datetime.combine(ref_today, datetime.min.time())
    since_day = (ref_today - timedelta(days=6)).isoformat()
    since_epoch = int(datetime.combine(ref_today - timedelta(days=6), datetime.min.time(), tzinfo=timezone.utc).timestamp())

    logged_gym_dates: set[str] = set()
    override_types: list[str] = []
    training_conn = get_training_db()
    training_conn.row_factory = sqlite3.Row
    try:
        tcur = training_conn.cursor()
        for row in tcur.execute(
            """
            SELECT DISTINCT date_iso
            FROM workouts
            WHERE date_iso IS NOT NULL AND date_iso >= ?
            """,
            (since_day,),
        ).fetchall():
            d_iso = str(row["date_iso"] or "").strip()
            if d_iso:
                logged_gym_dates.add(d_iso)
        try:
            rows = tcur.execute(
                "SELECT LOWER(COALESCE(decision_type, '')) AS decision_type FROM override_log WHERE ts >= ?",
                (since_epoch,),
            ).fetchall()
            override_types = [str(r["decision_type"] or "").strip().lower() for r in rows]
        except Exception:
            override_types = []
    finally:
        training_conn.close()

    performed_runs_7d = 0
    days_since_last_run: int | None = None
    planned_runs_3w = 0
    run_conn = None
    try:
        run_conn = get_runs_db()
        run_conn.row_factory = sqlite3.Row
        rcur = run_conn.cursor()
        row = rcur.execute("SELECT COUNT(*) AS c FROM runs WHERE date >= ?", (since_day,)).fetchone()
        performed_runs_7d = int((row["c"] if row else 0) or 0)
        row_max = rcur.execute("SELECT MAX(substr(date, 1, 10)) AS d FROM runs").fetchone()
        last_run_day = str(row_max["d"] or "").strip() if row_max else ""
        if last_run_day:
            try:
                days_since_last_run = max(0, (ref_today - date.fromisoformat(last_run_day)).days)
            except Exception:
                days_since_last_run = None
    except Exception:
        performed_runs_7d = 0
        days_since_last_run = None
    finally:
        try:
            if run_conn:
                run_conn.close()
        except Exception:
            pass

    metrics = _compute_adherence_from_context(
        plan,
        today=ref_today,
        now_dt=ref_now,
        logged_gym_dates=logged_gym_dates,
        performed_runs_7d=performed_runs_7d,
        override_types_7d=override_types,
        days_since_last_run=days_since_last_run,
        late_logging_window_hours=late_logging_window_hours,
        late_logging_window_days=late_logging_window_days,
    )

    # Recompute planned run count for 3-week cardio-debt helper.
    try:
        base_week = (plan or {}).get("base_week") or []
        if isinstance(base_week, list) and base_week:
            planned_runs_3w = 0
            for offset in range(20, -1, -1):
                d = ref_today - timedelta(days=offset)
                day_tpl = base_week[d.weekday()] if d.weekday() < len(base_week) else {}
                if isinstance(day_tpl, dict):
                    rs = day_tpl.get("run_sessions") or []
                    if isinstance(rs, list):
                        planned_runs_3w += len([x for x in rs if isinstance(x, dict)])
    except Exception:
        planned_runs_3w = 0
    performed_runs_3w = 0
    run_conn2 = None
    try:
        run_conn2 = get_runs_db()
        run_conn2.row_factory = sqlite3.Row
        rcur2 = run_conn2.cursor()
        since_3w = (ref_today - timedelta(days=20)).isoformat()
        row3 = rcur2.execute("SELECT COUNT(*) AS c FROM runs WHERE date >= ?", (since_3w,)).fetchone()
        performed_runs_3w = int((row3["c"] if row3 else 0) or 0)
    except Exception:
        performed_runs_3w = 0
    finally:
        try:
            if run_conn2:
                run_conn2.close()
        except Exception:
            pass
    metrics["planned_runs_last_3_weeks"] = int(planned_runs_3w)
    metrics["performed_runs_last_3_weeks"] = int(performed_runs_3w)
    return metrics


def _rotation_order(plan: dict, sessions: list[dict]) -> tuple[list[dict], int | None]:
    if not sessions:
        return [], None
    keys = [s["session_key"] for s in sessions]
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    rows = cur.execute(
        """
        SELECT session_key, name, date_iso
        FROM workouts
        WHERE date_iso IS NOT NULL
        ORDER BY date_iso DESC, id DESC
        LIMIT 30
        """
    ).fetchall()
    conn.close()

    last_key = None
    for r in rows:
        sk = r["session_key"]
        if sk and sk in keys:
            last_key = sk
            break
    if last_key is None:
        return sessions, 0
    idx = keys.index(last_key)
    next_idx = (idx + 1) % len(sessions)
    ordered = sessions[next_idx:] + sessions[:next_idx]
    return ordered, next_idx


def _session_category(day: dict | None) -> str:
    if not day or not isinstance(day, dict):
        return "unknown"
    counts = {"push": 0, "pull": 0, "legs": 0}
    for ex in (day.get("strength_exercises") or []):
        if not isinstance(ex, dict):
            continue
        name = ex.get("exercise_name") or ex.get("name") or ""
        variation = ex.get("variation") or ""
        pattern = classify_pattern(name, variation)
        if pattern in {"chest", "shoulders_arms"}:
            counts["push"] += 1
        elif pattern in {"back"}:
            counts["pull"] += 1
        elif pattern in {"legs"}:
            counts["legs"] += 1
    if counts["legs"] >= max(counts["push"], counts["pull"]) and counts["legs"] > 0:
        return "legs"
    if counts["push"] > counts["pull"] and counts["push"] > 0:
        return "push"
    if counts["pull"] > counts["push"] and counts["pull"] > 0:
        return "pull"
    if counts["push"] > 0 or counts["pull"] > 0:
        return "upper"
    return "unknown"


def _slot_session_category(slot: dict | None) -> str:
    if not isinstance(slot, dict):
        return "unknown"
    category = str(slot.get("category") or "").strip().lower()
    if category in {"legs", "lower"}:
        return "legs"
    if category in {"push", "pull", "upper"}:
        return category
    name = str(slot.get("session_name") or slot.get("label") or "").strip().lower()
    if any(token in name for token in ("legs", "lower", "beine")):
        return "legs"
    if "push" in name:
        return "push"
    if "pull" in name:
        return "pull"
    if "upper" in name:
        return "upper"
    return "unknown"




def _load_pain_movements(days: int = 30) -> set[str]:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        rows = cur.execute(
            "SELECT movement_key FROM pain_flags WHERE ts >= ? AND movement_key IS NOT NULL",
            (int(time()) - days * 86400,),
        ).fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()
    keys = set()
    for r in rows:
        if "movement_key" in r.keys() and r["movement_key"]:
            keys.add(str(r["movement_key"]).strip().lower())
    return keys


def _load_swap_library() -> tuple[dict, dict, dict]:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        lib_rows = cur.execute(
            "SELECT movement_key, label FROM movement_library"
        ).fetchall()
        group_rows = cur.execute(
            "SELECT group_key, movement_key FROM swap_groups"
        ).fetchall()
    except Exception:
        lib_rows = []
        group_rows = []
    finally:
        conn.close()

    key_to_label = {}
    label_to_key = {}
    for r in lib_rows:
        if "movement_key" not in r.keys() or not r["movement_key"]:
            continue
        key = str(r["movement_key"]).strip().lower()
        label = str(r["label"] or "").strip()
        if not key or not label:
            continue
        key_to_label[key] = label
        label_to_key[label.lower()] = key
    groups = {}
    for row in group_rows:
        gk = str(row["group_key"]).strip().lower()
        mk = str(row["movement_key"]).strip().lower()
        if not gk or not mk:
            continue
        groups.setdefault(gk, []).append(mk)
    return key_to_label, label_to_key, groups


def _apply_swaps_to_items(items: list[dict], pain_keys: set[str]) -> list[dict]:
    if not items:
        return items
    key_to_label, label_to_key, groups = _load_swap_library()
    if not key_to_label or not groups:
        return items
    for item in items:
        name = (item.get("title") or "").strip()
        if not name:
            continue
        key = label_to_key.get(name.lower())
        if not key or key not in pain_keys:
            continue
        group_key = None
        for gk, keys in groups.items():
            if key in keys:
                group_key = gk
                break
        if not group_key:
            continue
        swap_key = next((k for k in groups.get(group_key, []) if k != key), None)
        if not swap_key:
            continue
        swap_label = key_to_label.get(swap_key)
        if not swap_label:
            continue
        item["title"] = swap_label
        item.setdefault("pill", {})
        item["pill"]["text"] = "SWAP"
        item["pill"]["color"] = "yellow"
    return items


def _autopilot_learning_profile(plan: dict | None, lookback_days: int = 28) -> dict:
    today = date.today()
    lookback_days = max(21, min(90, int(lookback_days or 28)))
    since_28 = (today - timedelta(days=27)).isoformat()
    since_21 = (today - timedelta(days=20)).isoformat()
    since_14 = (today - timedelta(days=13)).isoformat()
    since_35 = (today - timedelta(days=34)).isoformat()
    since_epoch_28 = int(datetime.combine(today - timedelta(days=27), datetime.min.time(), tzinfo=timezone.utc).timestamp())

    gym_days_14: set[str] = set()
    override_count_28d = 0
    gym_avg_rpe_14d = None

    training_conn = get_training_db()
    training_conn.row_factory = sqlite3.Row
    try:
        tcur = training_conn.cursor()
        for row in tcur.execute(
            "SELECT DISTINCT date_iso FROM workouts WHERE date_iso IS NOT NULL AND date_iso >= ?",
            (since_14,),
        ).fetchall():
            d = str(row["date_iso"] or "").strip()
            if d:
                gym_days_14.add(d)
        try:
            row = tcur.execute(
                """
                SELECT AVG(s.rpe) AS avg_rpe
                FROM sets s
                JOIN exercises e ON e.id = s.exercise_id
                JOIN workouts w ON w.id = e.workout_id
                WHERE w.date_iso IS NOT NULL AND w.date_iso >= ? AND s.rpe IS NOT NULL
                """,
                (since_14,),
            ).fetchone()
            if row and row["avg_rpe"] is not None:
                gym_avg_rpe_14d = float(row["avg_rpe"])
        except Exception:
            gym_avg_rpe_14d = None

        try:
            rows = tcur.execute(
                "SELECT LOWER(COALESCE(decision_type, '')) AS decision_type FROM override_log WHERE ts >= ?",
                (since_epoch_28,),
            ).fetchall()
            override_count_28d = sum(
                1
                for r in rows
                if str(r["decision_type"] or "").strip().lower() in _OVERRIDE_WHITELIST_TYPES
            )
        except Exception:
            override_count_28d = 0
    finally:
        training_conn.close()

    run_days_14: set[str] = set()
    performed_runs_21d = 0
    run_conn = None
    try:
        run_conn = get_runs_db()
        run_conn.row_factory = sqlite3.Row
        rcur = run_conn.cursor()
        row = rcur.execute("SELECT COUNT(*) AS c FROM runs WHERE date >= ?", (since_21,)).fetchone()
        performed_runs_21d = int((row["c"] if row else 0) or 0)
        for row in rcur.execute("SELECT DISTINCT substr(date, 1, 10) AS d FROM runs WHERE date >= ?", (since_14,)).fetchall():
            d = str(row["d"] or "").strip()
            if d:
                run_days_14.add(d)
    except Exception:
        performed_runs_21d = 0
        run_days_14 = set()
    finally:
        try:
            if run_conn:
                run_conn.close()
        except Exception:
            pass

    planned_runs_21d = 0
    try:
        base_week = (plan or {}).get("base_week") or []
        if isinstance(base_week, list) and base_week:
            for offset in range(20, -1, -1):
                d = today - timedelta(days=offset)
                tpl = base_week[d.weekday()] if d.weekday() < len(base_week) else {}
                if not isinstance(tpl, dict):
                    continue
                run_sessions = tpl.get("run_sessions") or []
                if isinstance(run_sessions, list):
                    planned_runs_21d += len([x for x in run_sessions if isinstance(x, dict)])
    except Exception:
        planned_runs_21d = 0

    recovery_low_days_21d = 0
    recovery_days_21d = 0
    rmssd_base = None
    rhr_base = None
    hrv_conn = None
    try:
        hrv_conn = get_hrv_db()
        hrv_conn.row_factory = sqlite3.Row
        rows = hrv_conn.execute(
            """
            SELECT
                substr(COALESCE(date_utc, ts_measurement), 1, 10) AS d,
                AVG(rmssd) AS rmssd_avg,
                AVG(hr) AS hr_avg
            FROM hrv_measurements
            WHERE substr(COALESCE(date_utc, ts_measurement), 1, 10) >= ?
            GROUP BY d
            ORDER BY d ASC
            """,
            (since_35,),
        ).fetchall()
        daily = []
        for row in rows:
            d = str(row["d"] or "").strip()
            if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", d):
                continue
            daily.append({
                "d": d,
                "rmssd": _to_optional_float(row["rmssd_avg"]),
                "rhr": _to_optional_float(row["hr_avg"]),
            })
        rmssd_vals = [x["rmssd"] for x in daily if x["rmssd"] is not None]
        rhr_vals = [x["rhr"] for x in daily if x["rhr"] is not None]
        if rmssd_vals:
            rmssd_base = sum(rmssd_vals) / len(rmssd_vals)
        if rhr_vals:
            rhr_base = sum(rhr_vals) / len(rhr_vals)

        for rec in daily:
            d = rec["d"]
            if d < since_21:
                continue
            low = False
            has_signal = False
            rmssd_v = rec.get("rmssd")
            rhr_v = rec.get("rhr")
            if rmssd_v is not None and rmssd_base and rmssd_base > 0:
                has_signal = True
                if rmssd_v < (0.90 * rmssd_base):
                    low = True
            if rhr_v is not None and rhr_base and rhr_base > 0:
                has_signal = True
                if rhr_v > (1.06 * rhr_base):
                    low = True
            if has_signal:
                recovery_days_21d += 1
                if low:
                    recovery_low_days_21d += 1
    except Exception:
        recovery_low_days_21d = 0
        recovery_days_21d = 0
    finally:
        try:
            if hrv_conn:
                hrv_conn.close()
        except Exception:
            pass

    training_days_14d = len(gym_days_14 | run_days_14)
    override_rate_28d = (override_count_28d / 28.0) if override_count_28d > 0 else 0.0
    recovery_low_rate_21d = (
        (recovery_low_days_21d / recovery_days_21d)
        if recovery_days_21d > 0
        else 0.25
    )
    run_compliance_21d = (
        (performed_runs_21d / float(planned_runs_21d))
        if planned_runs_21d > 0
        else 0.65
    )
    run_compliance_21d = max(0.0, min(1.2, run_compliance_21d))
    samples_days = max(recovery_days_21d, training_days_14d, min(21, planned_runs_21d))
    learning_ready = bool(samples_days >= 10 and (training_days_14d >= 5 or recovery_days_21d >= 8))

    return {
        "learning_ready": learning_ready,
        "samples_days": int(samples_days),
        "override_rate_28d": float(max(0.0, min(1.0, override_rate_28d))),
        "recovery_low_rate_21d": float(max(0.0, min(1.0, recovery_low_rate_21d))),
        "run_compliance_21d": float(run_compliance_21d),
        "gym_avg_rpe_14d": float(gym_avg_rpe_14d) if gym_avg_rpe_14d is not None else 7.4,
        "training_days_14d": int(training_days_14d),
        "planned_runs_21d": int(planned_runs_21d),
        "performed_runs_21d": int(performed_runs_21d),
        "recovery_days_21d": int(recovery_days_21d),
    }


def _autopilot_state_snapshot():
    hrv_rows = _load_hrv_daily_summary(60)
    recovery = _compute_recovery_snapshot(28)
    rmssd_7d = recovery.get("rmssd_7d")
    rmssd_28d = recovery.get("rmssd_28d")
    rhr_7d = recovery.get("rhr_7d")
    rhr_28d = recovery.get("rhr_28d")
    rmssd_today = recovery.get("rmssd_today")
    rhr_today = recovery.get("rhr_today")
    hrv_flags = _load_hrv_flags(days=7)
    subjective = _load_hrv_subjective_snapshot(35)
    signal_low_days = _hrv_signal_quality_low_days(hrv_rows)

    gym_load = _compute_gym_load(28)
    run_load = _compute_run_load()

    core_mode_enabled = bool(_get_core_mode_enabled())
    plan, plan_source = _active_plan_for_decision(core_mode_enabled)
    adherence = _compute_adherence(plan)

    state = compute_state(
        recovery={
            "rmssd_today": rmssd_today,
            "rhr_today": rhr_today,
            "rmssd_7d": rmssd_7d,
            "rmssd_28d": rmssd_28d,
            "rhr_7d": rhr_7d,
            "rhr_28d": rhr_28d,
            "recovery_today_missing": recovery.get("recovery_today_missing"),
            "recovery_history_available": recovery.get("recovery_history_available"),
            "recovery_data_missing": recovery.get("recovery_data_missing"),
        },
        hrv_daily=hrv_rows,
        sickness=hrv_flags.get("sickness"),
        alcohol=hrv_flags.get("alcohol"),
        signal_quality_low_days=signal_low_days,
        gym_load=gym_load,
        run_load=run_load,
        adherence=adherence,
    )
    state["subjective"] = subjective
    flags = state.setdefault("flags", {})
    flags["subjective_low_motivation"] = subjective.get("motivation_state") == "low"
    flags["subjective_high_fatigue"] = subjective.get("fatigue_state") == "high"
    flags["subjective_low_sleep"] = subjective.get("sleep_state") == "low"
    flags["subjective_high_readiness"] = subjective.get("readiness_state") == "high"
    state["learning_profile"] = _autopilot_learning_profile(plan)
    state["decision_mode"] = "core" if core_mode_enabled else "base"
    state["plan_source"] = plan_source
    return state




def _autopilot_is_quality_run(run_type: str | None) -> bool:
    rt = (run_type or "").strip().lower()
    return rt in {"threshold", "tempo", "interval", "quality", "intervals"}


def _autopilot_week_layer_for_day(day_id: str) -> dict:
    fallback = {
        "week_type": "build",
        "rpe_cap": None,
        "strength_factor": 1.0,
        "run_factor": 1.0,
    }
    try:
        with app.test_request_context(f"/api/dashboard/plan_check_week_overview?asof={day_id}"):
            ov_resp = api_dashboard_plan_check_week_overview()
        ov_obj = ov_resp[0] if isinstance(ov_resp, tuple) else ov_resp
        ov_json = ov_obj.get_json() if hasattr(ov_obj, "get_json") else {}
        layer = (ov_json or {}).get("layer") if isinstance(ov_json, dict) else {}
        week = (ov_json or {}).get("week") if isinstance(ov_json, dict) else {}
        if isinstance(layer, dict) or isinstance(week, dict):
            week_type = str((week or {}).get("week_type") or (layer or {}).get("week_type") or "build").strip().lower()
            if week_type not in {"build", "overreach", "deload"}:
                week_type = "build"
            return {
                "week_type": week_type,
                "rpe_cap": _to_optional_float((layer or {}).get("rpe_cap")),
                "strength_factor": _to_optional_float((layer or {}).get("volume_mult")) or fallback["strength_factor"],
                "run_factor": fallback["run_factor"],
            }
    except Exception:
        pass

    try:
        target_day = date.fromisoformat(str(day_id))
    except Exception:
        return fallback

    plan_row = _get_active_gym_plan_record()
    if not isinstance(plan_row, dict):
        return fallback

    plan_json = plan_row.get("plan_json")
    rules_json = plan_row.get("rules_json")
    if not isinstance(plan_json, dict) or not isinstance(rules_json, dict):
        return fallback

    try:
        cycle = _gym_plan_cycle_status(plan_json, rules_json, today=target_day)
        week_label = str(cycle.get("week_label") or "W1")
        week_row = (rules_json.get("weeks") or {}).get(week_label) or {}
        week_type = str(week_row.get("tag") or cycle.get("phase_label") or "build").strip().lower()
        if week_type not in {"build", "overreach", "deload"}:
            week_type = "build"
        try:
            rpe_cap = float(week_row.get("rpe_cap")) if week_row.get("rpe_cap") is not None else None
        except Exception:
            rpe_cap = None
        try:
            strength_factor = float(week_row.get("strength_factor")) if week_row.get("strength_factor") is not None else 1.0
        except Exception:
            strength_factor = 1.0
        try:
            run_factor = float(week_row.get("run_factor")) if week_row.get("run_factor") is not None else 1.0
        except Exception:
            run_factor = 1.0
        return {
            "week_type": week_type,
            "rpe_cap": rpe_cap,
            "strength_factor": strength_factor,
            "run_factor": run_factor,
        }
    except Exception:
        return fallback




def _autopilot_weekday_label(idx: int) -> str:
    labels = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]
    return labels[idx] if 0 <= idx < len(labels) else ""


def _autopilot_rolling_weekday_date(anchor_day: date, weekday_idx: int) -> date:
    # Rolling week model: each weekday points to its next occurrence from anchor_day.
    delta = (int(weekday_idx) - int(anchor_day.weekday())) % 7
    return anchor_day + timedelta(days=delta)


def _autopilot_run_kind(run_session: dict | None) -> str:
    if not run_session or not isinstance(run_session, dict):
        return "z2"
    run_type = run_session.get("run_type")
    return "threshold" if _autopilot_is_quality_run(run_type) else "z2"


def _autopilot_run_duration_min(run_session: dict | None) -> int | None:
    if not isinstance(run_session, dict):
        return None
    raw = run_session.get("amount_value")
    try:
        if raw is not None and str(raw).strip() != "":
            val = int(round(float(raw)))
            return val if val > 0 else None
    except Exception:
        pass
    notes = str(run_session.get("notes") or "").strip()
    m = re.search(r"(\d{1,3})\s*min", notes, flags=re.IGNORECASE)
    if m:
        try:
            val = int(m.group(1))
            return val if val > 0 else None
        except Exception:
            return None
    return None


def _autopilot_run_label(kind: str) -> str:
    if kind == "threshold":
        return "Run THRESHOLD"
    return "Run Z2"


def _autopilot_week_number_for_day(day_iso: str) -> int | None:
    try:
        ctx = _autopilot_plan_context_for_day(day_iso)
        wk = str(ctx.get("week") or "").strip()
        m = re.match(r"^\s*(\d+)\s*/", wk)
        if m:
            val = int(m.group(1))
            return val if val > 0 else None
    except Exception:
        return None
    return None


def _autopilot_block_run_kind_for_day(day_iso: str, weekday_idx: int, default_kind: str) -> str:
    wk = _autopilot_week_number_for_day(day_iso)
    if wk is None:
        return default_kind
    rec = _get_active_gym_plan_record() or {}
    blocks = rec.get("blocks_json") if isinstance(rec.get("blocks_json"), dict) else {}
    if not isinstance(blocks, dict):
        return default_kind

    run_entries = None
    for key, value in blocks.items():
        if "run block" in str(key).lower() and isinstance(value, list):
            run_entries = value
            break
    if not isinstance(run_entries, list):
        return default_kind

    day_label = _autopilot_weekday_label(weekday_idx)
    target = None
    for row in run_entries:
        if not isinstance(row, dict):
            continue
        if str(row.get("day") or "").strip().lower() == day_label.lower():
            target = row
            break
    if not isinstance(target, dict):
        return default_kind
    lines = target.get("lines") if isinstance(target.get("lines"), list) else []
    if not lines:
        return default_kind

    chosen = None
    for line in lines:
        txt = str(line or "").strip()
        if not txt:
            continue
        m_range = re.search(r"Woche\s+(\d+)\s*[–-]\s*(\d+)", txt, flags=re.IGNORECASE)
        if m_range:
            a = int(m_range.group(1))
            b = int(m_range.group(2))
            if a <= wk <= b:
                chosen = txt
                break
        m_single = re.search(r"Woche\s+(\d+)", txt, flags=re.IGNORECASE)
        if m_single and int(m_single.group(1)) == wk:
            chosen = txt
            break
    if not chosen:
        chosen = str(lines[0] or "")

    low = chosen.lower()
    if any(tok in low for tok in ["threshold", "interval", "quality", "tempo", "schwelle"]):
        return "threshold"
    if "easy" in low or "z2" in low:
        return "z2"
    return default_kind




def _autopilot_planned_primary_slot(day: dict | None, idx: int) -> dict:
    day = day or {}
    strength = day.get("strength_exercises") or []
    if isinstance(strength, list) and strength:
        name = (day.get("session_name") or "").strip() or f"Session {idx + 1}"
        return {
            "kind": "plan",
            "session_key": _session_key_from_day(idx, name),
            "session_name": name,
            "label": name,
            "category": _session_category(day),
        }
    run_sessions = day.get("run_sessions") or []
    if isinstance(run_sessions, list) and run_sessions:
        first_run = run_sessions[0] if isinstance(run_sessions[0], dict) else None
        kind = _autopilot_run_kind(first_run)
        return {
            "kind": "run",
            "run_kind": kind,
            "run_duration_min": _autopilot_run_duration_min(first_run),
            "label": _autopilot_run_label(kind),
        }
    return {"kind": "rest", "label": "Rest"}


def _autopilot_week_start(d: date) -> date:
    return d - timedelta(days=d.weekday())

_SHIFT_VERSION = "v4_run_duration_slots"


def _autopilot_load_shifted_week(week_start: date, planned_json: str, plan_id: int | None = None) -> tuple[list[dict] | None, list[str] | None]:
    conn = get_training_db()
    try:
        _ensure_autopilot_schema(conn)
        row = conn.execute(
            "SELECT planned_json, shifted_json, reason_codes_json, plan_id FROM autopilot_week WHERE week_start=? LIMIT 1",
            (week_start.isoformat(),),
        ).fetchone()
    except Exception:
        row = None
    finally:
        conn.close()
    if not row or not row["shifted_json"]:
        return None, None
    if plan_id is not None:
        try:
            cached_plan_id = int(row["plan_id"]) if row["plan_id"] is not None else None
        except Exception:
            cached_plan_id = None
        if cached_plan_id != int(plan_id):
            return None, None
    if row["planned_json"] and planned_json and row["planned_json"] != planned_json:
        return None, None
    try:
        shifted = json.loads(row["shifted_json"])
    except Exception:
        return None, None
    if not isinstance(shifted, list):
        return None, None
    if len(shifted) < 7:
        return None, None
    if not all(isinstance(d, dict) and d.get("day_id") for d in shifted):
        return None, None
    # Reject shifted weeks with duplicate plan session_keys (stale/bad data)
    seen_keys = set()
    for d in shifted:
        if d.get("kind") != "plan":
            continue
        key = d.get("session_key")
        if not key:
            continue
        if key in seen_keys:
            return None, None
        seen_keys.add(key)
    reasons = None
    try:
        if row["reason_codes_json"]:
            reasons = json.loads(row["reason_codes_json"])
    except Exception:
        reasons = None
    if not reasons or _SHIFT_VERSION not in reasons:
        return None, reasons
    return shifted, reasons


def _autopilot_week_plan(plan: dict, anchor_day: date) -> list[dict]:
    base_week = plan.get("base_week") or []
    floating_template = bool(base_week) and not any(
        str((d or {}).get("day") or "").strip()
        for d in base_week
        if isinstance(d, dict)
    )
    ref_today = date.today()
    out = []
    for idx in range(7):
        source_idx = idx
        if floating_template and base_week:
            weekday_day = _autopilot_rolling_weekday_date(anchor_day, idx)
            source_idx = (weekday_day - ref_today).days % len(base_week)
            day = base_week[source_idx] if source_idx < len(base_week) else {}
        else:
            day = base_week[idx] if idx < len(base_week) else {}
        date_iso = _autopilot_rolling_weekday_date(anchor_day, idx).isoformat()
        planned = _autopilot_planned_primary_slot(day, source_idx)
        if planned.get("kind") == "run":
            run_kind = str(planned.get("run_kind") or "z2").strip().lower()
            run_kind = _autopilot_block_run_kind_for_day(date_iso, idx, run_kind)
            planned["run_kind"] = run_kind
            planned["label"] = _autopilot_run_label(run_kind)
        slot = {
            "day_id": date_iso,
            "kind": planned.get("kind") or "rest",
            "label": planned.get("label") or "Rest",
            "session_key": planned.get("session_key"),
            "session_name": planned.get("session_name"),
            "run_kind": planned.get("run_kind"),
            "run_duration_min": planned.get("run_duration_min"),
            "category": planned.get("category"),
            "minimal_gym": planned.get("minimal_gym"),
            "origin_day_id": date_iso,
            "weekday_idx": idx,
        }
        out.append(slot)
    return out


_CATCHUP_MUST = "MUST_CATCH_UP"
_CATCHUP_NICE = "NICE_TO_HAVE"
_CATCHUP_DROP = "DROP_OK"


def _autopilot_plan_slot_for_date(plan: dict, target_day: date, anchor_day: date) -> tuple[dict[str, Any], dict[str, Any]]:
    base_week = plan.get("base_week") or []
    if not isinstance(base_week, list) or not base_week:
        date_iso = target_day.isoformat()
        return ({
            "day_id": date_iso,
            "kind": "rest",
            "label": "Rest",
            "session_key": None,
            "session_name": None,
            "run_kind": None,
            "run_duration_min": None,
            "category": None,
            "minimal_gym": False,
            "origin_day_id": date_iso,
            "weekday_idx": target_day.weekday(),
        }, {})

    floating_template = not any(
        str((d or {}).get("day") or "").strip()
        for d in base_week
        if isinstance(d, dict)
    )
    if floating_template:
        source_idx = (target_day - date.today()).days % len(base_week)
    else:
        source_idx = target_day.weekday() % len(base_week)
    day_tpl = base_week[source_idx] if source_idx < len(base_week) else {}
    planned = _autopilot_planned_primary_slot(day_tpl, source_idx)
    date_iso = target_day.isoformat()
    if planned.get("kind") == "run":
        run_kind = str(planned.get("run_kind") or "z2").strip().lower()
        run_kind = _autopilot_block_run_kind_for_day(date_iso, target_day.weekday(), run_kind)
        planned["run_kind"] = run_kind
        planned["label"] = _autopilot_run_label(run_kind)
    slot = {
        "day_id": date_iso,
        "kind": planned.get("kind") or "rest",
        "label": planned.get("label") or "Rest",
        "session_key": planned.get("session_key"),
        "session_name": planned.get("session_name"),
        "run_kind": planned.get("run_kind"),
        "run_duration_min": planned.get("run_duration_min"),
        "category": planned.get("category"),
        "minimal_gym": planned.get("minimal_gym"),
        "origin_day_id": date_iso,
        "weekday_idx": target_day.weekday(),
    }
    return slot, day_tpl if isinstance(day_tpl, dict) else {}


def _autopilot_slot_catchup_policy(slot: dict[str, Any] | None, day_tpl: dict[str, Any] | None = None) -> str:
    if not isinstance(slot, dict):
        return _CATCHUP_DROP
    meta = day_tpl if isinstance(day_tpl, dict) else {}
    slot_meta = slot.get("meta") if isinstance(slot.get("meta"), dict) else {}
    for raw in (
        slot.get("catchup_policy"),
        slot_meta.get("catchup_policy"),
        meta.get("catchup_policy"),
        meta.get("priority"),
    ):
        text = str(raw or "").strip().upper()
        if text in {_CATCHUP_MUST, _CATCHUP_NICE, _CATCHUP_DROP}:
            return text

    tags = set()
    for value in (
        meta.get("tags"),
        slot_meta.get("tags"),
        meta.get("session_tags"),
    ):
        if isinstance(value, list):
            tags.update(str(item or "").strip().lower() for item in value if str(item or "").strip())
        elif isinstance(value, str) and value.strip():
            tags.update(part.strip().lower() for part in value.split(",") if part.strip())

    kind = str(slot.get("kind") or "").strip().lower()
    if kind == "plan":
        category = str(slot.get("category") or "").strip().lower()
        label = str(slot.get("session_name") or slot.get("label") or "").strip().lower()
        if category in {"mobility", "accessory", "pump"} or any(tag in tags for tag in {"optional", "accessory", "pump", "mobility", "recovery"}):
            return _CATCHUP_DROP
        if "mobility" in label or "recovery" in label or "pump" in label:
            return _CATCHUP_DROP
        return _CATCHUP_MUST

    if kind == "run":
        run_kind = str(slot.get("run_kind") or "").strip().lower()
        label = str(slot.get("label") or "").strip().lower()
        if any(tag in tags for tag in {"must_catch_up", "key_run", "quality_run", "long_run"}):
            return _CATCHUP_MUST
        if any(tag in tags for tag in {"drop_ok", "easy_run", "recovery_run", "optional"}):
            return _CATCHUP_DROP
        if "long" in label:
            return _CATCHUP_MUST
        if run_kind == "threshold":
            return _CATCHUP_NICE
        return _CATCHUP_DROP

    return _CATCHUP_DROP


def _autopilot_slot_to_decision(slot: dict[str, Any]) -> dict[str, Any]:
    kind = str(slot.get("kind") or "").strip().lower()
    if kind == "plan":
        return {
            "kind": "plan",
            "session_key": slot.get("session_key"),
            "session_name": slot.get("session_name") or slot.get("label"),
            "minimal_gym": bool(slot.get("minimal_gym")),
        }
    if kind == "run":
        return {
            "kind": "run",
            "run_kind": slot.get("run_kind") or "z2",
            "run_duration_min": slot.get("run_duration_min"),
        }
    return {"kind": "rest"}


def _autopilot_load_core_override_choice_map(start_day: date, end_day: date) -> dict[str, str]:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    out: dict[str, str] = {}
    try:
        _ensure_core_decision_schema(conn)
        rows = conn.execute(
            """
            SELECT date, choice
            FROM core_override_choices
            WHERE date BETWEEN ? AND ?
            """,
            (start_day.isoformat(), end_day.isoformat()),
        ).fetchall()
        for row in rows:
            day_id = str(row["date"] or "").strip()
            choice = str(row["choice"] or "").strip().lower()
            if day_id and choice:
                out[day_id] = choice
    except Exception:
        return {}
    finally:
        conn.close()
    return out


def _autopilot_load_actual_completion_maps(start_day: date, end_day: date) -> tuple[dict[str, list[dict[str, Any]]], dict[str, int]]:
    workouts_by_day: dict[str, list[dict[str, Any]]] = {}
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            """
            SELECT date_iso, name, session_key
            FROM workouts
            WHERE date_iso IS NOT NULL AND date_iso BETWEEN ? AND ?
            ORDER BY date_iso ASC, id ASC
            """,
            (start_day.isoformat(), end_day.isoformat()),
        ).fetchall()
        for row in rows:
            day_id = str(row["date_iso"] or "").strip()
            if not day_id:
                continue
            workouts_by_day.setdefault(day_id, []).append(
                {
                    "name": str(row["name"] or "").strip(),
                    "session_key": str(row["session_key"] or "").strip(),
                }
            )
    except Exception:
        workouts_by_day = {}
    finally:
        conn.close()

    runs_by_day: dict[str, int] = {}
    try:
        run_conn = get_runs_db()
        run_conn.row_factory = sqlite3.Row
        rows = run_conn.execute(
            """
            SELECT substr(date, 1, 10) AS day_id, COUNT(*) AS c
            FROM runs
            WHERE substr(date, 1, 10) BETWEEN ? AND ?
            GROUP BY substr(date, 1, 10)
            """,
            (start_day.isoformat(), end_day.isoformat()),
        ).fetchall()
        for row in rows:
            day_id = str(row["day_id"] or "").strip()
            if day_id:
                runs_by_day[day_id] = int(row["c"] or 0)
    except Exception:
        runs_by_day = {}
    finally:
        try:
            run_conn.close()
        except Exception:
            pass
    return workouts_by_day, runs_by_day


def _autopilot_slot_completed_on_day(
    slot: dict[str, Any],
    day_id: str,
    workouts_by_day: dict[str, list[dict[str, Any]]],
    runs_by_day: dict[str, int],
) -> bool:
    kind = str(slot.get("kind") or "").strip().lower()
    if kind == "run":
        return int(runs_by_day.get(day_id, 0) or 0) > 0
    if kind != "plan":
        return False
    target_key = str(slot.get("session_key") or "").strip().lower()
    target_name = _norm_text(slot.get("session_name") or slot.get("label") or "")
    for row in workouts_by_day.get(day_id, []) or []:
        row_key = str((row or {}).get("session_key") or "").strip().lower()
        row_name = _norm_text((row or {}).get("name") or "")
        if target_key and row_key and target_key == row_key:
            return True
        if target_name and row_name and target_name == row_name:
            return True
    return False


def _autopilot_slot_is_eligible_for_day(slot: dict[str, Any], prev_slot: dict[str, Any] | None) -> bool:
    if not isinstance(slot, dict):
        return False
    if not isinstance(prev_slot, dict):
        return True
    if str(slot.get("kind") or "").strip().lower() != "plan":
        return True
    if str(prev_slot.get("kind") or "").strip().lower() != "plan":
        return True
    curr_cat = str(slot.get("category") or "").strip().lower()
    prev_cat = str(prev_slot.get("category") or "").strip().lower()
    if curr_cat in {"legs", "lower"} and prev_cat in {"legs", "lower"}:
        return False
    if curr_cat and prev_cat and curr_cat == prev_cat and curr_cat in {"push", "pull"}:
        return False
    return True


def _autopilot_day_can_host_slot(
    day_id: str,
    slot: dict[str, Any],
    *,
    today_day: date,
    schedule_cache: dict[tuple[str, str], dict[str, Any]],
) -> tuple[bool, str | None]:
    kind = str(slot.get("kind") or "").strip().lower()
    if kind == "rest":
        return True, None
    try:
        target_day = date.fromisoformat(day_id)
    except Exception:
        return True, None
    if target_day < today_day:
        return True, None
    cache_key = (day_id, json.dumps(_autopilot_slot_to_decision(slot), ensure_ascii=True, sort_keys=True))
    if cache_key not in schedule_cache:
        try:
            schedule_cache[cache_key] = plan_training_window(
                day_id,
                decision=_autopilot_slot_to_decision(slot),
                force_recompute=False,
                write_calendar=False,
                horizon_sync=False,
            ) or {}
        except Exception:
            schedule_cache[cache_key] = {}
    schedule = schedule_cache.get(cache_key) or {}
    status = str(schedule.get("status") or "").strip().lower()
    if status in {"scheduled", ""}:
        return True, None
    if status == "no_window_available":
        return False, "calendar_conflict"
    if status == "rest_day":
        return False, "rest_day"
    return True, None


def _autopilot_build_shift_note(slot: dict[str, Any], reason: str) -> str:
    name = str(slot.get("session_name") or slot.get("label") or "Session").strip()
    policy = str(slot.get("catchup_policy") or "").strip()
    if reason == "calendar_conflict":
        return f"{name} wird auf den nächsten sinnvollen Tag geschoben, weil heute kein sauberes Fenster frei ist."
    if reason == "skip_override":
        return f"{name} wird nachgezogen, weil der ursprüngliche Tag bewusst übersprungen wurde."
    if reason == "spacing_guard":
        return f"{name} bleibt in der Queue, weil der Abstand heute nicht sauber genug wäre."
    if policy == _CATCHUP_DROP:
        return f"{name} entfällt, weil die Einheit niedrige Priorität hat."
    return f"{name} bleibt in der Microcycle-Reihenfolge und wird nach hinten geschoben."


def _autopilot_build_rolling_shifted_week(
    plan: dict,
    anchor_day: date,
    *,
    lookback_days: int = 7,
    horizon_days: int = 14,
    late_logging_window_hours: int = 36,
    late_logging_window_days: int = 2,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    today_day = date.today()
    now_dt = datetime.now()
    display_dates = [_autopilot_rolling_weekday_date(anchor_day, idx) for idx in range(7)]
    start_day = min(today_day, anchor_day) - timedelta(days=max(1, int(lookback_days or 7)))
    end_day = max(display_dates) + timedelta(days=max(7, int(horizon_days or 14)) - 1)

    override_choices = _autopilot_load_core_override_choice_map(start_day, end_day)
    workouts_by_day, runs_by_day = _autopilot_load_actual_completion_maps(start_day, end_day)
    schedule_cache: dict[tuple[str, str], dict[str, Any]] = {}

    pending: list[dict[str, Any]] = []
    placed_prev: dict[str, Any] | None = None
    final_map: dict[str, dict[str, Any]] = {}
    shift_events: list[dict[str, Any]] = []
    dropped_sessions: list[dict[str, Any]] = []
    carryover_sessions: list[dict[str, Any]] = []
    seen_display_ids = {d.isoformat() for d in display_dates}

    day = start_day
    while day <= end_day:
        day_id = day.isoformat()
        planned_slot, day_tpl = _autopilot_plan_slot_for_date(plan, day, anchor_day)
        planned_kind = str(planned_slot.get("kind") or "").strip().lower()
        if planned_kind in {"plan", "run"}:
            planned_slot["catchup_policy"] = _autopilot_slot_catchup_policy(planned_slot, day_tpl)
        explicit_rest = override_choices.get(day_id) == "rest"
        is_past = day < today_day
        age_hours = (now_dt - datetime.combine(day, datetime.min.time())).total_seconds() / 3600.0
        within_late_window = (age_hours <= float(late_logging_window_hours)) or ((today_day - day).days <= int(late_logging_window_days))

        should_enter_queue = (
            planned_kind in {"plan", "run"}
            and planned_slot.get("catchup_policy") in {_CATCHUP_MUST, _CATCHUP_NICE}
            and (day >= today_day or explicit_rest)
        )
        if should_enter_queue:
            pending.append(dict(planned_slot))

        chosen: dict[str, Any] | None = None
        blocked_reason = "skip_override" if explicit_rest else None

        if not explicit_rest:
            if pending:
                candidate = pending[0]
                if _autopilot_slot_is_eligible_for_day(candidate, placed_prev):
                    allowed, deny_reason = _autopilot_day_can_host_slot(day_id, candidate, today_day=today_day, schedule_cache=schedule_cache)
                    if allowed:
                        chosen = candidate
                        pending.pop(0)
                    else:
                        blocked_reason = deny_reason or blocked_reason
                else:
                    blocked_reason = "spacing_guard"
            elif planned_kind in {"plan", "run"} and planned_slot.get("catchup_policy") == _CATCHUP_DROP:
                if _autopilot_slot_is_eligible_for_day(planned_slot, placed_prev):
                    allowed, deny_reason = _autopilot_day_can_host_slot(day_id, planned_slot, today_day=today_day, schedule_cache=schedule_cache)
                    if allowed:
                        chosen = dict(planned_slot)
                    else:
                        blocked_reason = deny_reason or blocked_reason

        if chosen and is_past and not _autopilot_slot_completed_on_day(chosen, day_id, workouts_by_day, runs_by_day):
            if within_late_window and not explicit_rest:
                pass
            else:
                policy = str(chosen.get("catchup_policy") or "").strip().upper()
                if policy in {_CATCHUP_MUST, _CATCHUP_NICE}:
                    pending.insert(0, chosen)
                else:
                    dropped_sessions.append(
                        {
                            "day_id": day_id,
                            "session_name": chosen.get("session_name") or chosen.get("label"),
                            "catchup_policy": policy or _CATCHUP_DROP,
                            "reason": "missed_without_clean_slot",
                        }
                    )
                chosen = None

        if (
            not chosen
            and planned_kind in {"plan", "run"}
            and planned_slot.get("catchup_policy") == _CATCHUP_DROP
            and (day >= today_day or explicit_rest)
        ):
            dropped_sessions.append(
                {
                    "day_id": day_id,
                    "session_name": planned_slot.get("session_name") or planned_slot.get("label"),
                    "catchup_policy": _CATCHUP_DROP,
                    "reason": blocked_reason or ("priority_drop" if pending else "no_clean_slot"),
                }
            )

        if chosen:
            chosen = dict(chosen)
            chosen["day_id"] = day_id
            chosen["weekday_idx"] = day.weekday()
            chosen["shift_applied"] = bool(chosen.get("origin_day_id") and chosen.get("origin_day_id") != day_id)
            if chosen["shift_applied"]:
                chosen["shifted_from_date"] = chosen.get("origin_day_id")
                chosen["shifted_reason"] = blocked_reason or "carryover_preserved"
                chosen["scheduling_notes"] = _autopilot_build_shift_note(chosen, chosen["shifted_reason"])
                shift_events.append(
                    {
                        "session_name": chosen.get("session_name") or chosen.get("label"),
                        "from_date": chosen.get("origin_day_id"),
                        "to_date": day_id,
                        "catchup_policy": chosen.get("catchup_policy"),
                        "reason": chosen["shifted_reason"],
                        "note": chosen["scheduling_notes"],
                    }
                )
            else:
                chosen["shifted_from_date"] = None
                chosen["shifted_reason"] = None
                chosen["scheduling_notes"] = None
            final_map[day_id] = chosen
            placed_prev = chosen
        else:
            final_map[day_id] = {
                "day_id": day_id,
                "kind": "rest",
                "label": "Rest",
                "session_key": None,
                "session_name": None,
                "run_kind": None,
                "run_duration_min": None,
                "category": None,
                "minimal_gym": False,
                "origin_day_id": day_id,
                "weekday_idx": day.weekday(),
                "shift_applied": False,
                "shifted_from_date": None,
                "shifted_reason": blocked_reason,
                "scheduling_notes": "Rest bleibt stehen." if not blocked_reason else _autopilot_build_shift_note(planned_slot, blocked_reason),
                "catchup_policy": None,
            }
            placed_prev = None if explicit_rest else placed_prev

        day += timedelta(days=1)

    for slot in pending:
        carryover_sessions.append(
            {
                "session_name": slot.get("session_name") or slot.get("label"),
                "origin_day_id": slot.get("origin_day_id"),
                "catchup_policy": slot.get("catchup_policy"),
                "reason": "horizon_exhausted",
            }
        )

    week_final: list[dict[str, Any]] = []
    for idx, target_day in enumerate(display_dates):
        day_id = target_day.isoformat()
        slot = dict(final_map.get(day_id) or {
            "day_id": day_id,
            "kind": "rest",
            "label": "Rest",
            "origin_day_id": day_id,
            "weekday_idx": idx,
        })
        slot["weekday_idx"] = idx
        week_final.append(slot)

    visible_start_iso = min(display_dates).isoformat()
    shift_events = [
        item for item in shift_events
        if str(item.get("from_date") or "") >= visible_start_iso or str(item.get("to_date") or "") >= visible_start_iso
    ]
    dropped_sessions = [
        item for item in dropped_sessions
        if str(item.get("day_id") or "") >= visible_start_iso
    ]
    carryover_sessions = [
        item for item in carryover_sessions
        if str(item.get("origin_day_id") or "") >= visible_start_iso
    ]

    return week_final, {
        "shift_applied": bool(shift_events or dropped_sessions or carryover_sessions),
        "shift_events": shift_events,
        "carryover_sessions": carryover_sessions,
        "dropped_sessions": dropped_sessions,
        "scheduling_notes": [item.get("note") for item in shift_events if item.get("note")] + [
            f"{item.get('session_name')} entfällt, weil {item.get('reason')}."
            for item in dropped_sessions[:4]
            if item.get("session_name")
        ],
    }


def _autopilot_apply_week_override(week_plan: list[dict], week_start: date, planned_json: str, plan_id: int | None = None) -> list[dict]:
    shifted, _ = _autopilot_load_shifted_week(week_start, planned_json, plan_id=plan_id)
    if not shifted:
        return [dict(d) for d in week_plan]
    shift_map = {d.get("day_id"): d for d in shifted if isinstance(d, dict) and d.get("day_id")}
    out = []
    for day in week_plan:
        day_id = day.get("day_id")
        if day_id in shift_map:
            out.append(dict(shift_map[day_id]))
        else:
            out.append(dict(day))
    return out


def _slot_from_decision(decision: dict, base_slot: dict | None = None) -> dict:
    base_slot = base_slot or {}
    kind = decision.get("kind") or base_slot.get("kind") or "rest"
    if kind == "run":
        rk = decision.get("run_kind") or base_slot.get("run_kind") or "z2"
        run_duration_min = decision.get("run_duration_min")
        if run_duration_min is None:
            run_duration_min = base_slot.get("run_duration_min")
        return {
            "kind": "run",
            "label": "Run Z2" if rk == "z2" else "Run THRESHOLD",
            "run_kind": rk,
            "run_duration_min": run_duration_min,
            "minimal_gym": False,
        }
    if kind == "plan":
        name = decision.get("session_name") or base_slot.get("session_name") or base_slot.get("label") or "Gym"
        return {
            "kind": "plan",
            "label": name,
            "session_key": decision.get("session_key") or base_slot.get("session_key"),
            "session_name": name,
            "category": base_slot.get("category"),
            "minimal_gym": bool(decision.get("minimal_gym") or base_slot.get("minimal_gym")),
        }
    return {"kind": "rest", "label": "Rest"}


def _autopilot_clean_label(value: str | None) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    text = re.sub(r"\s*·\s*Reassess\b", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*\(Reassess\)\s*", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\s{2,}", " ", text)
    return text.strip()


def _autopilot_week_days(week_plan: list[dict], week_final: list[dict], anchor_day: date, today_iso: str) -> list[dict]:
    move_map = {}
    for day in week_final:
        origin = day.get("origin_day_id")
        if origin and origin != day.get("day_id"):
            move_map[origin] = day.get("day_id")

    out = []
    for idx in range(7):
        planned_slot = next((d for d in week_plan if int(d.get("weekday_idx", -1)) == idx), None)
        final_slot = next((d for d in week_final if int(d.get("weekday_idx", -1)) == idx), None)
        if (not planned_slot) or (not final_slot):
            date_iso = _autopilot_rolling_weekday_date(anchor_day, idx).isoformat()
            planned_slot = planned_slot or next((d for d in week_plan if d.get("day_id") == date_iso), None)
            final_slot = final_slot or next((d for d in week_final if d.get("day_id") == date_iso), None)
        else:
            date_iso = str(planned_slot.get("day_id") or final_slot.get("day_id") or _autopilot_rolling_weekday_date(anchor_day, idx).isoformat())
        if not planned_slot or not final_slot:
            planned_slot = planned_slot or {"day_id": date_iso, "kind": "rest", "label": "Rest"}
            final_slot = final_slot or planned_slot
        planned_label = _autopilot_clean_label(planned_slot.get("label") or "Rest") or "Rest"
        final_label = _autopilot_clean_label(final_slot.get("label") or planned_label) or planned_label
        final_kind = final_slot.get("kind") or planned_slot.get("kind") or "rest"
        if str(planned_slot.get("kind") or "").strip().lower() == "run":
            planned_label = _autopilot_run_label(str(planned_slot.get("run_kind") or "z2").strip().lower())
        if str(final_kind or "").strip().lower() == "run":
            rk_final = str(final_slot.get("run_kind") or planned_slot.get("run_kind") or "z2").strip().lower()
            final_label = _autopilot_run_label(rk_final)
        weekday = _autopilot_weekday_label(idx)

        shift_to = move_map.get(date_iso)
        if shift_to and final_label == planned_label:
            shift_weekday = _autopilot_weekday_label(date.fromisoformat(shift_to).weekday())
            label = f"{weekday} \u00b7 {planned_label} \u2192 {shift_weekday}"
        elif final_label == planned_label:
            label = f"{weekday} \u00b7 {planned_label}"
        else:
            label = f"{weekday} \u00b7 {planned_label} \u2192 {final_label}"

        meta = {}
        badges = []
        if date_iso > today_iso:
            meta["forecast"] = True
        if shift_to:
            meta["shift_to"] = shift_to
            meta["override"] = True
        elif final_label != planned_label:
            meta["override"] = True
        if final_slot.get("shift_applied"):
            meta["shift_applied"] = True
        if final_slot.get("shifted_from_date"):
            meta["shifted_from_date"] = final_slot.get("shifted_from_date")
        if final_slot.get("shifted_reason"):
            meta["shifted_reason"] = final_slot.get("shifted_reason")
        if final_slot.get("catchup_policy"):
            meta["catchup_policy"] = final_slot.get("catchup_policy")
        if final_slot.get("scheduling_notes"):
            meta["scheduling_notes"] = final_slot.get("scheduling_notes")
        if final_slot.get("minimal_gym"):
            badges.append("Light")

        display_label = label
        if badges:
            uniq = []
            for b in badges:
                if b not in uniq:
                    uniq.append(b)
            display_label = f"{label} \u00b7 " + " \u00b7 ".join(uniq)

        out.append({
            "day_id": date_iso,
            "weekday_short": weekday,
            "planned_label": planned_label,
            "final_label": final_label,
            "kind": final_kind,
            "label": display_label,
            "display_label": display_label,
            "badges": badges,
            "meta": meta,
            "session_key": final_slot.get("session_key"),
            "run_kind": final_slot.get("run_kind"),
            "minimal_gym": final_slot.get("minimal_gym"),
            "origin_day_id": final_slot.get("origin_day_id") or date_iso,
            "weekday_idx": idx,
            "catchup_policy": final_slot.get("catchup_policy"),
        })
    return out


def _autopilot_persist_week(
    week_start: date,
    week_plan: list[dict],
    week_final: list[dict],
    reason_codes: list[str] | None = None,
    plan_id: int | None = None,
):
    conn = get_training_db()
    try:
        _ensure_autopilot_schema(conn)
        shifted_json = json.dumps(week_final, ensure_ascii=False, sort_keys=True)
        reasons = list(reason_codes or [])
        if _SHIFT_VERSION not in reasons:
            reasons.append(_SHIFT_VERSION)
        conn.execute(
            """
            INSERT OR REPLACE INTO autopilot_week (week_start, plan_id, data_json, planned_json, shifted_json, reason_codes_json, created_ts, last_updated_ts)
            VALUES (?, ?, ?, ?, ?, ?, COALESCE((SELECT created_ts FROM autopilot_week WHERE week_start=?), ?), ?)
            """,
            (
                week_start.isoformat(),
                plan_id,
                shifted_json,
                json.dumps(week_plan, ensure_ascii=False, sort_keys=True),
                shifted_json,
                json.dumps(reasons, ensure_ascii=False),
                week_start.isoformat(),
                int(time()),
                int(time()),
            ),
        )
        conn.commit()
    finally:
        conn.close()


def _autopilot_build_explain(
    state_snapshot: dict,
    week_days: list[dict],
    selected_day_id: str,
    decision: dict,
    is_light_day: bool = False,
    rolling_shift: dict[str, Any] | None = None,
) -> dict:
    day_row = next((d for d in week_days if d.get("day_id") == selected_day_id), {}) or {}
    planned_label = day_row.get("planned_label") or ""
    final_label = day_row.get("final_label") or planned_label
    change_line = day_row.get("label") or ""
    rolling_shift = rolling_shift if isinstance(rolling_shift, dict) else {}

    recovery = (state_snapshot.get("recovery") or {})
    rmssd_today = recovery.get("rmssd_today")
    rhr_today = recovery.get("rhr_today")
    rmssd_28d = recovery.get("rmssd_28d")
    rhr_28d = recovery.get("rhr_28d")

    if rmssd_today is None or rhr_today is None:
        recovery_line = "Recovery heute: keine Messung (konservativ entschieden)"
    else:
        recovery_line = (
            f"Recovery heute: RMSSD {int(round(rmssd_today))} ms \u00b7 "
            f"Ruhepuls {int(round(rhr_today))} bpm"
        )
        if rmssd_28d is not None and rhr_28d is not None:
            recovery_line += (
                f" (im Vergleich zu \u00d828d RMSSD {int(round(rmssd_28d))} / RP {int(round(rhr_28d))})"
            )
    trend_line = ""
    rmssd_7d = recovery.get("rmssd_7d")
    rhr_7d = recovery.get("rhr_7d")
    if rmssd_7d is not None and rmssd_28d is not None and rhr_7d is not None and rhr_28d is not None:
        trend_line = (
            f"Trend: RMSSD 7d {int(round(rmssd_7d))} vs 28d {int(round(rmssd_28d))} \u00b7 "
            f"RHR 7d {int(round(rhr_7d))} vs 28d {int(round(rhr_28d))}"
        )

    reason_map = {
        "SICK": "Krank gemeldet",
        "RECOVERY_MISSING": "Recovery-Daten fehlen",
        "HRV_VERY_LOW": "HRV heute deutlich niedrig",
        "HRV_LOW": "HRV heute niedrig",
        "RHR_HIGH": "Ruhepuls erhöht",
        "ALCOHOL": "Alkohol eingetragen",
        "ZNS_FATIGUE": "ZNS aktuell müde",
        "LEGS_FATIGUE": "Beine aktuell müde",
        "PUSH_FATIGUE": "Push aktuell müde",
        "PULL_FATIGUE": "Pull aktuell müde",
        "HI_BACK_TO_BACK_GUARD": "Keine zwei harten Tage in Folge",
        "SHIFTED": "Einheit wurde in der Woche verschoben",
        "CORE_PUSH_GYM": "CORE öffnet heute ein HEAVY-Fenster im Gym",
        "CORE_PUSH_RUN": "CORE öffnet heute ein Progressionsfenster im Lauf",
        "CORE_TACTICAL_NORMAL": "CORE reduziert heute taktisch auf NORMAL, um die Sequenz stärker zu halten.",
        "CORE_EMERGENCY_LIGHT": "CORE setzt heute LIGHT als echte Schutzentscheidung.",
        "CORE_TACTICAL_RUN": "CORE steuert den Run heute kontrolliert statt maximal.",
        "CORE_PROTECT_RUN": "CORE schützt den Run heute vor unvernünftiger Belastung.",
    }
    reasons = decision.get("reason_codes") or []
    why_lines = [reason_map.get(r, r) for r in reasons][:6]

    hint_parts = []
    flags = (state_snapshot.get("flags") or {})
    if flags.get("alcohol"):
        hint_parts.append("Heute keine hohe Intensität")
    if flags.get("zns_fatigue"):
        hint_parts.append("ZNS entlasten")
    elif (flags.get("local_fatigue") or {}).get("legs"):
        hint_parts.append("Beine schonen")
    if flags.get("sick"):
        hint_parts.append("Morgen wieder leicht einsteigen")
    if is_light_day:
        hint_parts.append("Leichter Einstieg: weniger Volumen, niedrigere Intensität")
    hint = ". ".join(hint_parts) if hint_parts else ""

    lines = []
    if change_line:
        lines.append(change_line)
    if planned_label:
        lines.append(f"Geplant: {planned_label}")
    if final_label:
        lines.append(f"Heute: {final_label}")
    if recovery_line:
        lines.append(recovery_line)
    if trend_line:
        lines.append(trend_line)
    if why_lines:
        lines.append("Warum: " + ", ".join(why_lines))
    if hint:
        lines.append(f"Hinweis: {hint}")

    scheduling_notes = [str(line).strip() for line in (rolling_shift.get("scheduling_notes") or []) if str(line).strip()]
    if scheduling_notes:
        lines.extend(scheduling_notes[:3])

    return {
        "title": "Autopilot",
        "change_line": change_line,
        "planned": f"Geplant: {planned_label}" if planned_label else "",
        "today": f"Heute: {final_label}" if final_label else "",
        "recovery_line": recovery_line,
        "trend_line": trend_line,
        "why_lines": why_lines,
        "hint": hint,
        "lines": lines,
        "last_lines": [],
        "shift_applied": bool(rolling_shift.get("shift_applied")),
        "carryover_sessions": list(rolling_shift.get("carryover_sessions") or []),
        "dropped_sessions": list(rolling_shift.get("dropped_sessions") or []),
        "shift_events": list(rolling_shift.get("shift_events") or []),
        "scheduling_notes": scheduling_notes,
    }


def _build_core_dashboard_explain(
    state_snapshot: dict,
    week_days: list[dict],
    selected_day_id: str,
    decision: dict,
    core_info: dict | None,
    is_light_day: bool = False,
) -> dict:
    day_row = next((d for d in week_days if d.get("day_id") == selected_day_id), {}) or {}
    planned_label = str(day_row.get("planned_label") or "").strip()
    final_label = str(day_row.get("final_label") or planned_label or "").strip()
    planned_label_ui = re.sub(r"\s*[-·]\s*(LIGHT|HEAVY|NORMAL|PUSH)\s*$", "", planned_label, flags=re.IGNORECASE).strip()
    final_label_ui = re.sub(r"\s*[-·]\s*(LIGHT|HEAVY|NORMAL|PUSH)\s*$", "", final_label, flags=re.IGNORECASE).strip()
    change_line = str(day_row.get("label") or "").strip()
    reason_codes = [str(code or "").strip() for code in (decision.get("reason_codes") or []) if str(code or "").strip()]
    override_active = bool(planned_label and final_label and planned_label != final_label) or any(code.startswith("CORE_") for code in reason_codes)
    decision_kind = str(decision.get("kind") or "").strip().lower()
    run_kind = str(decision.get("run_kind") or "").strip().lower()
    recovery = state_snapshot.get("recovery") if isinstance(state_snapshot.get("recovery"), dict) else {}
    subjective = state_snapshot.get("subjective") if isinstance(state_snapshot.get("subjective"), dict) else {}
    flags = state_snapshot.get("flags") if isinstance(state_snapshot.get("flags"), dict) else {}

    def _fmt_num(value: Any, digits: int = 0) -> str:
        try:
            v = float(value)
        except Exception:
            return ""
        if digits <= 0:
            return str(int(round(v)))
        return f"{v:.{digits}f}"

    def _ratio_pct(value: Any) -> str:
        try:
            v = float(value)
        except Exception:
            return ""
        return f"{int(round(v * 100))}%"

    coverage = _core_data_coverage_payload() if callable(_core_data_coverage_payload) else {}
    quality = str((coverage or {}).get("quality") or "Mittel").strip()
    quality_note = str((coverage or {}).get("note") or "brauchbar, aber nicht überall sauber gefüttert").strip()

    core_info = core_info if isinstance(core_info, dict) else {}
    actions = core_info.get("actions") if isinstance(core_info.get("actions"), dict) else {}
    execution = core_info.get("execution") if isinstance(core_info.get("execution"), dict) else {}
    execution_profile = core_info.get("execution_profile") if isinstance(core_info.get("execution_profile"), dict) else {}
    principle_items = list(core_info.get("principles") or [])
    principles = get_core_principle_scores() if callable(get_core_principle_scores) else {}
    principle_impacts = _core_principle_impacts(principles) if callable(_core_principle_impacts) else []
    memory_catalog = _core_memory_catalog() if callable(_core_memory_catalog) else []
    memory_by_key = {str(item.get("memory_key") or ""): item for item in memory_catalog if str(item.get("memory_key") or "").strip()}

    used_memory: list[dict] = []
    for item in principle_impacts:
        memory = memory_by_key.get(str(item.get("memory_key") or ""))
        if memory and memory.get("status") not in {"ignored", "archived"}:
            used_memory.append(memory)
    for item in memory_catalog:
        if item.get("type") == "Exercise" and item.get("status") not in {"ignored", "archived"}:
            used_memory.append(item)
            break

    execution_mode = "normal"
    if decision_kind == "run":
        execution_mode = str(execution.get("run_mode") or ("light" if is_light_day else "normal")).strip().lower()
    elif decision_kind == "plan":
        execution_mode = str(execution.get("gym_mode") or ("light" if is_light_day else "normal")).strip().lower()
    elif is_light_day:
        execution_mode = "light"

    if execution_mode == "push":
        execution_mode = "heavy"

    material_override = bool(
        (planned_label and final_label and planned_label != final_label)
        or execution_mode in {"light", "heavy"}
        or is_light_day
    )

    status = "Bestätigt"
    if execution_mode == "light" or is_light_day or (planned_label and final_label and planned_label != final_label):
        status = "Eingriff"
    elif execution_mode == "heavy":
        status = "Freigabe"
    elif quality == "Schwach" or bool(actions.get("rpe_guard")) or bool(actions.get("interference_guard")) or bool(actions.get("signal_guard")):
        status = "Vorsicht"

    if material_override and (planned_label and final_label and planned_label != final_label):
        lead_line = f"CORE greift ein: {final_label_ui or final_label}"
    elif execution_mode == "heavy" and final_label:
        lead_line = f"CORE gibt heute grün für: {final_label_ui or final_label}"
    else:
        lead_line = f"CORE bestätigt heute den Plan: {final_label_ui or planned_label_ui or 'heute ruhig halten'}"

    mode_label_map = {
        "light": "Light",
        "normal": "Normal",
        "heavy": "Heavy",
    }
    today_suffix = mode_label_map.get(execution_mode)
    today_line = final_label_ui or final_label
    if (final_label_ui or final_label) and today_suffix:
        today_line = f"{final_label_ui or final_label} · {today_suffix}"

    reason_map = {
        "RECOVERY_MISSING": "Für heute fehlen Recovery-Daten, deshalb bleibt CORE vorsichtiger.",
        "HRV_VERY_LOW": "RMSSD liegt heute klar unter deinem Normalniveau; CORE wertet das als systemisches Bremssignal.",
        "HRV_LOW": "RMSSD liegt heute unter deiner Basis; CORE zieht deshalb etwas Sicherheitsmarge ein.",
        "RHR_HIGH": "Dein Ruhepuls liegt heute über Basis; CORE liest das als Erholungssignal gegen Vollgas.",
        "ZNS_FATIGUE": "Du hast heute ein systemisches Müdigkeitssignal; deshalb gilt Vorsicht für die ganze Session.",
        "LEGS_FATIGUE": "Die Beinmüdigkeit ist heute lokal erhöht; das drückt nur Lower, nicht automatisch HEAVY.",
        "PUSH_FATIGUE": "Push ist lokal müde; CORE vermeidet deshalb heute Extra-Druck auf der drückenden Seite.",
        "PULL_FATIGUE": "Pull ist lokal müde; CORE vermeidet deshalb heute Extra-Druck auf der ziehenden Seite.",
        "ALCOHOL": "Heute gibt es ein klares Bremssignal aus der Erholung.",
        "HI_BACK_TO_BACK_GUARD": "Heute würde sonst zu viel Härte direkt auf Härte folgen.",
        "SHIFTED": "Heute wurde der Tag bewusst anders gelegt als ursprünglich geplant.",
        "CORE_LIGHT_GYM": "CORE nimmt heute Volumen und Ziel-RPE raus, damit die Einheit reproduzierbar bleibt.",
        "CORE_PUSH_GYM": "CORE gibt heute im Gym HEAVY frei, weil die harten Marker nicht gegen Progression sprechen.",
        "CORE_DOWN_SHIFT_RUN": "Heute nimmt CORE Tempo aus dem Lauf und hält ihn bewusst locker.",
        "CORE_PUSH_RUN": "Heute sieht CORE ein sauberes Lauf-Fenster für Qualität.",
        "CORE_REPEATABLE_RUN": "Heute hält CORE den Lauf bewusst wiederholbar statt aggressiv.",
        "CORE_STABLE_RUN": "Heute bleibt der Lauf bewusst sauber und kontrolliert.",
        "CORE_REENTRY_RUN": "Heute ist ein ruhiger Wiedereinstieg sinnvoller als Qualität.",
        "CORE_REENTRY_GYM": "Heute ist ein ruhiger Wiedereinstieg sinnvoller als Druck.",
        "CORE_PROGRESS_WINDOW": "Heute sieht CORE eher ein sauberes Progressionsfenster als ein Bremssignal.",
        "CORE_TACTICAL_NORMAL": "Heute drosselt CORE nur taktisch auf NORMAL, damit die nächsten Schlüsselreize stärker bleiben.",
        "CORE_EMERGENCY_LIGHT": "Heute setzt CORE LIGHT nur als echte Schutzentscheidung.",
        "CORE_TACTICAL_RUN": "Heute steuert CORE den Lauf kontrolliert, um die Sequenz stabil zu halten.",
        "CORE_PROTECT_RUN": "Heute schützt CORE den Lauf klar vor unvernünftiger Last.",
    }

    relevant_principles: list[dict] = []
    for item in principle_items:
        topic = str(item.get("topic") or "").strip()
        if topic == "plan_first" and not override_active:
            relevant_principles.append(item)
        elif decision_kind == "run" and topic in {"run_quality", "regeneration_honesty", "nutrition_discipline"}:
            relevant_principles.append(item)
        elif decision_kind == "plan" and topic in {"rpe_honesty", "logging_quality", "regeneration_honesty", "nutrition_discipline", "regression_response"}:
            relevant_principles.append(item)
        elif decision_kind in {"rest", "recovery"} and topic in {"regeneration_honesty", "plan_first"}:
            relevant_principles.append(item)

    why_lines: list[str] = []
    for code in reason_codes:
        text = reason_map.get(code)
        if text and text not in why_lines:
            why_lines.append(text)
        if len(why_lines) >= 3:
            break

    if len(why_lines) < 3 and decision_kind == "run":
        if actions.get("interference_guard"):
            text = "Heute schützt CORE die Laufqualität, weil Kraft und Laufen sich sonst beißen würden."
            if text not in why_lines:
                why_lines.append(text)
        if len(why_lines) < 3 and actions.get("signal_guard"):
            text = "Heute bekommen Erholung und Warnsignale mehr Gewicht als Tempo."
            if text not in why_lines:
                why_lines.append(text)
        if len(why_lines) < 3 and run_kind == "z2" and override_active:
            text = "Heute soll der Lauf locker bleiben, damit morgen wieder Qualität möglich ist."
            if text not in why_lines:
                why_lines.append(text)

    if len(why_lines) < 3 and decision_kind == "plan":
        hrv_ratio = _to_optional_float(recovery.get("hrv_ratio"))
        rhr_ratio = _to_optional_float(recovery.get("rhr_ratio"))
        rmssd_today = _to_optional_float(recovery.get("rmssd_today"))
        rmssd_28d = _to_optional_float(recovery.get("rmssd_28d"))
        rhr_today = _to_optional_float(recovery.get("rhr_today"))
        rhr_28d = _to_optional_float(recovery.get("rhr_28d"))
        readiness_today = _to_optional_float(subjective.get("readiness_score"))
        readiness_base = _to_optional_float(subjective.get("readiness_baseline"))
        motivation_today = _to_optional_float(subjective.get("motivation_today"))
        motivation_base = _to_optional_float(subjective.get("motivation_baseline"))
        fatigue_today = _to_optional_float(subjective.get("fatigue_today"))
        fatigue_base = _to_optional_float(subjective.get("fatigue_baseline"))

        if len(why_lines) < 3 and execution_mode == "heavy" and hrv_ratio is not None and hrv_ratio >= 0.97:
            base_txt = f"{_ratio_pct(hrv_ratio)} deiner HRV-Basis"
            if rmssd_today is not None and rmssd_28d is not None:
                text = f"RMSSD heute {_fmt_num(rmssd_today)} ms vs {_fmt_num(rmssd_28d)} ms Basis; mit {base_txt} liegt kein HRV-Bremssignal vor."
            else:
                text = f"HRV liegt heute bei {base_txt}; CORE sieht darüber kein systemisches Bremssignal."
            if text not in why_lines:
                why_lines.append(text)
        if len(why_lines) < 3 and execution_mode in {"normal", "heavy"} and rhr_ratio is not None and rhr_ratio <= 1.03:
            if rhr_today is not None and rhr_28d is not None:
                text = f"Ruhepuls heute {_fmt_num(rhr_today)} bpm vs {_fmt_num(rhr_28d)} bpm Basis; kein klarer Erholungs-Alarm."
            else:
                text = f"Ruhepuls liegt heute bei {_ratio_pct(rhr_ratio)} deiner Basis; das spricht nicht gegen normales Drücken."
            if text not in why_lines:
                why_lines.append(text)
        if len(why_lines) < 3 and actions.get("signal_guard"):
            if execution_mode == "light":
                text = "Die Summe aus Recovery- und Fatigue-Signalen reicht heute für ein echtes Downshift, nicht nur für etwas Vorsicht."
            else:
                text = "Es gibt weiche Warnsignale, aber sie reichen nicht aus, um Push auf Light zu setzen; die harten Marker bleiben dafür zu stabil."
