    if not signal_lines:
        signal_lines.append(f"Datenlage: {quality}")

    decision_subject = final_label_ui or planned_label_ui or "heute"
    decision_line = ""
    if decision_kind == "run":
        run_mode_raw = str(execution.get("run_mode") or "").strip().lower()
