@app.route("/makros/update/<int:row_id>", methods=["POST"])
def update_makros(row_id):
    data = request.get_json(silent=True) or {}

    def num(v):
        if v in ("", "-", None):
            return None
        return float(str(v).replace(",", "."))

    conn = get_nutrition_db()
    cur = conn.cursor()

    cur.execute("""
        UPDATE weight_logs
        SET
            weight_kg = ?,
            kcal      = ?,
            protein   = ?,
            carbs     = ?,
            fat       = ?,
            sugar     = ?
        WHERE id = ?
    """, (
        num(data.get("weight_kg")),
        num(data.get("kcal")),
        num(data.get("protein")),
        num(data.get("carbs")),
        num(data.get("fat")),
        num(data.get("sugar")),
        row_id
    ))

    conn.commit()
    conn.close()

    touch_last_update()

    return jsonify(success=True)



@app.route("/api/makros/delete/<int:row_id>", methods=["DELETE"])
def delete_makros(row_id):
    conn = get_nutrition_db()
    conn.execute("DELETE FROM weight_logs WHERE id=?", (row_id,))
    conn.commit()
    conn.close()

    touch_last_update()
    return jsonify(success=True)


@app.route("/api/log_weight", methods=["POST"])
def api_log_weight():
    data = request.get_json(silent=True) or {}
    if not data:
        return {"success": False, "error": "No JSON received"}, 400

    # --------------------------------------------------
    # Gewicht
    # --------------------------------------------------
    weight_raw = data.get("weight")
    if weight_raw is None:
        return {"success": False, "error": "Missing weight"}, 400

    try:
        weight = float(str(weight_raw).replace(",", "."))
    except Exception:
        return {"success": False, "error": "Invalid weight"}, 400

    # --------------------------------------------------
    # Datum (createdAt → lokal → Tagesdatum)
    # --------------------------------------------------
    created_at_raw = data.get("createdAt") or data.get("updatedAt")
    if not created_at_raw:
        return {"success": False, "error": "Missing createdAt"}, 400

    def parse_iso_utc(s: str) -> datetime:
        s = s.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.fromisoformat(s)
        except Exception:
            if "." in s:
                base, rest = s.split(".", 1)
                tz = "+00:00"
                if "+" in rest:
                    tz = "+" + rest.split("+", 1)[1]
                return datetime.fromisoformat(base + tz)
            raise

    try:
        dt_utc = parse_iso_utc(created_at_raw)

        if dt_utc.tzinfo is None:
            dt_utc = dt_utc.replace(tzinfo=timezone.utc)

        # Lokalzeit (Berlin, UTC+1 reicht hier)
        dt_local = dt_utc.astimezone(timezone(timedelta(hours=1)))

    except Exception as e:
        return {
            "success": False,
            "error": "Invalid createdAt format",
            "detail": str(e)
        }, 400

    # 🔑 FORMATE
    date_iso = dt_local.strftime("%Y-%m-%d")
    date_pretty = dt_local.strftime("%d.%m.%y")   # ← GENAU DAS WOLLTEST DU
    created_at_db = dt_local.strftime("%Y-%m-%d %H:%M:%S")

    # --------------------------------------------------
    # raw_json
    # --------------------------------------------------
    raw_json = data.get("raw_json")
    if raw_json is not None and not isinstance(raw_json, str):
        raw_json = json.dumps(raw_json)

    # --------------------------------------------------
    # DB
    # --------------------------------------------------
    conn = get_nutrition_db()
    cur = conn.cursor()

    try:
        # Existiert schon ein Eintrag für den Tag?
        cur.execute("SELECT id FROM weight_logs WHERE date_iso = ?", (date_iso,))
        row = cur.fetchone()

        if row:
            cur.execute("""
                UPDATE weight_logs
                SET weight_kg = ?,
                    raw_json = ?
                WHERE date_iso = ?
            """, (weight, raw_json, date_iso))

            conn.commit()
            touch_last_update()
            return jsonify(success=True, updated=True, date_iso=date_iso)

        else:
            cur.execute("""
                INSERT INTO weight_logs (
                    date,
                    date_iso,
                    weight_kg,
                    created_at,
                    raw_json
                ) VALUES (?, ?, ?, ?, ?)
            """, (
                date_pretty,
                date_iso,
                weight,
                created_at_db,
                raw_json
            ))

            conn.commit()
            touch_last_update()
            return jsonify(success=True, inserted=True, date_iso=date_iso)

    finally:
        conn.close()


@app.route("/add_row", methods=["POST"])
def add_row():
    # ---------- robust payload parse ----------
    data = None

    # 1) proper JSON
    if request.is_json:
        data = request.get_json(silent=True)

    # 2) body contains JSON but header is wrong/missing
    if data is None:
        raw = (request.get_data(as_text=True) or "").strip()
        if raw:
            try:
                data = json.loads(raw)
            except Exception:
                data = None

    # 3) form-encoded fallback (application/x-www-form-urlencoded / multipart)
    if data is None and request.form:
        data = request.form.to_dict()

    # 4) querystring fallback
    if not data:
        data = dict(request.args)

    if not data:
        return jsonify(success=False, error="No payload received"), 400

    # ---------- raw_json normalize ----------
    raw_json = data.get("raw_json")
    if raw_json is not None and not isinstance(raw_json, str):
        raw_json = json.dumps(raw_json)

    # ---------------- helpers ----------------
    def num(v):
        if v in ("", "-", None):
            return None
        try:
            return float(str(v).replace(",", "."))
        except Exception:
            return None

    def parse_any_date(s: str):
        """
        Accepts:
          - dd.mm.yy / dd.mm.yyyy
          - yyyy-mm-dd
          - ISO datetime (with or without Z)
        Returns naive datetime.
        """
        if s is None:
            return None
        s = str(s).strip()
        if not s:
            return None

        if s.endswith("Z"):
            s = s[:-1] + "+00:00"

        # ISO datetime or ISO date
        try:
            return datetime.fromisoformat(s)
        except Exception:
            pass

        for fmt in ("%d.%m.%y", "%d.%m.%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                continue

        return None

    # ---------------- detect payload type ----------------
    # UI payload: has explicit date/date_iso/dateIso OR any of the manual fields
    manual_date_raw = data.get("date") or data.get("date_iso") or data.get("dateIso")
    manual_keys = ("kcal", "weight_kg", "protein", "carbs", "fat", "sugar")
    is_manual_ui = bool(manual_date_raw) or any(k in data for k in manual_keys)

    # Tracker payload: uses *_today/_yesterday + createdAt/updatedAt
    is_tracker = any(k in data for k in ("kcal_today", "kcal_yesterday", "createdAt", "updatedAt"))

    # If both somehow present, prefer UI (safer for Makros table edits)
    if is_manual_ui and not is_tracker:
        # ---------------- MANUELLE ZEILE (UI) ----------------
        if not manual_date_raw:
            # du willst: alles darf NULL sein, aber Datum MUSS da sein
            return jsonify(success=False, error="date required"), 400

        dt = parse_any_date(manual_date_raw)
        if not dt:
            return jsonify(success=False, error="Invalid date format"), 400

        date_pretty = dt.strftime("%d.%m.%y")
        date_iso = dt.strftime("%Y-%m-%d")

        vals = {
            "weight_kg": num(data.get("weight_kg")),
            "kcal": num(data.get("kcal")),
            "protein": num(data.get("protein")),
            "carbs": num(data.get("carbs")),
            "fat": num(data.get("fat")),
            "sugar": num(data.get("sugar")),
        }

        conn = get_nutrition_db()
        cur = conn.cursor()

        try:
            cur.execute("SELECT id FROM weight_logs WHERE date_iso=?", (date_iso,))
            row = cur.fetchone()
            updated = bool(row)

            if updated:
                cur.execute("""
                    UPDATE weight_logs
                    SET date=?,
                        weight_kg=?,
                        kcal=?,
                        protein=?,
                        carbs=?,
                        fat=?,
                        sugar=?,
                        raw_json=?
                    WHERE date_iso=?
                """, (
                    date_pretty,
                    vals["weight_kg"],
                    vals["kcal"],
                    vals["protein"],
                    vals["carbs"],
                    vals["fat"],
                    vals["sugar"],
                    raw_json,
                    date_iso
                ))
            else:
                # FIX: korrektes VALUES mapping (11 Spalten -> 11 Werte)
                cur.execute("""
                    INSERT INTO weight_logs (
                        date, date_iso,
                        weight_kg, kcal, protein, carbs, fat, sugar,
                        created_at, raw_json
                    ) VALUES (
                        ?, ?,
                        ?, ?, ?, ?, ?, ?,
                        datetime('now'), ?
                    )
                """, (
                    date_pretty,
                    date_iso,
                    vals["weight_kg"],
                    vals["kcal"],
                    vals["protein"],
                    vals["carbs"],
                    vals["fat"],
                    vals["sugar"],
                    raw_json
                ))

            conn.commit()
        finally:
            conn.close()

        touch_last_update()
        return jsonify(success=True, updated=updated)

    # ---------------- TRACKER FLOW (today/yesterday auto-update) ----------------
    # DATE BASIS: createdAt/updatedAt preferred, otherwise allow date_* fallback, otherwise now
    created_at = data.get("createdAt") or data.get("updatedAt") or data.get("date_iso") or data.get("dateIso") or data.get("date")
    dt = parse_any_date(created_at) if created_at else None
    if dt is None:
        dt = datetime.now()

    today_iso = dt.strftime("%Y-%m-%d")
    today_pretty = dt.strftime("%d.%m.%y")

    yesterday_dt = dt - timedelta(days=1)
    y_iso = yesterday_dt.strftime("%Y-%m-%d")
    y_pretty = yesterday_dt.strftime("%d.%m.%y")

    day_payloads = {
        today_iso: {
            "date": today_pretty,
            "kcal": num(data.get("kcal_today")),
            "carbs": num(data.get("carbs_today")),
            "protein": num(data.get("protein_today")),
            "fat": num(data.get("fat_today")),
            "sugar": num(data.get("sugar_today")),
        },
        y_iso: {
            "date": y_pretty,
            "kcal": num(data.get("kcal_yesterday")),
            "carbs": num(data.get("carbs_yesterday")),
            "protein": num(data.get("protein_yesterday")),
            "fat": num(data.get("fat_yesterday")),
            "sugar": num(data.get("sugar_yesterday")),
        }
    }

    conn = get_nutrition_db()
    cur = conn.cursor()

    try:
        for date_iso, vals in day_payloads.items():
            # komplett leere Tage überspringen (Tracker-Flow bleibt so)
            if all(v in (None, 0) for v in (vals["kcal"], vals["carbs"], vals["protein"], vals["fat"], vals["sugar"])):
                continue

            cur.execute("SELECT weight_kg FROM weight_logs WHERE date_iso=?", (date_iso,))
            row = cur.fetchone()

            if row:
                # UPDATE, aber Gewicht NICHT anfassen
                cur.execute("""
                    UPDATE weight_logs
                    SET kcal=?,
                        carbs=?,
                        protein=?,
                        fat=?,
                        sugar=?,
                        raw_json=?
                    WHERE date_iso=?
                """, (
                    vals["kcal"],
                    vals["carbs"],
                    vals["protein"],
                    vals["fat"],
                    vals["sugar"],
                    raw_json,
                    date_iso
                ))
            else:
                # INSERT ohne Gewicht
                cur.execute("""
                    INSERT INTO weight_logs (
                        date, date_iso,
                        kcal, carbs, protein, fat, sugar,
                        weight_kg,
                        created_at, raw_json
                    ) VALUES (
                        ?, ?,
                        ?, ?, ?, ?, ?,
                        NULL,
                        datetime('now'), ?
                    )
                """, (
                    vals["date"],
                    date_iso,
                    vals["kcal"],
                    vals["carbs"],
                    vals["protein"],
                    vals["fat"],
                    vals["sugar"],
                    raw_json
                ))

        conn.commit()
    finally:
        conn.close()

    touch_last_update()
    return jsonify(success=True)








