def _format_run_label(run_type: str | None):
    if not run_type:
        return "Run"
    raw = run_type.strip()
    low = raw.lower()
    if "threshold" in low:
        return "Threshold Run"
    if "tempo" in low:
        return "Tempo Run"
    if "interval" in low:
        return "Intervals Run"
    if "long" in low:
        return "Long Run"
    if "easy" in low:
        return "Easy Run"
    if "run" in low:
        return raw
    return f"{raw} Run"


def _date_range_list(start_iso: str | None, end_iso: str | None):
    start = _parse_iso(start_iso)
    end = _parse_iso(end_iso)
    if not start or not end:
        return []
    if start > end:
        start, end = end, start
    out = []
    current = start
    while current <= end:
        out.append(current)
        current = current + timedelta(days=1)
    return out


def _mean(values):
    clean = [v for v in values if v is not None]
    if not clean:
        return None
    return sum(clean) / len(clean)


def _compute_stats(values):
    clean = [v for v in values if v is not None]
    if not clean:
        return {"mean": None, "sd": None}
    mean = sum(clean) / len(clean)
    variance = sum((v - mean) ** 2 for v in clean) / len(clean)
    return {"mean": mean, "sd": math.sqrt(variance)}










def _load_load_series(start_iso: str, end_iso: str):
    training_conn = get_training_db()
    training_conn.row_factory = sqlite3.Row
    tcur = training_conn.cursor()
    tcur.execute(
        """
        SELECT w.date_iso AS date_iso,
               SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE w.date_iso BETWEEN ? AND ?
        GROUP BY w.date_iso
        """,
        (start_iso, end_iso)
    )
    training_rows = tcur.fetchall()
    training_conn.close()

    runs_conn = get_runs_db()
    runs_conn.row_factory = sqlite3.Row
    rcur = runs_conn.cursor()
    rcur.execute(
        """
        SELECT substr(date, 1, 10) AS date_iso,
               SUM(distance) AS distance_m
        FROM runs
        WHERE substr(date, 1, 10) BETWEEN ? AND ?
        GROUP BY substr(date, 1, 10)
        """,
        (start_iso, end_iso)
    )
    run_rows = rcur.fetchall()
    runs_conn.close()

    data = {}
    for row in training_rows:
        if not row["date_iso"]:
            continue
        data[row["date_iso"]] = {
            "date_iso": row["date_iso"],
            "gym_tonnage": float(row["tonnage"] or 0),
            "run_km": 0.0,
        }
    for row in run_rows:
        if not row["date_iso"]:
            continue
        entry = data.get(row["date_iso"])
        if not entry:
            entry = {"date_iso": row["date_iso"], "gym_tonnage": 0.0, "run_km": 0.0}
            data[row["date_iso"]] = entry
        entry["run_km"] = float(row["distance_m"] or 0) / 1000.0

    rows = sorted(data.values(), key=lambda r: r["date_iso"])
    for entry in rows:
        entry["load_score"] = float(entry["gym_tonnage"] or 0) + (float(entry["run_km"] or 0) * 1000.0)
    return rows


def _build_energy_daily(rows, settings, timeline):
    daily = []
    for row in rows:
        date_iso = row.get("date_iso")
        if not date_iso:
            continue
        kcal = row.get("calories")
        snapshot = _nutrition_mode_snapshot(date_iso, settings, timeline)
        target = snapshot["target"]
        delta = kcal - target if kcal is not None and target is not None else None
        status = _kcal_status_for_mode(snapshot["mode"], delta, target) if kcal is not None else "neutral"
        if snapshot["mode_missing"] or target is None or kcal is None:
            status = "neutral"
        status_label = _band_status_label(snapshot["mode"], delta, status)
        daily.append({
            "date_iso": date_iso,
            "daily_kcal": kcal,
            "daily_target_kcal": target,
            "daily_delta": delta,
            "daily_band_low": snapshot["band_low"],
            "daily_band_high": snapshot["band_high"],
            "daily_status": status,
            "daily_status_label": status_label,
            "mode": snapshot["mode"],
            "mode_missing": snapshot["mode_missing"],
        })
    return sorted(daily, key=lambda d: d["date_iso"])


def _compute_energy_momentum(daily):
    kcal_rows = [row for row in daily if row.get("daily_kcal") is not None]
    if len(kcal_rows) < 17:
        return {
            "has_data": False,
            "recent_days": len(kcal_rows[-3:]),
            "prev_days": max(0, len(kcal_rows) - 3),
            "avg_recent": None,
            "avg_prev": None,
            "momentum": None,
        }
    recent = kcal_rows[-3:]
    baseline = kcal_rows[-17:-3]
    if len(recent) < 3 or len(baseline) < 14:
        return {
            "has_data": False,
            "recent_days": len(recent),
            "prev_days": len(baseline),
            "avg_recent": None,
            "avg_prev": None,
            "momentum": None,
        }
    avg_recent = _mean([row["daily_kcal"] for row in recent])
    avg_prev = _mean([row["daily_kcal"] for row in baseline])
    momentum = None
    if avg_recent is not None and avg_prev is not None:
        momentum = round((avg_recent - avg_prev) / 10.0) * 10.0
    return {
        "has_data": momentum is not None,
        "recent_days": len(recent),
        "prev_days": len(baseline),
        "avg_recent": avg_recent,
        "avg_prev": avg_prev,
        "momentum": momentum,
    }


def _aggregate_by_week(rows, value_key, reducer):
    buckets = {}
    for row in rows:
        date_iso = row.get("date_iso")
        if not date_iso:
            continue
        dt = _parse_iso(date_iso)
        if not dt:
            continue
        iso_weekday = dt.isocalendar().weekday
        week_start = dt - timedelta(days=iso_weekday - 1)
        bucket_key = week_start.isoformat()
        buckets.setdefault(bucket_key, []).append(row.get(value_key))
    out = []
    for bucket_key, values in buckets.items():
        dt = _parse_iso(bucket_key)
        label = dt.strftime("%d.%m") if dt else bucket_key
        out.append({
            "bucket": bucket_key,
            "label": label,
            "value": reducer([v for v in values if v is not None]),
        })
    return sorted(out, key=lambda r: r["bucket"])


