@app.get("/api/dashboard/today")
def api_dashboard_today():
    raw_range = (request.args.get("range") or request.args.get("days") or "7").strip().lower()
    debug = request.args.get("debug") == "1"
    window = _dashboard_range_window(raw_range, "0", 7)

    plan_row = _get_active_plan_row()
    plan = plan_row_to_dict(plan_row) if plan_row else None
    today_idx = date.today().weekday()
    day = plan["base_week"][today_idx] if plan and plan.get("base_week") else {}
    run_session = (day.get("run_sessions") or [None])[0]

    has_run = bool(run_session and (run_session.get("run_type") or run_session.get("amount_value") or run_session.get("pace") or run_session.get("notes")))
    has_gym = bool(day.get("strength_exercises") or (day.get("session_name") or "").strip())
    session_type = "rest"
    if has_gym:
        session_type = "gym"
    elif has_run:
        session_type = "run"

    session_label = "Rest"
    if session_type == "run":
        session_label = _format_run_label(run_session.get("run_type") if isinstance(run_session, dict) else None)
    elif session_type == "gym":
        session_label = (day.get("session_name") or "Gym").strip() or "Gym"

    # Use the Gym-plan cycle as SSOT so the Today pill matches Wochenregeln.
    plan_week = _dashboard_plan_week_from_active_gym(today=date.today()) or _legacy_dashboard_plan_week(plan, today=date.today())

    conn = get_nutrition_db()
    _ensure_nutrition_daily_view(conn)
    settings = _load_nutrition_settings()
    timeline = _load_nutrition_mode_timeline(conn, settings)
    nutrition_rows = _load_nutrition_series(days=120)
    conn.close()

    energy_daily = _build_energy_daily(nutrition_rows, settings, timeline)
    energy_momentum = _compute_energy_momentum(energy_daily)
    latest_snapshot = _nutrition_mode_snapshot(energy_daily[-1]["date_iso"], settings, timeline) if energy_daily else {
        "mode": settings.get("selected_mode") or "maintenance",
        "target": _target_for_mode(settings, settings.get("selected_mode")),
        "band_low": None,
        "band_high": None,
        "mode_missing": True,
    }

    end_date = date.today()
    strip_start = end_date - timedelta(days=13)
    energy_map = {row["date_iso"]: row for row in energy_daily}
    strip_days = []
    for i in range(14):
        dt = strip_start + timedelta(days=i)
        date_iso = dt.isoformat()
        entry = energy_map.get(date_iso)
        strip_days.append({
            "date_iso": date_iso,
            "status": entry["daily_status"] if entry else "neutral",
            "kcal": entry.get("daily_kcal") if entry else None,
            "mode": entry.get("mode") if entry else None,
        })

    load_window = _dashboard_range_window("28", "0", 28)
    load_rows = _load_load_series(load_window["start_iso"], load_window["end_iso"])
    load_map = {row["date_iso"]: row for row in load_rows}
    load_dates = _date_range_list(load_window["start_iso"], load_window["end_iso"])
    load_values = []
    for dt in load_dates:
        date_iso = dt.isoformat()
        entry = load_map.get(date_iso)
        load_values.append(entry.get("load_score") if entry else 0.0)
    recent_load = load_values[-7:]
    prev_load = load_values[:-7]
    avg_recent_load = _mean(recent_load)
    avg_prev_load = _mean(prev_load[-21:]) if prev_load else None
    load_momentum = None
    if avg_recent_load is not None and avg_prev_load not in (None, 0):
        load_momentum = ((avg_recent_load - avg_prev_load) / avg_prev_load) * 100
    load_has_data = any(v > 0 for v in load_values)

    hrv_conn = get_hrv_db()
    hrv_cur = hrv_conn.cursor()
    hrv_rows = hrv_cur.execute(
        """
        SELECT COALESCE(date(date_utc), date(ts_measurement)) AS date_iso,
               rmssd
        FROM hrv_measurements
        WHERE (date_utc IS NOT NULL OR ts_measurement IS NOT NULL)
          AND COALESCE(date(date_utc), date(ts_measurement)) BETWEEN ? AND ?
        ORDER BY date_iso ASC
        """,
        (load_window["start_iso"], load_window["end_iso"])
    ).fetchall()
    hrv_conn.close()
    hrv_daily = {}
    for row in hrv_rows:
        date_iso = row["date_iso"]
        rmssd = row["rmssd"]
        if date_iso is None or rmssd is None:
            continue
        hrv_daily.setdefault(date_iso, []).append(float(rmssd))
    hrv_values = []
    hrv_mean_map = {}
    for dt in load_dates:
        date_iso = dt.isoformat()
        vals = hrv_daily.get(date_iso)
        avg = _mean(vals) if vals else None
        hrv_values.append(avg)
        if avg is not None:
            hrv_mean_map[date_iso] = avg
    hrv_mean = _mean([v for v in hrv_values if v is not None])
    recent_hrv = [v for v in hrv_values[-7:] if v is not None]
    prev_hrv = [v for v in hrv_values[:-7] if v is not None][-21:]
    avg_recent_hrv = _mean(recent_hrv)
    avg_prev_hrv = _mean(prev_hrv)
    recovery_delta = None
    if avg_recent_hrv is not None and avg_prev_hrv not in (None, 0):
        recovery_delta = ((avg_recent_hrv - avg_prev_hrv) / avg_prev_hrv) * 100
    recovery_has_data = len(recent_hrv) >= 3 and len(prev_hrv) >= 6

    recovery_strip = []
    for i in range(14):
        dt = strip_start + timedelta(days=i)
        date_iso = dt.isoformat()
        value = hrv_mean_map.get(date_iso)
        status = "neutral"
        if value is not None and hrv_mean is not None:
            if value >= hrv_mean * 1.05:
                status = "ok"
            elif value <= hrv_mean * 0.95:
                status = "bad"
            else:
                status = "warn"
        recovery_strip.append({
            "date_iso": date_iso,
            "status": status,
            "value": value,
        })

    hrv_latest = None
    hrv_conn = get_hrv_db()
    hrv_cur = hrv_conn.cursor()
    latest_row = hrv_cur.execute(
        """
        SELECT date_utc, ts_measurement
        FROM hrv_measurements
        ORDER BY ts_measurement DESC, date_utc DESC
        LIMIT 1
        """
    ).fetchone()
    hrv_conn.close()
    if latest_row:
        hrv_latest = latest_row["date_utc"] or latest_row["ts_measurement"]

    last_logs = {"training": None, "runs": None, "nutrition": None}
    conn = get_training_db()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT date_iso, name
        FROM workouts
        WHERE date_iso IS NOT NULL
        ORDER BY date_iso DESC, id DESC
        LIMIT 1
        """
    )
    row = cur.fetchone()
    conn.close()
    if row:
        last_logs["training"] = {"date_iso": row["date_iso"], "name": row["name"]}
    conn = get_runs_db()
    cur = conn.cursor()
    cur.execute("SELECT date FROM runs ORDER BY date DESC LIMIT 1")
    row = cur.fetchone()
    conn.close()
    if row:
        last_logs["runs"] = {"date": row["date"]}

    conn = get_nutrition_db()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT date_iso
            FROM nutrition_daily
            WHERE kcal IS NOT NULL
            ORDER BY date_iso DESC
            LIMIT 1
            """
        )
    except Exception:
        cur.execute(
            """
            SELECT date_iso
            FROM weight_logs
            WHERE kcal IS NOT NULL
            ORDER BY date_iso DESC
            LIMIT 1
            """
        )
    row = cur.fetchone()
    conn.close()
    if row:
        last_logs["nutrition"] = {"date_iso": row["date_iso"]}

    payload = {
        "ok": True,
        "range": window,
        "plan": {"name": plan.get("name")} if plan else None,
        "plan_week": plan_week,   # NEW
        "today": {
            "session_type": session_type,
            "session_label": session_label,
            "run_session": run_session,
            "day": day,
            "day_index": today_idx,
        },
        "energy": {
            "momentum": energy_momentum,
            "mode": latest_snapshot["mode"],
            "band_low": latest_snapshot["band_low"],
            "band_high": latest_snapshot["band_high"],
            "strip": strip_days,
        },
        "load": {
            "momentum_pct": load_momentum,
            "avg_recent": avg_recent_load,
            "avg_prev": avg_prev_load,
            "has_data": load_has_data,
        },
        "recovery": {
            "delta_pct": recovery_delta,
            "avg_recent": avg_recent_hrv,
            "avg_prev": avg_prev_hrv,
            "has_data": recovery_has_data,
            "strip": recovery_strip,
        },
        "last_logs": last_logs,
        "hrv_latest": hrv_latest,
    }

    if debug:
        payload["debug"] = {
            "avg_kcal_recent": energy_momentum.get("avg_recent"),
            "avg_kcal_prev": energy_momentum.get("avg_prev"),
            "momentum": energy_momentum.get("momentum"),
            "coverage": {
                "recent_days": energy_momentum.get("recent_days"),
                "prev_days": energy_momentum.get("prev_days"),
            },
            "active_mode": latest_snapshot.get("mode"),
            "band_low": latest_snapshot.get("band_low"),
            "band_high": latest_snapshot.get("band_high"),
        }

    return jsonify(payload)


@app.get("/api/dashboard/mcp_context")
def api_dashboard_mcp_context():
    raw_day = (request.args.get("day") or request.args.get("date") or date.today().isoformat()).strip()
    try:
        day_key = date.fromisoformat(raw_day).isoformat()
    except ValueError:
        return jsonify({"ok": False, "error": "invalid_day"}), 400
    return jsonify({"ok": True, "day": day_key, **liva_mcp_day_context(day_key)})



@app.get("/api/dashboard/signals")
def api_dashboard_signals():
    debug = request.args.get("debug") == "1"
    end_date = date.today()
    start_date = end_date - timedelta(days=13)
    start_iso = start_date.isoformat()
    end_iso = end_date.isoformat()
    days = _date_range_list(start_iso, end_iso)
    day_isos = [dt.isoformat() for dt in days]
    WEEKDAY_LETTERS = ["M", "D", "M", "D", "F", "S", "S"]
    weekday_letters = [WEEKDAY_LETTERS[dt.weekday()] for dt in days]
    baseline_days = 28
    baseline_start_iso = (start_date - timedelta(days=baseline_days)).isoformat()

    recovery_rows = _annotate_recovery_rows(_merge_recovery_rows())
    usable_recovery_rows = [row for row in recovery_rows if row.get("usable")]
    recovery_points = []
    debug_reasons = [] if debug else None

    for dt in days:
        date_iso = dt.isoformat()
        row = _choose_recovery_row_for_day(usable_recovery_rows, date_iso) or _choose_recovery_row_for_day(recovery_rows, date_iso)
        if not row:
            recovery_point = {
                "state": "missing",
                "reason": "recovery_missing",
                "score": None,
                "rmssd": None,
                "nightPulse": None,
                "sleepScore": None,
                "flag": None,
                "source": None,
                "status": None,
                "contradiction": False,
            }
            recovery_points.append(recovery_point)
            if debug_reasons is not None:
                debug_reasons.append({"date_iso": date_iso, "reason": "recovery_missing"})
            continue

        baseline = _recovery_baseline(usable_recovery_rows, row, baseline_days)
        readiness = _compute_recovery_readiness(row, baseline)
        status = str(readiness.get("status") or "").strip().upper()
        recovery_score = _to_optional_float(row.get("recovery_score"))
        recovery_status = str(row.get("recovery_status") or "").strip().lower()
        flag = _normalize_hrv_flag(row.get("flag"), row)
        contradiction = bool(readiness.get("contradiction"))

        if recovery_score is None or not row.get("usable"):
            state = "missing"
            reason = "recovery_score_missing"
        elif recovery_status in {"stark", "bereit"}:
            state = "good"
            reason = f"recovery_score_{recovery_status}"
        elif recovery_status == "vorsichtig":
            state = "neutral"
            reason = "recovery_score_vorsichtig"
        elif recovery_status in {"reduziert", "rot"}:
            state = "bad"
            reason = f"recovery_score_{recovery_status}"
        else:
            state = "neutral"
            reason = "recovery_score_unknown"

        recovery_point = {
            "state": state,
            "reason": reason,
            "score": _to_optional_float(row.get("recovery_score")),
            "recoveryScore": _to_optional_float(row.get("recovery_score")),
            "recoveryStatus": recovery_status or None,
            "readinessScore": _to_optional_float(readiness.get("score")),
            "rmssd": _to_optional_float(row.get("rmssd")),
            "nightPulse": _to_optional_float(row.get("nightPulse")),
            "sleepScore": _to_optional_float(row.get("sleepScore")),
            "flag": flag,
            "source": row.get("source"),
            "status": status,
            "contradiction": contradiction,
        }
        recovery_points.append(recovery_point)
        if debug_reasons is not None:
            debug_reasons.append({"date_iso": date_iso, "reason": reason, "source": row.get("source"), "status": status, "flag": flag})

    nutrition_conn = get_nutrition_db()
    _ensure_nutrition_daily_view(nutrition_conn)
    settings = _load_nutrition_settings()
    timeline = _load_nutrition_mode_timeline(nutrition_conn, settings)
    plan_timeline = _load_week_template_target_timeline(nutrition_conn)
    nutrition_rows = _load_nutrition_series(days=90)
    energy_daily = _build_energy_daily(nutrition_rows, settings, timeline)
    energy_map = {row["date_iso"]: row for row in energy_daily}

    run_conn = get_runs_db()
    run_cur = run_conn.cursor()
    run_rows = run_cur.execute(
        """
        SELECT substr(date, 1, 10) AS date_iso,
               SUM(distance) AS distance_m
        FROM runs
        WHERE substr(date, 1, 10) BETWEEN ? AND ?
        GROUP BY substr(date, 1, 10)
        """,
        (start_iso, end_iso)
    ).fetchall()
    run_conn.close()
    run_map = {row["date_iso"]: float(row["distance_m"] or 0) / 1000.0 for row in run_rows if row["date_iso"]}

    gym_conn = get_training_db()
    gym_cur = gym_conn.cursor()
    gym_rows = gym_cur.execute(
        """
        SELECT w.date_iso AS date_iso,
               SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE w.date_iso BETWEEN ? AND ?
        GROUP BY w.date_iso
        """,
        (start_iso, end_iso)
    ).fetchall()
    gym_conn.close()
    gym_map = {row["date_iso"]: float(row["tonnage"] or 0) for row in gym_rows if row["date_iso"]}

    energy_points = []
    energy_debug = [] if debug else None
    for dt in days:
        date_iso = dt.isoformat()
        entry = energy_map.get(date_iso)
        kcal_intake = entry.get("daily_kcal") if entry else None
        target_ctx = _active_planning_target_context_for_date(date_iso) or _target_context_for_date(
            date_iso,
            settings,
            timeline,
            plan_timeline,
            conn=nutrition_conn,
        )
        target_kcal = _parse_float_or_none(target_ctx.get("target_kcal"))
        green_low = _parse_float_or_none(target_ctx.get("green_low"))
        green_high = _parse_float_or_none(target_ctx.get("green_high"))
        yellow_low = _parse_float_or_none(target_ctx.get("yellow_low"))
        yellow_high = _parse_float_or_none(target_ctx.get("yellow_high"))
        band_low = green_low
        band_high = green_high
        state, reason = _energy_state_and_reason(kcal_intake, target_kcal, green_low, green_high, yellow_low, yellow_high)
        diff = (kcal_intake - target_kcal) if kcal_intake is not None and target_kcal is not None else None
        abs_diff = abs(diff) if diff is not None else None
        energy_points.append({
            "state": state,
            "value": kcal_intake,
            "band_low": band_low,
            "band_high": band_high,
            "reason": reason,
            "kcal_intake": kcal_intake,
            "kcal_target": target_kcal,
            "mode": target_ctx.get("mode"),
            "target_source": target_ctx.get("source"),
        })
        if energy_debug is not None:
            energy_debug.append({
                "date_iso": date_iso,
                "active_mode": target_ctx.get("mode"),
                "kcal_intake": kcal_intake,
                "kcal_target": target_kcal,
                "green_low": green_low,
                "green_high": green_high,
                "yellow_low": yellow_low,
                "yellow_high": yellow_high,
                "target_source": target_ctx.get("source"),
                "diff": diff,
                "abs_diff": abs_diff,
                "state": state,
                "reason": reason,
            })
    nutrition_conn.close()

    run_points = []
    for dt in days:
        date_iso = dt.isoformat()
        value = run_map.get(date_iso)
        if value and value > 0:
            state = "present"
            metric = value
        else:
            state = "missing"
            metric = None
        run_points.append({"state": state, "value": metric})

    gym_points = []
    for dt in days:
        date_iso = dt.isoformat()
        value = gym_map.get(date_iso)
        if value and value > 0:
            state = "present"
            metric = value
        else:
            state = "missing"
            metric = None
        gym_points.append({"state": state, "value": metric})

    recovery_day_keys = [str(row.get("date") or "").strip() for row in recovery_rows if str(row.get("date") or "").strip()]
    first_hrv_date = recovery_day_keys[-1] if recovery_day_keys else None
    last_hrv_date = recovery_day_keys[0] if recovery_day_keys else None

    def _avg_non_null(values):
        vals = [v for v in values if v is not None]
        return _mean(vals) if vals else None

    def _last_n_non_null(values, n):
        vals = [v for v in values if v is not None]
        return vals[-n:] if len(vals) >= n else vals

    energy_series = [point.get("value") for point in energy_points]
    energy_nonnull = [v for v in energy_series if v is not None]
    avg_14d = _avg_non_null(energy_series)
    avg_3d_vals = _last_n_non_null(energy_series, 3)
    avg_3d = _mean(avg_3d_vals) if len(avg_3d_vals) >= 3 else None
    trend_diff = (avg_3d - avg_14d) if avg_3d is not None and avg_14d is not None else None
    trend_abs = abs(trend_diff) if trend_diff is not None else None
    if len(energy_nonnull) < 5 or trend_abs is None:
        energy_trend_state = "missing"
    elif trend_abs <= 150:
        energy_trend_state = "good"
    elif trend_abs <= 350:
        energy_trend_state = "neutral"
    else:
        energy_trend_state = "bad"

    recovery_series = [point.get("score") for point in recovery_points]
    recovery_nonnull = [v for v in recovery_series if v is not None]
    recovery_avg_7 = _mean(recovery_nonnull[-7:]) if len(recovery_nonnull) >= 3 else None
    recovery_today = recovery_points[-1].get("score") if recovery_points else None
    recovery_diff = recovery_today - recovery_avg_7 if recovery_today is not None and recovery_avg_7 is not None else None
    recovery_state_today = recovery_points[-1]["state"] if recovery_points else "missing"

    # keep the load signal smooth by decaying the last known training stress instead of dropping to None
    LOAD_DECAY_FACTOR = 0.65
    LOAD_BASELINE_THRESHOLD = 0.2
    LOAD_LOOKBACK_DAYS = 21
    carry_start_date = start_date - timedelta(days=LOAD_LOOKBACK_DAYS)
    carry_start_iso = carry_start_date.isoformat()
    load_rows = _load_load_series(carry_start_iso, end_iso)
    load_map_extended = {
        row["date_iso"]: float(row.get("load_score") or 0.0)
        for row in load_rows
        if row.get("date_iso")
    }

    smoothed_by_date = {}
    trailing_load = None
    reached_baseline = False
    extended_days = _date_range_list(carry_start_iso, end_iso)
    for dt in extended_days:
        date_iso = dt.isoformat()
        combined = load_map_extended.get(date_iso, 0.0)

        smoothed = None
        if combined > 0:
            trailing_load = combined
            reached_baseline = False
            smoothed = combined
        elif trailing_load is not None:
            trailing_load = max(0.0, trailing_load * LOAD_DECAY_FACTOR)
            if trailing_load <= LOAD_BASELINE_THRESHOLD:
                trailing_load = None
                smoothed = 0.0
                reached_baseline = True
            else:
                smoothed = trailing_load
        elif reached_baseline:
            smoothed = 0.0
        else:
            smoothed = None

        smoothed_by_date[date_iso] = smoothed

    load_series = [smoothed_by_date.get(date_iso) for date_iso in day_isos]
    load_max = 0.0
    for date_iso in day_isos:
        combined = load_map_extended.get(date_iso, 0.0)
        if combined > load_max:
            load_max = combined

    payload = {
        "ok": True,
        "start": start_iso,
        "end": end_iso,
        "days": day_isos,
        "weekdays": weekday_letters,
        "lanes": {
            "recovery": recovery_points,
            "energy": energy_points,
            "run_load": run_points,
            "strength": gym_points,
        },
        "context": {
            "energy": {
                "series": energy_series,
                "avg_3d": avg_3d,
                "avg_14d": avg_14d,
                "trend_diff": trend_diff,
                "state": energy_trend_state,
            },
            "recovery": {
                "series": recovery_series,
                "state": recovery_state_today,
                "avg_7d": recovery_avg_7,
                "today": recovery_today,
                "trend_diff": recovery_diff,
            },
            "load": {
                "series": load_series,
                "max": load_max,
            },
        },
    }
    if debug:
        payload["debug"] = {
            "hrv_rows": len(recovery_rows),
            "first_hrv": first_hrv_date,
            "last_hrv": last_hrv_date,
            "recovery_debug": debug_reasons,
            "energy_mode": settings.get("active_mode") or "maintenance",
            "energy_debug": energy_debug,
        }
    return jsonify(payload)


@app.get("/api/dashboard/charts")
def api_dashboard_charts():
    raw_range = (request.args.get("range") or request.args.get("days") or "30").strip().lower()
    window = _dashboard_range_window(raw_range, "0", 30)
    days = window["days"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]
    use_weekly = days > 31

    load_rows = _load_load_series(start_iso, end_iso)
    hrv_conn = get_hrv_db()
    hrv_cur = hrv_conn.cursor()
    hrv_rows = hrv_cur.execute(
        """
        SELECT COALESCE(date(date_utc), date(ts_measurement)) AS date_iso,
               rmssd
        FROM hrv_measurements
        WHERE (date_utc IS NOT NULL OR ts_measurement IS NOT NULL)
          AND COALESCE(date(date_utc), date(ts_measurement)) BETWEEN ? AND ?
        ORDER BY date_iso ASC
        """,
        (start_iso, end_iso)
    ).fetchall()
    hrv_conn.close()
    hrv_series = []
    for row in hrv_rows:
        if row["date_iso"] and row["rmssd"] is not None:
            hrv_series.append({"date_iso": row["date_iso"], "rmssd": float(row["rmssd"])})

    nutrition_rows = _load_nutrition_series(start_iso=start_iso, end_iso=end_iso)

    labels = []
    load_values = []
    recovery_values = []
    kcal_values = []
    weight_values = []

    if use_weekly:
        load_buckets = _aggregate_by_week(load_rows, "load_score", lambda vals: sum(vals) if vals else None)
        hrv_buckets = _aggregate_by_week(hrv_series, "rmssd", _mean)
        kcal_buckets = _aggregate_by_week(nutrition_rows, "calories", _mean)
        weight_buckets = _aggregate_by_week(nutrition_rows, "bodyweight_kg", _mean)

        bucket_map = {}
        for row in load_buckets:
            bucket_map.setdefault(row["bucket"], {})["load"] = row["value"]
            bucket_map[row["bucket"]]["label"] = row["label"]
        for row in hrv_buckets:
            bucket_map.setdefault(row["bucket"], {})["recovery"] = row["value"]
            bucket_map[row["bucket"]]["label"] = bucket_map.get(row["bucket"], {}).get("label") or row["label"]
        for row in kcal_buckets:
            bucket_map.setdefault(row["bucket"], {})["kcal"] = row["value"]
            bucket_map[row["bucket"]]["label"] = bucket_map.get(row["bucket"], {}).get("label") or row["label"]
        for row in weight_buckets:
            bucket_map.setdefault(row["bucket"], {})["weight"] = row["value"]
            bucket_map[row["bucket"]]["label"] = bucket_map.get(row["bucket"], {}).get("label") or row["label"]

        for bucket in sorted(bucket_map.keys()):
            labels.append(bucket_map[bucket].get("label") or bucket)
            load_values.append(bucket_map[bucket].get("load") or 0.0)
            recovery_values.append(bucket_map[bucket].get("recovery"))
            kcal_values.append(bucket_map[bucket].get("kcal"))
            weight_values.append(bucket_map[bucket].get("weight"))
    else:
        days_list = _date_range_list(start_iso, end_iso)
        load_map = {row["date_iso"]: row for row in load_rows}
        hrv_map = {}
        for row in hrv_series:
            hrv_map.setdefault(row["date_iso"], []).append(row["rmssd"])
        kcal_map = {}
        weight_map = {}
        for row in nutrition_rows:
            date_iso = row.get("date_iso")
            if not date_iso:
                continue
            if row.get("calories") is not None:
                kcal_map[date_iso] = row.get("calories")
            if row.get("bodyweight_kg") is not None:
                weight_map[date_iso] = row.get("bodyweight_kg")
        for dt in days_list:
            date_iso = dt.isoformat()
            labels.append(dt.strftime("%d.%m"))
            load_values.append(load_map.get(date_iso, {}).get("load_score") or 0.0)
            rmssd_vals = hrv_map.get(date_iso)
            recovery_values.append(_mean(rmssd_vals) if rmssd_vals else None)
            kcal_values.append(kcal_map.get(date_iso))
            weight_values.append(weight_map.get(date_iso))

        # 7T weight avg for smoother line
        rolling = []
        for idx, _ in enumerate(weight_values):
            window_vals = [v for v in weight_values[max(0, idx - 6): idx + 1] if v is not None]
            rolling.append(_mean(window_vals))
        weight_values = rolling

    prev_window = None
    if raw_range != "all":
        prev_window = _dashboard_range_window(raw_range, str(days), 30)

    recovery_trend = None
    load_trend = None
    if prev_window:
        prev_load_rows = _load_load_series(prev_window["start_iso"], prev_window["end_iso"])
        prev_hrv_conn = get_hrv_db()
        prev_hrv_cur = prev_hrv_conn.cursor()
        prev_hrv_rows = prev_hrv_cur.execute(
            """
            SELECT COALESCE(date(date_utc), date(ts_measurement)) AS date_iso,
                   rmssd
            FROM hrv_measurements
            WHERE (date_utc IS NOT NULL OR ts_measurement IS NOT NULL)
              AND COALESCE(date(date_utc), date(ts_measurement)) BETWEEN ? AND ?
            ORDER BY date_iso ASC
            """,
            (prev_window["start_iso"], prev_window["end_iso"])
        ).fetchall()
        prev_hrv_conn.close()

        current_load_avg = _mean([row.get("load_score") for row in load_rows if row.get("load_score") is not None])
        prev_load_avg = _mean([row.get("load_score") for row in prev_load_rows if row.get("load_score") is not None])
        if current_load_avg is not None and prev_load_avg not in (None, 0):
            load_trend = ((current_load_avg - prev_load_avg) / prev_load_avg) * 100

        current_hrv_avg = _mean([row.get("rmssd") for row in hrv_series if row.get("rmssd") is not None])
        prev_hrv_avg = _mean([row["rmssd"] for row in prev_hrv_rows if row["rmssd"] is not None])
        if current_hrv_avg is not None and prev_hrv_avg not in (None, 0):
            recovery_trend = ((current_hrv_avg - prev_hrv_avg) / prev_hrv_avg) * 100

    nutrition_conn = get_nutrition_db()
    _ensure_nutrition_daily_view(nutrition_conn)
    settings = _load_nutrition_settings()
    timeline = _load_nutrition_mode_timeline(nutrition_conn, settings)
    nutrition_conn.close()
    energy_daily = _build_energy_daily(nutrition_rows, settings, timeline)
    heat_map = {row["date_iso"]: row for row in energy_daily}

    end_dt = _parse_iso(end_iso) or date.today()
    heatstrip = []
    for i in range(6, -1, -1):
        dt = end_dt - timedelta(days=i)
        date_iso = dt.isoformat()
        entry = heat_map.get(date_iso)
        status = entry.get("daily_status") if entry else "neutral"
        heatstrip.append({
            "date_iso": date_iso,
            "status": status,
            "kcal": entry.get("daily_kcal") if entry else None,
        })

    protein_rows = [row for row in nutrition_rows if row.get("protein_g") is not None]
    weight_vals = [row.get("bodyweight_kg") for row in nutrition_rows if row.get("bodyweight_kg") is not None]
    avg_weight = _mean(weight_vals)
    protein_hits = 0
    protein_total = 0
    protein_window_start = end_dt - timedelta(days=6)
    for row in nutrition_rows:
        dt = _parse_iso(row.get("date_iso"))
        if not dt or dt < protein_window_start or dt > end_dt:
            continue
        protein = row.get("protein_g")
        if protein is None:
            continue
        protein_total += 1
        ref_weight = row.get("bodyweight_kg") or avg_weight
        if ref_weight and protein >= ref_weight * 2.0:
            protein_hits += 1

    return jsonify({
        "ok": True,
        "range": window,
        "bucket": "week" if use_weekly else "day",
        "labels": labels,
        "load": load_values,
        "recovery": recovery_values,
        "kcal": kcal_values,
        "weight": weight_values,
        "trends": {
            "recovery_pct": recovery_trend,
            "load_pct": load_trend,
        },
        "nutrition": {
            "heatstrip": heatstrip,
            "protein_hits": protein_hits,
            "protein_total": protein_total,
        }
    })


@app.get("/api/dashboard/plan")
def api_dashboard_plan():
    plan_row = _get_active_plan_row()
    if not plan_row:
        return jsonify({"ok": False, "error": "no_active_plan"}), 404
    plan = plan_row_to_dict(plan_row)

    today_idx = date.today().weekday()
    base_week = plan.get("base_week") or []
    events = []
    for offset in range(0, len(base_week) * 2):
        if len(events) >= 3:
            break
        idx = (today_idx + offset) % len(base_week) if base_week else 0
        day = base_week[idx] if base_week else {}
        event_date = date.today() + timedelta(days=offset)

        run_sessions = day.get("run_sessions") or []
        strength = day.get("strength_exercises") or []
        session_name = (day.get("session_name") or "").strip()

        if run_sessions:
            run_label = _format_run_label(run_sessions[0].get("run_type") if isinstance(run_sessions[0], dict) else None)
            events.append({
                "type": "run",
                "label": run_label,
                "date_iso": event_date.isoformat(),
            })
        if strength or session_name:
            gym_label = session_name or "Gym"
            events.append({
                "type": "gym",
                "label": gym_label,
                "date_iso": event_date.isoformat(),
            })
        if not run_sessions and not strength and not session_name and len(events) < 3:
            events.append({
                "type": "rest",
                "label": "Rest",
                "date_iso": event_date.isoformat(),
            })

    last_gym = None
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    row = cur.execute(
        """
        SELECT id, name, date_iso
        FROM workouts
        WHERE date_iso IS NOT NULL
        ORDER BY date_iso DESC, id DESC
        LIMIT 1
        """
    ).fetchone()
    if row:
        sets = cur.execute(
            """
            SELECT s.weight, s.reps
            FROM sets s
            JOIN exercises e ON e.id = s.exercise_id
            WHERE e.workout_id = ?
            """,
            (row["id"],),
        ).fetchall()
        tonnage = 0.0
        for s in sets:
            if s["weight"] is not None and s["reps"] is not None:
                tonnage += float(s["weight"]) * float(s["reps"])
        last_gym = {
            "date_iso": row["date_iso"],
            "name": row["name"],
            "tonnage": tonnage if sets else None,
        }
    conn.close()

    last_run = None
    conn = get_runs_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    row = cur.execute(
        """
        SELECT date, distance, pace
        FROM runs
        ORDER BY date DESC
        LIMIT 1
        """
    ).fetchone()
    conn.close()
    if row:
        last_run = {
            "date": row["date"],
            "distance_m": row["distance"],
            "pace_s": row["pace"],
        }

    sessions = _plan_strength_sessions(plan)
    today_info, _ = _today_plan_default(sessions, plan, debug=False)

    return jsonify({
        "ok": True,
        "plan": {"name": plan.get("name")},
        "next": events[:3],
        "last_gym": last_gym,
        "last_run": last_run,
        "plan_check": {
            "sessions": sessions,
            "default_session_key": today_info.get("default_session_key"),
            "default_session_name": today_info.get("default_session_name"),
            "today_session_key": today_info.get("today_session_key"),
        },
    })


@app.get("/api/dashboard/block_status")
def api_dashboard_block_status():
    active_gym = _get_active_gym_plan_record()
    if not active_gym:
        return jsonify(
            {
                "ok": True,
                "has_plan": False,
                "plan_name": "Kein aktiver Block",
                "block_week": None,
                "block_weeks_total": None,
                "phase": "OFF",
                "badge": "NO PLAN",
                "badge_reason": "",
                "status_line": "Kein aktiver Plan",
                "job_line": "Job: Plan wählen und aktivieren.",
                "chip_guardrail": "",
                "chip_expectation": "",
                "days_to_deload": None,
                "last_week_before_deload": False,
                "hrv_expected": None,
                "hrv_observed": "keine Daten",
                "hrv_verdict": "neutral",
                "hrv_line": "HRV: keine Daten",
                "mission": "Wähle einen Plan oder aktiviere Autopilot.",
                "rules": [],
                "expectation": "Ohne aktiven Block gibt es keine Zykluslogik.",
                "milestone": "Plan aktivieren.",
                "tripwire": "Mehrere Einheiten ohne Planbezug.",
                "action": "Aktiven Plan setzen.",
                "partial": False,
            }
        )

    plan_json = active_gym.get("plan_json") if isinstance(active_gym.get("plan_json"), dict) else {}
    rules_json = active_gym.get("rules_json") if isinstance(active_gym.get("rules_json"), dict) else {}
    cycle = _gym_plan_cycle_status(plan_json, rules_json)
    periodization_enabled = bool((plan_json.get("meta") or {}).get("periodization_enabled"))
    phase = _normalize_block_phase(cycle.get("phase_label"))
    phase_tpl = _BLOCK_STATUS_PHASE_TEMPLATES.get(phase, _BLOCK_STATUS_PHASE_TEMPLATES["BUILD"])
    plan_name = active_gym.get("title") or active_gym.get("name") or "Gym Plan"

    week_label = str(cycle.get("week_label") or "W1")
    rules_weeks = rules_json.get("weeks") if isinstance(rules_json.get("weeks"), dict) else {}
    week_row = rules_weeks.get(week_label) if isinstance(rules_weeks.get(week_label), dict) else {}
    rules = _block_status_rules(phase_tpl.get("rules") or [], week_row)
    last_week_before_deload, days_to_deload = _block_status_last_week_before_deload(
        cycle, plan_json, rules_json, today=date.today()
    )

    legacy_plan_row = _get_active_plan_row()
    legacy_plan_id = int(legacy_plan_row["id"]) if legacy_plan_row and legacy_plan_row["id"] is not None else None
    events = _block_status_event_snapshot(legacy_plan_id, today=date.today())
    badge_reason = str(events.get("drift_reason") or "").strip()
    badge = "DRIFT" if badge_reason else "CONSISTENT"

    tripwire = str(phase_tpl.get("tripwire") or "").strip()
    action = str(phase_tpl.get("action") or "").strip()
    if badge == "DRIFT":
        if badge_reason == "Autopilot überstimmt":
            tripwire = "Autopilot wurde wiederholt überstimmt."
            action = "Autopilot-Entscheidungen akzeptieren oder Modus bewusst wechseln."
        elif badge_reason == "Targets übersteuert":
            tripwire = "Targets wurden manuell übersteuert."
            action = "Volumen/Intensität wieder auf Plan-Caps setzen."
        elif badge_reason == "Overrides häufen sich":
            tripwire = "Overrides häufen sich (≥3 in 7 Tagen)."
            action = "Plan nicht manuell eskalieren, Volumen/Intensität deckeln."
        elif badge_reason == "RPE-Cap wiederholt gebrochen":
            tripwire = "RPE-Cap wurde wiederholt gebrochen."
            action = "Volumen/Intensität deckeln und nächste Sessions strikt unter Cap halten."

    partial = False
    if not str(active_gym.get("title") or active_gym.get("name") or "").strip():
        partial = True
    if cycle.get("week_current") is None or cycle.get("week_total") is None:
        partial = True

    chip_guardrail = _block_status_chip_guardrail(week_row)
    chip_expectation = _block_status_chip_expectation(phase, last_week_before_deload=last_week_before_deload)
    hrv_fit = _block_status_hrv_fit(phase=phase, last_week_before_deload=last_week_before_deload)

    return jsonify(
        {
            "ok": True,
            "has_plan": True,
            "plan_name": plan_name,
            "block_week": int(cycle.get("week_current") or 1) if periodization_enabled else None,
            "block_weeks_total": int(cycle.get("week_total") or 1) if periodization_enabled else None,
            "phase": phase if periodization_enabled else "",
            "badge": badge,
            "badge_reason": badge_reason,
            "status_line": _block_status_status_line(plan_name, cycle, phase, days_to_deload=days_to_deload) if periodization_enabled else plan_name,
            "job_line": _block_status_job_line(phase, last_week_before_deload=last_week_before_deload) if periodization_enabled else "",
            "chip_guardrail": chip_guardrail if periodization_enabled else "",
            "chip_expectation": chip_expectation if periodization_enabled else "",
            "days_to_deload": days_to_deload if periodization_enabled else None,
            "last_week_before_deload": last_week_before_deload if periodization_enabled else False,
            "hrv_expected": hrv_fit.get("expected"),
            "hrv_observed": hrv_fit.get("observed"),
            "hrv_verdict": hrv_fit.get("verdict"),
            "hrv_line": hrv_fit.get("line"),
            "mission": str(phase_tpl.get("mission") or "").strip() if periodization_enabled else "",
            "rules": rules if periodization_enabled else [],
            "expectation": _block_status_expectation_text(phase, cycle, plan_json, rules_json, today=date.today()) if periodization_enabled else "",
            "milestone": _block_status_milestone_text(phase, cycle, plan_json, rules_json, today=date.today()) if periodization_enabled else "",
            "tripwire": tripwire if periodization_enabled else "",
            "action": action if periodization_enabled else "",
            "partial": partial,
            "events": {
                "recent_checks": int(events.get("recent_checks") or 0),
                "recent_violations": int(events.get("recent_violations") or 0),
                "override_count_7d": int(events.get("override_count_7d") or 0),
                "override_by_type": events.get("override_by_type") or {},
                "rpe_cap_violations": int(events.get("rpe_cap_violations") or 0),
                "rpe_cap_violations_7d": int(events.get("rpe_cap_violations_7d") or 0),
                "rpe_cap_max_breach": float(events.get("rpe_cap_max_breach") or 0.0),
                "volume_over_violations": int(events.get("volume_over_violations") or 0),
                "extra_violations": int(events.get("extra_violations") or 0),
                "extra_volume_two_sessions": bool(events.get("extra_volume_two_sessions")),
                "escalated_two_sessions": bool(events.get("escalated_two_sessions")),
                "rule_break_detected": bool(events.get("rule_break_detected")),
            },
        }
    )


def _dashboard_control_plane_payload(day_iso: str | None = None) -> dict:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    try:
        date.fromisoformat(day_key)
    except Exception:
        day_key = date.today().isoformat()

    active_gym = _get_active_gym_plan_record()
    cycle = {}
    week_row = {}
    phase = "OFF"
    plan_name = ""
    if isinstance(active_gym, dict):
        plan_name = str(active_gym.get("title") or active_gym.get("name") or "").strip()
        plan_json = active_gym.get("plan_json") if isinstance(active_gym.get("plan_json"), dict) else {}
        rules_json = active_gym.get("rules_json") if isinstance(active_gym.get("rules_json"), dict) else {}
        cycle = _gym_plan_cycle_status(plan_json, rules_json)
        phase = _normalize_block_phase(cycle.get("phase_label"))
        week_label = str(cycle.get("week_label") or "W1")
        rules_weeks = rules_json.get("weeks") if isinstance(rules_json.get("weeks"), dict) else {}
        week_row = rules_weeks.get(week_label) if isinstance(rules_weeks.get(week_label), dict) else {}

    week_rpe_cap = None
    week_strength_factor = 1.0
    week_run_factor = 1.0
    try:
        week_rpe_cap = float(week_row.get("rpe_cap")) if week_row.get("rpe_cap") is not None else None
    except Exception:
        week_rpe_cap = None
    try:
        week_strength_factor = float(week_row.get("strength_factor")) if week_row.get("strength_factor") is not None else 1.0
    except Exception:
        week_strength_factor = 1.0
    try:
        week_run_factor = float(week_row.get("run_factor")) if week_row.get("run_factor") is not None else 1.0
    except Exception:
        week_run_factor = 1.0

    kienzl_dec = None
    try:
        with timed_block("dashboard.control_plane.kienzl_decision"):
            from kienzl import kienzl as _kienzl
            dec = _kienzl.get_decision(day_key)
            if isinstance(dec, dict):
                kienzl_dec = dec
    except Exception:
        kienzl_dec = None

    kienzl_mode = str((kienzl_dec or {}).get("mode") or "").strip().upper() if isinstance(kienzl_dec, dict) else ""
    kienzl_intensity = None
    kienzl_volume = None
    kienzl_rpe_cap = None
    if isinstance(kienzl_dec, dict):
        try:
            kienzl_intensity = float(kienzl_dec.get("intensity_factor")) if kienzl_dec.get("intensity_factor") is not None else None
        except Exception:
            kienzl_intensity = None
        try:
            kienzl_volume = float(kienzl_dec.get("volume_factor")) if kienzl_dec.get("volume_factor") is not None else None
        except Exception:
            kienzl_volume = None
        try:
            kienzl_rpe_cap = float(kienzl_dec.get("rpe_cap")) if kienzl_dec.get("rpe_cap") is not None else None
        except Exception:
            kienzl_rpe_cap = None

    final_gym_rpe_cap = None
    if week_rpe_cap is not None and kienzl_rpe_cap is not None:
        final_gym_rpe_cap = min(float(week_rpe_cap), float(kienzl_rpe_cap))
    elif week_rpe_cap is not None:
        final_gym_rpe_cap = float(week_rpe_cap)
    elif kienzl_rpe_cap is not None:
        final_gym_rpe_cap = float(kienzl_rpe_cap)

    final_strength_volume_factor = None
    if kienzl_volume is not None:
        final_strength_volume_factor = float(kienzl_volume)
    else:
        final_strength_volume_factor = float(week_strength_factor)

    execution = {
        "session_kind": None,
        "session_name": None,
        "run_kind": None,
        "run_duration_min": None,
        "selected_day_id": day_key,
        "reason_codes": [],
    }

    return {
        "ok": True,
        "as_of_day": day_key,
        "roles": {
            "periodization": "guardrails",
            "kienzl": "readiness_adjustments",
            "training": "execution",
        },
        "cycle": {
            "has_plan": bool(active_gym),
            "plan_name": plan_name,
            "phase": phase,
            "week_label": str(cycle.get("week_label") or "W1") if isinstance(cycle, dict) else "W1",
            "week_current": (int(cycle.get("week_current")) if isinstance(cycle, dict) and cycle.get("week_current") is not None else None),
            "week_total": (int(cycle.get("week_total")) if isinstance(cycle, dict) and cycle.get("week_total") is not None else None),
            "deload": bool(week_row.get("deload")) if isinstance(week_row, dict) else False,
        },
        "governor": {
            "week_rpe_cap": week_rpe_cap,
            "week_strength_factor": week_strength_factor,
            "week_run_factor": week_run_factor,
            "kienzl_mode": kienzl_mode or None,
            "kienzl_intensity_factor": kienzl_intensity,
            "kienzl_volume_factor": kienzl_volume,
            "kienzl_rpe_cap": kienzl_rpe_cap,
            "final_gym_rpe_cap": final_gym_rpe_cap,
            "final_strength_volume_factor": final_strength_volume_factor,
        },
        "execution": execution,
    }


def _invoke_view_json(path: str, view_func) -> Any:
    try:
        with app.test_request_context(path):
            resp = view_func()
        if isinstance(resp, tuple):
            resp = resp[0]
        if hasattr(resp, "get_json"):
            return resp.get_json(silent=True)
    except Exception:
        return None
    return None


_SNAPSHOT_TTLS = {
    "dashboard_snapshot": 30,
    "today_snapshot": 30,
    "next_session_snapshot": 30,
    "training_today_card_snapshot": 30,
    "training_snapshot": 120,
    "remote_snapshot": 15,
}

_TEST_UI_WRITE_METHODS = {"POST", "PUT", "PATCH", "DELETE"}


