def _format_de_unit_label(unit: Any) -> str:
    raw = str(unit or "").strip()
    if not raw:
        return ""
    normalized = raw.lower()
    if normalized == "pcs":
        return "Stk."
    return raw


def _test_ui_url(path: str) -> str:
    raw = str(path or "").strip() or "/"
    return raw if raw.startswith("/") else f"/{raw}"

_SNAPSHOT_WARMUP_LOCK = threading.Lock()
_SNAPSHOT_WARMED = False
_MEALPLAN_WARMUP_DAY = ""
_MEALPLAN_WARMUP_LOCK = threading.Lock()


def _snapshot_json_response(payload: dict[str, Any], *, max_age: int = 5):
    response = jsonify(payload)
    response.headers["Cache-Control"] = f"private, max-age={max(0, int(max_age))}, stale-while-revalidate=30"
    generated_at = str((payload or {}).get("generated_at") or "").strip()
    if generated_at:
        try:
            response.set_etag(hashlib.sha1(generated_at.encode("utf-8")).hexdigest())
            response.last_modified = datetime.fromisoformat(generated_at.replace("Z", "+00:00"))
        except Exception:
            pass
    return response


def _schedule_snapshot_warmup() -> None:
    global _SNAPSHOT_WARMED, _MEALPLAN_WARMUP_DAY
    if bool(app.config.get("TESTING")) or os.environ.get("PYTEST_CURRENT_TEST"):
        return
    if _SNAPSHOT_WARMED:
        return
    with _SNAPSHOT_WARMUP_LOCK:
        if _SNAPSHOT_WARMED:
            return
        _SNAPSHOT_WARMED = True
    today_key = date.today().isoformat()

    def _runner() -> None:
        global _MEALPLAN_WARMUP_DAY
        tasks = [
            (
                f"dashboard_snapshot:{today_key}",
                lambda: _build_dashboard_snapshot(today_key),
                _SNAPSHOT_TTLS["dashboard_snapshot"],
                {"route": "warmup", "snapshot": "dashboard_snapshot", "day": today_key},
            ),
            (
                f"today_snapshot:{today_key}",
                lambda: _build_today_snapshot(today_key),
                _SNAPSHOT_TTLS["today_snapshot"],
                {"route": "warmup", "snapshot": "today_snapshot", "day": today_key},
            ),
            (
                f"next_session_snapshot:{today_key}:0",
                lambda: _build_next_session_snapshot(today_key, False),
                _SNAPSHOT_TTLS["next_session_snapshot"],
                {"route": "warmup", "snapshot": "next_session_snapshot", "day": today_key},
            ),
            (
                "training_snapshot",
                _build_training_page_snapshot,
                _SNAPSHOT_TTLS["training_snapshot"],
                {"route": "warmup", "snapshot": "training_snapshot"},
            ),
            (
                "remote_snapshot",
                _build_remote_page_snapshot,
                _SNAPSHOT_TTLS["remote_snapshot"],
                {"route": "warmup", "snapshot": "remote_snapshot"},
            ),
        ]
        for snapshot_key, builder, ttl_seconds, meta in tasks:
            try:
                build_snapshot(snapshot_key, builder=builder, ttl_seconds=ttl_seconds, meta=meta)
            except Exception:
                app.logger.exception("snapshot warmup failed: %s", snapshot_key)

        if _MEALPLAN_WARMUP_DAY != today_key:
            with _MEALPLAN_WARMUP_LOCK:
                if _MEALPLAN_WARMUP_DAY != today_key:
                    _MEALPLAN_WARMUP_DAY = today_key
                    try:
                        from nutrition.nutrition_planning_api import build_today_plan_payload
                        build_today_plan_payload(include_items=True, bypass_cache=False)
                    except Exception:
                        app.logger.exception("mealplan warmup failed")

    threading.Thread(target=_runner, name="snapshot-warmup", daemon=True).start()


@app.before_request
def _prime_ui_snapshots_once():
    if str(request.path or "").startswith("/static/"):
        return None
    try:
        _schedule_snapshot_warmup()
    except Exception:
        app.logger.exception("snapshot warmup scheduling failed")


def _build_dashboard_snapshot(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    partial = False
    data: dict[str, Any] = {"ok": True, "day": day_key}

    def _load(name: str, fn, path: str, *, default: Any = None):
        nonlocal partial
        payload = _invoke_view_json(path, fn)
        if payload is None:
            partial = True
            return default
        return payload

    with timed_block("dashboard.snapshot.build", day=day_key):
        data["settings"] = _load("settings", api_settings, "/api/settings", default={})
        data["makrosSettings"] = _load("makrosSettings", api_makros_settings, "/api/makros/settings", default={})
        data["makrosSeries"] = _load("makrosSeries", api_makros_series, "/api/makros/series?days=60", default={})
        data["hrvLatest"] = _load("hrvLatest", api_hrv_latest, "/api/hrv/latest", default={})
        data["hrvSeries"] = _load("hrvSeries", api_hrv_series, "/api/hrv/series?days=60", default={})
        data["trainingCurrent"] = _load("trainingCurrent", api_dashboard_training_summary, "/api/dashboard/training_summary?days=30", default={})
        data["trainingDouble"] = _load("trainingDouble", api_dashboard_training_summary, "/api/dashboard/training_summary?days=60", default={})
        data["trainingWeek"] = _load("trainingWeek", api_dashboard_training_summary, "/api/dashboard/training_summary?days=7", default={})
        data["runsCurrent"] = _load("runsCurrent", api_dashboard_runs_summary, "/api/dashboard/runs_summary?days=30", default={})
        data["runsDouble"] = _load("runsDouble", api_dashboard_runs_summary, "/api/dashboard/runs_summary?days=60", default={})
        plans_payload = _load("plans", api_list_plans, "/api/plans", default=[])
    data["plans"] = plans_payload if isinstance(plans_payload, list) else []
    data["planWeek"] = _load("planWeek", api_dashboard_plan_check_week_overview, f"/api/dashboard/plan_check_week_overview?day={day_key}", default={})
    with timed_block("dashboard.snapshot.next_session_embed", day=day_key):
        next_session_payload = get_snapshot(
            f"next_session_snapshot:{day_key}:0",
            builder=lambda: _build_next_session_snapshot(day_key, False),
            ttl_seconds=_SNAPSHOT_TTLS["next_session_snapshot"],
            allow_stale=False,
            background_refresh=False,
            meta={"route": "dashboard_snapshot_embed", "day": day_key, "explain": False},
            fallback_payload=_next_session_snapshot_fallback(day_key),
        )
    next_session_payload = dict(next_session_payload or {})
    next_session_payload.pop("status_code", None)
    data["nextSession"] = next_session_payload
    data["lastLogs"] = _load("lastLogs", api_dashboard_last_logs, "/api/dashboard/last_logs", default={})
    data["signals14"] = _load("signals14", api_dashboard_signals, "/api/dashboard/signals?days=14", default={})
    data["today"] = _load("today", api_dashboard_today, f"/api/dashboard/today?day={day_key}", default={})
    try:
        from nutrition.nutrition_planning_api import api_nutrition_logging_day

        data["mealplanToday"] = _load(
            "mealplanToday",
            api_nutrition_logging_day,
            f"/api/nutrition/logging/day?date={day_key}",
            default={},
        )
    except Exception:
        data["mealplanToday"] = {}
        partial = True
    with timed_block("dashboard.snapshot.today_agenda", day=day_key):
        data["todayAgenda"] = _build_today_agenda_payload(day_key)
    data["controlPlane"] = _load("controlPlane", api_dashboard_control_plane, f"/api/dashboard/control_plane?day={day_key}", default={})
    data["blockStatus"] = _load("blockStatus", api_dashboard_block_status, "/api/dashboard/block_status", default={})
    data["enduranceApproval"] = _load("enduranceApproval", api_dashboard_endurance_approval, f"/api/dashboard/endurance-approval?day={day_key}", default={})
    data["coreDecisionCard"] = _load("coreDecisionCard", api_core_decision_card, f"/api/core/decision_card?day={day_key}", default={})
    data["coreDashboardCard"] = _load("coreDashboardCard", api_core_dashboard_card_v3, f"/api/core/dashboard_card_v3?day={day_key}", default={})
    # Training cards have one canonical source: the GPT decision read model
    # below.  Keep the legacy key empty for old clients, but never let a
    # persisted CORE/autopilot card compete with the GPT card again.
    data["coreTrainingCard"] = None
    data["trainingTodayCard"] = get_snapshot(
        f"training_today_card_snapshot:{day_key}",
        builder=lambda: _build_training_today_card_snapshot(day_key),
        ttl_seconds=_SNAPSHOT_TTLS["training_today_card_snapshot"],
        allow_stale=True,
        background_refresh=True,
        meta={"route": "dashboard_training_today_card_embed", "day": day_key},
        fallback_payload=_training_today_card_snapshot_fallback(day_key),
    )
    data["partial"] = partial
    return data


def _build_today_snapshot(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    payload = _invoke_view_json(f"/api/dashboard/today?day={day_key}", api_dashboard_today) or {"ok": False}
    payload["partial"] = not bool(payload.get("ok"))
    return payload


def _build_next_session_snapshot(day_iso: str | None = None, explain: bool = False) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    query = f"/api/next_session?day={day_key}"
    if explain:
        query = f"{query}&explain=1"
    started = perf_counter()
    try:
        with timed_block("next_session.snapshot.build", day=day_key, explain=bool(explain)):
            with app.test_request_context(query):
                resp = _autopilot_plan_check_payload()
        payload, status = resp if isinstance(resp, tuple) else (resp, 200)
    except Exception:
        app.logger.exception("build next session snapshot failed")
        payload = None
        status = 500
    if not isinstance(payload, dict):
        payload = {
            "ok": False,
            "error": "next_session_failed",
            "selected_day_id": day_key,
            "week_days": [],
            "session": {"session_name": "Error", "session_key": "", "meta": {"autopilot": True}},
            "items": [],
            "summary": {"flags": ["ERROR"], "status": "red"},
        }
    payload["ok"] = bool(payload.get("ok", False)) and int(status) < 500
    payload["items"] = list(payload.get("items") or [])
    payload["partial"] = not bool(payload.get("ok"))
    payload["status_code"] = int(status)
    record_timing("next_session.snapshot.total", perf_counter() - started, day=day_key, explain=bool(explain), status=int(status))
    return payload


def _dashboard_snapshot_fallback(day_iso: str) -> dict[str, Any]:
    return {
        "ok": True,
        "day": day_iso,
        "loading": True,
        "settings": {},
        "makrosSettings": {},
        "makrosSeries": {"data": []},
        "hrvLatest": {},
        "hrvSeries": {"data": []},
        "trainingCurrent": {},
        "trainingDouble": {},
        "trainingWeek": {},
        "runsCurrent": {},
        "runsDouble": {},
        "plans": [],
        "planWeek": {},
        "nextSession": _next_session_snapshot_fallback(day_iso),
        "lastLogs": {},
        "signals14": {"days": []},
        "today": {},
        "todayAgenda": {"ok": False, "day": day_iso, "items": []},
        "controlPlane": {},
        "blockStatus": {},
        "coreDecisionCard": {},
        "coreDashboardCard": {},
        "trainingTodayCard": _training_today_card_snapshot_fallback(day_iso),
        "partial": True,
    }


def _training_today_card_snapshot_fallback(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    return {
        "ok": False,
        "date": day_key,
        "status": "loading",
        "title": "Nächste geplante Einheit · —",
        "subtitle": "Letzte Ausführung: —",
        "source_label": "GPT-Coaching",
        "headline": "GPT-Coaching wird vorbereitet …",
        "global_note": None,
        "items": [],
        "fallback": {"visible": False, "message": None},
    }


def _build_training_today_card_snapshot(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    started = perf_counter()
    try:
        payload = {"ok": True, **_training_today_card_payload(day_key)}
    except Exception:
        app.logger.exception("build training today card snapshot failed")
        payload = _training_today_card_snapshot_fallback(day_key)
        payload["status"] = "failed"
        payload["headline"] = "GPT-Coaching konnte nicht geladen werden."
        payload["fallback"] = {"visible": True, "message": "GPT-Entscheidung konnte gerade nicht geladen werden."}
    record_timing("training_today_card.snapshot.total", perf_counter() - started, day=day_key, ok=bool(payload.get("ok")))
    return payload


@app.get("/api/dashboard/training_today_card")
def api_dashboard_training_today_card():
    day_iso = (request.args.get("date") or request.args.get("day") or "").strip() or date.today().isoformat()
    try:
        payload = get_snapshot(
            f"training_today_card_snapshot:{day_iso}",
            builder=lambda: _build_training_today_card_snapshot(day_iso),
            ttl_seconds=_SNAPSHOT_TTLS["training_today_card_snapshot"],
            allow_stale=True,
            background_refresh=True,
            meta={"route": "/api/dashboard/training_today_card", "day": day_iso},
            fallback_payload=_training_today_card_snapshot_fallback(day_iso),
        )
        return jsonify(payload)
    except Exception:
        app.logger.exception("dashboard training_today_card failed")
        payload = _training_today_card_snapshot_fallback(day_iso)
        payload["status"] = "failed"
        payload["headline"] = "GPT-Coaching konnte nicht geladen werden."
        payload["fallback"] = {"visible": True, "message": "GPT-Entscheidung konnte gerade nicht geladen werden."}
        return jsonify(payload), 200


def _dashboard_bootstrap_payload(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    _schedule_snapshot_warmup()
    with timed_block("dashboard.bootstrap.snapshot", day=day_key):
        payload = get_snapshot(
            f"dashboard_snapshot:{day_key}",
            builder=lambda: _build_dashboard_snapshot(day_key),
            ttl_seconds=_SNAPSHOT_TTLS["dashboard_snapshot"],
            allow_stale=True,
            background_refresh=True,
            meta={"route": "dashboard_html_bootstrap", "day": day_key},
            fallback_payload=_dashboard_snapshot_fallback(day_key),
        )
    if not isinstance(payload, dict):
        return _dashboard_snapshot_fallback(day_key)
    return payload


def _dashboard_initial_mealplan() -> dict[str, Any]:
    payload = None
    try:
        from nutrition.nutrition_planning_api import read_cached_today_plan_payload

        payload = read_cached_today_plan_payload(include_items=True)
    except Exception:
        payload = None
    result: dict[str, Any] = {
        "date_label": "--",
        "rows": [],
        "has_core": False,
    }
    if not isinstance(payload, dict):
        return result

    weekday = str(payload.get("weekday") or "").strip()
    date_iso = str(payload.get("date") or "").strip()
    parts = date_iso.split("-")
    if weekday and len(parts) >= 3:
        result["date_label"] = f"{weekday}, {parts[2]}.{parts[1]}."

    meals = payload.get("meals") if isinstance(payload.get("meals"), list) else []
    next_open = (((payload.get("core_nutrition") or {}).get("nutrition_state") or {}).get("next_open_meal") or {})
    next_slot_id = int(next_open.get("slot_id") or 0) if isinstance(next_open, dict) else 0

    rows: list[dict[str, Any]] = []
    for idx, meal in enumerate(meals):
        if not isinstance(meal, dict):
            continue
        state = str(meal.get("state") or "").strip().lower()
        status = str(meal.get("status") or "").strip().lower()
        source = str(meal.get("source_of_truth") or meal.get("status_source") or "").strip().lower()
        mutated = bool(meal.get("core_adjusted_time") or meal.get("core_adjusted_name") or str(meal.get("last_mutation_type") or "").strip())
        display_state = "open"
        if state == "logged" or status in {"logged", "telegram_confirmed", "changed", "manual_override"}:
            display_state = "done"
        elif state == "replaced":
            display_state = "replaced"
        elif state in {"fulfilled_by_alternative", "cancelled_by_replan", "merged_into_other_meal"}:
            display_state = "historical"
        elif state == "skipped" or status in {"skipped", "missed"}:
            display_state = "skipped"
        elif state in {"shifted_by_core", "portion_adjusted_by_core", "accepted_adjustment", "switched"} or status in {"shifted", "adjusted_by_core"} or (mutated and source == "core"):
            display_state = "adjusted"
        rows.append(
            {
                "slot_id": int(meal.get("slot_id") or 0),
                "time": str(meal.get("time") or meal.get("time_text") or meal.get("core_adjusted_time") or meal.get("base_time") or "").strip() or "—",
                "name": str(meal.get("name") or meal.get("title") or meal.get("core_adjusted_name") or meal.get("base_name") or "Meal").strip() or "Meal",
                "items_inline": " · ".join(
                    [
                        (
                            f"{str(item.get('name') or '').strip()} "
                            f"{str(int(item.get('amount'))) if isinstance(item.get('amount'), (int, float)) and float(item.get('amount')).is_integer() else str(item.get('amount') or '').strip()} "
                            f"{_format_de_unit_label(item.get('unit'))}"
                        ).strip()
                        for item in (meal.get("items") if isinstance(meal.get("items"), list) else [])
                        if isinstance(item, dict) and str(item.get("name") or "").strip()
                    ][:8]
                ),
                "state": display_state,
                "badge": (
                    "DONE" if display_state == "done" else
                    "ANGEPASST" if display_state == "adjusted" else
                    "RAUS" if display_state == "skipped" else
                    "ERSETZT" if display_state == "replaced" else
                    "HISTORIE" if display_state == "historical" else
                    ""
                ),
                "sort_index": idx,
            }
        )

    if next_slot_id:
        for row in rows:
            if int(row["slot_id"]) == next_slot_id and row["state"] in {"open", "adjusted"}:
                row["state"] = "next_up"
                if row["badge"] == "ANGEPASST":
                    row["badge"] = "ANGEPASST"
                break
    elif rows:
        for row in rows:
            if row["state"] in {"open", "adjusted"}:
                row["state"] = "next_up"
                break

    result["rows"] = rows
    result["has_core"] = isinstance(payload.get("core_nutrition"), dict)
    return result


def _today_agenda_normalize_minutes(raw: Any) -> int | None:
    text = str(raw or "").strip()
    if not text:
        return None
    match = re.match(r"^(\d{1,2}):(\d{2})$", text)
    if not match:
        return None
    hours = int(match.group(1))
    minutes = int(match.group(2))
    if not (0 <= hours <= 23 and 0 <= minutes <= 59):
        return None
    return hours * 60 + minutes


def _today_agenda_time_label(start_time: str | None, end_time: str | None, *, all_day: bool = False) -> str:
    if all_day:
        return "Ganztägig"
    start = str(start_time or "").strip()
    end = str(end_time or "").strip()
    if start and end:
        return f"{start}–{end}"
    return start or end or "Offen"


def _today_agenda_source_label(kind: str) -> str:
    return {
        "meal": "Meal",
        "school": "Untis",
        "calendar": "Kalender",
        "gym": "Training",
        "run": "Run",
    }.get(str(kind or "").strip().lower(), "Termin")


def _today_agenda_school_alias(raw: Any) -> str:
    text = str(raw or "").strip()
    if not text:
        return "Untis"
    subject_code = text.split("_", 1)[0].strip().upper()
    aliases = {
        "KU": "Kunst",
        "KR": "Religion",
        "E": "Englisch",
        "SP": "Sport LK",
        "M": "Mathe LK",
        "IF": "Info",
        "GE": "Geschichte",
        "BI": "Bio",
        "D": "Deutsch",
        "SW": "SoWi",
    }
    return aliases.get(subject_code, text)


def _today_agenda_split_school_meta(raw: Any) -> list[str]:
    text = str(raw or "").strip()
    if not text:
        return []
    parts = [part.strip() for part in text.split(",")]
    return [part for part in parts if part]


def _today_agenda_contains_email(raw: Any) -> bool:
    text = str(raw or "").strip()
    if not text:
        return False
    return bool(re.search(r"\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b", text, re.IGNORECASE))


def _today_agenda_strip_emails(raw: Any) -> str:
    text = str(raw or "").strip()
    if not text:
        return ""
    return re.sub(r"\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b", "", text, flags=re.IGNORECASE).strip(" ,·-")


def _today_agenda_calendar_subtitle(calendar_summary: Any, location: Any) -> str:
    summary = str(calendar_summary or "").strip()
    place = str(location or "").strip()
    bits = [_today_agenda_strip_emails(summary), _today_agenda_strip_emails(place)]
    clean_bits = [bit for bit in bits if bit]
    if clean_bits:
        return " · ".join(clean_bits)
    if _today_agenda_contains_email(summary):
        return "Privater Kalender"
    return ""


def _today_agenda_should_hide_calendar_title(raw: Any) -> bool:
    title = str(raw or "").strip().lower()
    if not title:
        return False
    hidden_prefixes = ("jonas ", "mama ", "papa ", "carsten ", "heike ")
    return any(prefix in title for prefix in hidden_prefixes)


def _today_agenda_filter_items(items: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    if not isinstance(items, list):
        return []
    out: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        if str(item.get("kind") or "").strip().lower() == "calendar":
            if _today_agenda_should_hide_calendar_title(item.get("title")):
                continue
        out.append(item)
    return out


_UNTIS_STANDARD_SLOTS: tuple[tuple[int, tuple[str, ...], str, str], ...] = (
    (1, ("08:00", "08:45"), "08:00", "09:30"),
    (2, ("09:55", "10:40"), "09:55", "11:25"),
    (3, ("11:45", "12:30"), "11:45", "13:15"),
    (4, ("14:00",), "14:00", "15:30"),
)


def _today_agenda_school_slot(raw_start: Any, raw_end: Any) -> dict[str, Any]:
    start = str(raw_start or "").strip()
    end = str(raw_end or "").strip()
    for slot_index, aliases, slot_start, slot_end in _UNTIS_STANDARD_SLOTS:
        if start in aliases:
            return {
                "slot_index": slot_index,
                "start_time": slot_start,
                "end_time": slot_end,
            }
    return {
        "slot_index": None,
        "start_time": start or None,
        "end_time": end or None,
    }


def _today_agenda_school_items_should_merge(current: dict[str, Any], item: dict[str, Any]) -> bool:
    if str(current.get("kind") or "").strip().lower() != "school":
        return False
    if str(item.get("kind") or "").strip().lower() != "school":
        return False
    current_slot = current.get("_slot_index")
    item_slot = item.get("_slot_index")
    if current_slot is not None and item_slot is not None:
        try:
            current_slot_i = int(current_slot)
            item_slot_i = int(item_slot)
        except Exception:
            current_slot_i = None
            item_slot_i = None
        if current_slot_i is not None and item_slot_i is not None:
            return item_slot_i in {current_slot_i, current_slot_i + 1}
    current_end = str(current.get("end_time") or "").strip()
    item_start = str(item.get("start_time") or "").strip()
    return bool(current_end and item_start and current_end == item_start)


def _today_agenda_merge_school_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None

    def _finalize_school(block: dict[str, Any]) -> dict[str, Any]:
        subjects = [str(value or "").strip() for value in (block.get("_subjects") or []) if str(value or "").strip()]
        teachers = [str(value or "").strip() for value in (block.get("_teachers") or []) if str(value or "").strip()]
        rooms = [str(value or "").strip() for value in (block.get("_rooms") or []) if str(value or "").strip()]
        block["title"] = ", ".join(subjects) or str(block.get("title") or "").strip() or "Untis"
        subtitle_bits: list[str] = []
        if teachers:
            subtitle_bits.append(", ".join(teachers))
        if rooms:
            subtitle_bits.append(", ".join(rooms))
        block["subtitle"] = " · ".join(subtitle_bits)
        block["time_label"] = _today_agenda_time_label(block.get("start_time"), block.get("end_time"))
        block.pop("_subjects", None)
        block.pop("_teachers", None)
        block.pop("_rooms", None)
        return block

    for item in items:
        if not isinstance(item, dict):
            continue
        if current is None:
            if str(item.get("kind") or "").strip().lower() == "school":
                current = {
                    **item,
                    "_subjects": [str(item.get("title") or "").strip()],
                    "_teachers": [str(item.get("_teacher") or "").strip()] if str(item.get("_teacher") or "").strip() else [],
                    "_rooms": _today_agenda_split_school_meta(item.get("_room")),
                }
            else:
                out.append(item)
            continue
        if _today_agenda_school_items_should_merge(current, item):
            subject = str(item.get("title") or "").strip()
            teacher = str(item.get("_teacher") or "").strip()
            rooms = _today_agenda_split_school_meta(item.get("_room"))
            if subject and subject not in current["_subjects"]:
                current["_subjects"].append(subject)
            if teacher and teacher not in current["_teachers"]:
                current["_teachers"].append(teacher)
            for room in rooms:
                if room and room not in current["_rooms"]:
                    current["_rooms"].append(room)
            current["end_time"] = item.get("end_time")
            current["_slot_index"] = item.get("_slot_index") if item.get("_slot_index") is not None else current.get("_slot_index")
            continue
        out.append(_finalize_school(current))
        if str(item.get("kind") or "").strip().lower() == "school":
            current = {
                **item,
                "_subjects": [str(item.get("title") or "").strip()],
                "_teachers": [str(item.get("_teacher") or "").strip()] if str(item.get("_teacher") or "").strip() else [],
                "_rooms": _today_agenda_split_school_meta(item.get("_room")),
            }
        else:
            current = None
            out.append(item)

    if current is not None:
        out.append(_finalize_school(current))
    return out


def _today_agenda_school_status(raw: Any) -> str:
    return str(raw or "").strip().lower()


def _today_agenda_school_entry_is_cancelled(entry: dict[str, Any], following_entries: list[dict[str, Any]] | None = None) -> bool:
    status = _today_agenda_school_status(entry.get("status_hint"))
    raw_text = str(entry.get("raw_text") or "").strip().lower()
    if status in {"cancelled", "canceled", "eva", "entfall", "frei", "free"}:
        return True
    if any(token in raw_text for token in (" eva", "entfall", " entfällt", "frei", "ausfall")):
        return True
    teacher = str(entry.get("teacher") or "").strip()
    subject = str(entry.get("subject") or "").strip()
    end_time = str(entry.get("end_time") or "").strip()
    if teacher or not subject or not end_time or not following_entries:
        return False
    for next_entry in following_entries:
        if not isinstance(next_entry, dict):
            continue
        if str(next_entry.get("date") or "").strip() != str(entry.get("date") or "").strip():
            continue
        next_subject = str(next_entry.get("subject") or "").strip()
        next_start = str(next_entry.get("start_time") or "").strip()
        next_teacher = str(next_entry.get("teacher") or "").strip()
        next_status = _today_agenda_school_status(next_entry.get("status_hint"))
        if next_subject == subject and next_start == end_time and next_teacher and next_status not in {"cancelled", "canceled", "eva", "entfall", "frei", "free"}:
            return True
    return False


def _today_agenda_dedupe_key(item: dict[str, Any]) -> tuple[str, str, str, str]:
    title = re.sub(r"\s+", " ", str(item.get("title") or "").strip().lower())
    start = str(item.get("start_time") or "").strip()
    end = str(item.get("end_time") or "").strip()
    kind = str(item.get("kind") or "").strip().lower()
    return (kind, title, start, end)


def _today_agenda_training_title_key(raw: Any) -> str:
    title = re.sub(r"\s+", " ", str(raw or "").strip().lower())
    if not title:
        return ""
    if title.startswith("training · "):
        title = title[len("training · ") :].strip()
    elif title.startswith("training: "):
        title = title[len("training: ") :].strip()
    return title


def _today_agenda_is_training_duplicate(candidate: dict[str, Any], existing: list[dict[str, Any]]) -> bool:
    kind = str(candidate.get("kind") or "").strip().lower()
    if kind not in {"gym", "calendar"}:
        return False
    title_key = _today_agenda_training_title_key(candidate.get("title"))
    if not title_key:
        return False
    for item in existing:
        other_kind = str(item.get("kind") or "").strip().lower()
        if {kind, other_kind} != {"gym", "calendar"}:
            continue
        if _today_agenda_training_title_key(item.get("title")) == title_key:
            return True
    return False


def _today_agenda_cache_file(day_iso: str, source: str) -> Path:
    slug = re.sub(r"[^a-z0-9_-]+", "_", str(source or "").strip().lower()) or "agenda"
    cache_dir = APP_ROOT / "var" / "dashboard_cache"
    return cache_dir / f"{slug}_{day_iso}.json"


def _read_today_agenda_cache(day_iso: str, source: str, *, max_age_seconds: float | None = None) -> list[dict[str, Any]] | None:
    path = _today_agenda_cache_file(day_iso, source)
    if not path.exists():
        return None
    if max_age_seconds is not None:
        with suppress(Exception):
            age_seconds = max(0.0, time() - float(path.stat().st_mtime))
            if age_seconds > float(max_age_seconds):
                return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    items = payload.get("items") if isinstance(payload, dict) else None
    return _today_agenda_filter_items(items)


def _load_recent_school_snapshot_entries(day_iso: str) -> list[dict[str, Any]]:
    conn = get_training_db()
    try:
        conn.row_factory = sqlite3.Row
        row = conn.execute(
            """
            SELECT s.id, s.raw_json
            FROM school_schedule_snapshots s
            WHERE s.date = ?
              AND EXISTS (
                SELECT 1
                FROM school_schedule_entries e
                WHERE e.snapshot_id = s.id
                  AND e.date = ?
              )
            ORDER BY s.fetched_at DESC, s.id DESC
            LIMIT 1
            """,
            (day_iso, day_iso),
        ).fetchone()
    except Exception:
        return []
    finally:
        conn.close()

    if not row:
        return []
    try:
        payload = json.loads(row["raw_json"] or "{}")
    except Exception:
        return []
    entries = payload.get("entries") if isinstance(payload, dict) else None
    if not isinstance(entries, list):
        return []
    return [entry for entry in entries if isinstance(entry, dict) and str(entry.get("date") or "").strip() == day_iso]


def _write_today_agenda_cache(day_iso: str, source: str, items: list[dict[str, Any]]) -> None:
    path = _today_agenda_cache_file(day_iso, source)
    filtered_items = _today_agenda_filter_items(items)
    with suppress(Exception):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps({"day": day_iso, "source": source, "items": filtered_items}, ensure_ascii=False),
            encoding="utf-8",
        )


def _load_today_school_agenda(day_iso: str) -> list[dict[str, Any]]:
    path = APP_ROOT / "var" / "schoolsync" / "latest_today.json"
    if not path.exists():
        entries = _load_recent_school_snapshot_entries(day_iso)
        if not entries:
            return []
        payload = {"entries_visible": entries}
    else:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            entries = _load_recent_school_snapshot_entries(day_iso)
            if not entries:
                return []
            payload = {"entries_visible": entries}

    entries = payload.get("entries_visible") if isinstance(payload, dict) else None
    if not isinstance(entries, list):
        return []
    if not any(isinstance(entry, dict) and str(entry.get("date") or "").strip() == day_iso for entry in entries):
        fallback_entries = _load_recent_school_snapshot_entries(day_iso)
        if fallback_entries:
            entries = fallback_entries

    normalized: list[dict[str, Any]] = []
    for idx, entry in enumerate(entries):
        if not isinstance(entry, dict):
            continue
        if str(entry.get("date") or "").strip() != day_iso:
            continue
        if _today_agenda_school_entry_is_cancelled(entry, entries[idx + 1:]):
            continue
        subject = _today_agenda_school_alias(entry.get("subject") or entry.get("lesson_text"))
        teacher = str(entry.get("teacher") or "").strip()
        room = str(entry.get("room") or "").strip()
        slot = _today_agenda_school_slot(entry.get("start_time"), entry.get("end_time"))
        normalized.append(
            {
                "kind": "school",
                "source_label": _today_agenda_source_label("school"),
                "title": subject,
                "subtitle": "",
                "start_time": slot.get("start_time"),
                "end_time": slot.get("end_time"),
                "time_label": _today_agenda_time_label(slot.get("start_time"), slot.get("end_time")),
                "all_day": False,
                "_teacher": teacher,
                "_room": room,
                "_slot_index": slot.get("slot_index"),
            }
        )
    normalized.sort(key=lambda item: (_today_agenda_normalize_minutes(item.get("start_time")) or 9999, _today_agenda_normalize_minutes(item.get("end_time")) or 9999, str(item.get("title") or "")))
    return normalized


def _load_today_google_agenda_sync(day_iso: str) -> list[dict[str, Any]]:
    try:
        from gcalsync.config import load_config
        from gcalsync.service import build_service, list_events_across_calendars
    except Exception:
        return []
    try:
        config = load_config()
        service = build_service(config.credentials_file, config.token_file)
        start_iso = f"{day_iso}T00:00:00+02:00"
        end_iso = f"{day_iso}T23:59:59+02:00"
        excluded = [config.school_calendar_id] if str(config.school_calendar_id or "").strip() else []
        payload = list_events_across_calendars(
            service,
            time_min=start_iso,
            time_max=end_iso,
            exclude_calendar_ids=excluded,
        )
    except Exception:
        return []
    events = payload.get("events") if isinstance(payload, dict) else None
    if not isinstance(events, list):
        return []
    out: list[dict[str, Any]] = []
    for event in events:
        if not isinstance(event, dict):
            continue
        title = str(event.get("title") or event.get("summary") or "Termin").strip() or "Termin"
        if _today_agenda_should_hide_calendar_title(title):
            continue
        start_raw = str(event.get("start") or "").strip()
        end_raw = str(event.get("end") or "").strip()
        start_day = start_raw[:10] if len(start_raw) >= 10 else ""
        end_day = end_raw[:10] if len(end_raw) >= 10 else ""
        all_day = bool(event.get("all_day") or event.get("is_all_day"))
        if not all_day and start_day != day_iso and end_day != day_iso:
            continue
        if all_day and start_day != day_iso:
            continue
        start_time = None
        end_time = None
        if not all_day:
            with suppress(Exception):
                start_time = datetime.fromisoformat(start_raw.replace("Z", "+00:00")).astimezone(ZoneInfo("Europe/Berlin")).strftime("%H:%M")
            with suppress(Exception):
                end_time = datetime.fromisoformat(end_raw.replace("Z", "+00:00")).astimezone(ZoneInfo("Europe/Berlin")).strftime("%H:%M")
        subtitle = _today_agenda_calendar_subtitle(
            event.get("calendar_summary"),
            event.get("location"),
        )
        out.append(
            {
                "kind": "calendar",
                "source_label": _today_agenda_source_label("calendar"),
                "title": title,
                "subtitle": subtitle,
                "start_time": start_time,
                "end_time": end_time,
                "time_label": _today_agenda_time_label(start_time, end_time, all_day=all_day),
                "all_day": all_day,
            }
        )
    return out


def _load_today_google_agenda(day_iso: str) -> list[dict[str, Any]]:
    fresh_cached = _read_today_agenda_cache(day_iso, "google", max_age_seconds=900)
    if isinstance(fresh_cached, list):
        return fresh_cached

    holder: dict[str, Any] = {"items": None}
    done = threading.Event()

    def runner() -> None:
        try:
            holder["items"] = _load_today_google_agenda_sync(day_iso)
        except Exception:
            holder["items"] = []
        finally:
            done.set()

    thread = threading.Thread(target=runner, name="today-agenda-google", daemon=True)
    thread.start()
    if not done.wait(timeout=1.2):
        stale_cached = _read_today_agenda_cache(day_iso, "google", max_age_seconds=None)
        return stale_cached if isinstance(stale_cached, list) else []

    items = holder.get("items")
    if isinstance(items, list):
        _write_today_agenda_cache(day_iso, "google", items)
        return items
    return []


def _load_today_meal_agenda(day_iso: str) -> list[dict[str, Any]]:
    try:
        from nutrition.nutrition_planning_api import read_cached_today_plan_payload, build_today_plan_payload
        payload = read_cached_today_plan_payload(include_items=True) or build_today_plan_payload(include_items=True, bypass_cache=False)
    except Exception:
        return []
    if str((payload or {}).get("date") or "").strip() != day_iso:
        return []
    meals = payload.get("meals") if isinstance(payload, dict) else None
    if not isinstance(meals, list):
        return []
    out: list[dict[str, Any]] = []
    for meal in meals:
        if not isinstance(meal, dict):
            continue
        items = meal.get("items") if isinstance(meal.get("items"), list) else []
        preview = ", ".join(
            str(item.get("name") or "").strip()
            for item in items[:3]
            if isinstance(item, dict) and str(item.get("name") or "").strip()
        )
        state = str(meal.get("state") or meal.get("status") or "").strip().lower()
        out.append(
            {
                "kind": "meal",
                "source_label": _today_agenda_source_label("meal"),
                "title": str(meal.get("name") or meal.get("title") or "Meal").strip() or "Meal",
                "subtitle": preview,
                "start_time": str(meal.get("time") or meal.get("time_text") or "").strip() or None,
                "end_time": None,
                "time_label": _today_agenda_time_label(meal.get("time") or meal.get("time_text"), None),
                "all_day": False,
                "state": state,
            }
        )
    return out


def _load_today_training_agenda(day_iso: str) -> list[dict[str, Any]]:
    plan_row = _get_active_plan_row()
    plan = plan_row_to_dict(plan_row) if plan_row else None
    if not isinstance(plan, dict):
        gym_record = _get_active_gym_plan_record()
        if isinstance(gym_record, dict):
            with suppress(Exception):
                plan = _legacy_plan_from_gym_record(gym_record)
    if not isinstance(plan, dict):
        return []
    try:
        weekday_idx = date.fromisoformat(day_iso).weekday()
    except Exception:
        return []
    base_week = plan.get("base_week") if isinstance(plan.get("base_week"), list) else []
    day_entry = base_week[weekday_idx] if 0 <= weekday_idx < len(base_week) and isinstance(base_week[weekday_idx], dict) else {}
    out: list[dict[str, Any]] = []
    session_name = str(day_entry.get("session_name") or "").strip()
    if session_name:
        out.append(
            {
                "kind": "gym",
                "source_label": _today_agenda_source_label("gym"),
                "title": session_name,
                "subtitle": "Geplante Kraft-Session",
                "start_time": None,
                "end_time": None,
                "time_label": "Training",
                "all_day": False,
            }
        )
    run_sessions = day_entry.get("run_sessions") if isinstance(day_entry.get("run_sessions"), list) else []
    for idx, run in enumerate(run_sessions):
        if not isinstance(run, dict):
            continue
        title = str(run.get("run_type") or run.get("title") or "Run").strip() or "Run"
        bits = []
        if run.get("amount_value") is not None:
            bits.append(f"{run.get('amount_value')} {str(run.get('amount_unit') or '').strip()}".strip())
        if str(run.get("pace") or "").strip():
            bits.append(str(run.get("pace")).strip())
        if str(run.get("notes") or "").strip():
            bits.append(str(run.get("notes")).strip())
        out.append(
            {
                "kind": "run",
                "source_label": _today_agenda_source_label("run"),
                "title": title,
                "subtitle": " · ".join([bit for bit in bits if bit]),
                "start_time": None,
                "end_time": None,
                "time_label": "Run",
                "all_day": False,
                "_sort_fallback": 700 + idx,
            }
        )
    return out


def _build_today_agenda_payload(day_iso: str | None = None) -> dict[str, Any]:
    day_key = str(day_iso or date.today().isoformat()).strip() or date.today().isoformat()
    merged: list[dict[str, Any]] = []
    merged.extend(_load_today_meal_agenda(day_key))
    merged.extend(_load_today_school_agenda(day_key))
    merged.extend(_load_today_google_agenda(day_key))
    merged.extend(_load_today_training_agenda(day_key))

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, str]] = set()
    for item in merged:
        if _today_agenda_is_training_duplicate(item, deduped):
            continue
        key = _today_agenda_dedupe_key(item)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)

    for idx, item in enumerate(deduped):
        minutes = _today_agenda_normalize_minutes(item.get("start_time"))
        item["sort_minutes"] = minutes if minutes is not None else int(item.get("_sort_fallback") or (1000 + idx))
        item["sort_index"] = idx
        item["time_label"] = str(item.get("time_label") or "Offen").strip() or "Offen"

    deduped.sort(key=lambda item: (int(item.get("sort_minutes") or 9999), int(item.get("sort_index") or 0), str(item.get("title") or "")))
    deduped = _today_agenda_merge_school_items(deduped)
    for item in deduped:
        item.pop("_sort_fallback", None)
        item.pop("sort_index", None)
        item.pop("_teacher", None)
        item.pop("_room", None)

    return {
        "ok": True,
        "day": day_key,
        "items": deduped,
    }


@app.get("/api/dashboard/today_agenda")
def api_dashboard_today_agenda():
    day_iso = (request.args.get("day") or request.args.get("date") or "").strip() or date.today().isoformat()
    return jsonify(_build_today_agenda_payload(day_iso))


