CORE_OVERVIEW_FORBIDDEN_RE = re.compile(
    r"(median|\bn\s*=|Δ|σ|trigger|bad-actions|28d\s*vs\s*28d)",
    re.IGNORECASE,
)

CORE_OVERVIEW_EXERCISE_HINTS = {
    "laeuft": "Kleine Schritte reichen, Form bleibt vor Lastsprung.",
    "stabil": "Linie halten und gleichmaessige Qualitaet sichern.",
    "zaeh": "Volumen sauber verteilen und bewusst kontrolliert arbeiten.",
    "riskant": "Belastung deckeln und Technik heute priorisieren.",
}


def _core_overview_day(day_iso: str | None = None) -> date:
    if day_iso:
        raw = str(day_iso or "").strip()[:10]
        try:
            return date.fromisoformat(raw)
        except Exception:
            pass
    return datetime.now(ZoneInfo("Europe/Berlin")).date()


def _core_overview_clean_text(text: str, fallback: str) -> str:
    out = str(text or "").strip()
    out = CORE_OVERVIEW_FORBIDDEN_RE.sub("", out)
    out = re.sub(r"\s+", " ", out).strip(" -.;")
    if not out:
        return fallback
    return out


def _core_overview_domain_for_learning(item: dict[str, Any]) -> str:
    tag = str(item.get("tag") or "").strip().lower()
    item_id = str(item.get("id") or "").strip().lower()
    if tag in {"recovery", "sleep", "risk"}:
        return "recovery"
    if tag in {"strength"}:
        return "training"
    if tag in {"run", "rhythm", "planning", "nutrition", "data"}:
        return "rhythmus"
    if item_id in {"sleep_to_rpe_drift", "first_set_daytype", "strength_trend", "lower_to_run_interference"}:
        return "training"
    return "rhythmus"


def _core_overview_confidence_label(score: float) -> str:
    if score >= 80:
        return "hoch"
    if score >= 60:
        return "mittel"
    return "niedrig"


def _ensure_core_card_seen_schema(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS core_card_seen (
            surface TEXT NOT NULL,
            seen_date TEXT NOT NULL,
            item_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (surface, seen_date, item_id)
        )
        """
    )


def _core_card_recent_seen_ids(conn: sqlite3.Connection, surface: str, since_iso: str) -> set[str]:
    rows = conn.execute(
        """
        SELECT DISTINCT item_id
        FROM core_card_seen
        WHERE surface = ? AND seen_date >= ?
        """,
        (surface, since_iso),
    ).fetchall()
    return {str(r[0]) for r in rows or [] if r and r[0]}


def _core_card_mark_seen(conn: sqlite3.Connection, surface: str, seen_date: str, item_ids: list[str]) -> None:
    now_iso = datetime.utcnow().isoformat()
    for item_id in item_ids:
        key = str(item_id or "").strip()
        if not key:
            continue
        conn.execute(
            """
            INSERT OR IGNORE INTO core_card_seen (surface, seen_date, item_id, created_at)
            VALUES (?, ?, ?, ?)
            """,
            (surface, seen_date, key, now_iso),
        )


def _core_overview_today_items(day_key: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]], int]:
    memory = _dashboard_autopilot_memory_payload(day_iso=day_key, lookback_days=84)
    source = memory.get("learnings") if isinstance(memory.get("learnings"), list) else []
    candidates: list[dict[str, Any]] = []
    for item in source:
        if not isinstance(item, dict):
            continue
        item_id = str(item.get("id") or "").strip()
        if not item_id:
            continue
        if item_id == "data_profile":
            continue
        domain = _core_overview_domain_for_learning(item)
        tpl = CORE_OVERVIEW_TODAY_TEMPLATES.get(item_id)
        default_line = "Keine neuen Auffaelligkeiten - CORE haelt Kurs."
        txt = tpl[1] if tpl else str(item.get("implication") or item.get("title") or "").strip()
        clean = _core_overview_clean_text(txt, default_line)
        confidence = float(item.get("confidence") or 0.0)
        samples = int((item.get("evidence") or {}).get("samples") or 0)
        score = confidence + min(20, samples) * 0.8
        candidates.append({
            "id": item_id,
            "domain": tpl[0] if tpl else domain,
            "text": clean,
            "confidence": confidence,
            "samples": samples,
            "score": score,
        })
    candidates.sort(key=lambda x: (float(x.get("score") or 0.0), float(x.get("confidence") or 0.0)), reverse=True)

    seen_conn = get_training_db()
    try:
        _ensure_core_card_seen_schema(seen_conn)
        asof = date.fromisoformat(day_key)
        since = (asof - timedelta(days=6)).isoformat()
        recent_ids = _core_card_recent_seen_ids(seen_conn, "dashboard_card", since)

        fresh = [c for c in candidates if str(c.get("id") or "") not in recent_ids]
        selected = fresh[:2]
        if len(selected) < 2:
            used = {str(x.get("id") or "") for x in selected}
            for c in candidates:
                cid = str(c.get("id") or "")
                if cid in used:
                    continue
                selected.append(c)
                used.add(cid)
                if len(selected) >= 2:
                    break
        if not selected:
            selected = [
                {"id": "fallback_stable", "domain": "recovery", "text": "Keine neuen Auffaelligkeiten - CORE haelt Kurs.", "confidence": 40.0},
                {"id": "fallback_rhythm", "domain": "rhythmus", "text": "Der Tagesrhythmus bleibt der Haupthebel fuer stabile Einheiten.", "confidence": 38.0},
            ]
        _core_card_mark_seen(seen_conn, "dashboard_card", day_key, [str(x.get("id") or "") for x in selected])
        seen_conn.commit()
    finally:
        seen_conn.close()

    more_count = max(0, len(candidates) - len(selected))
    selected_clean = [{"id": x["id"], "domain": x["domain"], "text": x["text"], "confidence": x.get("confidence", 0.0)} for x in selected]
    return selected_clean, candidates, more_count


def _core_overview_state_from_text(text: str) -> tuple[str, str, str]:
    t = str(text or "").strip().lower()
    if any(k in t for k in ("risk", "stop", "krit", "zu hoch", "ueber", "warn", "deckel")):
        return ("riskant", "Risk", "⚠")
    if any(k in t for k in ("zach", "zaeh", "limit", "eng", "deload", "reduzier", "runter")):
        return ("zaeh", "Limit", "↘")
    if any(k in t for k in ("progress", "plus", "hoch", "drauf", "steig", "weiter")):
        return ("laeuft", "Progress", "↗")
    if any(k in t for k in ("halt", "stabil", "gleich", "konstant", "sauber")):
        return ("stabil", "Plateau", "→")
    return ("stabil", "Plateau", "→")


def _core_overview_exercise_focus(day_key: str) -> list[dict[str, Any]]:
    heavy_tokens = ("bank", "bench", "squat", "kniebeuge", "rdl", "deadlift", "kreuzheben", "ohp", "press", "rudern", "row")
    asof = date.fromisoformat(day_key)
    workouts_payload: dict[str, Any] = {}
    try:
        with app.test_request_context("/api/dashboard/plan_check_recent?days=21"):
            resp = api_dashboard_plan_check_recent()
        resp_obj = resp[0] if isinstance(resp, tuple) else resp
        workouts_payload = resp_obj.get_json(silent=True) if hasattr(resp_obj, "get_json") else {}
    except Exception:
        workouts_payload = {}

    workouts = workouts_payload.get("workouts") if isinstance(workouts_payload.get("workouts"), list) else []
    buckets: dict[str, dict[str, Any]] = {}

    def _ex_key(raw: str) -> str:
        base = re.sub(r"[^a-z0-9]+", "_", str(raw or "").lower()).strip("_")
        return base or "exercise"

    for wk in workouts:
        if not isinstance(wk, dict):
            continue
        wmeta = wk.get("workout") if isinstance(wk.get("workout"), dict) else {}
        day_iso = str(wmeta.get("date_iso") or "")[:10]
        try:
            wday = date.fromisoformat(day_iso)
        except Exception:
            continue
        age = (asof - wday).days
        if age < 0 or age > 35:
            continue
        recency = max(0.15, (35 - age) / 35.0)
        items = wk.get("items") if isinstance(wk.get("items"), list) else []
        for it in items:
            if not isinstance(it, dict):
                continue
            title = str(it.get("title") or "").strip()
            if not title:
                continue
            key = _ex_key(title)
            text_blob = " ".join([
                str(it.get("suggestion_inline") or ""),
                str((it.get("pill") or {}).get("text") or ""),
            ]).strip()
            state, tag, icon = _core_overview_state_from_text(text_blob)
            priority_bonus = 1.2 if any(tok in title.lower() for tok in heavy_tokens) else 0.0
            item_score = 1.0 + recency + priority_bonus
            row = buckets.setdefault(key, {
                "exercise_key": key,
                "title": title,
                "score": 0.0,
                "last_day": day_iso,
                "state": state,
                "tag": tag,
                "icon": icon,
                "hint": CORE_OVERVIEW_EXERCISE_HINTS.get(state, CORE_OVERVIEW_EXERCISE_HINTS["stabil"]),
                "count": 0,
            })
            row["score"] = float(row.get("score") or 0.0) + item_score
            row["count"] = int(row.get("count") or 0) + 1
            if day_iso >= str(row.get("last_day") or ""):
                row["title"] = title
                row["last_day"] = day_iso
                row["state"] = state
                row["tag"] = tag
                row["icon"] = icon
                row["hint"] = CORE_OVERVIEW_EXERCISE_HINTS.get(state, CORE_OVERVIEW_EXERCISE_HINTS["stabil"])

    ranked = sorted(
        buckets.values(),
        key=lambda x: (float(x.get("score") or 0.0), int(x.get("count") or 0), str(x.get("last_day") or "")),
        reverse=True,
    )
    return [
        {
            "exercise_key": str(x.get("exercise_key") or ""),
            "title": str(x.get("title") or "Uebung"),
            "state": str(x.get("state") or "stabil"),
            "tag": str(x.get("tag") or "Plateau"),
            "hint": _core_overview_clean_text(str(x.get("hint") or ""), "Linie halten und gleichmaessige Qualitaet sichern."),
            "icon": str(x.get("icon") or "→"),
        }
        for x in ranked[:3]
    ]


def _core_overview_updated_label(day_key: str) -> str:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            """
            SELECT date_iso
            FROM workouts
            WHERE date_iso IS NOT NULL
            ORDER BY date_iso DESC, id DESC
            LIMIT 1
            """
        ).fetchone()
    finally:
        conn.close()
    last_iso = str(row["date_iso"] or "")[:10] if row else ""
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", last_iso):
        return "heute Morgen"
    try:
        diff = (date.fromisoformat(day_key) - date.fromisoformat(last_iso)).days
    except Exception:
        return "heute Morgen"
    return "nach letzter Einheit" if diff <= 1 else "heute Morgen"


def _core_overview_influence(today_items: list[dict[str, Any]], exercise_focus: list[dict[str, Any]]) -> str:
    ex_states = {str(x.get("state") or "").lower() for x in (exercise_focus or [])}
    domains = {str(x.get("domain") or "").lower() for x in (today_items or [])}
    if "riskant" in ex_states:
        return "CORE steuert heute ueber Reps und Satzanzahl statt Lastdruck."
    if "zaeh" in ex_states:
        return "CORE steuert heute ueber Tempo und Satzqualitaet statt Gewichtssprung."
    if "recovery" in domains:
        return "CORE steuert heute ueber kontrollierte Dichte statt aggressiver Volumenspitzen."
    if "training" in domains:
        return "CORE steuert heute ueber kleine Progressionsschritte statt grosser Lastwechsel."
    return "CORE steuert heute ueber Rhythmus und saubere Ausfuehrung statt Tempojagd."


def _core_overview_payload(day_iso: str | None = None) -> dict[str, Any]:
    asof = _core_overview_day(day_iso)
    day_key = asof.isoformat()
    selected_items, all_candidates, more_count = _core_overview_today_items(day_key)
    exercise_focus = _core_overview_exercise_focus(day_key)
    top_conf = max([float(x.get("confidence") or 0.0) for x in selected_items], default=0.0)
    confidence_label = _core_overview_confidence_label(top_conf)

    domain_conf = {"training": 0.0, "recovery": 0.0, "rhythmus": 0.0}
    for c in all_candidates:
        dom = str(c.get("domain") or "rhythmus").lower()
        if dom not in domain_conf:
            dom = "rhythmus"
        domain_conf[dom] = max(domain_conf[dom], float(c.get("confidence") or 0.0))

    def _domain_status(v: float) -> str:
        if v >= 80:
            return "aktiv"
        if v >= 60:
            return "stabil"
        if v > 0:
            return "leicht"
        return "neutral"

    return {
        "ok": True,
        "as_of_day": day_key,
        "confidence_label": confidence_label,
        "updated_label": _core_overview_updated_label(day_key),
        "domain_status": {
            "training": _domain_status(domain_conf["training"]),
            "recovery": _domain_status(domain_conf["recovery"]),
            "rhythmus": _domain_status(domain_conf["rhythmus"]),
        },
        "today_important": [
            {"id": str(x.get("id") or ""), "domain": str(x.get("domain") or "rhythmus"), "text": str(x.get("text") or "")}
            for x in selected_items[:2]
        ],
        "exercise_focus": exercise_focus[:3],
        "influence": {"text": _core_overview_influence(selected_items, exercise_focus)},
        "more_count": int(max(0, more_count)),
    }


@app.get("/api/core/overview_card")
def api_core_overview_card():
    day = (request.args.get("day") or "").strip() or None
    return jsonify(_core_overview_payload(day))


def _ensure_core_decision_schema(conn: sqlite3.Connection) -> None:
    row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='core_overrides' LIMIT 1").fetchone()
    if row:
        cols = {
            str(r[1]).strip().lower()
            for r in conn.execute("PRAGMA table_info(core_overrides)").fetchall()
            if r and len(r) > 1
        }
        required = {"id", "session_id", "target", "value", "locked", "created_at"}
        if not required.issubset(cols):
            legacy = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name='core_overrides_legacy' LIMIT 1"
            ).fetchone()
            if legacy:
                conn.execute("DROP TABLE core_overrides")
            else:
                conn.execute("ALTER TABLE core_overrides RENAME TO core_overrides_legacy")
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS core_overrides (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT NOT NULL,
            target TEXT NOT NULL,
            value TEXT NOT NULL,
            locked INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS idx_core_overrides_session_target
        ON core_overrides (session_id, target)
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS core_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT NOT NULL,
            kind TEXT NOT NULL,
            source TEXT NOT NULL,
            title TEXT NOT NULL,
            session_id TEXT,
            undo_payload TEXT
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS core_override_choices (
            date TEXT PRIMARY KEY,
            choice TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS core_feedback_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            date TEXT NOT NULL,
            kind TEXT NOT NULL,
            from_value TEXT,
            to_value TEXT,
            context_json TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    _ensure_core_card_seen_schema(conn)


def _core_iso_or_none(raw: Any) -> str | None:
    text = str(raw or "").strip()[:10]
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
        return text
    return None


_CORE_OVERRIDE_CHOICES = {"heavy_run", "heavy", "normal_run", "normal", "light", "rest"}


def _core_translate_override_choice(choice: str) -> tuple[str, str, bool]:
    key = str(choice or "").strip().lower()
    if key not in _CORE_OVERRIDE_CHOICES:
        return "", "", False
    if key == "rest":
        return "REST", "", False
    if key.endswith("_run"):
        base = key.replace("_run", "").upper()
        return base, "EASY", True
    return key.upper(), "", False


def _core_set_override_choice(day_iso: str, choice: str) -> None:
    conn = get_training_db()
    try:
        _ensure_core_decision_schema(conn)
        conn.execute(
            """
            INSERT INTO core_override_choices (date, choice, created_at)
            VALUES (?, ?, ?)
            ON CONFLICT(date) DO UPDATE SET
                choice=excluded.choice,
                created_at=excluded.created_at
            """,
            (day_iso, choice, _utc_now()),
        )
        conn.commit()
    finally:
        conn.close()


def _core_get_override_choice(day_iso: str) -> str:
    conn = get_training_db()
    try:
        _ensure_core_decision_schema(conn)
        row = conn.execute(
            "SELECT choice FROM core_override_choices WHERE date = ? LIMIT 1",
            (day_iso,),
        ).fetchone()
        return str(row["choice"]).strip().lower() if row and row["choice"] else ""
    finally:
        conn.close()


def _core_run_plan_from_slot(slot: dict[str, Any] | None) -> str:
    if not isinstance(slot, dict):
        return "NONE"
    if str(slot.get("kind") or "").strip().lower() != "run":
        return "NONE"
    run_kind = str(slot.get("run_kind") or "").strip().lower()
    if run_kind == "threshold":
        return "QUALITY"
    label = str(slot.get("label") or slot.get("final_label") or "").strip().lower()
    if "threshold" in label or "quality" in label:
        return "QUALITY"
    return "EASY"


def _core_canonical_run_plan(value: Any) -> str:
    raw = str(value or "").strip().upper()
    if raw in {"LONG", "QUALITY", "EASY", "NONE"}:
        return raw
    # Legacy compatibility: old plans are collapsed into EASY in the new 3-option model.
    if raw in {"SHORTEN", "SKIP"}:
        return "EASY"
    return "NONE"


def _core_canonical_gym_mode(value: Any, default: str = "HEAVY") -> str:
    raw = str(value or "").strip().upper()
    if not raw and str(default or "") == "":
        return ""
    if raw == "PUSH":
        raw = "HEAVY"
    if raw in {"HEAVY", "NORMAL", "LIGHT", "REST"}:
        return raw
    fallback = str(default or "HEAVY").strip().upper()
    if fallback == "PUSH":
        fallback = "HEAVY"
    return fallback if fallback in {"HEAVY", "NORMAL", "LIGHT", "REST"} else "HEAVY"


def _core_slug(value: str) -> str:
    out = re.sub(r"[^a-z0-9]+", "_", str(value or "").lower()).strip("_")
    return out or "slot"


def _core_session_id_for_slot(item_type: str, day_id: str | None, slot: dict[str, Any] | None) -> str | None:
    day = _core_iso_or_none(day_id)
    if not day:
        return None
    if item_type == "gym":
        label = str((slot or {}).get("session_name") or (slot or {}).get("label") or "gym").strip()
        # Stable id: strip mode suffixes so overrides survive label changes (LIGHT/HEAVY etc.).
        label = re.sub(r"\s*[-·]\s*(LIGHT|NORMAL|HEAVY|PUSH)\s*$", "", label, flags=re.IGNORECASE).strip()
        return f"gym_{day}_{_core_slug(label)}"
    if item_type == "run":
        run_kind = str((slot or {}).get("run_kind") or "").strip().lower()
        if run_kind == "threshold":
            label = "quality"
        elif run_kind == "z2":
            label = "z2"
        else:
            label = str((slot or {}).get("label") or "run").strip()
        return f"run_{day}_{_core_slug(label)}"
    return None


def _core_find_next_days(week_days: list[dict[str, Any]], day_key: str) -> tuple[str | None, str | None]:
    if not isinstance(week_days, list) or not week_days:
        return None, None
    idx = next((i for i, row in enumerate(week_days) if str(row.get("day_id") or "") == day_key), 0)
    ordered = (week_days[idx:] + week_days[:idx]) if week_days else []
    next_gym = None
    next_run = None
    for row in ordered:
        if not isinstance(row, dict):
            continue
        day_id = _core_iso_or_none(row.get("day_id"))
        kind = str(row.get("kind") or "").strip().lower()
        if not day_id:
            continue
        if kind == "plan" and not next_gym:
            next_gym = day_id
        if kind == "run" and not next_run:
            next_run = day_id
        if next_gym and next_run:
            break
    return next_gym, next_run


def _core_day_distance(from_day: str | None, to_day: str | None, *, default: int = 0) -> int:
    try:
        if not from_day or not to_day:
            return int(default)
        return int((date.fromisoformat(str(to_day)) - date.fromisoformat(str(from_day))).days)
    except Exception:
        return int(default)


def _core_slot_focus(slot: dict[str, Any] | None) -> str:
    if not isinstance(slot, dict):
        return "unknown"
    kind = str(slot.get("kind") or "").strip().lower()
    if kind == "run":
        return "run"
    blob = " ".join([
        str(slot.get("category") or ""),
        str(slot.get("session_name") or ""),
        str(slot.get("label") or ""),
        str(slot.get("final_label") or ""),
    ]).strip().lower()
    if any(tok in blob for tok in ("lower", "legs", "leg", "squat", "deadlift", "rdl")):
        return "legs"
    if any(tok in blob for tok in ("push", "bench", "chest", "shoulder", "trizeps", "triceps")):
        return "push"
    if any(tok in blob for tok in ("pull", "back", "row", "rudern", "lat", "biceps")):
        return "pull"
    if "upper" in blob:
        return "upper"
    if "full" in blob:
        return "full"
    return "gym"


def _core_future_slots(week_days: list[dict[str, Any]], day_key: str, horizon_days: int = 5) -> list[tuple[int, dict[str, Any]]]:
    if not isinstance(week_days, list) or not week_days:
        return []
    idx = next((i for i, row in enumerate(week_days) if str(row.get("day_id") or "") == str(day_key)), 0)
    ordered = (week_days[idx:] + week_days[:idx]) if week_days else []
    out: list[tuple[int, dict[str, Any]]] = []
    for off, row in enumerate(ordered[: max(1, int(horizon_days) + 1)]):
        if not isinstance(row, dict):
            continue
        out.append((off, row))
    return out


def _core_smart_decide_gym_run(
    *,
    selected_day_id: str,
    next_gym_day_id: str | None,
    next_run_day_id: str | None,
    next_gym_slot: dict[str, Any] | None,
    next_run_slot: dict[str, Any] | None,
    week_final: list[dict[str, Any]],
    state_snapshot: dict[str, Any],
    reason_codes: set[str],
    core_actions: dict[str, Any],
    is_deload_week: bool,
) -> dict[str, Any]:
    today_iso = datetime.now(ZoneInfo("Europe/Berlin")).date().isoformat()
    days_ahead = max(0, _core_day_distance(today_iso, selected_day_id, default=0))
    # Acute Tages-Signale sollen in der Zukunft schnell abklingen.
    projection_decay = max(0.15, 1.0 - 0.45 * float(days_ahead))

    flags = state_snapshot.get("flags") if isinstance(state_snapshot.get("flags"), dict) else {}
    recovery = state_snapshot.get("recovery") if isinstance(state_snapshot.get("recovery"), dict) else {}
    subjective = state_snapshot.get("subjective") if isinstance(state_snapshot.get("subjective"), dict) else {}
    hrv_ratio = _to_optional_float(recovery.get("hrv_ratio"))
    rhr_ratio = _to_optional_float(recovery.get("rhr_ratio"))
    fatigue_state = str(subjective.get("fatigue_state") or "").strip().lower()
    readiness_state = str(subjective.get("readiness_state") or "").strip().lower()

    gym_focus = _core_slot_focus(next_gym_slot)
    run_kind = str((next_run_slot or {}).get("run_kind") or "").strip().lower()
    days_to_gym = max(0, _core_day_distance(selected_day_id, next_gym_day_id, default=0))
    days_to_run = max(0, _core_day_distance(selected_day_id, next_run_day_id, default=0))
    short_decay_gym = max(0.15, 1.0 - 0.45 * max(0, days_to_gym - 1))
    short_decay_run = max(0.15, 1.0 - 0.45 * max(0, days_to_run - 1))

    hard_stop_codes = {"SICK", "ALCOHOL", "HRV_VERY_LOW"}
    strong_codes = {"HRV_LOW", "RHR_HIGH", "LEGS_FATIGUE", "PUSH_FATIGUE", "PULL_FATIGUE", "HI_BACK_TO_BACK_GUARD", "ZNS_FATIGUE"}
    soft_codes = {"SHIFTED", "RECOVERY_OK", "RECOVERY_MISSING"}
    hard_stop_hits_all = set(code for code in reason_codes if code in hard_stop_codes)
    strong_hits = set(code for code in reason_codes if code in strong_codes)
    soft_hits = set(code for code in reason_codes if code in soft_codes)
    hard_stop_hits_gym: set[str] = set()
    hard_stop_hits_run: set[str] = set()
    if "SICK" in hard_stop_hits_all:
        hard_stop_hits_gym.add("SICK")
        hard_stop_hits_run.add("SICK")
    if "ALCOHOL" in hard_stop_hits_all:
        hard_stop_hits_gym.add("ALCOHOL")
        hard_stop_hits_run.add("ALCOHOL")
    # Very low HRV is treated as hard-stop only in near horizon.
    if "HRV_VERY_LOW" in hard_stop_hits_all and days_to_gym <= 1:
        hard_stop_hits_gym.add("HRV_VERY_LOW")
    if "HRV_VERY_LOW" in hard_stop_hits_all and days_to_run <= 1:
        hard_stop_hits_run.add("HRV_VERY_LOW")

    gym_strong = 0.0
    gym_soft = 0.0
    gym_structural = 0.0
    run_strong = 0.0
    run_soft = 0.0
    run_structural = 0.0

    if hard_stop_hits_gym:
        gym_structural += 2.4 * projection_decay
    if hard_stop_hits_run:
        run_structural += 2.4 * projection_decay

    if "HRV_LOW" in strong_hits:
        gym_strong += 0.7 * projection_decay
        run_strong += 0.7 * projection_decay
    if "RHR_HIGH" in strong_hits:
        gym_strong += 0.7 * projection_decay
        run_strong += 0.7 * projection_decay
    if "LEGS_FATIGUE" in strong_hits:
        gym_strong += (1.2 if gym_focus in {"legs", "full"} else 0.35) * short_decay_gym
        run_strong += 1.2 * short_decay_run
    if "PUSH_FATIGUE" in strong_hits:
        gym_strong += (1.0 if gym_focus in {"push", "upper", "full"} else 0.25) * short_decay_gym
        run_soft += 0.2 * short_decay_run
    if "PULL_FATIGUE" in strong_hits:
        gym_strong += (0.9 if gym_focus in {"pull", "upper", "full"} else 0.2) * short_decay_gym
        run_soft += 0.15 * short_decay_run
    if "HI_BACK_TO_BACK_GUARD" in strong_hits:
        gym_strong += 0.7 * short_decay_gym * projection_decay
        run_strong += 0.5 * short_decay_run * projection_decay

    if hrv_ratio is not None and hrv_ratio <= 0.90:
        gym_strong += 0.9 * projection_decay
        run_strong += 0.9 * projection_decay
    elif hrv_ratio is not None and hrv_ratio <= 0.95:
        gym_soft += 0.45 * projection_decay
        run_soft += 0.45 * projection_decay
    if rhr_ratio is not None and rhr_ratio >= 1.06:
        gym_strong += 0.9 * projection_decay
        run_strong += 0.9 * projection_decay
    elif rhr_ratio is not None and rhr_ratio >= 1.03:
        gym_soft += 0.45 * projection_decay
        run_soft += 0.45 * projection_decay

    if fatigue_state == "high":
        gym_strong += 0.8 * projection_decay
        run_strong += 0.8 * projection_decay
    elif fatigue_state == "ok":
        gym_soft += 0.15 * projection_decay
        run_soft += 0.15 * projection_decay
    if readiness_state == "low":
        gym_soft += 0.3 * projection_decay
        run_soft += 0.3 * projection_decay

    if bool(core_actions.get("rpe_guard")):
        gym_strong += 0.6 * short_decay_gym * projection_decay
    if bool(core_actions.get("interference_guard")):
        gym_strong += (0.6 if gym_focus in {"legs", "full"} else 0.2) * short_decay_gym * projection_decay
        run_strong += 0.75 * short_decay_run * projection_decay
    if bool(core_actions.get("signal_guard")):
        gym_structural += 0.75 * projection_decay
        run_structural += 0.75 * projection_decay
    if bool(core_actions.get("nutrition_guard")):
        gym_soft += 0.3 * projection_decay
        run_soft += 0.25 * projection_decay
    if bool(core_actions.get("consistency_guard")):
        gym_soft += 0.25 * short_decay_gym * projection_decay
        run_soft += 0.35 * short_decay_run * projection_decay
    if bool(core_actions.get("deload_guard")):
        gym_structural += 0.55 * projection_decay
        run_structural += 0.45 * projection_decay
    if is_deload_week:
        gym_structural += 0.35
        run_structural += 0.25

    future = _core_future_slots(week_final, selected_day_id, horizon_days=5)
    rest_within_2 = any(off <= 2 and str((slot or {}).get("kind") or "").strip().lower() == "rest" for off, slot in future[1:])
    training_next_2 = sum(1 for off, slot in future[1:] if off <= 2 and str((slot or {}).get("kind") or "").strip().lower() in {"plan", "run"})
    heavy_windows_5 = sum(1 for _off, slot in future if str((slot or {}).get("kind") or "").strip().lower() == "plan")
    run_windows_5 = sum(1 for _off, slot in future if str((slot or {}).get("kind") or "").strip().lower() == "run")

    seq_penalty = 0.0
    if training_next_2 >= 2 and not rest_within_2:
        seq_penalty += 0.8
    if not rest_within_2 and bool(core_actions.get("interference_guard")):
        seq_penalty += 0.35

    opportunity_bonus = 0.0
    if heavy_windows_5 <= 1:
        opportunity_bonus += 0.55
    if run_windows_5 <= 1:
        opportunity_bonus += 0.35
    if rest_within_2:
        opportunity_bonus += 0.35

    next_gym_after_run = None
    if next_run_day_id:
        run_idx = next((i for i, row in enumerate(week_final or []) if str(row.get("day_id") or "") == str(next_run_day_id)), None)
        if run_idx is not None:
            for i in range(run_idx + 1, len(week_final or [])):
                row = (week_final or [])[i]
                if str((row or {}).get("kind") or "").strip().lower() == "plan":
                    next_gym_after_run = row
                    break
    gym_after_run_focus = _core_slot_focus(next_gym_after_run)
    if gym_after_run_focus in {"legs", "full"}:
        run_strong += 0.45

    gym_risk = max(0.0, gym_strong + gym_soft * 0.55 + gym_structural * 0.85 + seq_penalty - opportunity_bonus)
    run_risk = max(0.0, run_strong + run_soft * 0.55 + run_structural * 0.85 + (0.25 if run_kind == "threshold" else 0.0) - (0.25 if rest_within_2 else 0.0))

    gym_hard_stop_active = bool(hard_stop_hits_gym) or bool(flags.get("sick")) or bool(flags.get("alcohol"))
    run_hard_stop_active = bool(hard_stop_hits_run) or bool(flags.get("sick")) or bool(flags.get("alcohol"))
    if gym_hard_stop_active and (("SICK" in hard_stop_hits_gym) or ("ALCOHOL" in hard_stop_hits_gym)):
        gym_mode = "LIGHT"
    elif gym_risk >= 4.1:
        gym_mode = "LIGHT"
    elif gym_risk >= 1.7:
        gym_mode = "NORMAL"
    else:
        gym_mode = "HEAVY"

    run_plan = "NONE"
    if isinstance(next_run_slot, dict) and str(next_run_slot.get("kind") or "").strip().lower() == "run":
        # New run model: EASY / QUALITY / LONG.
        if run_kind == "z2":
            if run_hard_stop_active or run_risk >= 4.0:
                run_plan = "EASY"
            elif run_risk <= 1.0 and rest_within_2:
                run_plan = "LONG"
            elif run_risk <= 1.3 and run_windows_5 <= 1:
                run_plan = "LONG"
            else:
                run_plan = "EASY"
        else:
            if run_hard_stop_active or run_risk >= 4.0:
                run_plan = "EASY"
            elif run_risk >= 2.2:
                run_plan = "EASY"
            else:
                run_plan = "QUALITY"

    return {
        "gym_mode": gym_mode,
        "run_plan": run_plan,
        "gym_risk": round(float(gym_risk), 3),
        "run_risk": round(float(run_risk), 3),
        "hard_stop_active": bool(gym_hard_stop_active or run_hard_stop_active),
        "hard_stop_hits": sorted(hard_stop_hits_gym | hard_stop_hits_run),
        "strong_hits": sorted(strong_hits),
        "soft_hits": sorted(soft_hits),
        "rest_within_2": bool(rest_within_2),
    }


def _core_cleanup_past_overrides(conn: sqlite3.Connection, today_iso: str) -> None:
    conn.execute(
        """
        DELETE FROM core_overrides
        WHERE substr(session_id, 5, 10) < ?
        """,
        (today_iso,),
    )


def _core_load_overrides_for_sessions(session_ids: list[str]) -> list[dict[str, Any]]:
    keys = [str(x or "").strip() for x in (session_ids or []) if str(x or "").strip()]
    if not keys:
        return []
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        _ensure_core_decision_schema(conn)
        today_iso = datetime.now(ZoneInfo("Europe/Berlin")).date().isoformat()
        _core_cleanup_past_overrides(conn, today_iso)
        marks = ",".join(["?"] * len(keys))
        rows = conn.execute(
            f"""
            SELECT id, session_id, target, value, locked, created_at
            FROM core_overrides
            WHERE session_id IN ({marks})
            ORDER BY id DESC
            """,
            tuple(keys),
        ).fetchall()
        conn.commit()
        return [dict(r) for r in rows]
    finally:
        conn.close()


def _core_get_active_overrides(next_gym_session_id: str | None, next_run_session_id: str | None) -> list[dict[str, Any]]:
    if not _get_core_mode_enabled():
        return []
    valid_session_ids = [x for x in [next_gym_session_id, next_run_session_id] if x]
    return _core_load_overrides_for_sessions(valid_session_ids)


def _core_resolve_effective_decision(context: dict[str, Any], overrides: list[dict[str, Any]]) -> dict[str, Any]:
    suggested = context.get("suggested_decision") if isinstance(context.get("suggested_decision"), dict) else {}
    gym_mode = _core_canonical_gym_mode(suggested.get("gym_mode") or "HEAVY")
    run_plan = _core_canonical_run_plan(suggested.get("run_plan") or "NONE")
    gym_mode = _core_canonical_gym_mode(gym_mode)
    used: list[dict[str, Any]] = []
    next_gym_session_id = str(context.get("next_gym_session_id") or "")
    next_run_session_id = str(context.get("next_run_session_id") or "")
    for row in (overrides or []):
        session_id = str(row.get("session_id") or "").strip()
        target = str(row.get("target") or "").strip().lower()
        value = str(row.get("value") or "").strip().upper()
        if value == "RESET":
            continue
        if target == "gym_mode" and session_id == next_gym_session_id:
            gym_mode = _core_canonical_gym_mode(value, default=gym_mode)
            used.append(row)
        elif target == "run_plan" and session_id == next_run_session_id:
            norm_value = _core_canonical_run_plan(value)
            if norm_value != "NONE":
                run_plan = norm_value
            used.append(row)

    return {
        "gym_mode": gym_mode,
        "run_plan": run_plan,
        "override_active": bool(used),
        "overrides": used,
    }


def _core_session_label(session_id: str) -> str:
    sid = str(session_id or "").strip()
    if sid.startswith("gym_"):
        return f"Gym: {sid.split('_', 2)[-1].replace('_', ' ').title()}"
    if sid.startswith("run_"):
        return f"Run: {sid.split('_', 2)[-1].replace('_', ' ').title()}"
    return sid or "Session"


def _core_format_rel_time(ts_iso: str) -> str:
    raw = str(ts_iso or "").strip()
    if not raw:
        return "kürzlich"
    try:
        dt = datetime.fromisoformat(raw.replace("Z", ""))
    except Exception:
        return "kürzlich"
    now = datetime.utcnow()
    diff_h = max(0.0, (now - dt).total_seconds() / 3600.0)
    if diff_h < 1:
        return "vor kurzer Zeit"
    if diff_h < 24:
        return f"vor {int(diff_h)} Stunden"
    if diff_h < 48:
        return "gestern"
    return f"vor {int(diff_h // 24)} Tagen"


def _core_past_day_note(day_iso: str, stats: dict[str, Any] | None = None) -> str:
    stats = stats if isinstance(stats, dict) else _core_day_activity_stats(day_iso)
    workouts = int(stats.get("workouts") or 0)
    avg_rpe = stats.get("avg_rpe")
    runs = int(stats.get("runs") or 0)
    km = float(stats.get("run_km") or 0.0)
    avg_hr = stats.get("run_avg_hr")

    parts: list[str] = []
    if workouts > 0 and avg_rpe is not None:
        parts.append(f"Gym ØRPE {avg_rpe:.1f}")
    elif workouts > 0:
        parts.append("Gym absolviert")
    if runs > 0 and avg_hr is not None:
        parts.append(f"Run ØPuls {int(round(float(avg_hr)))}")
    elif runs > 0 and km > 0:
        parts.append(f"Run {km:.1f} km")
    elif runs > 0:
        parts.append("Run absolviert")
    return " · ".join(parts[:2])


_CORE_ACTIVITY_STATS_CACHE_TTL = 90.0
_CORE_ACTIVITY_STATS_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_CORE_NEXT_SESSION_CACHE_TTL = 180.0
_CORE_NEXT_SESSION_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_CORE_DECISION_CACHE_TTL = 120.0
_CORE_DECISION_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_CORE_DASHBOARD_CARD_CACHE_TTL = 120.0
_CORE_DASHBOARD_CARD_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_CORE_TODAY_CACHE_TTL = 15.0
_CORE_NIGHT_MODE_CACHE_TTL = 120.0
_CORE_NIGHT_MODE_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
def _core_cache_get(cache: dict[str, tuple[float, dict[str, Any]]], key: str, ttl_seconds: float) -> dict[str, Any] | None:
    entry = cache.get(key)
    if not entry:
        return None
    ts, payload = entry
    if (time() - float(ts or 0.0)) > float(ttl_seconds):
        cache.pop(key, None)
        return None
    return payload if isinstance(payload, dict) else None


def _core_cache_set(cache: dict[str, tuple[float, dict[str, Any]]], key: str, payload: dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    cache[key] = (time(), payload)


def _core_invalidate_dashboard_caches(day_iso: str | None = None) -> None:
    _CORE_DASHBOARD_CARD_CACHE.clear()
    _CORE_DECISION_CACHE.clear()
    _CORE_NEXT_SESSION_CACHE.clear()
    _CORE_NIGHT_MODE_CACHE.clear()
    if day_iso:
        day = _core_iso_or_none(day_iso)
        if day:
            invalidate_snapshot(f"dashboard_snapshot:{day}")
            invalidate_snapshot(f"training_today_card_snapshot:{day}")
            invalidate_snapshot(f"today_snapshot:{day}")
            invalidate_snapshot(f"next_session_snapshot:{day}:0")
            invalidate_snapshot(f"next_session_snapshot:{day}:1")
            _CORE_ACTIVITY_STATS_CACHE.pop(day, None)
            return
    invalidate_snapshot_prefix("dashboard_snapshot:")
    invalidate_snapshot_prefix("training_today_card_snapshot:")
    invalidate_snapshot_prefix("today_snapshot:")
    invalidate_snapshot_prefix("next_session_snapshot:")
    _CORE_ACTIVITY_STATS_CACHE.clear()


def _core_day_activity_stats_bulk(day_isos: list[str]) -> dict[str, dict[str, Any]]:
    days = sorted({_core_iso_or_none(x) for x in (day_isos or []) if _core_iso_or_none(x)})
    if not days:
        return {}
    now_ts = time()
    out: dict[str, dict[str, Any]] = {}
    misses: list[str] = []
    for day in days:
        cached = _CORE_ACTIVITY_STATS_CACHE.get(day)
        if cached and (now_ts - float(cached[0] or 0.0)) <= _CORE_ACTIVITY_STATS_CACHE_TTL and isinstance(cached[1], dict):
            out[day] = dict(cached[1])
        else:
            misses.append(day)
    if not misses:
        return out

    placeholders = ",".join(["?"] * len(misses))
    tconn = get_training_db()
    tconn.row_factory = sqlite3.Row
    rconn = get_runs_db()
    rconn.row_factory = sqlite3.Row
    try:
        trows = tconn.execute(
            f"""
            SELECT w.date_iso AS day_key,
                   COUNT(DISTINCT w.id) AS workouts,
                   COUNT(s.id) AS gym_sets,
                   AVG(CASE WHEN s.rpe IS NOT NULL THEN s.rpe END) AS avg_rpe
            FROM workouts w
            LEFT JOIN sets s ON s.workout_id = w.id
            WHERE w.date_iso IN ({placeholders})
            GROUP BY w.date_iso
            """,
            tuple(misses),
        ).fetchall()
        tmap = {str(r["day_key"] or ""): r for r in (trows or [])}

        run_cols = {str(row["name"] or "").strip().lower() for row in rconn.execute("PRAGMA table_info(runs)").fetchall()}
        if "date_iso" in run_cols:
            run_rows = rconn.execute(
                f"""
                SELECT
                    CASE
                        WHEN TRIM(COALESCE(date_iso, '')) <> '' THEN date_iso
                        ELSE substr(COALESCE(date, ''), 1, 10)
                    END AS day_key,
                    COUNT(*) AS runs,
                    SUM(COALESCE(distance, 0)) AS dist_sum,
                    AVG(NULLIF(avg_hr, 0)) AS avg_hr
                FROM runs
                WHERE date_iso IN ({placeholders})
                   OR substr(COALESCE(date, ''), 1, 10) IN ({placeholders})
                GROUP BY day_key
                """,
                tuple(misses + misses),
            ).fetchall()
        else:
            run_rows = rconn.execute(
                f"""
                SELECT
                    substr(COALESCE(date, ''), 1, 10) AS day_key,
                    COUNT(*) AS runs,
                    SUM(COALESCE(distance, 0)) AS dist_sum,
                    AVG(NULLIF(avg_hr, 0)) AS avg_hr
                FROM runs
                WHERE substr(COALESCE(date, ''), 1, 10) IN ({placeholders})
                GROUP BY day_key
                """,
                tuple(misses),
            ).fetchall()
        rmap = {str(r["day_key"] or ""): r for r in (run_rows or [])}
    except Exception:
        tmap = {}
        rmap = {}
    finally:
        tconn.close()
        rconn.close()

    for day in misses:
        trow = tmap.get(day)
        rrow = rmap.get(day)
        dist_sum = float(rrow["dist_sum"] or 0.0) if rrow and rrow["dist_sum"] is not None else 0.0
        run_km = (dist_sum / 1000.0) if dist_sum > 1000.0 else dist_sum
        avg_rpe = float(trow["avg_rpe"]) if trow and trow["avg_rpe"] is not None else None
        if avg_rpe is not None and avg_rpe <= 0:
            avg_rpe = None
        run_avg_hr = float(rrow["avg_hr"]) if rrow and rrow["avg_hr"] is not None else None
        if run_avg_hr is not None and run_avg_hr <= 0:
            run_avg_hr = None
        stats = {
            "workouts": int((trow["workouts"] or 0) if trow else 0),
            "gym_sets": int((trow["gym_sets"] or 0) if trow else 0),
            "avg_rpe": avg_rpe,
            "runs": int((rrow["runs"] or 0) if rrow else 0),
            "run_km": float(run_km or 0.0),
            "run_avg_hr": run_avg_hr,
        }
        out[day] = stats
        _CORE_ACTIVITY_STATS_CACHE[day] = (now_ts, stats)
    return out


def _core_day_activity_stats(day_iso: str) -> dict[str, Any]:
    day = _core_iso_or_none(day_iso)
    if not day:
        return {"workouts": 0, "gym_sets": 0, "avg_rpe": None, "runs": 0, "run_km": 0.0, "run_avg_hr": None}
    cached = _CORE_ACTIVITY_STATS_CACHE.get(day)
    if cached and (time() - float(cached[0] or 0.0)) <= _CORE_ACTIVITY_STATS_CACHE_TTL and isinstance(cached[1], dict):
        return dict(cached[1])
    bulk = _core_day_activity_stats_bulk([day])
    return bulk.get(day) or {"workouts": 0, "gym_sets": 0, "avg_rpe": None, "runs": 0, "run_km": 0.0, "run_avg_hr": None}


def _core_mode_label_for_ui(mode: str | None) -> str:
    m = _core_canonical_gym_mode(mode, default="")
    if m == "LIGHT":
        return "LIGHT"
    if m == "HEAVY":
        return "HEAVY"
    return ""


def _core_intensity_color_for_rpe(avg_rpe: float | None) -> str:
    if avg_rpe is None:
        return "neutral"
    if float(avg_rpe) <= 7.0:
        return "green"
    if float(avg_rpe) >= 8.5:
        return "red"
    return "yellow"


def _core_intensity_color_for_hr(avg_hr: float | None) -> str:
    if avg_hr is None:
        return "neutral"
    if float(avg_hr) <= 145.0:
        return "green"
    if float(avg_hr) >= 163.0:
        return "red"
    return "yellow"


def _core_item_intensity_color(item_type: str, mode_effective: str, run_effective: str) -> str:
    it = str(item_type or "").lower()
    if it == "gym":
        m = _core_canonical_gym_mode(mode_effective)
        if m == "LIGHT":
            return "green"
        if m == "HEAVY":
            return "red"
        return "yellow"
    if it == "run":
        p = str(run_effective or "").upper()
        if p == "EASY":
            return "green"
        if p == "QUALITY":
            return "red"
        if p == "LONG":
            return "yellow"
    return "neutral"


def _core_merge_effort_colors(colors: list[str]) -> str:
    vals = [str(c or "neutral").lower() for c in colors if str(c or "").strip()]
    if not vals:
        return "neutral"
    if "red" in vals:
        return "red"
    if "yellow" in vals:
        return "yellow"
    if "green" in vals:
        return "green"
    return "neutral"


def _core_event_title(target: str, value: str, session_id: str) -> tuple[str, str]:
    t = str(target or "").strip().lower()
    v = str(value or "").strip().upper()
    if t == "gym_mode":
        return "GYM", f"{_core_session_label(session_id)} auf {v} gesetzt"
    if t == "run_plan":
        return "RUN", f"{_core_session_label(session_id)} auf {v} gesetzt"
    return "CORE", f"{_core_session_label(session_id)} aktualisiert"


def _core_apply_override(session_id: str, target: str, value: str, lock: bool = False, source: str = "USER") -> dict[str, Any]:
    sid = str(session_id or "").strip()
    tgt = str(target or "").strip().lower()
    val = str(value or "").strip().upper()
    if tgt == "gym_mode":
        val = _core_canonical_gym_mode(val)
    if not sid:
        return {"ok": False, "error": "missing_session_id"}
    if tgt not in {"gym_mode", "run_plan"}:
        return {"ok": False, "error": "invalid_target"}
    val = _core_canonical_run_plan(val) if tgt == "run_plan" and val != "RESET" else val
    allowed = {"gym_mode": {"LIGHT", "NORMAL", "HEAVY", "REST", "RESET"}, "run_plan": {"EASY", "QUALITY", "LONG", "RESET"}}
    if val not in allowed[tgt]:
        return {"ok": False, "error": "invalid_value"}

    conn = get_training_db()
    try:
        _ensure_core_decision_schema(conn)
        now_iso = datetime.utcnow().isoformat()
        if val == "RESET":
            conn.execute("DELETE FROM core_overrides WHERE session_id = ? AND target = ?", (sid, tgt))
        else:
            conn.execute(
                """
                INSERT INTO core_overrides (session_id, target, value, locked, created_at)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(session_id, target) DO UPDATE SET
                    value = excluded.value,
                    locked = excluded.locked,
                    created_at = excluded.created_at
                """,
                (sid, tgt, val, 1 if bool(lock) else 0, now_iso),
            )
        kind, title = _core_event_title(tgt, "RESET" if val == "RESET" else val, sid)
        undo_payload = json.dumps({"target": tgt, "session_id": sid, "value": "RESET"}, ensure_ascii=False)
        conn.execute(
            """
            INSERT INTO core_events (ts, kind, source, title, session_id, undo_payload)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (now_iso, kind, str(source or "USER").upper(), title if val != "RESET" else f"{_core_session_label(sid)} zurückgesetzt", sid, undo_payload),
        )
        conn.commit()
    finally:
        conn.close()
    day_match = re.match(r"^(?:gym|run)_(\d{4}-\d{2}-\d{2})_", sid)
    _core_invalidate_dashboard_caches(day_match.group(1) if day_match else None)
    return {"ok": True}


def _core_resolve_effective_plan(day_key: str, horizon_days: int = 5, past_days: int = 0) -> dict[str, Any]:
    try:
        base_day = date.fromisoformat(day_key)
    except Exception:
        base_day = _core_overview_day(None)
        day_key = base_day.isoformat()

    future_days = max(1, int(horizon_days or 5))
    past_days = max(0, int(past_days or 0))
    offsets = list(range(-past_days, future_days + 1))
    if not offsets:
        offsets = [0]
    past_iso_days = [(base_day + timedelta(days=off)).isoformat() for off in offsets if off < 0]
    past_stats_map = _core_day_activity_stats_bulk(past_iso_days) if past_iso_days else {}

    weekday_short = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]
    session_ids: list[str] = []
    days: list[dict[str, Any]] = []
    next_gym = None
    next_run = None

    for off in offsets:
        curr = base_day + timedelta(days=off)
        curr_iso = curr.isoformat()
        label = "Heute" if off == 0 else ("Gestern" if off == -1 else ("Morgen" if off == 1 else weekday_short[curr.weekday()]))
        relation = "past" if off < 0 else ("today" if off == 0 else "future")

        day_summary = _core_fetch_day_summary(curr_iso)
        kind = str(day_summary.get("kind") or "").strip().lower()
        slot = {
            "kind": kind,
            "label": str(day_summary.get("slot") or "").strip(),
            "session_name": str(day_summary.get("slot") or "").strip(),
            "run_kind": day_summary.get("run_kind"),
        }
        items: list[dict[str, Any]] = []
        if kind == "plan":
            sid = _core_session_id_for_slot("gym", curr_iso, slot)
            session_ids.append(str(sid or ""))
            if off >= 0 and not next_gym:
                next_gym = {"date": curr_iso, "slot": slot.get("label"), "session_id": sid}
            mode_s = _core_canonical_gym_mode(day_summary.get("mode_suggested") or "HEAVY")
            mode_e = _core_canonical_gym_mode(day_summary.get("mode_effective") or mode_s, default=mode_s)
            items.append({
                "type": "gym",
                "slot": str(slot.get("label") or "Gym"),
                "mode_suggested": mode_s,
                "mode_core": mode_e,
                "mode_effective": mode_e,
                "state": "OVERRIDE" if mode_e != mode_s else "SUGGESTED",
                "session_id": sid,
            })
        elif kind == "run":
            sid = _core_session_id_for_slot("run", curr_iso, slot)
            session_ids.append(str(sid or ""))
            if off >= 0 and not next_run:
                next_run = {"date": curr_iso, "slot": slot.get("label"), "session_id": sid}
            run_s = str(day_summary.get("run_plan_suggested") or "EASY").upper()
            run_e = str(day_summary.get("run_plan_effective") or run_s).upper()
            items.append({
                "type": "run",
                "slot": str(slot.get("label") or "Run"),
                "plan_suggested": run_s,
                "plan_core": run_e,
                "plan_effective": run_e,
                "state": "OVERRIDE" if run_e != run_s else "SUGGESTED",
                "session_id": sid,
            })
        days.append({
            "date": curr_iso,
            "label": label,
            "relation": relation,
            "items": items,
            "past_note": _core_past_day_note(curr_iso, past_stats_map.get(curr_iso)) if relation == "past" else "",
        })

    overrides = _core_load_overrides_for_sessions([s for s in session_ids if s]) if _get_core_mode_enabled() else []
    by_key = {(str(r.get("session_id") or ""), str(r.get("target") or "")): r for r in overrides}
    for day in days:
        for item in day.get("items") or []:
            sid = str(item.get("session_id") or "")
            is_past_day = str(day.get("relation") or "") == "past"
            if item.get("type") == "gym":
                row = by_key.get((sid, "gym_mode"))
                if (not is_past_day) and row and str(row.get("value") or "").upper() != "RESET":
                    item["mode_effective"] = _core_canonical_gym_mode(row.get("value") or item.get("mode_effective") or "HEAVY")
                    item["state"] = "OVERRIDE"
                if str(day.get("relation") or "") == "past" and item.get("state") == "SUGGESTED":
                    item["state"] = "DONE"
            elif item.get("type") == "run":
                row = by_key.get((sid, "run_plan"))
                if (not is_past_day) and row and str(row.get("value") or "").upper() != "RESET":
                    item["plan_effective"] = str(row.get("value") or item.get("plan_effective") or "EASY").upper()
                    item["state"] = "OVERRIDE"
                if str(day.get("relation") or "") == "past" and item.get("state") == "SUGGESTED":
                    item["state"] = "DONE"

    return {"days": days, "overrides": overrides, "next_gym": next_gym, "next_run": next_run}

def _core_decision_call_next_session(day_key: str) -> dict[str, Any]:
    key = _core_iso_or_none(day_key) or str(day_key or "").strip()
    if not key:
        return {}
    cached = _core_cache_get(_CORE_NEXT_SESSION_CACHE, key, _CORE_NEXT_SESSION_CACHE_TTL)
    if cached is not None:
        return cached
    try:
        with app.test_request_context(f"/api/next_session?day={key}"):
            resp = api_next_session()
        resp_obj = resp[0] if isinstance(resp, tuple) else resp
        payload = resp_obj.get_json(silent=True) if hasattr(resp_obj, "get_json") else {}
        out = payload if isinstance(payload, dict) else {}
        _core_cache_set(_CORE_NEXT_SESSION_CACHE, key, out)
        return out
    except Exception:
        return {}


def _core_mode_from_night_cycle(day_key: str | None) -> dict[str, Any] | None:
    day = _core_iso_or_none(day_key)
    if not day:
        return None
    cached = _core_cache_get(_CORE_NIGHT_MODE_CACHE, day, _CORE_NIGHT_MODE_CACHE_TTL)
    if cached is not None:
        return cached
    conn = get_core_db()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            """
            SELECT date, payload_json
            FROM core_decision_explain_v2
            WHERE date <= ?
            ORDER BY date DESC
            LIMIT 1
            """,
            (day,),
        ).fetchone()
    except Exception:
        row = None
    finally:
        conn.close()
    if not row:
        return None
    try:
        payload = json.loads(row["payload_json"] or "{}")
    except Exception:
        payload = {}
    decision = payload.get("decision") if isinstance(payload.get("decision"), dict) else {}
    mode_raw = str(decision.get("mode") or "").strip().upper()
    if mode_raw == "PUSH":
        mode_raw = "HEAVY"
    mode = _core_canonical_gym_mode(mode_raw or "HEAVY")
    out = {"mode": mode, "source_date": str(row["date"] or "")}
    _core_cache_set(_CORE_NIGHT_MODE_CACHE, day, out)
    return out


def _core_fetch_day_summary(day_key: str | None) -> dict[str, Any]:
    if not day_key:
        return {
            "date": None,
            "kind": "rest",
            "slot": "Rest",
            "run_kind": None,
            "mode_suggested": "HEAVY",
            "mode_effective": "HEAVY",
            "run_plan_suggested": "NONE",
            "run_plan_effective": "NONE",
        }
    payload = _core_decision_call_next_session(day_key)
    if not payload:
        return {
            "date": day_key,
            "kind": "rest",
            "slot": "Rest",
            "run_kind": None,
            "mode_suggested": "HEAVY",
            "mode_effective": "HEAVY",
            "run_plan_suggested": "NONE",
            "run_plan_effective": "NONE",
        }
    final_day = payload.get("final_day") if isinstance(payload.get("final_day"), dict) else {}
    planned_day = payload.get("planned_day") if isinstance(payload.get("planned_day"), dict) else {}
    session = payload.get("session") if isinstance(payload.get("session"), dict) else {}
    meta = session.get("meta") if isinstance(session.get("meta"), dict) else {}
    kind = str(final_day.get("kind") or "").strip().lower() or "rest"
    slot = str(session.get("session_name") or final_day.get("label") or "Rest").strip() or "Rest"
    run_kind = str(final_day.get("run_kind") or planned_day.get("run_kind") or "").strip().lower() or None
    if kind == "run":
        slot = _autopilot_run_label(run_kind or "z2")

    inferred_run_suggested = "NONE"
    if kind == "run":
        inferred_run_suggested = "QUALITY" if run_kind == "threshold" else "EASY"
    elif str(planned_day.get("kind") or "").strip().lower() == "run":
        inferred_run_suggested = "QUALITY" if str(planned_day.get("run_kind") or "").strip().lower() == "threshold" else "EASY"

    meta_run_suggested = str(meta.get("autopilot_run_plan_suggested") or "").upper().strip()
    meta_run_effective = str(meta.get("autopilot_run_plan_effective") or "").upper().strip()
    run_suggested = _core_canonical_run_plan(meta_run_suggested) if meta_run_suggested else _core_canonical_run_plan(inferred_run_suggested)
    run_effective = _core_canonical_run_plan(meta_run_effective) if meta_run_effective else run_suggested
    if run_suggested == "NONE":
        run_suggested = _core_canonical_run_plan(inferred_run_suggested)
    if run_effective == "NONE":
        run_effective = run_suggested

    mode_suggested = _core_canonical_gym_mode(meta.get("autopilot_mode_suggested") or "HEAVY")
    mode_effective = _core_canonical_gym_mode(meta.get("autopilot_mode_effective") or meta.get("autopilot_mode_suggested") or "HEAVY")
    # Dashboard/Decision-Card an CORE-Night-Decision koppeln, damit /core und Dashboard
    # denselben Gym-Mode zeigen.
    if kind == "plan":
        nc_mode = _core_mode_from_night_cycle(day_key)
        if isinstance(nc_mode, dict) and str(nc_mode.get("mode") or "").strip():
            mode_suggested = _core_canonical_gym_mode(nc_mode.get("mode") or mode_suggested, default=mode_suggested)
            mode_effective = _core_canonical_gym_mode(nc_mode.get("mode") or mode_effective, default=mode_suggested)

    return {
        "date": day_key,
        "kind": kind,
        "slot": slot,
        "run_kind": run_kind,
        "mode_suggested": mode_suggested,
        "mode_effective": mode_effective,
        "run_plan_suggested": run_suggested,
        "run_plan_effective": run_effective,
        "payload": payload,
    }


def _core_decision_driver_candidates(ns_payload: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    session = ns_payload.get("session") if isinstance(ns_payload.get("session"), dict) else {}
    meta = session.get("meta") if isinstance(session.get("meta"), dict) else {}
    decision_meta = meta.get("decision_meta") if isinstance(meta.get("decision_meta"), dict) else {}
    inputs = decision_meta.get("inputs") if isinstance(decision_meta.get("inputs"), dict) else {}
    recovery = inputs.get("recovery") if isinstance(inputs.get("recovery"), dict) else {}
    flags = inputs.get("flags") if isinstance(inputs.get("flags"), dict) else {}
    core_overlay = decision_meta.get("core_overlay") if isinstance(decision_meta.get("core_overlay"), dict) else {}
    actions = core_overlay.get("actions") if isinstance(core_overlay.get("actions"), dict) else {}
    execution = core_overlay.get("execution") if isinstance(core_overlay.get("execution"), dict) else {}
    reasons = [str(x or "").strip().upper() for x in (meta.get("reason_codes") or []) if str(x or "").strip()]

    drivers: list[dict[str, Any]] = []

    hrv_today = recovery.get("rmssd_today")
    hrv_base = recovery.get("rmssd_28d")
    if hrv_today is not None and hrv_base is not None:
        try:
            if float(hrv_today) >= float(hrv_base) * 0.95:
                drivers.append({
                    "id": "drv_recovery_stable",
                    "timeframe": "today",
                    "domain": "recovery",
                    "status": "OK",
                    "text": "Recovery stabil -> heute kein zusaetzlicher Bremszug",
                    "hint": f"RMSSD {int(round(float(hrv_today)))} vs {int(round(float(hrv_base)))}",
                    "weight": 82,
                })
            else:
                drivers.append({
                    "id": "drv_recovery_low",
                    "timeframe": "today",
                    "domain": "recovery",
                    "status": "WARN",
                    "text": "Recovery unter Basis -> Last heute enger fuehren",
                    "hint": f"RMSSD {int(round(float(hrv_today)))} vs {int(round(float(hrv_base)))}",
                    "weight": 88,
                })
        except Exception:
            pass

    if any(code in reasons for code in {"PUSH_FATIGUE", "LEGS_FATIGUE", "PULL_FATIGUE"}):
        drivers.append({
            "id": "drv_rpe_recent_high",
            "timeframe": "today",
            "domain": "training",
            "status": "WARN",
            "text": "Letzte Satzhaerte hoch -> Volumen heute begrenzen",
            "hint": "Topsets zuletzt grenzwertig",
            "weight": 86,
        })
    elif _core_canonical_gym_mode(execution.get("gym_mode") or "", default="") == "HEAVY":
        drivers.append({
            "id": "drv_push_window",
            "timeframe": "next_gym",
            "domain": "training",
            "status": "OK",
            "text": "Fenster stabil -> naechstes Gym kann mutiger laufen",
            "hint": "keine harten Bremsmarker aktiv",
            "weight": 80,
        })

    if actions.get("interference_guard"):
        drivers.append({
            "id": "drv_run_tradeoff",
            "timeframe": "next_run",
            "domain": "run",
            "status": "WARN",
            "text": "Run-Druck steigt -> Gym bleibt normal, Run wird easy",
            "hint": "Reize werden heute getrennt getaktet",
            "weight": 84,
        })
    if actions.get("plan_anchor"):
        drivers.append({
            "id": "drv_plan_anchor",
            "timeframe": "week",
            "domain": "rhythmus",
            "status": "OK",
            "text": "Plananker aktiv -> Reihenfolge bleibt stabil",
            "hint": "kein Tageshopping im Wochenfluss",
            "weight": 72,
        })
    if flags.get("sick"):
        drivers.append({
            "id": "drv_sick_guard",
            "timeframe": "today",
            "domain": "recovery",
            "status": "LOW",
            "text": "Krankheitsflag aktiv -> Last wird direkt runtergezogen",
            "hint": "Sick-Flag heute aktiv",
            "weight": 95,
        })

    if not drivers:
        drivers.append({
            "id": "drv_default",
            "timeframe": "today",
            "domain": "rhythmus",
            "status": "OK",
            "text": "Keine harte Abweichung -> CORE bleibt plan-nah",
            "hint": "heute ohne dominantes Warnsignal",
            "weight": 60,
        })

    if context.get("today_has_run") is False and context.get("next_run_date"):
        drivers.append({
            "id": "drv_run_future_scope",
            "timeframe": "next_run",
            "domain": "run",
            "status": "OK",
            "text": "Run liegt spaeter -> Steuerung gilt fuer naechsten Run",
            "hint": "heute kein Run im Plan",
            "weight": 76,
        })

    dedup: dict[str, dict[str, Any]] = {}
    for d in drivers:
        did = str(d.get("id") or "").strip()
        if not did:
            continue
        prev = dedup.get(did)
        if not prev or float(d.get("weight") or 0) > float(prev.get("weight") or 0):
            dedup[did] = d
    return sorted(dedup.values(), key=lambda x: float(x.get("weight") or 0), reverse=True)


def _core_decision_select_drivers(day_key: str, candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
    conn = get_training_db()
    try:
        _ensure_core_decision_schema(conn)
        asof = date.fromisoformat(day_key)
        since = (asof - timedelta(days=2)).isoformat()
        recent_ids = _core_card_recent_seen_ids(conn, "decision_card_driver", since)
        selected: list[dict[str, Any]] = []
        for idx, row in enumerate(candidates):
            if idx == 0:
                selected.append(row)
                continue
            rid = str(row.get("id") or "")
            if rid in recent_ids:
                continue
            selected.append(row)
            if len(selected) >= 3:
                break
        if len(selected) < 3:
            used = {str(x.get("id") or "") for x in selected}
            for row in candidates:
                rid = str(row.get("id") or "")
                if rid in used:
                    continue
                selected.append(row)
                used.add(rid)
                if len(selected) >= 3:
                    break
        _core_card_mark_seen(conn, "decision_card_driver", day_key, [str(x.get("id") or "") for x in selected])
        conn.commit()
        return selected[:3]
    finally:
        conn.close()


def _core_decision_payload(day_iso: str | None = None) -> dict[str, Any]:
    started = perf_counter()
    ensure_core_schema()
    asof = _core_overview_day(day_iso)
    day_key = asof.isoformat()
    cache_key = f"decision::{day_key}"
    cache_ttl = _CORE_TODAY_CACHE_TTL if day_key == date.today().isoformat() else _CORE_DECISION_CACHE_TTL
    cached = _core_cache_get(_CORE_DECISION_CACHE, cache_key, cache_ttl)
    if cached is not None:
        record_timing("core.decision.total", perf_counter() - started, day=day_key, cache_hit=True)
        return cached
    with timed_block("core.decision.total", day=day_key, cache_hit=False):
        ns_payload = _core_decision_call_next_session(day_key)
        with timed_block("core.decision.daily_ui", day=day_key):
            daily_ui = build_core_daily_ui_payload(day_key)
        daily_decision = (daily_ui.get("daily_decision") if isinstance(daily_ui, dict) else {}) or {}
        week_days = ns_payload.get("week_days") if isinstance(ns_payload.get("week_days"), list) else []
        today_row = next((row for row in week_days if str(row.get("day_id") or "") == day_key), None)
        next_gym_date, next_run_date = _core_find_next_days(week_days, day_key)

    today_summary = _core_fetch_day_summary(day_key)
    next_gym_summary = today_summary if next_gym_date == day_key else _core_fetch_day_summary(next_gym_date)
    next_run_summary = today_summary if next_run_date == day_key else _core_fetch_day_summary(next_run_date)
    today_kind = str(today_summary.get("kind") or "rest").lower()
    today_slot = {
        "kind": today_kind,
        "label": str(today_summary.get("slot") or "").strip(),
        "session_name": str(today_summary.get("slot") or "").strip(),
        "run_kind": today_summary.get("run_kind"),
    }
    next_gym_slot = {
        "kind": str(next_gym_summary.get("kind") or "plan").strip().lower() or "plan",
        "label": str(next_gym_summary.get("slot") or "").strip(),
        "session_name": str(next_gym_summary.get("slot") or "").strip(),
        "run_kind": next_gym_summary.get("run_kind"),
    }
    next_run_slot = {
        "kind": str(next_run_summary.get("kind") or "run").strip().lower() or "run",
        "label": str(next_run_summary.get("slot") or "").strip(),
        "session_name": str(next_run_summary.get("slot") or "").strip(),
        "run_kind": next_run_summary.get("run_kind"),
    }
    today_gym_session_id = _core_session_id_for_slot("gym", day_key, today_slot) if today_kind == "plan" else None
    today_run_session_id = _core_session_id_for_slot("run", day_key, today_slot) if today_kind == "run" else None
    next_gym_session_id = _core_session_id_for_slot("gym", next_gym_date, next_gym_slot) if next_gym_date else None
    next_run_session_id = _core_session_id_for_slot("run", next_run_date, next_run_slot) if next_run_date else None
    override_rows = _core_load_overrides_for_sessions([x for x in [today_gym_session_id, today_run_session_id, next_gym_session_id, next_run_session_id] if x]) if _get_core_mode_enabled() else []
    override_map = {
        (str(r.get("session_id") or ""), str(r.get("target") or "")): str(r.get("value") or "").upper()
        for r in (override_rows or [])
    }

    today_gym = {
        "is_planned": today_kind == "plan",
        "slot": str(today_summary.get("slot") or "Rest"),
        "mode_suggested": _core_canonical_gym_mode(today_summary.get("mode_suggested") or "HEAVY"),
        "mode_effective": _core_canonical_gym_mode(today_summary.get("mode_effective") or "HEAVY"),
    }
    today_run = {
        "is_planned": today_kind == "run",
        "label": (
            str(today_summary.get("slot") or "Run")
            if today_kind == "run"
            else "kein Run heute"
        ),
    }
    upcoming = {
        "next_run": {
            "date": next_run_date,
            "slot": str(next_run_summary.get("slot") or "Run"),
            "plan_suggested": str(next_run_summary.get("run_plan_suggested") or "NONE"),
            "plan_effective": str(next_run_summary.get("run_plan_effective") or "NONE"),
        },
        "next_gym": {
            "date": next_gym_date,
            "slot": str(next_gym_summary.get("slot") or "Gym"),
            "mode_suggested": _core_canonical_gym_mode(next_gym_summary.get("mode_suggested") or "HEAVY"),
            "mode_effective": _core_canonical_gym_mode(next_gym_summary.get("mode_effective") or "HEAVY"),
        },
    }

    run_date_txt = next_run_date or "offen"
    run_slot_txt = str(upcoming["next_run"].get("slot") or "Run")
    run_plan_txt = _core_canonical_run_plan(upcoming["next_run"].get("plan_effective") or "NONE")
    timeline_hint = f"Naechster Run: {run_date_txt} · {run_slot_txt} (Plan: {run_plan_txt})"
    if not next_run_date:
        timeline_hint = "Naechster Run: aktuell keiner geplant"
    upcoming["timeline_hint"] = timeline_hint

    driver_ctx = {
        "today_has_run": today_run["is_planned"],
        "next_run_date": next_run_date,
    }
    candidates = _core_decision_driver_candidates(ns_payload, driver_ctx)
    drivers = _core_decision_select_drivers(day_key, candidates)
    conf_score = max((float(x.get("weight") or 0.0) for x in drivers), default=0.0)
    confidence_label = "hoch" if conf_score >= 80 else ("mittel" if conf_score >= 60 else "niedrig")

    domain_status = {"training": "neutral", "recovery": "neutral", "rhythmus": "neutral"}
    for d in drivers:
        dom = str(d.get("domain") or "rhythmus").lower()
        if dom == "run":
            dom = "rhythmus"
        status = str(d.get("status") or "OK").upper()
        if status == "LOW":
            domain_status[dom] = "vorsicht"
        elif status == "WARN" and domain_status.get(dom) != "vorsicht":
            domain_status[dom] = "aktiv"
        elif domain_status.get(dom) == "neutral":
            domain_status[dom] = "stabil"

    mode_allowed = ["LIGHT", "NORMAL", "HEAVY"]
    run_allowed = ["EASY", "QUALITY", "LONG"]
    run_known = {"EASY", "QUALITY", "LONG", "NONE"}
    mode_suggested = _core_canonical_gym_mode(upcoming["next_gym"]["mode_suggested"] or "HEAVY")
    mode_effective = _core_canonical_gym_mode(upcoming["next_gym"]["mode_effective"] or mode_suggested, default=mode_suggested)
    mode_user_override_today = False
    mode_user_override_next = False
    run_user_override_today = False
    run_user_override_next = False
    night_mode_today = _core_mode_from_night_cycle(day_key)
    forced_mode_today = _core_canonical_gym_mode((night_mode_today or {}).get("mode") or "", default="")
    if today_gym["is_planned"] and forced_mode_today in {"HEAVY", "NORMAL", "LIGHT"}:
        today_gym["mode_suggested"] = forced_mode_today
        if not mode_user_override_today:
            today_gym["mode_effective"] = forced_mode_today
        if next_gym_date == day_key:
            mode_suggested = forced_mode_today
            if not mode_user_override_next:
                mode_effective = forced_mode_today
            upcoming["next_gym"]["mode_suggested"] = forced_mode_today
            if not mode_user_override_next:
                upcoming["next_gym"]["mode_effective"] = forced_mode_today
    run_suggested = _core_canonical_run_plan(upcoming["next_run"]["plan_suggested"])
    run_effective = _core_canonical_run_plan(upcoming["next_run"]["plan_effective"])
    if today_gym_session_id:
        ov = override_map.get((today_gym_session_id, "gym_mode"), "")
        if ov and ov != "RESET":
            today_gym["mode_effective"] = _core_canonical_gym_mode(ov, default=today_gym["mode_suggested"])
            mode_user_override_today = True
    if next_gym_session_id:
        ov = override_map.get((next_gym_session_id, "gym_mode"), "")
        if ov and ov != "RESET":
            mode_effective = _core_canonical_gym_mode(ov, default=mode_suggested)
            upcoming["next_gym"]["mode_effective"] = mode_effective
            mode_user_override_next = True
    if today_run_session_id:
        ov = override_map.get((today_run_session_id, "run_plan"), "")
        if ov and ov != "RESET":
            run_effective = _core_canonical_run_plan(ov)
            run_user_override_today = (run_effective != "NONE")
    if next_run_session_id:
        ov = override_map.get((next_run_session_id, "run_plan"), "")
        if ov and ov != "RESET":
            run_effective = _core_canonical_run_plan(ov)
            upcoming["next_run"]["plan_effective"] = run_effective
            run_user_override_next = (run_effective != "NONE")

    if run_suggested == "NONE":
        run_suggested = "EASY"
    if run_effective == "NONE":
        run_effective = run_suggested
    mode_suggested = _core_canonical_gym_mode(mode_suggested)
    mode_effective = _core_canonical_gym_mode(mode_effective, default=mode_suggested)
    if today_gym["is_planned"]:
        today_gym["mode_effective"] = _core_canonical_gym_mode(today_gym["mode_effective"], default=today_gym["mode_suggested"])

    summary_line = f"Heute: {today_gym['slot'] if today_gym['is_planned'] else 'Rest'} · Modus: {today_gym['mode_effective'] if today_gym['is_planned'] else 'REST'}"
    if today_run["is_planned"]:
        summary_line += f" | Run: {run_effective}"

    if today_kind == "run" and today_run_session_id:
        primary_knob = {
            "target": "run_plan",
            "session_id": today_run_session_id,
            "applies_to": "today_run",
            "allowed": run_allowed,
            "suggested": run_suggested,
            "effective": run_effective,
        }
        secondary_knob = {
            "type": "gym_mode",
            "target": "gym_mode",
            "session_id": next_gym_session_id,
            "applies_to": "next_gym",
            "allowed": [x.lower() for x in mode_allowed],
            "suggested": mode_suggested.lower(),
            "effective": mode_effective.lower(),
        }
    elif today_kind == "plan" and today_gym_session_id:
        primary_knob = {
            "target": "gym_mode",
            "session_id": today_gym_session_id,
            "applies_to": "today_gym",
            "allowed": mode_allowed,
            "suggested": mode_suggested,
            "effective": mode_effective,
        }
        secondary_knob = {
            "type": "run_plan",
            "target": "run_plan",
            "session_id": next_run_session_id,
            "applies_to": "next_run",
            "allowed": [x.lower() for x in run_allowed],
            "suggested": run_suggested.lower(),
            "effective": run_effective.lower(),
        }
    else:
        primary_knob = {
            "target": "gym_mode",
            "session_id": next_gym_session_id,
            "applies_to": "next_gym",
            "allowed": mode_allowed,
            "suggested": mode_suggested,
            "effective": mode_effective,
        }
        secondary_knob = {
            "type": "run_plan",
            "target": "run_plan",
            "session_id": next_run_session_id,
            "applies_to": "next_run",
            "allowed": [x.lower() for x in run_allowed],
            "suggested": run_suggested.lower(),
            "effective": run_effective.lower(),
        }

    payload = {
        "ok": True,
        "as_of_day": day_key,
        "daily_decision": daily_decision if isinstance(daily_decision, dict) else {},
        "daily_ui": daily_ui if isinstance(daily_ui, dict) else {},
        "override_choice": _core_get_override_choice(day_key),
        "confidence_label": confidence_label,
        "updated_label": _core_overview_updated_label(day_key),
        "domain_status": domain_status,
        "decision": {
            "summary_line": (str((daily_ui or {}).get("hero") or "").strip() if isinstance(daily_ui, dict) and daily_ui else summary_line),
            "legacy_summary_line": summary_line,
        },
        "today": {
            "date": day_key,
            "gym": today_gym,
            "run": today_run,
        },
        "upcoming": upcoming,
        "drivers": [
            {
                "id": str(d.get("id") or ""),
                "timeframe": str(d.get("timeframe") or "today"),
                "domain": str(d.get("domain") or "rhythmus"),
                "status": str(d.get("status") or "OK"),
                "text": _core_overview_clean_text(str(d.get("text") or ""), "Signal -> Impact"),
                "hint": _core_overview_clean_text(str(d.get("hint") or ""), ""),
                "weight": int(d.get("weight") or 0),
            }
            for d in drivers[:3]
        ],
        "knobs": {
            "mode": primary_knob,
            "secondary": secondary_knob,
        },
        "detail_url": "/core",
    }
    _core_cache_set(_CORE_DECISION_CACHE, cache_key, payload)
    return payload


def _core_dashboard_card_payload(day_iso: str | None = None) -> dict[str, Any]:
    started = perf_counter()
    ensure_core_schema()
    day = _core_overview_day(day_iso)
    day_key = day.isoformat()
    cache_key = f"dashboard::{day_key}"
    cache_ttl = _CORE_TODAY_CACHE_TTL if day_key == date.today().isoformat() else _CORE_DASHBOARD_CARD_CACHE_TTL
    cached = _core_cache_get(_CORE_DASHBOARD_CARD_CACHE, cache_key, cache_ttl)
    if cached is not None:
        record_timing("core.dashboard_card.total", perf_counter() - started, day=day_key, cache_hit=True)
        return cached
    with timed_block("core.dashboard_card.total", day=day_key, cache_hit=False):
        # Default timeline is 7 days (3 past + today + 3 future); iPad trims to 3 in frontend.
        with timed_block("core.dashboard_card.effective_plan", day=day_key):
            eff = _core_resolve_effective_plan(day_key, horizon_days=3, past_days=3)
        dec = _core_decision_payload(day_key)
        with timed_block("core.dashboard_card.plan_context", day=day_key):
            plan_ctx = _autopilot_plan_context_for_day(day_key)

    timeline_days_raw = eff.get("days") if isinstance(eff.get("days"), list) else []
    override_rows = eff.get("overrides") if isinstance(eff.get("overrides"), list) else []
    override_map = {
        (str(r.get("session_id") or ""), str(r.get("target") or "")): r
        for r in override_rows
        if isinstance(r, dict)
    }
    day_stats_map = _core_day_activity_stats_bulk([
        str(d.get("date") or "")
        for d in timeline_days_raw
        if isinstance(d, dict)
    ])
    night_mode_today = _core_mode_from_night_cycle(day_key)
    forced_mode_today = _core_canonical_gym_mode((night_mode_today or {}).get("mode") or "", default="")

    rolling_days: list[dict[str, Any]] = []
    adhered_count = 0
    core_deviation_count = 0
    user_override_count = 0
    missed_count = 0
    mismatch_count = 0
    compliance_rows: list[dict[str, Any]] = []
    diff_items: list[dict[str, Any]] = []

    for day_row in timeline_days_raw:
        day_iso_value = _core_iso_or_none(day_row.get("date")) or day_key
        relation = str(day_row.get("relation") or "future")
        stats = day_stats_map.get(day_iso_value) or _core_day_activity_stats(day_iso_value)
        has_workout = int(stats.get("workouts") or 0) > 0
        has_run = int(stats.get("runs") or 0) > 0
        avg_rpe = stats.get("avg_rpe")
        avg_hr = stats.get("run_avg_hr")
        def _gym_mode_from_history(rpe_value: Any) -> str:
            try:
                rpe = float(rpe_value)
            except Exception:
                return "NORMAL"
            if rpe <= 7.0:
                return "LIGHT"
            if rpe >= 8.5:
                return "HEAVY"
            return "NORMAL"
        def _run_plan_from_history(hr_value: Any) -> str:
            try:
                hr = float(hr_value)
            except Exception:
                return "EASY"
            if hr <= 145.0:
                return "EASY"
            if hr >= 163.0:
                return "QUALITY"
            return "EASY"
        day_items = []
        for item in (day_row.get("items") or []):
            it_type = str(item.get("type") or "").lower()
            session_id = str(item.get("session_id") or "")
            planned_mode = _core_canonical_gym_mode(item.get("mode_suggested") or "HEAVY") if it_type == "gym" else "NONE"
            core_mode = _core_canonical_gym_mode(item.get("mode_core") or item.get("mode_effective") or planned_mode, default=planned_mode) if it_type == "gym" else "NONE"
            planned_plan = str(item.get("plan_suggested") or "NONE").upper() if it_type == "run" else "NONE"
            core_plan = str(item.get("plan_core") or item.get("plan_effective") or planned_plan).upper() if it_type == "run" else "NONE"
            effective_mode = core_mode if it_type == "gym" else "NONE"
            effective_plan = core_plan if it_type == "run" else "NONE"
            ov_key = (session_id, "gym_mode" if it_type == "gym" else "run_plan")
            has_user_override = (relation != "past") and (ov_key in override_map)
            if has_user_override:
                if it_type == "gym":
                    effective_mode = _core_canonical_gym_mode((override_map.get(ov_key) or {}).get("value") or core_mode, default=core_mode)
                elif it_type == "run":
                    effective_plan = str((override_map.get(ov_key) or {}).get("value") or core_plan).upper()
            if it_type == "gym" and day_iso_value == day_key and forced_mode_today in {"HEAVY", "NORMAL", "LIGHT"}:
                planned_mode = forced_mode_today
                core_mode = forced_mode_today
                if not has_user_override:
                    effective_mode = forced_mode_today
            if relation == "past":
                if it_type == "gym" and has_workout:
                    effective_mode = _gym_mode_from_history(avg_rpe)
                elif it_type == "run" and has_run:
                    effective_plan = _run_plan_from_history(avg_hr)
            mode_label = _core_mode_label_for_ui(effective_mode) if it_type == "gym" else ""
            intensity_color = _core_item_intensity_color(it_type, effective_mode, effective_plan)
            is_core_deviation = (core_mode != planned_mode) if it_type == "gym" else (core_plan != planned_plan)
            # A user override must remain visible as user intent even if it matches current CORE value.
            is_user_override = bool(has_user_override)
            changed_by = "user" if is_user_override else ("core" if (is_core_deviation and relation != "past") else None)
            done_specific = (it_type == "gym" and has_workout) or (it_type == "run" and has_run)
            done_any = bool(has_workout or has_run)
            status = "suggested"
            if relation == "past":
                # Past days should only be "missed" when there is no training log at all.
                # If a different modality was logged (e.g. gym instead of planned run), treat it as deviation.
                status = "done" if done_any else "missed"
            elif is_user_override:
                status = "override"
            elif is_core_deviation:
                status = "override"
            final_mode = effective_mode if (it_type == "gym" and done_specific) else None
            final_plan = effective_plan if (it_type == "run" and done_specific) else None
            actual_mode = final_mode if it_type == "gym" else final_plan
            mismatch_flag = bool(
                done_any
                and (
                    (not done_specific)
                    or (it_type == "gym" and final_mode != planned_mode)
                    or (it_type == "run" and final_plan != planned_plan)
                )
            )
            compliance_status = "planned"
            if relation == "past":
                if not done_any:
                    compliance_status = "missed"
                elif mismatch_flag:
                    compliance_status = "mismatch"
                elif done_specific:
                    compliance_status = "adhered"
            if relation == "past":
                if compliance_status == "adhered":
                    adhered_count += 1
                elif compliance_status == "mismatch":
                    mismatch_count += 1
                elif status == "missed":
                    missed_count += 1
            if is_core_deviation:
                core_deviation_count += 1
            if is_user_override:
                user_override_count += 1

            if is_core_deviation or is_user_override:
                before = planned_mode if it_type == "gym" else planned_plan
                after = effective_mode if it_type == "gym" else effective_plan
                if it_type == "gym":
                    before = _core_mode_label_for_ui(before) or "PLAN"
                    after = _core_mode_label_for_ui(after) or "PLAN"
                diff_items.append({
                    "id": f"diff_{session_id}",
                    "text": f"{'Gym' if it_type == 'gym' else 'Run'} ({day_row.get('label')}): {before} → {after}",
                    "by": "USER" if is_user_override else "CORE",
                    "date": day_iso_value,
                })

            day_items.append({
                "type": it_type,
                "label": str(item.get("slot") or ("Gym" if it_type == "gym" else "Run")),
                "slot": str(item.get("slot") or ("Gym" if it_type == "gym" else "Run")),
                "session_id": session_id,
                "planned_mode": planned_mode,
                "core_mode": core_mode,
                "effective_mode": effective_mode,
                "final_mode": final_mode,
                "planned_plan": planned_plan,
                "core_plan": core_plan,
                "effective_plan": effective_plan,
                "final_plan": final_plan,
                "changed_by": changed_by,
                "status": status,
                "mismatch_flag": mismatch_flag,
                "is_core_deviation": bool(is_core_deviation),
                "is_user_override": bool(is_user_override),
                "compliance_status": compliance_status,
                "actual_mode": actual_mode,
                "mode_label": mode_label,
                "intensity_color": intensity_color,
                "state": str(item.get("state") or "").upper() or ("OVERRIDE" if status == "override" else "SUGGESTED"),
            })

        if relation == "past":
            status_txt = "Resttag"
            if day_items:
                if any(str(x.get("status") or "") == "missed" for x in day_items):
                    status_txt = f"{day_row.get('label')}: geplant, aber ausgelassen ❌"
                elif any(str(x.get("compliance_status") or "") == "mismatch" for x in day_items):
                    status_txt = f"{day_row.get('label')}: umgesetzt mit Abweichung ⚠"
                else:
                    status_txt = f"{day_row.get('label')}: eingehalten ✅"
            compliance_rows.append({"date": day_iso_value, "label": str(day_row.get("label") or ""), "text": status_txt})

        colors: list[str] = []
        if avg_rpe is not None:
            colors.append(_core_intensity_color_for_rpe(float(avg_rpe)))
        if avg_hr is not None:
            colors.append(_core_intensity_color_for_hr(float(avg_hr)))
        effort_color = _core_merge_effort_colors(colors)
        effort_label = "neutral"
        if effort_color == "green":
            effort_label = "leicht"
        elif effort_color == "yellow":
            effort_label = "moderat"
        elif effort_color == "red":
            effort_label = "hart"

        rolling_days.append({
            "date": day_iso_value,
            "label": str(day_row.get("label") or ""),
            "relation": relation,
            "past_note": str(day_row.get("past_note") or ""),
            "past_metrics": {
                "gym_avg_rpe": (round(float(avg_rpe), 1) if avg_rpe is not None else None),
                "run_avg_hr": (int(round(float(avg_hr))) if avg_hr is not None else None),
                "effort_color": effort_color,
                "effort_label": effort_label,
            },
            "items": day_items[:2],
        })

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        _ensure_core_decision_schema(conn)
        event_rows = conn.execute(
            """
            SELECT id, ts, kind, source, title, session_id, undo_payload
            FROM core_events
            ORDER BY ts DESC
            LIMIT 20
            """
        ).fetchall()
    finally:
        conn.close()

    events = []
    for row in event_rows[:5]:
        events.append({
            "id": f"evt_{row['id']}",
            "kind": str(row["kind"] or "CORE").upper(),
            "source": str(row["source"] or "SYSTEM").upper(),
            "title": str(row["title"] or "").strip() or "Änderung",
            "when": _core_format_rel_time(str(row["ts"] or "")),
        })

    if not events:
        for d in rolling_days:
            for it in (d.get("items") or []):
                if str(it.get("changed_by") or "") == "core":
                    val_from = it.get("planned_mode") if it.get("type") == "gym" else it.get("planned_plan")
                    val_to = it.get("effective_mode") if it.get("type") == "gym" else it.get("effective_plan")
                    events.append({
                        "id": f"evt_auto_{it.get('session_id')}",
                        "kind": str(it.get("type") or "CORE").upper(),
                        "source": "SYSTEM",
                        "title": f"{it.get('slot')}: {val_from} → {val_to}",
                        "when": "aktuell",
                    })
                    if len(events) >= 3:
                        break
            if len(events) >= 3:
                break
    if not events:
        for row in compliance_rows:
            txt = str(row.get("text") or "")
            if "ausgelassen" in txt:
                kind = "CORE"
                source = "SYSTEM"
                title = txt
            elif "eingehalten" in txt:
                kind = "DONE"
                source = "SYSTEM"
                title = txt
            else:
                kind = "CORE"
                source = "SYSTEM"
                title = txt
            events.append({
                "id": f"evt_cmp_{row.get('date')}",
                "kind": kind,
                "source": source,
                "title": title,
                "when": "kürzlich",
            })
            if len(events) >= 3:
                break

    next_gym = eff.get("next_gym") if isinstance(eff.get("next_gym"), dict) else {}
    next_run = eff.get("next_run") if isinstance(eff.get("next_run"), dict) else {}
    gym_mode_plan = "NORMAL"
    gym_mode_eff = "NORMAL"
    run_plan_plan = "QUALITY"
    run_plan_eff = "EASY"
    gym_changed_by = None
    run_changed_by = None
    for d in rolling_days:
        for it in (d.get("items") or []):
            if it.get("type") == "gym" and str(it.get("session_id") or "") == str(next_gym.get("session_id") or ""):
                gym_mode_plan = _core_canonical_gym_mode(it.get("planned_mode") or "HEAVY")
                gym_mode_eff = _core_canonical_gym_mode(it.get("effective_mode") or gym_mode_plan, default=gym_mode_plan)
                gym_changed_by = str(it.get("changed_by") or "").lower() or None
            if it.get("type") == "run" and str(it.get("session_id") or "") == str(next_run.get("session_id") or ""):
                run_plan_plan = str(it.get("planned_plan") or "EASY").upper()
                run_plan_eff = str(it.get("effective_plan") or run_plan_plan).upper()
                run_changed_by = str(it.get("changed_by") or "").lower() or None

    gym_mode_plan_ui = _core_mode_label_for_ui(gym_mode_plan)
    gym_mode_eff_ui = _core_mode_label_for_ui(gym_mode_eff)
    gym_part_eff = gym_mode_eff_ui if gym_mode_eff_ui else "plan-nah"
    gym_part_plan = gym_mode_plan_ui if gym_mode_plan_ui else "plan-nah"
    override_source = "user" if ("user" in {gym_changed_by, run_changed_by}) else ("core" if ("core" in {gym_changed_by, run_changed_by}) else "none")
    actor_prefix = "Dein Override aktuell" if override_source == "user" else "CORE ändert aktuell"
    if run_plan_eff != run_plan_plan and gym_mode_eff == gym_mode_plan:
        diff_line = f"{actor_prefix}: Run wird {run_plan_eff}, Gym bleibt {gym_part_eff}."
    elif gym_mode_eff != gym_mode_plan and run_plan_eff == run_plan_plan:
        diff_line = f"{actor_prefix}: Gym {gym_part_eff}, Run bleibt {run_plan_eff}."
    elif gym_mode_eff != gym_mode_plan or run_plan_eff != run_plan_plan:
        diff_line = f"{actor_prefix}: Gym {gym_part_plan} → {gym_part_eff}, Run {run_plan_plan} → {run_plan_eff}."
    else:
        diff_line = "Keine Abweichungen in 7 Tagen."

    past_notes = [str(d.get("past_note") or "").strip() for d in rolling_days if str(d.get("relation") or "") == "past" and str(d.get("past_note") or "").strip()]
    summary_line = "Vergangene 3 Tage: " + (" | ".join(past_notes[:3]) if past_notes else "noch keine vollständigen Logs")

    phase_name = str(plan_ctx.get("phase") or "BUILD").upper()
    deload_in_days = _clean_int(plan_ctx.get("days_to_deload"))
    confidence_label = str(dec.get("confidence_label") or "mittel")
    confidence_value = 0.86 if confidence_label == "hoch" else (0.64 if confidence_label == "mittel" else 0.42)
    domains = dec.get("domain_status") if isinstance(dec.get("domain_status"), dict) else {}

    today_row = next((d for d in rolling_days if str(d.get("relation") or "") == "today"), {})
    today_items = today_row.get("items") if isinstance(today_row, dict) else []
    today_plan = "Rest"
    today_mode = "—"
    today_override = "—"
    today_override_by = "none"
    if isinstance(today_items, list) and today_items:
        first = today_items[0] if isinstance(today_items[0], dict) else {}
        first_by = str(first.get("changed_by") or "").lower()
        if str(first.get("type") or "") == "gym":
            today_plan = f"Gym {first.get('slot')}"
            today_mode = str(first.get("mode_label") or "—")
            today_override = "aktiv" if str(first.get("changed_by") or "") in {"core", "user"} else "—"
            today_override_by = first_by if first_by in {"core", "user"} else "none"
        elif str(first.get("type") or "") == "run":
            slot_txt = str(first.get("slot") or "").strip()
            today_plan = slot_txt if slot_txt.lower().startswith("run") else f"Run {slot_txt}"
            today_mode = str(first.get("effective_plan") or "EASY")
            today_override = "aktiv" if str(first.get("changed_by") or "") in {"core", "user"} else "—"
            today_override_by = first_by if first_by in {"core", "user"} else "none"
    # Final authority for today's gym mode: decision payload (shared with /core).
    dec_today = dec.get("today") if isinstance(dec.get("today"), dict) else {}
    dec_today_gym = dec_today.get("gym") if isinstance(dec_today.get("gym"), dict) else {}
    if bool(dec_today_gym.get("is_planned")):
        dec_mode = _core_canonical_gym_mode(dec_today_gym.get("mode_effective") or dec_today_gym.get("mode_suggested") or "NORMAL", default="NORMAL")
        today_mode = _core_mode_label_for_ui(dec_mode) or dec_mode
        dec_slot = str(dec_today_gym.get("slot") or "").strip()
        if dec_slot:
            today_plan = f"Gym {dec_slot}"

    payload = {
        "ok": True,
        "override_choice": _core_get_override_choice(day_key),
        "updated_label": _core_overview_updated_label(day_key),
        "confidence": {"label": confidence_label, "value": confidence_value},
        "phase": {"name": phase_name, "deload_in_days": deload_in_days},
        "status_pills": [
            {"k": "Training", "v": str(domains.get("training") or "stabil")},
            {"k": "Recovery", "v": str(domains.get("recovery") or "stabil")},
            {"k": "Rhythmus", "v": str(domains.get("rhythmus") or "stabil")},
        ],
        "timeline": {"days": rolling_days},
        "rolling_days": rolling_days,
        "diff": {
            "plan_default": {"gym_mode": gym_mode_plan, "run_plan_next": run_plan_plan},
            "core_effective": {"gym_mode": gym_mode_eff, "run_plan_next": run_plan_eff},
            "one_liner": diff_line,
            "items": diff_items[:2],
        },
        "summary_line": summary_line,
        "events": {"window_label": "Neueste", "items": events[:3]},
        "recent_events": events[:3],
        "links": {"details": "/core", "settings": "/core/settings"},
        "today_mini": {"plan": today_plan, "mode": today_mode, "override": today_override},
        "override_flag": {
            "active": bool(override_source in {"user", "core"}),
            "source": override_source,
            "label": ("Dein Override aktiv" if override_source == "user" else ("CORE-Override aktiv" if override_source == "core" else "Kein Override")),
            "today_source": today_override_by,
        },
        "compliance": {
            "adhered_count": int(adhered_count),
            "core_deviation_count": int(core_deviation_count),
            "user_override_count": int(user_override_count),
            "mismatch_count": int(mismatch_count),
            "missed_count": int(missed_count),
            "rows": compliance_rows[:7],
        },
        "compliance_7d": {
            "adhered_count": int(adhered_count),
            "core_deviation_count": int(core_deviation_count),
            "user_override_count": int(user_override_count),
            "mismatch_count": int(mismatch_count),
            "missed_count": int(missed_count),
        },
        "changes_7d": [{"text": str(x.get("text") or ""), "by": str(x.get("by") or "CORE")} for x in diff_items[:2]],
        "events_preview": events[:5],
    }
    v3_days: list[dict[str, Any]] = []
    for day in rolling_days:
            day_items = day.get("items") if isinstance(day.get("items"), list) else []
            day_stats = day_stats_map.get(str(day.get("date") or "")) or _core_day_activity_stats(str(day.get("date") or ""))
            out_items: list[dict[str, Any]] = []
            for it in day_items[:2]:
                it_type = str(it.get("type") or "")
                planned_value = str(it.get("planned_mode") or "") if it_type == "gym" else _core_canonical_run_plan(it.get("planned_plan") or "")
                effective_value = str(it.get("effective_mode") or "") if it_type == "gym" else _core_canonical_run_plan(it.get("effective_plan") or "")
                actual_status = str(it.get("status") or "suggested").lower()
                if actual_status == "suggested":
                    actual_status = "planned"
                actual_value = None
                if actual_status == "done":
                    actual_value = str(it.get("final_mode") or effective_value) if it_type == "gym" else str(it.get("final_plan") or effective_value)
                metrics = {
                    "sets": int(day_stats.get("gym_sets") or 0) if it_type == "gym" and actual_status == "done" else None,
                    "avg_rpe": float(day_stats.get("avg_rpe")) if it_type == "gym" and actual_status == "done" and day_stats.get("avg_rpe") is not None else None,
                    "km": float(day_stats.get("run_km")) if it_type == "run" and actual_status == "done" and day_stats.get("run_km") is not None else None,
                    "avg_hr": int(round(float(day_stats.get("run_avg_hr")))) if it_type == "run" and actual_status == "done" and day_stats.get("run_avg_hr") is not None else None,
                }
                slot_label = str(it.get("slot") or it.get("label") or "").strip()
                if it_type == "run":
                    title = slot_label if slot_label.lower().startswith("run") else f"Run {slot_label}".strip()
                else:
                    title = f"Gym {slot_label}".strip()
                out_items.append({
                    "type": it_type,
                    "title": title,
                    "session_id": str(it.get("session_id") or ""),
                    "planned": {
                        "mode_or_plan": planned_value,
                        "label": str(it.get("slot") or it.get("label") or ""),
                    },
                    "effective": {
                        "mode_or_plan": effective_value,
                        "changed_by": it.get("changed_by"),
                    },
                    "actual": {
                        "status": actual_status,
                        "mode_or_plan": actual_value,
                        **metrics,
                    },
                    "planned_mode": str(it.get("planned_mode") or ""),
                    "core_mode": str(it.get("core_mode") or ""),
                    "effective_mode": str(it.get("effective_mode") or ""),
                    "actual_mode": it.get("actual_mode"),
                    "planned_plan": str(it.get("planned_plan") or ""),
                    "core_plan": str(it.get("core_plan") or ""),
                    "effective_plan": str(it.get("effective_plan") or ""),
                    "is_core_deviation": bool(it.get("is_core_deviation")),
                    "is_user_override": bool(it.get("is_user_override")),
                    "compliance_status": str(it.get("compliance_status") or "planned"),
                    "mode_label": str(it.get("mode_label") or ""),
                    "intensity_color": str(it.get("intensity_color") or "neutral"),
                })
            diff_text = ""
            has_diff = False
            if out_items:
                first = out_items[0]
                pv = str(((first.get("planned") or {}).get("mode_or_plan")) or "")
                ev = str(((first.get("effective") or {}).get("mode_or_plan")) or "")
                av = str(((first.get("actual") or {}).get("mode_or_plan")) or "")
                if pv and ev and pv != ev:
                    has_diff = True
                    diff_text = f"Plan: {pv} → Ist: {ev}"
                elif pv and av and av and pv != av:
                    has_diff = True
                    diff_text = f"Plan: {pv} → Ist: {av}"
            v3_days.append({
                "date": str(day.get("date") or ""),
                "label": str(day.get("label") or ""),
                "relation": str(day.get("relation") or ""),
                "items": out_items,
                "diff": {"has_diff": has_diff, "text": diff_text},
                "past_metrics": day.get("past_metrics") or {},
            })
    payload["timeline"] = {"days": v3_days}
    _core_cache_set(_CORE_DASHBOARD_CARD_CACHE, cache_key, payload)
    return payload


