@app.post("/api/core/decision_override")
@require_admin
def api_core_decision_override():
    payload = request.get_json(silent=True) or {}
    ensure_core_schema()
    day_raw = _core_iso_or_none(payload.get("created_for_date")) or _core_iso_or_none(payload.get("date"))
    if not day_raw:
        day_raw = _core_overview_day(None).isoformat()

    override_choice = str(payload.get("override_choice") or "").strip().lower()
    if override_choice:
        print(f"[core override] received override_choice={override_choice}")
    override = payload.get("override") if isinstance(payload.get("override"), dict) else {}
    mode = str(override.get("mode") or "").strip().upper() if override.get("mode") is not None else ""
    run_plan = str(override.get("run_plan") or override.get("secondary") or "").strip().upper() if (override.get("run_plan") is not None or override.get("secondary") is not None) else ""
    mode_target = str(override.get("mode_target") or override.get("target") or "").strip().lower()
    mode_session_id = str(override.get("mode_session_id") or override.get("session_id") or "").strip()
    run_target = str(override.get("run_target") or "").strip().lower()
    run_session_id = str(override.get("run_session_id") or "").strip()
    if override_choice:
        if override_choice not in _CORE_OVERRIDE_CHOICES:
            return jsonify({"ok": False, "error": "invalid_override_choice"}), 400
        print(f"[core override] persisted override_choice={override_choice}")
        _core_set_override_choice(day_raw, override_choice)
        mode, run_plan, include_run = _core_translate_override_choice(override_choice)
        print(f"[core override] apply override_choice={override_choice} -> mode={mode} include_run={include_run}")

    if mode:
        mode = _core_canonical_gym_mode(mode, default="")
    if mode and mode not in {"LIGHT", "NORMAL", "HEAVY", "REST"}:
        return jsonify({"ok": False, "error": "invalid_mode"}), 400
    run_plan = _core_canonical_run_plan(run_plan) if run_plan else ""
    if run_plan and run_plan not in {"EASY", "QUALITY", "LONG"}:
        return jsonify({"ok": False, "error": "invalid_run_plan"}), 400
    if not mode and not run_plan:
        return jsonify({"ok": False, "error": "empty_override"}), 400

    eff = _core_resolve_effective_plan(day_raw, horizon_days=14, past_days=0)
    next_gym = eff.get("next_gym") if isinstance(eff.get("next_gym"), dict) else {}
    next_run = eff.get("next_run") if isinstance(eff.get("next_run"), dict) else {}
    if mode and mode_target == "run_plan":
        run_plan = mode
        mode = ""
        if mode_session_id and not run_session_id:
            run_session_id = mode_session_id
        if not run_target:
            run_target = "run_plan"
    mode_sid = mode_session_id or str(next_gym.get("session_id") or "")
    run_sid = run_session_id or str(next_run.get("session_id") or "")
    saved_keys: list[str] = []
    if mode and mode_sid:
        res = _core_apply_override(mode_sid, "gym_mode", mode, lock=False, source="USER")
        if not res.get("ok"):
            return jsonify(res), 400
        saved_keys.append("mode")
    if run_plan and run_sid:
        res = _core_apply_override(run_sid, "run_plan", run_plan, lock=False, source="USER")
        if not res.get("ok"):
            return jsonify(res), 400
        saved_keys.append("run_plan")

    return jsonify({
        "ok": True,
        "created_for_date": day_raw,
        "saved": saved_keys,
        "override_choice": override_choice or None,
        "decision_card": _core_decision_payload(day_raw),
    })


@app.post("/api/core/override")
@require_admin
def api_core_override():
    payload = request.get_json(silent=True) or {}
    fast = str(request.args.get("fast") or payload.get("fast") or "").strip().lower() in {"1", "true", "yes", "on"}
    session_id = str(payload.get("session_id") or "").strip()
    target = str(payload.get("target") or "").strip().lower()
    value = str(payload.get("value") or "").strip().upper()
    lock = bool(payload.get("lock"))
    if not session_id:
        return jsonify({"ok": False, "error": "missing_session_id"}), 400
    if target == "gym_mode" and not session_id.startswith("gym_"):
        return jsonify({"ok": False, "error": "target_session_mismatch"}), 400
    if target == "run_plan" and not session_id.startswith("run_"):
        return jsonify({"ok": False, "error": "target_session_mismatch"}), 400
    result = _core_apply_override(session_id, target, value, lock=lock, source="USER")
    if not result.get("ok"):
        return jsonify(result), 400
    override_day = None
    m = re.match(r"^(?:gym|run)_(\d{4}-\d{2}-\d{2})_", session_id)
    if m:
        override_day = m.group(1)
    dashboard_card = None if fast else _core_dashboard_card_payload(None)
    next_session_payload = None
    if (not fast) and override_day:
        next_session_payload = _core_decision_call_next_session(override_day)
    return jsonify({
        "ok": True,
        "override_day": override_day,
        "next_session": next_session_payload,
        "dashboard_card": dashboard_card,
    })


