@app.get("/api/dashboard/plan_check_latest")
def api_dashboard_plan_check_latest():
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    row = cur.execute("""
        SELECT * FROM workouts
        ORDER BY date_iso DESC, id DESC
        LIMIT 1
    """).fetchone()
    conn.close()

    if not row:
        return jsonify({"ok": False, "error": "no_workouts"}), 404

    workout = dict(row)
    recompute = request.args.get("recompute") == "1"
    report = None if recompute else load_plan_check_report(workout["id"])
    if not report:
        report = build_plan_check_for_workout(workout["id"])
        save_plan_check_report(report)

    if not report:
        return jsonify({
            "ok": False,
            "error": "plan_check_unavailable",
            "workout": {
                "id": workout["id"],
                "name": workout["name"],
                "date": workout["date"],
                "date_iso": workout["date_iso"],
            }
        }), 404

    top_exercises = []
    for ex in report.get("exercises") or []:
        name = (ex.get("name") or "").strip()
        if not name:
            continue
        top_exercises.append({
            "name": name,
            "coverage": ex.get("coverage"),
            "suggestion": ex.get("suggestion"),
        })
        if len(top_exercises) >= 3:
            break

    return jsonify({
        "ok": True,
        "workout": {
            "id": workout["id"],
            "name": workout["name"],
            "date": workout["date"],
            "date_iso": workout["date_iso"],
        },
        "plan_check": {
            "status": report.get("status"),
            "summary": report.get("summary"),
            "flags": report.get("flags") or [],
        },
        "top_exercises": top_exercises,
    })


@app.get("/api/dashboard/plan_check_week_overview")
def api_dashboard_plan_check_week_overview():
    debug = os.getenv("LIVA_DEBUG_PLAN_CHECK_OVERVIEW", "0") == "1"

    core_mode_enabled = bool(_get_core_mode_enabled())
    plan, plan_source = _active_plan_for_decision(core_mode_enabled)
    if not plan:
        return jsonify({"ok": False, "error": "no_active_plan"}), 404
    meta = (plan.get("meta") or {}) if isinstance(plan, dict) else {}

    # asof=YYYY-MM-DD (Debug/Test)
    asof = (request.args.get("asof") or "").strip()
    if asof:
        try:
            asof_date = datetime.strptime(asof, "%Y-%m-%d").date()
        except Exception:
            return jsonify({"ok": False, "error": "bad_asof"}), 400
    else:
        asof_date = date.today()

    # Strength sessions fürs Overview (wie bisher)
    sessions = _plan_strength_sessions(plan) or []

    base_week = plan.get("base_week") or []

    def day_title(day: dict | None) -> str:
        day = day or {}
        run_session = (day.get("run_sessions") or [None])[0]
        has_run = bool(
            run_session
            and isinstance(run_session, dict)
            and (
                run_session.get("run_type")
                or run_session.get("amount_value")
                or run_session.get("pace")
                or run_session.get("notes")
            )
        )
        has_gym = bool(day.get("strength_exercises") or (day.get("session_name") or "").strip())

        if has_gym:
            return (day.get("session_name") or "Gym").strip() or "Gym"
        # For dashboard "Heute" headline, strength label has priority over run label.
        if has_run:
            run_type = run_session.get("run_type") if isinstance(run_session, dict) else None
            return _format_run_label(run_type)
        return "Rest"

    # ------------------------------------------------------------
    # TODAY title
    # ------------------------------------------------------------
    today_idx = asof_date.weekday()  # Mo=0..So=6
    today_day = base_week[today_idx] if today_idx < len(base_week) else {}
    run_session_today = (today_day.get("run_sessions") or [None])[0] if isinstance(today_day, dict) else None
    today_has_run = bool(
        run_session_today
        and isinstance(run_session_today, dict)
        and (
            run_session_today.get("run_type")
            or run_session_today.get("amount_value")
            or run_session_today.get("pace")
            or run_session_today.get("notes")
        )
    )
    today_session_name = day_title(today_day)
    today_is_rest = (today_session_name == "Rest")

    # ------------------------------------------------------------
    # NEXT session (nächster Nicht-Rest Tag, ab morgen; wrapt in 7 Tagen)
    # NOTE: This is the "overall" next session (run has priority in day_title()).
    # ------------------------------------------------------------
    next_title = None
    next_idx = None
    next_date_iso = None
    for offset in range(1, 8):  # morgen .. in 7 Tagen
        idx = (today_idx + offset) % 7
        d = base_week[idx] if idx < len(base_week) else {}
        title = day_title(d)
        if title != "Rest":
            next_title = title
            next_idx = idx
            next_date_iso = (asof_date + timedelta(days=offset)).isoformat()
            break

    # fallback (falls wirklich alles Rest ist)
    if not next_title:
        next_title = "—"

    today_info = {
        "date_iso": asof_date.isoformat(),
        "weekday_index": today_idx,
        "weekday": ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"][today_idx],
        "today_is_rest": today_is_rest,
        "today_has_run": today_has_run,
        "today_session_key": None,  # strength-only key (filled below)
        "today_session_name": today_session_name,

        # NEXT (für Footer/Headline/whatever)
        "default_session_key": None,   # strength-only key (filled below)
        "default_session_name": next_title,  # overall next (run/gym)
        "default_session_date_iso": next_date_iso,
        "default_session_weekday_index": next_idx,
        "default_session_weekday": (["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"][next_idx] if next_idx is not None else None),
    }

    # ------------------------------------------------------------
    # Strength-only "default session" (Plan-Check dropdown default)
    # - today -> next strength day forward
    # ------------------------------------------------------------
    try:
        sessions_by_day = _strength_sessions_by_day(plan) or {}
        today_strength_raw = sessions_by_day.get(today_idx)
        # Wenn heute ein Run ist, soll Plan-Check NICHT "heute" auswählen, sondern die nächste Gym-Session.
        today_strength = None if today_has_run else today_strength_raw
        default_strength = None
        if today_strength:
            default_strength = today_strength
        else:
            for offset in range(1, 8):
                idx = (today_idx + offset) % 7
                if idx in sessions_by_day:
                    default_strength = sessions_by_day[idx]
                    # sync date to strength-default (nicht nur "overall next")
                    today_info["default_session_date_iso"] = (asof_date + timedelta(days=offset)).isoformat()
                    break

        if today_strength_raw and not today_has_run:
            today_info["today_session_key"] = today_strength_raw.get("session_key")
        if default_strength:
            today_info["default_session_key"] = default_strength.get("session_key")
            # For plan-check UI we want the gym session name here (not run-prioritized)
            today_info["default_session_name"] = default_strength.get("session_name")
            # weekday_index soll 0..6 sein (Mo..So), nicht "order_index" im Plan-Array
            def_wd = None
            for wd, sess in sessions_by_day.items():
                if sess and sess.get("session_key") == default_strength.get("session_key"):
                    def_wd = int(wd)
                    break
            if def_wd is not None:
                today_info["default_session_weekday_index"] = def_wd
                today_info["default_session_weekday"] = (["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"][def_wd])
    except Exception:
        pass

    # ------------------------------------------------------------
    # Plan week + layer (active week, deload/build, caps/mults)
    # - phase comes from the Gym-plan Wochenregeln SSOT.
    # ------------------------------------------------------------
    plan_week = _dashboard_plan_week_from_active_gym(today=asof_date) or _legacy_dashboard_plan_week(plan, today=asof_date)
    layer = {"has_config": False, "week_type": None, "rpe_cap": None, "volume_mult": None}
    try:
        start_date_iso = meta.get("start_date") if isinstance(meta, dict) else None
        if isinstance(start_date_iso, str) and start_date_iso.strip():
            start_d = datetime.strptime(start_date_iso.strip(), "%Y-%m-%d").date()
            today_d = asof_date
            days = (today_d - start_d).days

            if days >= 0:
                block_length = int(meta.get("block_length") or plan.get("block_length") or 4)
                total_weeks_raw = meta.get("total_weeks")
                try:
                    total_weeks = int(total_weeks_raw) if total_weeks_raw is not None else None
                except Exception:
                    total_weeks = None

                weekday = start_d.weekday()  # Mo=0..So=6
                week1_start = start_d if weekday == 0 else (start_d + timedelta(days=(7 - weekday)))

                if today_d < week1_start:
                    week_current = 1
                else:
                    week_current = ((today_d - week1_start).days // 7) + 1

                # week_override (manuell Woche setzen)
                if meta.get("week_override") is not None:
                    try:
                        week_current = int(meta["week_override"])
                    except Exception:
                        pass

                week_in_block = ((week_current - 1) % block_length) + 1

                # week_type override > standard rule
                wto = meta.get("week_type_override")
                if wto:
                    week_type = str(wto).strip().lower()
                else:
                    # Standard: letzte Woche im Block = deload, davor = overreach, sonst build
                    if week_in_block == block_length:
                        week_type = "deload"
                    elif week_in_block == (block_length - 1):
                        week_type = "overreach"
                    else:
                        week_type = "build"

                phase_label = {
                    "build": "BUILD",
                    "overreach": "OVERREACH",
                    "deload": "DELOAD",
                }.get(week_type, "")

                if plan_week is None:
                    plan_week = {
                        "start_date": start_date_iso.strip(),
                        "week_current": week_current,
                        "total_weeks": total_weeks,
                        "block_length": block_length,
                        "week_in_block": week_in_block,
                        "week_type": week_type,
                        "phase_label": phase_label,
                    }
                else:
                    week_type = str(plan_week.get("week_type") or week_type).strip().lower()
                    week_in_block = int(plan_week.get("week_in_block") or week_in_block)

                # Pull per-week plan overrides (if present)
                plan_rpe_cap = None
                plan_volume = None
                weeks = plan.get("weeks") if isinstance(plan.get("weeks"), list) else []
                if weeks and 1 <= week_in_block <= len(weeks):
                    w = weeks[week_in_block - 1] if isinstance(weeks[week_in_block - 1], dict) else {}
                    try:
                        plan_rpe_cap = float(w.get("rpe_cap")) if w.get("rpe_cap") is not None else None
                    except Exception:
                        plan_rpe_cap = None
                    try:
                        plan_volume = float(w.get("strength_volume_factor")) if w.get("strength_volume_factor") is not None else None
                    except Exception:
                        plan_volume = None

                defaults_rpe = {"build": 9.0, "overreach": 9.5, "deload": 6.5}
                defaults_vol = {"build": 1.0, "overreach": 1.0, "deload": 0.7}

                rpe_by_type = meta.get("rpe_cap_by_type") if isinstance(meta.get("rpe_cap_by_type"), dict) else {
                    "build": meta.get("build_rpe_cap", defaults_rpe["build"]),
                    "overreach": meta.get("overreach_rpe_cap", defaults_rpe["overreach"]),
                    "deload": meta.get("deload_rpe_cap", defaults_rpe["deload"]),
                }
                vol_by_type = meta.get("volume_mult_by_type") if isinstance(meta.get("volume_mult_by_type"), dict) else {
                    "build": meta.get("build_volume_mult", defaults_vol["build"]),
                    "overreach": meta.get("overreach_volume_mult", defaults_vol["overreach"]),
                    "deload": meta.get("deload_volume_mult", defaults_vol["deload"]),
                }

                def _finite_num(val):
                    try:
                        v = float(val)
                        return v
                    except Exception:
                        return None

                meta_cap = _finite_num(rpe_by_type.get(week_type))
                meta_vol = _finite_num(vol_by_type.get(week_type))

                # RPE cap is a "ceiling": if both exist, take the stricter (min).
                if plan_rpe_cap is not None and meta_cap is not None:
                    cap = min(plan_rpe_cap, meta_cap)
                else:
                    cap = plan_rpe_cap if plan_rpe_cap is not None else meta_cap

                # Volume multiplier is multiplicative: plan week factor * meta-by-type factor.
                if plan_volume is None and meta_vol is None:
                    vol = None
                else:
                    base_vol = plan_volume if plan_volume is not None else 1.0
                    type_vol = meta_vol if meta_vol is not None else 1.0
                    vol = base_vol * type_vol

                layer = {
                    "has_config": bool(cap is not None or vol is not None),
                    "week_type": week_type,
                    "rpe_cap": cap,
                    "volume_mult": vol,
                }
    except Exception:
        layer = {"has_config": False, "week_type": None, "rpe_cap": None, "volume_mult": None}

    # Kienzl daily decision overlay (must not contradict)
    kienzl_adj = None
    try:
        from kienzl import kienzl as _kienzl
        kienzl_adj = _kienzl.get_adjustments(asof_date.isoformat())
    except Exception:
        kienzl_adj = None

    if isinstance(kienzl_adj, dict) and kienzl_adj:
        # Do not modify plan-derived layer values here; just attach the daily adjustments for UI/reference.
        layer["kienzl"] = {
            "mode": kienzl_adj.get("mode"),
            "intensity_factor": kienzl_adj.get("intensity_factor"),
            "volume_factor": kienzl_adj.get("volume_factor"),
            "rpe_cap": kienzl_adj.get("rpe_cap"),
            "source": "kienzl_daily",
        }

    if debug:
        print("PLAN_CHECK_WEEK_OVERVIEW:", {
            "asof": asof_date.isoformat(),
            "today_idx": today_idx,
            "today_session_name": today_session_name,
            "today_is_rest": today_is_rest,
            "next_title": next_title,
            "next_date_iso": next_date_iso,
            "next_idx": next_idx,
            "week": plan_week,
            "layer": layer,
            "kienzl": kienzl_adj,
        })

    rv = {
        "ok": True,
        "plan": plan.get("name"),
        "plan_source": plan_source,
        "decision_mode": "core" if core_mode_enabled else "base",
        "meta": meta if isinstance(meta, dict) else {},
        "week": plan_week,
        "layer": layer,
        "adjustments": layer.get("kienzl") if isinstance(layer, dict) else None,
        "today": today_info,
        "sessions": sessions,  # bleibt wie bisher fürs Overview
    }
    if not sessions:
        rv["message"] = "Kein Kraftplan aktiv."
    return jsonify(rv)


def _apply_light_modifiers_to_decision(decision_obj: dict, row_obj: dict, name: str, device: str):
    structured = decision_obj.get("structured") if isinstance(decision_obj.get("structured"), dict) else {}
    if not structured:
        return decision_obj

    planned_max = _clean_float(row_obj.get("planned_rpe_max"))
    final_max = _clean_float(row_obj.get("final_rpe_max"))
    delta_rpe = 0.0
    if planned_max is not None and final_max is not None:
        delta_rpe = max(0.0, planned_max - final_max)

    def _safe_float(v):
        try:
            return float(v)
        except Exception:
            return None

    def _safe_int(v):
        try:
            return int(v)
        except Exception:
            return None

    reps_min = None
    reps_raw = str(row_obj.get("expected_reps") or "").strip()
    if reps_raw:
        reps_min, _reps_max = _parse_range(reps_raw, _clean_int)

    # LIGHT should preserve reference-near weights by default and make the
    # session easier via fewer reps / fewer sets / lower pressure.
    changed_weight = False
    new_reps = structured.get("new_reps") if isinstance(structured.get("new_reps"), list) else []
    changed_reps = False
    if new_reps:
        reps_out = [(_safe_int(r) if _safe_int(r) is not None else r) for r in new_reps]
        idx_candidates = [len(reps_out) - 1, 0] if len(reps_out) > 1 else [0]
        for idx in idx_candidates:
            rv = _safe_int(reps_out[idx])
            if rv is None:
                continue
            floor = reps_min if reps_min is not None else max(1, rv - 1)
            if rv > floor:
                reps_out[idx] = rv - 1
                changed_reps = True
                break
        structured["new_reps"] = reps_out

    # If load step cannot go down and reps are fixed at floor, trim one set for visible light pressure.
    if (not changed_weight) and (not changed_reps):
        reps_vals = structured.get("new_reps") if isinstance(structured.get("new_reps"), list) else []
        w_vals = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
        if len(reps_vals) > 1:
            structured["new_reps"] = reps_vals[:-1]
            if len(w_vals) > 1:
                structured["new_weights"] = w_vals[:-1]
            changed_reps = True

    structured["light_delta_rpe"] = round(delta_rpe, 2)
    structured["light_weight_factor"] = 1.0
    structured["light_weight_preserved"] = True

    # keep inline string aligned with structured payload
    reps_for_line = structured.get("new_reps") if isinstance(structured.get("new_reps"), list) else []
    w_for_line = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
    if reps_for_line and w_for_line:
        reps_txt = "/".join(str(int(r)) for r in reps_for_line if _safe_int(r) is not None)
        if w_for_line and all(_safe_float(x) is not None for x in w_for_line):
            w_num = [_safe_float(x) for x in w_for_line]
            if w_num and all(abs(float(v) - float(w_num[0])) < 0.001 for v in w_num):
                w_txt = f"{_format_weight_de(w_num[0])}kg"
            else:
                w_txt = f"{'/'.join(_format_weight_de(v) for v in w_num)}kg"
            decision_obj["suggestion_inline"] = f"{len(reps_for_line)} x {reps_txt} x {w_txt}"

    decision_obj["structured"] = structured
    return decision_obj






@app.get("/api/dashboard/plan_check_for_session")
def api_dashboard_plan_check_for_session():
    session_key = (request.args.get("session_key") or "").strip()
    debug = request.args.get("debug") == "1"
    mode = (request.args.get("mode") or "").strip().lower() or "normal"
    day_id = (request.args.get("day") or "").strip()
    if not session_key:
        return jsonify({"ok": False, "error": "missing_session_key"}), 400

    core_mode_enabled = bool(_get_core_mode_enabled())
    plan, plan_source = _active_plan_for_decision(core_mode_enabled)
    if not isinstance(plan, dict):
        return jsonify({"ok": False, "error": "no_active_plan"}), 404

    sessions = _plan_strength_sessions(plan)
    target = next((s for s in sessions if s["session_key"] == session_key), None)
    if not target:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    expected_info = expected_exercises_for_session(
        target,
        day_id=day_id,
        plan_ctx=plan,
        mode=mode,
    )

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        workout_by_name = None
        norm_target = _norm_text(target["session_name"])
        if norm_target:
            workout_by_name = cur.execute("""
                SELECT *
                FROM workouts
                WHERE LOWER(TRIM(COALESCE(name, ''))) = ?
                ORDER BY date_iso DESC, id DESC
                LIMIT 1
            """, (norm_target,)).fetchone()

        workout = workout_by_name
    finally:
        conn.close()

    def _build_today_prescription(*, title: str, device: str, planned: dict, structured: dict, done: dict, primary_change: dict | None):
        planned_sets = _clean_int(planned.get("sets")) or 0
        reps_min = _clean_int(planned.get("reps_min"))
        reps_max = _clean_int(planned.get("reps_max"))
        reps_values = structured.get("new_reps") if isinstance(structured.get("new_reps"), list) else []
        weight_values = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
        target_rpe = planned.get("display_rpe") or _format_rpe_range(_clean_float(planned.get("rpe_min")), _clean_float(planned.get("rpe_max")))
        ref = done.get("last_reference") if isinstance(done.get("last_reference"), dict) else None
        ref_weight = _clean_float(ref.get("weight")) if ref else None
        ref_reps = _clean_int(ref.get("reps")) if ref else None
        ref_rpe = _clean_float(ref.get("rpe")) if ref else None

        def _compact_target_weight_text(value):
            if value is None:
                return None
            try:
                v = float(value)
            except Exception:
                return None
            if not math.isfinite(v) or v <= 0:
                return None
            return _format_weight_de(v)

        if not reps_values and planned_sets:
            fill_rep = reps_max or reps_min or None
            if fill_rep is not None:
                reps_values = [fill_rep for _ in range(planned_sets)]
        if not weight_values and structured.get("working_weight") is not None and planned_sets:
            fill_weight = _clean_float(structured.get("working_weight"))
            if fill_weight is not None:
                weight_values = [fill_weight for _ in range(planned_sets)]

        count = max(len(reps_values), len(weight_values), planned_sets)
        if count <= 0:
            count = 1 if (reps_values or weight_values) else 0

        while len(reps_values) < count:
            reps_values.append(reps_values[-1] if reps_values else (reps_max or reps_min or 0))
        while len(weight_values) < count:
            weight_values.append(weight_values[-1] if weight_values else _clean_float(structured.get("working_weight")))

        weights_clean = [_clean_float(x) for x in weight_values[:count]]
        reps_clean = [_clean_int(x) for x in reps_values[:count]]
        top_weight = max([w for w in weights_clean if w is not None], default=None)
        rep_mid = None
        if reps_min is not None or reps_max is not None:
            if reps_min is not None and reps_max is not None:
                rep_mid = int(round((reps_min + reps_max) / 2.0))
            else:
                rep_mid = reps_min if reps_min is not None else reps_max

        sets_payload = []
        for idx in range(count):
            weight = weights_clean[idx] if idx < len(weights_clean) else None
            rep_val = reps_clean[idx] if idx < len(reps_clean) else None
            is_top = weight is not None and top_weight is not None and abs(weight - top_weight) < 0.001
            target_min = reps_min
            target_max = reps_max
            if reps_min is not None and reps_max is not None and count > 1:
                if is_top and idx == 0:
                    target_max = min(reps_max, rep_mid or reps_max)
                elif rep_mid is not None:
                    target_min = max(reps_min, rep_mid)
            if rep_val is not None and target_min is None and target_max is None:
                target_min = rep_val
                target_max = rep_val
            sets_payload.append({
                "set_index": idx + 1,
                "index": idx + 1,
                "role": ("top" if idx == 0 and is_top else ("backoff" if idx > 0 and weight is not None and top_weight is not None and weight < top_weight else "normal")),
                "target_weight": weight,
                "weight": weight,
                "target_weight_text": (_compact_target_weight_text(weight) + " kg") if weight is not None else None,
                "target_reps_min": target_min,
                "target_reps_max": target_max,
                "reps_min": target_min,
                "reps_max": target_max,
                "target_rpe": target_rpe,
                "rpe_target": target_rpe,
                "note": "backoff" if (idx > 0 and weight is not None and top_weight is not None and weight < top_weight) else "",
            })

        pill_text = ""
        if isinstance(primary_change, dict):
            pill_text = str(primary_change.get("kind") or "").strip().lower()
        adjustment_type = str(structured.get("mode") or "").strip().lower()
        label = ""
        if isinstance(primary_change, dict):
            kind = str(primary_change.get("kind") or "")
            direction = str(primary_change.get("dir") or "")
            if kind == "sets" and direction == "up":
                label = "Sätze ↑"
            elif kind == "sets" and direction == "down":
                label = "Sätze ↓"
            elif kind == "weight" and direction == "up":
                label = "Gewicht ↑"
            elif kind == "weight" and direction == "down":
                label = "Gewicht ↓"
        if not label:
            label = "halten"
        reason = "nur bei normalem Warm-up" if label in {"Sätze ↑", "Gewicht ↑"} else ("kontrolliert" if label == "halten" else "nicht erzwingen")
        gpt_reason_short = "Top-Satz drin lassen, aber keinen Zusatzdruck."
        if label == "Gewicht ↓":
            gpt_reason_short = "Heute Last etwas glätten, nicht schwerer erzwingen."
        elif label == "Sätze ↑":
            gpt_reason_short = "Zusatzsatz nur dann, wenn der Einstieg klar gut läuft."
        elif label == "Gewicht ↑":
            gpt_reason_short = "Steigerung ist möglich, aber nur bei normalem Warm-up."
        return {
            "exercise_name": title,
            "device": device,
            "reference": {
                "weight": ref_weight,
                "weight_text": (_compact_target_weight_text(ref_weight) + " kg") if ref_weight is not None else None,
                "reps": ref_reps,
                "rpe": ref_rpe,
            },
            "sets": sets_payload,
            "core_adjustment": {
                "type": adjustment_type or pill_text or "hold",
                "label": label,
                "reason": reason,
            },
            "change": {
                "label": label,
                "direction": ("up" if "↑" in label else "down" if "↓" in label else ("conservative" if reason == "nicht erzwingen" else "hold")),
                "reason_short": reason,
            },
            "gpt_reason_short": gpt_reason_short,
        }

    if not workout:
        expected_rows = expected_info.get("exercises") or []
        plan_targets = []
        for row in expected_rows:
            if not isinstance(row, dict):
                continue
            name = (row.get("name") or "").strip()
            if not name:
                continue
            plan_targets.append({
                "name": name,
                "variation": (row.get("variation") or "").strip(),
                "device": (row.get("device") or "").strip(),
            })
        history_map_same_session = _latest_exercise_history(plan_targets, session_name=target["session_name"])
        history_map_any = _latest_exercise_history(plan_targets)

        items = []
        conn = get_training_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        try:
            for slot_index, row in enumerate(expected_rows):
                name = (row.get("name") or "").strip()
                if not name:
                    continue

                plan_variation = (row.get("variation") or "").strip()
                plan_device = (row.get("device") or "").strip()
                reps_min = 0
                reps_max = 0
                reps_raw = row.get("expected_reps") or ""
                if isinstance(reps_raw, str) and "-" in reps_raw:
                    try:
                        rmin, rmax = reps_raw.split("-", 1)
                        reps_min = int(rmin.strip())
                        reps_max = int(rmax.strip())
                    except Exception:
                        pass
                elif isinstance(reps_raw, str) and reps_raw.strip().isdigit():
                    reps_min = int(reps_raw.strip())
                    reps_max = int(reps_raw.strip())

                use_sets = row.get("final_sets") if mode == "light" else row.get("planned_sets")
                use_rpe_min = row.get("final_rpe_min") if mode == "light" else row.get("planned_rpe_min")
                use_rpe_max = row.get("final_rpe_max") if mode == "light" else row.get("planned_rpe_max")
                planned_rpe_values = _rpe_series_for_sets(use_rpe_min, use_rpe_max, use_sets)

                history = _history_entry_for_target(
                    history_map_same_session,
                    history_map_any,
                    name=name,
                    variation=plan_variation,
                    device=plan_device,
                )

                plan_row = {
                    "exercise_name": name,
                    "variation": plan_variation,
                    "device": plan_device,
                    "sets": use_sets,
                    "reps_min": reps_min or None,
                    "reps_max": reps_max or None,
                    "rpe_min": use_rpe_min,
                    "rpe_max": use_rpe_max,
                }
                exercise_report = _exercise_report(
                    plan_row,
                    [],
                    "planned_missing",
                    history=history,
                )
                exercise_report["mode_hint"] = str(mode or "normal").upper()
                exercise_report["slot_index"] = slot_index
                exercise_report["exercise_key"] = row.get("exercise_key")

                history_occ, history_source = _previous_exercise_occurrences_with_fallback(
                    cur,
                    name=name,
                    variation=plan_variation,
                    device=plan_device,
                    session_name=target["session_name"],
                    current_date_iso="9999-12-31",
                    current_workout_id=2**31 - 1,
                    limit=8,
                )
                if history_occ:
                    exercise_report["history_sets"] = history_occ[0].get("sets") or []
                    exercise_report["history_source"] = history_source or "latest_any"
                    exercise_report["history_context"] = _history_context_from_occurrences(
                        history_occ,
                        reps_min=_clean_int(plan_row.get("reps_min")),
                        reps_max=_clean_int(plan_row.get("reps_max")),
                        planned_sets=_clean_int(use_sets),
                    )

                decision = _progression_decision(exercise_report)
                if mode == "light":
                    decision = _apply_light_modifiers_to_decision(decision, row, name, plan_device)
                structured = decision.get("structured") if isinstance(decision.get("structured"), dict) else {}
                new_weights = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
                planned_weight_suggestion = None
                if new_weights:
                    planned_weight_suggestion = _clean_float(new_weights[0])
                if planned_weight_suggestion is None:
                    planned_weight_suggestion = _clean_float(structured.get("working_weight"))

                items.append({
                    "title": name,
                    "exercise_key": row.get("exercise_key"),
                    "slot_index": row.get("slot"),
                    "coverage": "planned_missing",
                    "suggestion_inline": decision.get("suggestion_inline") or "",
                    "pill": decision.get("pill") or {"text": "Einbauen", "color": "red"},
                    "structured": structured,
                    "planned": {
                        "device": plan_device,
                        "variation": plan_variation,
                        "sets": _clean_int(use_sets) or 0,
                        "reps_min": reps_min,
                        "reps_max": reps_max,
                        "rpe_min": _clean_float(use_rpe_min),
                        "rpe_max": _clean_float(use_rpe_max),
                        "rpe_values": planned_rpe_values,
                        "display_rpe": _format_rpe_targets(planned_rpe_values) or _format_rpe_range(_clean_float(use_rpe_min), _clean_float(use_rpe_max)),
                        "weight_suggestion": planned_weight_suggestion,
                    },
                    "done": {
                        "sets": 0,
                        "reps": [],
                        "avg_rpe": None,
                        "weights": [],
                        "rpes": [],
                        "set_numbers": [],
                        "last_reference": _fallback_reference(exercise_report.get("prev_stats")) or None,
                    },
                    "todays_prescription": _build_today_prescription(
                        title=name,
                        device=plan_device,
                        planned={
                            "sets": _clean_int(use_sets) or 0,
                            "reps_min": reps_min,
                            "reps_max": reps_max,
                            "rpe_min": _clean_float(use_rpe_min),
                            "rpe_max": _clean_float(use_rpe_max),
                            "display_rpe": _format_rpe_targets(planned_rpe_values) or _format_rpe_range(_clean_float(use_rpe_min), _clean_float(use_rpe_max)),
                        },
                        structured=structured,
                        done={"last_reference": _fallback_reference(exercise_report.get("prev_stats")) or None},
                        primary_change=None,
                    ),
                })
        finally:
            conn.close()

        for item in items:
            structured = item.get("structured") if isinstance(item.get("structured"), dict) else {}
            guard = structured.get("weight_guard") if isinstance(structured.get("weight_guard"), dict) else {}
            if bool(guard.get("local_reason_present")):
                continue
            history_profile = structured.get("history_profile") if isinstance(structured.get("history_profile"), dict) else {}
            reference_weight = next(
                (
                    value
                    for value in (
                        _clean_float(history_profile.get("current_standard_weight")),
                        _clean_float(history_profile.get("proposal_basis_weight")),
                        _clean_float(history_profile.get("heavy_floor_weight")),
                        _clean_float(history_profile.get("last_plausible_working_load")),
                    )
                    if value is not None
                ),
                None,
            )
            weights = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
            current_weight = _clean_float(weights[0]) if weights else _clean_float(structured.get("working_weight"))
            if reference_weight is None or current_weight is None:
                continue
            planned = item.get("planned") if isinstance(item.get("planned"), dict) else {}
            step = _step_for_device_type(_detect_device_type(str(item.get("title") or ""), str(planned.get("device") or "")))
            floor_weight = _round_to_step(max(0.0, reference_weight - step), step)
            if current_weight >= floor_weight - 0.001:
                continue
            if weights:
                weights[0] = floor_weight
                structured["new_weights"] = weights
            structured["working_weight"] = floor_weight
            planned["weight_suggestion"] = floor_weight
            guard.update(
                {
                    "global_reduction_blocked": True,
                    "block_reason": "missing_session_rebuild_no_local_reason",
                    "final_top_weight": floor_weight,
                }
            )
            structured["weight_guard"] = guard
            item["structured"] = structured
            item["planned"] = planned

        expected_summary = {
            "count": len(expected_rows),
            "missing_count": len(expected_rows),
            "unexpected_count": 0,
        }
        return jsonify({
            "ok": True,
            "session": {
                "session_key": target["session_key"],
                "session_name": target["session_name"],
                "meta": {
                    "plan_source": plan_source,
                    "core_mode_enabled": core_mode_enabled,
                },
            },
            "reference_workout": None,
            "items": items,
            "expected_exercises": expected_info,
            "expected_exercises_summary": expected_summary,
            "expected_exercises_lines": [
                f"Expected: {expected_summary['count']} · Missing: {expected_summary['missing_count']} · Unexpected: {expected_summary['unexpected_count']}",
            ],
            "message": "Noch keine Logs für diese Einheit. Vorschläge basieren auf den zuletzt verfügbaren Daten."
        })

    workout_dict = dict(workout)
    workout_report = load_plan_check_report(workout_dict["id"])
    needs_recompute = debug
    if workout_report:
        if workout_report.get("version") != PLAN_CHECK_VERSION:
            needs_recompute = True
        if workout_report.get("plan_id") != plan.get("id"):
            needs_recompute = True
        for ex in workout_report.get("exercises") or []:
            done = ex.get("done")
            if not isinstance(done, dict):
                needs_recompute = True
                break
            if "weights" not in done or "rpes" not in done:
                needs_recompute = True
                break
    if not workout_report or needs_recompute:
        workout_report = build_plan_check_for_workout(workout_dict["id"])
        save_plan_check_report(workout_report)

    expected_info = expected_exercises_for_session(
        target,
        day_id=workout_dict.get("date_iso") or day_id,
        plan_ctx=plan,
        mode=mode,
    )
    expected_rows = expected_info.get("exercises") or []

    _, exercises, _ = _fetch_workout_with_sets(workout_dict["id"])
    log_exercises = _build_log_exercises(exercises)
    done_exercise_ids = [ex.get("id") for ex in log_exercises if ex.get("id") is not None]

    plan_targets = []
    for row in expected_rows:
        if not isinstance(row, dict):
            continue
        name = (row.get("name") or "").strip()
        if not name:
            continue
        plan_targets.append({
            "name": name,
            "variation": (row.get("variation") or "").strip(),
            "device": (row.get("device") or "").strip(),
        })

    history_map_same_session = _latest_exercise_history(plan_targets, session_name=target["session_name"])
    history_map_any = _latest_exercise_history(plan_targets)

    items = []
    exercise_reports = []
    debug_items = [] if debug else None
    item_meta = []
    planned_exercise_ids = []
    matched_ids = set()
    extra_ids = []
    status = "green"
    flags = []

    def _round_down_to_step(value: float, step: float) -> float:
        if step <= 0:
            return value
        return math.floor(value / step) * step

    def _normalize_done_set_numbers(nums: list, target_len: int) -> list[int]:
        out = []
        seen = set()
        for idx in range(max(0, target_len)):
            raw = nums[idx] if idx < len(nums) else None
            val = _clean_int(raw)
            if val is None or val <= 0 or val in seen:
                val = idx + 1
            seen.add(val)
            out.append(val)
        return out

    def _compact_target_weight_text(value):
        if value is None:
            return None
        try:
            v = float(value)
        except Exception:
            return None
        if not math.isfinite(v) or v <= 0:
            return None
        return _format_weight_de(v)

    def _build_today_prescription(*, title: str, device: str, planned: dict, structured: dict, done: dict, primary_change: dict | None):
        planned_sets = _clean_int(planned.get("sets")) or 0
        reps_min = _clean_int(planned.get("reps_min"))
        reps_max = _clean_int(planned.get("reps_max"))
        reps_values = structured.get("new_reps") if isinstance(structured.get("new_reps"), list) else []
        weight_values = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
        target_rpe = planned.get("display_rpe") or _format_rpe_range(_clean_float(planned.get("rpe_min")), _clean_float(planned.get("rpe_max")))
        ref = done.get("last_reference") if isinstance(done.get("last_reference"), dict) else None
        ref_weight = _clean_float(ref.get("weight")) if ref else None
        ref_reps = _clean_int(ref.get("reps")) if ref else None
        ref_rpe = _clean_float(ref.get("rpe")) if ref else None

        if not reps_values and planned_sets:
            fill_rep = reps_max or reps_min or None
            if fill_rep is not None:
                reps_values = [fill_rep for _ in range(planned_sets)]
        if not weight_values and structured.get("working_weight") is not None and planned_sets:
            fill_weight = _clean_float(structured.get("working_weight"))
            if fill_weight is not None:
                weight_values = [fill_weight for _ in range(planned_sets)]

        count = max(len(reps_values), len(weight_values), planned_sets)
        if count <= 0:
            count = 1 if (reps_values or weight_values) else 0

        while len(reps_values) < count:
            reps_values.append(reps_values[-1] if reps_values else (reps_max or reps_min or 0))
        while len(weight_values) < count:
            weight_values.append(weight_values[-1] if weight_values else _clean_float(structured.get("working_weight")))

        weights_clean = [_clean_float(x) for x in weight_values[:count]]
        reps_clean = [_clean_int(x) for x in reps_values[:count]]
        top_weight = max([w for w in weights_clean if w is not None], default=None)
        rep_mid = None
        if reps_min is not None or reps_max is not None:
            if reps_min is not None and reps_max is not None:
                rep_mid = int(round((reps_min + reps_max) / 2.0))
            else:
                rep_mid = reps_min if reps_min is not None else reps_max

        sets_payload = []
        for idx in range(count):
            weight = weights_clean[idx] if idx < len(weights_clean) else None
            rep_val = reps_clean[idx] if idx < len(reps_clean) else None
            is_top = weight is not None and top_weight is not None and abs(weight - top_weight) < 0.001
            target_min = reps_min
            target_max = reps_max
            if reps_min is not None and reps_max is not None and count > 1:
                if is_top and idx == 0:
                    target_max = min(reps_max, rep_mid or reps_max)
                elif rep_mid is not None:
                    target_min = max(reps_min, rep_mid)
            if rep_val is not None and target_min is None and target_max is None:
                target_min = rep_val
                target_max = rep_val
            sets_payload.append({
                "set_index": idx + 1,
                "index": idx + 1,
                "role": ("top" if idx == 0 and is_top else ("backoff" if idx > 0 and weight is not None and top_weight is not None and weight < top_weight else "normal")),
                "target_weight": weight,
                "weight": weight,
                "target_weight_text": (_compact_target_weight_text(weight) + " kg") if weight is not None else None,
                "target_reps_min": target_min,
                "target_reps_max": target_max,
                "reps_min": target_min,
                "reps_max": target_max,
                "target_rpe": target_rpe,
                "rpe_target": target_rpe,
                "note": "backoff" if (idx > 0 and weight is not None and top_weight is not None and weight < top_weight) else "",
            })

        pill_text = ""
        if isinstance(primary_change, dict):
            pill_text = str(primary_change.get("kind") or "").strip().lower()
        adjustment_type = str(structured.get("mode") or "").strip().lower()
        label = ""
        if isinstance(primary_change, dict):
            kind = str(primary_change.get("kind") or "")
            direction = str(primary_change.get("dir") or "")
            if kind == "sets" and direction == "up":
                label = "Sätze ↑"
            elif kind == "sets" and direction == "down":
                label = "Sätze ↓"
            elif kind == "weight" and direction == "up":
                label = "Gewicht ↑"
            elif kind == "weight" and direction == "down":
                label = "Gewicht ↓"
        if not label:
            label = "halten"
        reason = "nur bei normalem Warm-up" if label in {"Sätze ↑", "Gewicht ↑"} else ("kontrolliert" if label == "halten" else "nicht erzwingen")
        gpt_reason_short = "Top-Satz drin lassen, aber keinen Zusatzdruck."
        if label == "Gewicht ↓":
            gpt_reason_short = "Heute Last etwas glätten, nicht schwerer erzwingen."
        elif label == "Sätze ↑":
            gpt_reason_short = "Zusatzsatz nur dann, wenn der Einstieg klar gut läuft."
        elif label == "Gewicht ↑":
            gpt_reason_short = "Steigerung ist möglich, aber nur bei normalem Warm-up."
        return {
            "exercise_name": title,
            "device": device,
            "reference": {
                "weight": ref_weight,
                "weight_text": (_compact_target_weight_text(ref_weight) + " kg") if ref_weight is not None else None,
                "reps": ref_reps,
                "rpe": ref_rpe,
            },
            "sets": sets_payload,
            "core_adjustment": {
                "type": adjustment_type or pill_text or "hold",
                "label": label,
                "reason": reason,
            },
            "change": {
                "label": label,
                "direction": ("up" if "↑" in label else "down" if "↓" in label else ("conservative" if reason == "nicht erzwingen" else "hold")),
                "reason_short": reason,
            },
            "gpt_reason_short": gpt_reason_short,
        }

    def _structured_top_weight(structured_obj: dict | None) -> float | None:
        structured_obj = structured_obj if isinstance(structured_obj, dict) else {}
        weights = structured_obj.get("new_weights") if isinstance(structured_obj.get("new_weights"), list) else []
        if weights:
            return _clean_float(weights[0])
        return _clean_float(structured_obj.get("working_weight"))

    def _reference_top_weight_from_item(item_obj: dict) -> float | None:
        done_obj = item_obj.get("done") if isinstance(item_obj.get("done"), dict) else {}
        last_ref = done_obj.get("last_reference") if isinstance(done_obj.get("last_reference"), dict) else {}
        ref_weight = _clean_float(last_ref.get("weight"))
        if ref_weight is not None:
            return ref_weight
        done_weights = done_obj.get("weights") if isinstance(done_obj.get("weights"), list) else []
        for val in done_weights:
            num = _clean_float(val)
            if num is not None:
                return num
        structured_obj = item_obj.get("structured") if isinstance(item_obj.get("structured"), dict) else {}
        history_profile = structured_obj.get("history_profile") if isinstance(structured_obj.get("history_profile"), dict) else {}
        for key in ("current_standard_weight", "proposal_basis_weight", "heavy_floor_weight", "last_plausible_working_load"):
            num = _clean_float(history_profile.get(key))
            if num is not None:
                return num
        return None

    def _local_weight_down_from_item(item_obj: dict) -> bool:
        structured_obj = item_obj.get("structured") if isinstance(item_obj.get("structured"), dict) else {}
        guard = structured_obj.get("weight_guard") if isinstance(structured_obj.get("weight_guard"), dict) else {}
        return bool(guard.get("local_reason_present"))

    def _reanchor_item_top_weight(item_obj: dict, debug_reason: str) -> dict:
        planned_obj = item_obj.get("planned") if isinstance(item_obj.get("planned"), dict) else {}
        structured_obj = item_obj.get("structured") if isinstance(item_obj.get("structured"), dict) else {}
        ref_top = _reference_top_weight_from_item(item_obj)
        top_now = _structured_top_weight(structured_obj)
        if ref_top is None or top_now is None:
            return item_obj
        title = str(item_obj.get("title") or "")
        device = str(planned_obj.get("device") or "")
        step = _step_for_device_type(_detect_device_type(title, device))
        floor_weight = _round_to_step(max(0.0, float(ref_top) - float(step)), float(step))
        if floor_weight is None:
            floor_weight = max(0.0, float(ref_top) - float(step))
        if top_now >= (float(floor_weight) - 0.001):
            return item_obj
        lifted = round(float(floor_weight), 2)
        weights = structured_obj.get("new_weights") if isinstance(structured_obj.get("new_weights"), list) else []
        if weights:
            weights[0] = lifted
            structured_obj["new_weights"] = weights
        structured_obj["working_weight"] = lifted
        planned_obj["weight_suggestion"] = lifted
        guard = structured_obj.get("weight_guard") if isinstance(structured_obj.get("weight_guard"), dict) else {}
        guard["global_reduction_blocked"] = True
        guard["block_reason"] = debug_reason
        guard["final_top_weight"] = lifted
        structured_obj["weight_guard"] = guard
        item_obj["structured"] = structured_obj
        item_obj["planned"] = planned_obj
        return item_obj

    def _rebuild_if_global_downshift(items_list: list[dict]) -> list[dict]:
        if not items_list:
            return items_list
        total = 0
        down_without_local = 0
        inspected: list[dict] = []
        for item_obj in items_list:
            ref_top = _reference_top_weight_from_item(item_obj)
            planned_top = _structured_top_weight(item_obj.get("structured"))
            if ref_top is None or planned_top is None:
                inspected.append(item_obj)
                continue
            total += 1
            title = str(item_obj.get("title") or "")
            device = str((item_obj.get("planned") or {}).get("device") or "")
            step = _step_for_device_type(_detect_device_type(title, device))
            if planned_top < (float(ref_top) - float(step) - 0.001) and (not _local_weight_down_from_item(item_obj)):
                down_without_local += 1
            inspected.append(item_obj)
        if total <= 0 or down_without_local <= (total / 2.0):
            return inspected
        rebuilt = []
        for item_obj in inspected:
            if _local_weight_down_from_item(item_obj):
                rebuilt.append(item_obj)
                continue
            rebuilt.append(_reanchor_item_top_weight(item_obj, "global_rebuild_no_local_reason"))
        return rebuilt

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        has_session_key = _column_exists(cur, "workouts", "session_key")
        mapping_cache = _load_plan_session_map(cur, plan.get("id"), session_key)

        for slot_index, row in enumerate(expected_rows):
            if not isinstance(row, dict):
                continue
            plan_name = (row.get("name") or "").strip()
            if not plan_name:
                continue
            plan_variation = (row.get("variation") or "").strip()
            plan_device = (row.get("device") or "").strip()
            name_norm = _norm_text(plan_name)
            variation_norm = _norm_text(plan_variation)
            device_norm = _norm_text(plan_device)

            mapping = mapping_cache.get(slot_index)
            planned_ex_id = None
            planned_strategy = "none"
            matched_log = None
            match_strategy = "none"
            replacement_used = None

            if mapping and mapping.get("exercise_id"):
                candidate_id = mapping.get("exercise_id")
                if _exercise_exists(cur, candidate_id):
                    planned_ex_id = candidate_id
                    planned_strategy = "mapping_cache"

            # SSOT for right-hand "last set info": prefer exact exercise-name matches
            # from the selected reference workout. Variation/device are tie-breakers only.
            candidates = [
                ex for ex in log_exercises
                if ex.get("name_norm") == name_norm
                and ex.get("id") not in matched_ids
            ]
            if candidates:
                def _candidate_score(ex: dict) -> tuple[int, int, int]:
                    score = 0
                    ex_var = ex.get("variation_norm") or ""
                    ex_dev = ex.get("device_norm") or ""
                    if variation_norm:
                        if ex_var == variation_norm:
                            score += 6
                        elif ex_var:
                            score -= 1
                    if device_norm:
                        if ex_dev == device_norm:
                            score += 5
                        elif ex_dev:
                            score -= 1
                    sets_n = len(ex.get("sets") or [])
                    ex_id = int(ex.get("id") or 0)
                    return (score, sets_n, ex_id)

                matched_log = max(candidates, key=_candidate_score)
                strict_var = bool(variation_norm and (matched_log.get("variation_norm") == variation_norm))
                strict_dev = bool(device_norm and (matched_log.get("device_norm") == device_norm))
                match_strategy = "reference_match_strict" if (strict_var or strict_dev) else "reference_match_name"

            if matched_log is None:
                replacement_keys = set(_replacement_candidates(plan_name))
                if replacement_keys:
                    repl_candidates = [
                        ex for ex in log_exercises
                        if ex.get("id") not in matched_ids
                        and _replacement_key(ex.get("name") or "") in replacement_keys
                    ]
                    if repl_candidates:
                        matched_log = _pick_best_log(repl_candidates)
                        replacement_used = matched_log.get("name")
                        match_strategy = "replacement_match"

            if planned_ex_id is None:
                latest_id = _find_latest_exercise_id(
                    cur,
                    name=plan_name,
                    variation=plan_variation,
                    device=plan_device,
                    session_key=session_key,
                    session_name=target["session_name"],
                    has_session_key=has_session_key
                )
                if latest_id:
                    planned_ex_id = latest_id
                    planned_strategy = "history_match_session"

            if planned_ex_id is None:
                latest_any = _find_latest_exercise_id_any(
                    cur,
                    name=plan_name,
                    variation=plan_variation,
                    device=plan_device
                )
                if latest_any:
                    planned_ex_id = latest_any
                    planned_strategy = "history_match_any"

            if planned_ex_id is None and matched_log:
                planned_ex_id = matched_log.get("id")
                planned_strategy = "reference_fallback"

            _upsert_plan_session_map(
                cur,
                plan.get("id"),
                session_key,
                slot_index,
                plan_name,
                plan_variation,
                plan_device,
                planned_ex_id
            )

            if planned_ex_id is not None:
                planned_exercise_ids.append(planned_ex_id)

            if matched_log:
                matched_ids.add(matched_log.get("id"))

            history = _history_entry_for_target(
                history_map_same_session,
                history_map_any,
                name=plan_name,
                variation=plan_variation,
                device=plan_device,
            )

            coverage = "planned_missing"
            if matched_log:
                coverage = "planned_done_substitute" if replacement_used else "planned_done"

            use_sets = row.get("final_sets") if mode == "light" else row.get("planned_sets")
            use_rpe_min = row.get("final_rpe_min") if mode == "light" else row.get("planned_rpe_min")
            use_rpe_max = row.get("final_rpe_max") if mode == "light" else row.get("planned_rpe_max")
            plan_row = {
                "exercise_name": plan_name,
                "variation": plan_variation,
                "device": plan_device,
                "sets": use_sets,
                "reps_min": None,
                "reps_max": None,
                "rpe_min": use_rpe_min,
                "rpe_max": use_rpe_max,
            }
            reps_raw = row.get("expected_reps") or ""
            if isinstance(reps_raw, str) and "-" in reps_raw:
                try:
                    rmin, rmax = reps_raw.split("-", 1)
                    plan_row["reps_min"] = int(rmin.strip())
                    plan_row["reps_max"] = int(rmax.strip())
                except Exception:
                    pass
            elif isinstance(reps_raw, str) and reps_raw.strip().isdigit():
                plan_row["reps_min"] = int(reps_raw.strip())
                plan_row["reps_max"] = int(reps_raw.strip())

            exercise_report = _exercise_report(
                plan_row,
                [matched_log] if matched_log else [],
                coverage,
                history=history
            )
            exercise_report["mode_hint"] = str(mode or "normal").upper()
            exercise_report["slot_index"] = slot_index
            exercise_report["exercise_key"] = row.get("exercise_key")

            history_sets = []
            history_source = None
            history_occ, history_source = _previous_exercise_occurrences_with_fallback(
                cur,
                name=plan_name,
                variation=plan_variation,
                device=plan_device,
                session_name=target["session_name"],
                current_date_iso=workout_dict.get("date_iso") or "",
                current_workout_id=workout_dict.get("id"),
                limit=8,
            )
            if history_occ:
                exercise_report["history_context"] = _history_context_from_occurrences(
                    history_occ,
                    reps_min=_clean_int(plan_row.get("reps_min")),
                    reps_max=_clean_int(plan_row.get("reps_max")),
                    planned_sets=_clean_int(use_sets),
                )
                if coverage in ("planned_missing", "planned_done_substitute", "replaced_done"):
                    history_sets = history_occ[0].get("sets") or []
            if history_sets:
                exercise_report["history_sets"] = history_sets
                exercise_report["history_source"] = history_source or "history_match"

            prev_name = plan_name
            prev_variation = plan_variation
            prev_device = plan_device

            prev_occ, _prev_source = _previous_exercise_occurrences_with_fallback(
                cur,
                name=prev_name,
                variation=prev_variation,
                device=prev_device,
                session_name=target["session_name"],
                current_date_iso=workout_dict.get("date_iso") or "",
                current_workout_id=workout_dict.get("id"),
                limit=2,
            )
            prev_stats = {}
            if prev_occ:
                prev1 = prev_occ[0]
                prev_stats["prev1"] = {
                    "workout_id": prev1.get("workout_id"),
                    "date_iso": prev1.get("date_iso"),
                    "reference": _reference_set_from_sets(prev1.get("sets") or []),
                }
            if len(prev_occ) > 1:
                prev2 = prev_occ[1]
                prev_stats["prev2"] = {
                    "workout_id": prev2.get("workout_id"),
                    "date_iso": prev2.get("date_iso"),
                    "reference": _reference_set_from_sets(prev2.get("sets") or []),
                }
            if prev_stats:
                exercise_report["prev_stats"] = prev_stats

            exercise_reports.append(exercise_report)
            decision = _progression_decision(exercise_report)
            if mode == "light":
                decision = _apply_light_modifiers_to_decision(decision, row, plan_name, plan_device)
            done = exercise_report.get("done") if isinstance(exercise_report.get("done"), dict) else {}
            done_reps = done.get("reps") if isinstance(done.get("reps"), list) else []
            done_weights = done.get("weights") if isinstance(done.get("weights"), list) else []
            done_rpes = done.get("rpes") if isinstance(done.get("rpes"), list) else []
            done_set_count = max(len(done_reps), len(done_weights), len(done_rpes))
            done_set_numbers = _normalize_done_set_numbers(
                done.get("set_numbers") if isinstance(done.get("set_numbers"), list) else [],
                done_set_count,
            )
            structured = decision.get("structured") if isinstance(decision.get("structured"), dict) else {}
            new_weights = structured.get("new_weights") if isinstance(structured.get("new_weights"), list) else []
            planned_weight_suggestion = None
            if new_weights:
                planned_weight_suggestion = _clean_float(new_weights[0])
            if planned_weight_suggestion is None:
                planned_weight_suggestion = _clean_float(structured.get("working_weight"))
            planned_sets = _clean_int(use_sets) or 0
            planned_rpe_values = _rpe_series_for_sets(use_rpe_min, use_rpe_max, planned_sets)
            planned_display_rpe = _format_rpe_targets(planned_rpe_values) or _format_rpe_range(_clean_float(use_rpe_min), _clean_float(use_rpe_max))
            done_avg_rpe = done.get("avg_rpe")
            rpe_status = None
            if done_avg_rpe is not None and use_rpe_min is not None and use_rpe_max is not None:
                try:
                    avg_val = float(done_avg_rpe)
                    if avg_val > (float(use_rpe_max) + 0.5):
                        rpe_status = "above"
                    elif avg_val < (float(use_rpe_min) - 0.5):
                        rpe_status = "below"
                    else:
                        rpe_status = "on"
                except Exception:
                    rpe_status = None

            primary_change = _primary_change_from_done_and_target(done, structured, planned_sets)
            fallback_ref = _fallback_reference(exercise_report.get("prev_stats"))
            has_done_signal = _has_done_signal(done)

            items.append({
                "title": plan_name,
                "exercise_key": row.get("exercise_key"),
                "slot_index": slot_index,
                "coverage": exercise_report.get("coverage"),
                "suggestion_inline": decision.get("suggestion_inline") or "",
                "pill": decision.get("pill") or {},
                "structured": structured,
                "planned": {
                    "device": plan_device,
                    "variation": plan_variation,
                    "sets": planned_sets,
                    "reps_min": _clean_int(plan_row.get("reps_min")) or 0,
                    "reps_max": _clean_int(plan_row.get("reps_max")) or 0,
                    "rpe_min": _clean_float(use_rpe_min),
                    "rpe_max": _clean_float(use_rpe_max),
                    "rpe_values": planned_rpe_values,
                    "display_rpe": planned_display_rpe,
                    "weight_suggestion": planned_weight_suggestion,
                },
                "done": {
                    "sets": done.get("sets", 0),
                    "reps": done_reps,
                    "avg_rpe": done.get("avg_rpe"),
                    "weights": done_weights,
                    "rpes": done_rpes,
                    "set_numbers": done_set_numbers,
                    "completed_sets": done_set_count,
                    "has_signal": has_done_signal,
                    "last_reference": fallback_ref,
                    "adherence": {
                        "rpe_status": rpe_status,
                    },
                },
                "primary_change": primary_change,
                "todays_prescription": _build_today_prescription(
                    title=plan_name,
                    device=plan_device,
                    planned={
                        "sets": planned_sets,
                        "reps_min": _clean_int(plan_row.get("reps_min")) or 0,
                        "reps_max": _clean_int(plan_row.get("reps_max")) or 0,
                        "rpe_min": _clean_float(use_rpe_min),
                        "rpe_max": _clean_float(use_rpe_max),
                        "display_rpe": planned_display_rpe,
                    },
                    structured=structured,
                    done={
                        "last_reference": fallback_ref,
                    },
                    primary_change=primary_change,
                ),
            })

            item_meta.append({
                "coverage": exercise_report.get("coverage"),
                "labels": exercise_report.get("labels") or {},
                "exercise_key": row.get("exercise_key"),
                "planned_sets": (exercise_report.get("planned") or {}).get("sets") or 0,
                "done_sets": done.get("sets", 0),
                "rpe_target_hit": done.get("rpe_target_hit"),
            })

            if debug_items is not None:
                matched_done = []
                if matched_log:
                    sets = matched_log.get("sets") or []
                    matched_done.append({
                        "exercise_id": matched_log.get("id"),
                        "name": matched_log.get("name"),
                        "device": matched_log.get("device"),
                        "workout_id": workout_dict["id"],
                        "reps": [s.get("reps") for s in sets],
                        "weights": [s.get("weight") for s in sets],
                        "rpes": [s.get("rpe") for s in sets],
                        "set_numbers": [s.get("set_number") for s in sets],
                    })

                debug_payload = {
                    "coverage": exercise_report.get("coverage"),
                    "matching_strategy": match_strategy,
                    "planned_id_strategy": planned_strategy,
                    "planned": {
                        "exercise_id": planned_ex_id,
                        "name": plan_name,
                        "device": plan_device,
                        "reps_range": _format_range(_clean_int(plan_row.get("reps_min")), _clean_int(plan_row.get("reps_max"))),
                        "sets": _clean_int(row.get("expected_sets")) or 0,
                        "rpe_range": _format_range(_clean_float(row.get("rpe_min")), _clean_float(row.get("rpe_max"))),
                    },
                    "matched_done": matched_done,
                    "reference": {
                        "workout_id": workout_dict["id"],
                        "date_iso": workout_dict.get("date_iso"),
                        "session_key_used": workout_dict.get("session_key"),
                    }
                }
                if replacement_used:
                    debug_payload["replacement_used"] = replacement_used
                if history_source:
                    debug_payload["history_source"] = history_source
                debug_items.append(debug_payload)

        for ex in log_exercises:
            ex_id = ex.get("id")
            if ex_id in matched_ids:
                continue
            extra_ids.append(ex_id)

        flags_set = set()
        missing_count = sum(1 for m in item_meta if m.get("coverage") == "planned_missing")
        replacement_count = sum(1 for m in item_meta if m.get("coverage") in ("replaced_done", "planned_done_substitute"))
        volume_under = any((m.get("labels") or {}).get("volume") == "under" for m in item_meta)
        rpe_target_miss = any(m.get("rpe_target_hit") is False for m in item_meta)
        if mode == "light":
            rpe_target_miss = False
            for it in items:
                adh = (it.get("done") or {}).get("adherence") or {}
                if adh.get("rpe_status") == "above":
                    rpe_target_miss = True
                    break

        # Missing expected exercises based on SSOT
        expected_keys = [row.get("exercise_key") for row in expected_rows if row.get("exercise_key")]
        matched_keys = [m.get("exercise_key") for m in item_meta if m.get("coverage") != "planned_missing"]
        missing_expected = [k for k in expected_keys if k and k not in matched_keys]
        if missing_expected:
            flags_set.add("Übungen fehlen")
        if mode != "light":
            if any(
                (m.get("coverage") in ("planned_done", "replaced_done", "planned_done_substitute"))
                and m.get("planned_sets", 0) > m.get("done_sets", 0)
                for m in item_meta
            ):
                flags_set.add("Sätze fehlen")
        if any((m.get("labels") or {}).get("reps") in ("under", "over") for m in item_meta):
            flags_set.add("Reps daneben")
        if any((m.get("labels") or {}).get("rpe") in ("under", "over") for m in item_meta):
            flags_set.add("RPE daneben")

        if mode == "light":
            volume_under = False
        if missing_count or volume_under or rpe_target_miss:
            status = "red"
        elif flags_set:
            status = "yellow"
        else:
            status = "green"
        if replacement_count and status == "green":
            status = "yellow"

        flags = sorted(flags_set)

        if debug:
            overlap = set(planned_exercise_ids) & set(extra_ids)
            if overlap:
                print("PLAN_CHECK_EXTRA_OVERLAP:", {
                    "session_key": session_key,
                    "overlap": sorted(overlap),
                })

        conn.commit()
    finally:
        conn.close()

    if debug_items is not None:
        for idx, item in enumerate(items):
            if idx < len(debug_items):
                item["debug"] = debug_items[idx]

    plan_check_payload = {"exercises": exercise_reports}
    if workout_report:
        plan_check_payload = dict(workout_report)
        plan_check_payload["exercises"] = exercise_reports

    # expected/missing/unexpected lists
    expected_name_keys = {
        _norm_text(r.get("name") or "")
        for r in expected_rows
    }
    unexpected_logged = []
    for ex in log_exercises:
        ek = _norm_text(ex.get("name") or "")
        if ek and ek not in expected_name_keys:
            unexpected_logged.append({"name": ex.get("name"), "exercise_key": ek})

    missing_expected_list = [
        {"exercise_key": row.get("exercise_key"), "name": row.get("name")}
        for row in expected_rows
        if row.get("exercise_key") in missing_expected
    ]

    items = _rebuild_if_global_downshift(items)

    expected_summary = {
        "count": len(expected_rows),
        "missing_count": len(missing_expected_list),
        "unexpected_count": len(unexpected_logged),
    }

    return jsonify({
        "ok": True,
        "requested_session_key": session_key,
        "status": status,
        "flags": flags,
        "session": {
            "session_key": target["session_key"],
            "session_name": target["session_name"],
            "meta": {
                "plan_source": plan_source,
                "core_mode_enabled": core_mode_enabled,
            },
        },
        "reference_workout": {
            "id": workout_dict["id"],
            "date_iso": workout_dict["date_iso"],
            "display_date": _format_display_date(workout_dict.get("date_iso")),
            "name": workout_dict["name"],
            "session_key": workout_dict.get("session_key"),
        },
        "plan_check": plan_check_payload,
        "expected_exercises": expected_info,
        "expected_exercises_summary": expected_summary,
        "expected_exercises_lines": [
            f"Expected: {expected_summary['count']} · Missing: {expected_summary['missing_count']} · Unexpected: {expected_summary['unexpected_count']}",
        ],
        "expected_missing": missing_expected_list,
        "expected_unexpected": unexpected_logged,
        "items": items,
        "debug_info": {
            "reference_workout_id": workout_dict.get("id"),
            "reference_workout_date_iso": workout_dict.get("date_iso"),
            "planned_exercise_ids": sorted({pid for pid in planned_exercise_ids if pid is not None}) if debug else [],
            "done_exercise_ids": sorted(done_exercise_ids) if debug else [],
            "extra_exercise_ids": sorted(extra_ids) if debug else [],
        } if debug else None
    })


@app.get("/api/dashboard/plan_check_recent")
def api_dashboard_plan_check_recent():
    days_raw = request.args.get("days", "7")
    debug = request.args.get("debug") == "1"
    recompute = request.args.get("recompute") == "1"
    try:
        days = max(1, int(days_raw))
    except Exception:
        days = 7

    now = datetime.now(ZoneInfo("Europe/Berlin")).date()
    start_date = now - timedelta(days=days - 1)
    start_iso = start_date.isoformat()

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    workouts = cur.execute("""
        SELECT *
        FROM workouts
        WHERE date_iso IS NOT NULL AND date_iso >= ?
        ORDER BY date_iso DESC, id DESC
    """, (start_iso,)).fetchall()

    results = []
    try:
        for row in workouts:
            workout_dict = dict(row)
            report = None if recompute else load_plan_check_report(workout_dict["id"])
            if report and report.get("version") != PLAN_CHECK_VERSION:
                report = None
            if not report:
                report = build_plan_check_for_workout(workout_dict["id"])
                save_plan_check_report(report)
            if not report:
                continue

            exercises = report.get("exercises") or []
            extras_pool = [ex for ex in exercises if ex.get("coverage") == "extra"]
            extras_by_key = {}
            for ex in extras_pool:
                key = _replacement_key(ex.get("name") or "")
                extras_by_key.setdefault(key, []).append(ex)

            consumed_extras = set()
            final_exercises = []

            def _sets_from_done(done_dict: dict):
                reps = done_dict.get("reps") if isinstance(done_dict.get("reps"), list) else []
                weights = done_dict.get("weights") if isinstance(done_dict.get("weights"), list) else []
                rpes = done_dict.get("rpes") if isinstance(done_dict.get("rpes"), list) else []
                set_numbers = done_dict.get("set_numbers") if isinstance(done_dict.get("set_numbers"), list) else []
                max_len = max(len(reps), len(weights), len(rpes), len(set_numbers))
                sets = []
                for idx in range(max_len):
                    entry = {}
                    rep = reps[idx] if idx < len(reps) else None
                    weight = weights[idx] if idx < len(weights) else None
                    rpe = rpes[idx] if idx < len(rpes) else None
                    set_num = set_numbers[idx] if idx < len(set_numbers) else None
                    if rep is not None:
                        entry["reps"] = rep
                    if weight is not None:
                        entry["weight"] = weight
                    if rpe is not None:
                        entry["rpe"] = rpe
                    entry["set_number"] = set_num if set_num is not None else idx + 1
                    if entry:
                        sets.append(entry)
                return sets

            for ex in exercises:
                coverage = ex.get("coverage")
                name = (ex.get("name") or "").strip()
                if not name:
                    continue
                if coverage == "extra":
                    continue
                if coverage == "planned_missing":
                    repl_keys = _replacement_candidates(name)
                    replacement = None
                    for key in repl_keys:
                        candidates = extras_by_key.get(key) or []
                        if candidates:
                            replacement = candidates.pop(0)
                            consumed_extras.add(id(replacement))
                            break
                    if replacement:
                        done = replacement.get("done") if isinstance(replacement.get("done"), dict) else {}
                        reps_min, reps_max = _parse_range((ex.get("planned") or {}).get("reps") or "", _clean_int)
                        rpe_min, rpe_max = _parse_range((ex.get("planned") or {}).get("rpe") or "", _clean_float)
                        plan_row = {
                            "exercise_name": name,
                            "sets": (ex.get("planned") or {}).get("sets") or 0,
                            "reps_min": reps_min,
                            "reps_max": reps_max,
                            "rpe_min": rpe_min,
                            "rpe_max": rpe_max,
                            "device": ex.get("device") or "",
                        }
                        matched_log = {
                            "name": replacement.get("name"),
                            "device": replacement.get("device"),
                            "sets": _sets_from_done(done),
                        }
                        substitute = _exercise_report(plan_row, [matched_log], "planned_done")
                        substitute["coverage"] = "planned_done_substitute"
                        substitute["replacement_used"] = replacement.get("name")
                        final_exercises.append(substitute)
                        continue
                final_exercises.append(ex)

            items = []
            for ex in final_exercises:
                name = (ex.get("name") or "").strip()
                if not name:
                    continue
                done = ex.get("done") if isinstance(ex.get("done"), dict) else {}
                decision = _progression_decision(ex)
                items.append({
                    "title": name,
                    "planned": ex.get("planned") or {},
                    "done": {
                        "sets": done.get("sets", 0),
                        "reps": done.get("reps", []),
                        "weights": done.get("weights", []),
                        "rpes": done.get("rpes", []),
                        "set_numbers": done.get("set_numbers", []),
                        "avg_rpe": done.get("avg_rpe"),
                        "max_rpe": done.get("max_rpe"),
                    },
                    "suggestion_inline": decision.get("suggestion_inline") or "",
                    "pill": decision.get("pill") or {},
                    "structured": decision.get("structured") or {},
                })

            if debug:
                report = dict(report)
                report["exercises"] = final_exercises

            results.append({
                "workout": {
                    "id": workout_dict.get("id"),
                    "date_iso": workout_dict.get("date_iso"),
                    "name": workout_dict.get("name"),
                    "session_key": workout_dict.get("session_key"),
                },
                "items": items,
                "plan_check": report if debug else None,
            })
    finally:
        conn.close()

    return jsonify({
        "ok": True,
        "days": days,
        "start_date": start_iso,
        "workouts": results,
    })


@app.get("/api/dashboard/training_summary")
def api_dashboard_training_summary():
    window = _dashboard_range_window(request.args.get("days"), request.args.get("offset"), 7)
    days = window["days"]
    offset_days = window["offset_days"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]

    conn = get_training_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT COUNT(*) FROM workouts WHERE date_iso BETWEEN ? AND ?",
        (start_iso, end_iso)
    )
    sessions = int(cur.fetchone()[0] or 0)
    cur.execute(
        """
        SELECT SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage_sum
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE w.date_iso BETWEEN ? AND ?
        """,
        (start_iso, end_iso)
    )
    tonnage = cur.fetchone()[0]
    cur.execute(
        """
        SELECT date_iso, name
        FROM workouts
        WHERE date_iso IS NOT NULL
        ORDER BY date_iso DESC, id DESC
        LIMIT 1
        """
    )
    last_row = cur.fetchone()
    conn.close()

    tonnage_value = float(tonnage) if tonnage is not None else None
    if sessions == 0:
        tonnage_value = None

    return jsonify({
        "ok": True,
        "days": days,
        "offset": offset_days,
        "sessions": sessions,
        "tonnage": tonnage_value,
        "last_date": last_row["date_iso"] if last_row else None,
        "last_name": last_row["name"] if last_row else None,
    })


@app.get("/api/dashboard/training_detail")
def api_dashboard_training_detail():
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    last_row = cur.execute(
        """
        SELECT id, name, date_iso
        FROM workouts
        WHERE date_iso IS NOT NULL
        ORDER BY date_iso DESC, id DESC
        LIMIT 1
        """
    ).fetchone()

    if not last_row:
        conn.close()
        return jsonify({"ok": False, "error": "no_workouts"}), 404

    def workout_metrics(workout_id: int):
        rows = cur.execute(
            """
            SELECT e.name AS exercise, s.weight, s.reps, s.rpe
            FROM sets s
            JOIN exercises e ON e.id = s.exercise_id
            WHERE e.workout_id = ?
            """,
            (workout_id,),
        ).fetchall()

        tonnage = 0.0
        sets = 0
        rpe_sum = 0.0
        rpe_count = 0
        e1rm_by_ex = {}

        for row in rows:
            weight = row["weight"]
            reps = row["reps"]
            if weight is not None and reps is not None:
                try:
                    tonnage += float(weight) * float(reps)
                except Exception:
                    pass
            sets += 1
            rpe = row["rpe"]
            if rpe is not None:
                try:
                    rpe_sum += float(rpe)
                    rpe_count += 1
                except Exception:
                    pass
            if weight is not None and reps is not None and reps > 0:
                try:
                    e1rm = float(weight) * (1.0 + (float(reps) / 30.0))
                except Exception:
                    e1rm = None
                if e1rm is not None:
                    name = (row["exercise"] or "").strip()
                    if name:
                        e1rm_by_ex[name] = max(e1rm_by_ex.get(name) or 0.0, e1rm)

        top_exercise = None
        top_e1rm = None
        if e1rm_by_ex:
            top_exercise, top_e1rm = max(e1rm_by_ex.items(), key=lambda item: item[1])

        avg_rpe = (rpe_sum / rpe_count) if rpe_count else None
        return {
            "tonnage": tonnage if rows else None,
            "sets": sets if rows else None,
            "avg_rpe": avg_rpe,
            "top_exercise": top_exercise,
            "top_e1rm": top_e1rm,
            "_e1rm_by_ex": e1rm_by_ex,
        }

    last = {"id": last_row["id"], "name": last_row["name"], "date_iso": last_row["date_iso"]}
    last_metrics = workout_metrics(last_row["id"])

    prev_row = None
    if last_row["name"]:
        prev_row = cur.execute(
            """
            SELECT id, date_iso
            FROM workouts
            WHERE name = ? AND date_iso < ?
            ORDER BY date_iso DESC, id DESC
            LIMIT 1
            """,
            (last_row["name"], last_row["date_iso"]),
        ).fetchone()

    prev = {"id": prev_row["id"], "date_iso": prev_row["date_iso"]} if prev_row else None
    prev_metrics = workout_metrics(prev_row["id"]) if prev_row else None

    deltas = {"tonnage": None, "sets": None, "avg_rpe": None, "top_e1rm": None}
    if prev_metrics:
        if last_metrics.get("tonnage") is not None and prev_metrics.get("tonnage") is not None:
            deltas["tonnage"] = last_metrics["tonnage"] - prev_metrics["tonnage"]
        if last_metrics.get("sets") is not None and prev_metrics.get("sets") is not None:
            deltas["sets"] = last_metrics["sets"] - prev_metrics["sets"]
        if last_metrics.get("avg_rpe") is not None and prev_metrics.get("avg_rpe") is not None:
            deltas["avg_rpe"] = last_metrics["avg_rpe"] - prev_metrics["avg_rpe"]
        if last_metrics.get("top_exercise") and prev_metrics.get("_e1rm_by_ex"):
            prev_e1rm = prev_metrics["_e1rm_by_ex"].get(last_metrics["top_exercise"])
            if last_metrics.get("top_e1rm") is not None and prev_e1rm is not None:
                deltas["top_e1rm"] = last_metrics["top_e1rm"] - prev_e1rm

    conn.close()

    last_metrics.pop("_e1rm_by_ex", None)
    if prev_metrics:
        prev_metrics.pop("_e1rm_by_ex", None)

    return jsonify({
        "ok": True,
        "last": last,
        "prev": prev,
        "metrics": last_metrics,
        "prev_metrics": prev_metrics,
        "deltas": deltas,
    })


@app.get("/api/dashboard/training_split")
def api_dashboard_training_split():
    window = _dashboard_range_window(request.args.get("days"), "0", 7)
    days = window["days"]
    offset_days = window["offset_days"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    rows = cur.execute(
        """
        SELECT e.name, e.variation, e.muscle_primary, e.muscle_secondary
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE (w.date_iso BETWEEN ? AND ?)
           OR (w.date BETWEEN ? AND ?)
        """,
        (start_iso, end_iso, start_iso, end_iso)
    ).fetchall()
    conn.close()

    group_map = {
        "chest": "chest",
        "upper_back": "back",
        "back_horizontal": "back",
        "back_vertical": "back",
        "lats": "back",
        "traps": "back",
        "front_delts": "shoulders",
        "side_delts": "shoulders",
        "rear_delts": "shoulders",
        "delts": "shoulders",
        "biceps": "arms",
        "triceps": "arms",
        "forearms": "arms",
        "quads": "quads",
        "hamstrings": "hams",
        "glutes": "hams",
    }

    totals = {"chest": 0.0, "back": 0.0, "shoulders": 0.0, "arms": 0.0, "quads": 0.0, "hams": 0.0}

    for row in rows:
        muscles = resolve_muscles(
            row["name"] or "",
            row["variation"] or "",
            row["muscle_primary"],
            row["muscle_secondary"],
        )
        for muscle, weight in (muscles or {}).items():
            group = group_map.get(muscle)
            if not group:
                continue
            try:
                totals[group] += float(weight or 0)
            except Exception:
                continue

    return jsonify({
        "ok": True,
        "days": days,
        "offset": offset_days,
        "data": {k: round(v, 1) for k, v in totals.items()},
    })


@app.get("/api/dashboard/hrv_trend")
def api_dashboard_hrv_trend():
    raw_days = (request.args.get("days") or "7").strip().lower()
    if raw_days == "all":
        days = None
    else:
        days = _clamp_int(raw_days, 1, 3650, 7)

    conn = get_hrv_db()
    cur = conn.cursor()

    if days is None:
        cur.execute(
            """
            SELECT date_utc, rmssd
            FROM hrv_measurements
            WHERE date_utc IS NOT NULL
            ORDER BY date_utc ASC
            """
        )
    else:
        cur.execute(
            """
            SELECT date_utc, rmssd
            FROM hrv_measurements
            WHERE date_utc IS NOT NULL
              AND date(date_utc) >= date('now', ?)
            ORDER BY date_utc ASC
            """,
            (f"-{days * 2} days",)
        )

    rows = cur.fetchall()
    conn.close()

    def parse_date(value):
        if not value:
            return None
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00")).date()
        except Exception:
            try:
                return datetime.strptime(value[:10], "%Y-%m-%d").date()
            except Exception:
                return None

    values = []
    for row in rows:
        dt = parse_date(row["date_utc"])
        rmssd = row["rmssd"]
        if dt and rmssd is not None:
            try:
                values.append((dt, float(rmssd)))
            except Exception:
                continue

    if days is None:
        too_few = len(values) < 5
        return jsonify({
            "ok": True,
            "days": "all",
            "label": "Langtrend",
            "pct_change": None,
            "current_mean": None,
            "prev_mean": None,
            "current_count": len(values),
            "prev_count": 0,
            "too_few": too_few,
        })

    today = date.today()
    start = today - timedelta(days=days - 1)
    prev_end = start - timedelta(days=1)
    prev_start = prev_end - timedelta(days=days - 1)

    current_vals = [v for (d, v) in values if start <= d <= today]
    prev_vals = [v for (d, v) in values if prev_start <= d <= prev_end]

    too_few = len(current_vals) < 5 or len(prev_vals) < 5
    current_mean = sum(current_vals) / len(current_vals) if current_vals else None
    prev_mean = sum(prev_vals) / len(prev_vals) if prev_vals else None
    pct_change = None
    if current_mean is not None and prev_mean not in (None, 0) and not too_few:
        pct_change = ((current_mean - prev_mean) / prev_mean) * 100

    return jsonify({
        "ok": True,
        "days": days,
        "label": None,
        "pct_change": pct_change,
        "current_mean": current_mean,
        "prev_mean": prev_mean,
        "current_count": len(current_vals),
        "prev_count": len(prev_vals),
        "too_few": too_few,
    })


@app.get("/api/dashboard/hrv_series")
def api_dashboard_hrv_series():
    window = _dashboard_range_window(request.args.get("days"), "0", 30)
    days = window["days"]
    days_out = window["days_out"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]

    conn = get_hrv_db()
    cur = conn.cursor()

    base_sql = """
        SELECT COALESCE(date(date_utc), date(ts_measurement)) AS date, rmssd, hr, sdnn
        FROM hrv_measurements
        WHERE (date_utc IS NOT NULL OR ts_measurement IS NOT NULL)
    """
    params = [start_iso, end_iso]
    base_sql += " AND COALESCE(date(date_utc), date(ts_measurement)) BETWEEN ? AND ?"
    base_sql += " ORDER BY date ASC"

    rows = cur.execute(base_sql, params).fetchall()

    if not rows:
        try:
            tables = [row["name"] for row in cur.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()]
            if "hrv_series" in tables:
                series_sql = """
                    SELECT date AS date, rmssd_ms, hr_bpm, sdnn_ms
                    FROM hrv_series
                """
                series_sql += " WHERE date BETWEEN ? AND ? ORDER BY date ASC"
                rows = cur.execute(series_sql, (start_iso, end_iso)).fetchall()
        except Exception:
            rows = []
    conn.close()

    data = []
    for row in rows:
        date_value = row["date"] if "date" in row.keys() else None
        if not date_value:
            continue
        rmssd_value = row["rmssd_ms"] if "rmssd_ms" in row.keys() else row["rmssd"] if "rmssd" in row.keys() else None
        hr_value = row["hr_bpm"] if "hr_bpm" in row.keys() else row["hr"] if "hr" in row.keys() else None
        sdnn_value = row["sdnn_ms"] if "sdnn_ms" in row.keys() else row["sdnn"] if "sdnn" in row.keys() else None
        data.append({
            "date": date_value,
            "rmssd_ms": rmssd_value,
            "hr_bpm": hr_value,
            "sdnn_ms": sdnn_value,
        })

    if not data:
        print("DASHBOARD_HRV_SERIES_EMPTY: dataset=hrv_series")

    return jsonify({
        "ok": True,
        "dataset": "hrv_series",
        "days": days_out,
        "n": len(data),
        "data": data,
    })


@app.get("/api/dashboard/runs_summary")
def api_dashboard_runs_summary():
    window = _dashboard_range_window(request.args.get("days"), request.args.get("offset"), 7)
    days = window["days"]
    offset_days = window["offset_days"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]

    conn = get_runs_db()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT date, distance, pace, avg_hr
        FROM runs
        WHERE substr(date, 1, 10) BETWEEN ? AND ?
        ORDER BY date ASC
        """,
        (start_iso, end_iso)
    )
    rows = cur.fetchall()
    cur.execute(
        "SELECT date FROM runs ORDER BY date DESC LIMIT 1"
    )
    last_row = cur.fetchone()
    conn.close()

    total_distance = 0.0
    pace_weighted = 0.0
    pace_distance = 0.0
    hr_weighted = 0.0
    hr_distance = 0.0
    for row in rows:
        distance = row["distance"] or 0.0
        total_distance += distance
        pace = row["pace"]
        if pace is not None and distance:
            pace_weighted += pace * distance
            pace_distance += distance
        avg_hr = row["avg_hr"]
        if avg_hr is not None and distance:
            hr_weighted += float(avg_hr) * distance
            hr_distance += distance

    runs_count = len(rows)
    total_km = total_distance / 1000 if total_distance else None
    avg_pace_s = pace_weighted / pace_distance if pace_distance else None
    avg_hr = hr_weighted / hr_distance if hr_distance else None
    if runs_count == 0:
        total_km = None
        avg_pace_s = None
        avg_hr = None

    return jsonify({
        "ok": True,
        "days": days,
        "offset": offset_days,
        "runs": runs_count,
        "total_km": total_km,
        "avg_pace_s": avg_pace_s,
        "avg_hr": avg_hr,
        "last_date": last_row["date"] if last_row else None,
    })


@app.get("/api/dashboard/load_series")
def api_dashboard_load_series():
    window = _dashboard_range_window(request.args.get("days"), "0", 30)
    days = window["days"]
    start_iso = window["start_iso"]
    end_iso = window["end_iso"]

    training_conn = get_training_db()
    training_conn.row_factory = sqlite3.Row
    tcur = training_conn.cursor()
    tcur.execute(
        """
        SELECT w.date_iso AS date_iso,
               SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts w ON w.id = e.workout_id
        WHERE w.date_iso BETWEEN ? AND ?
        GROUP BY w.date_iso
        """,
        (start_iso, end_iso)
    )
    training_rows = tcur.fetchall()
    training_conn.close()

    runs_conn = get_runs_db()
    runs_conn.row_factory = sqlite3.Row
    rcur = runs_conn.cursor()
    rcur.execute(
        """
        SELECT substr(date, 1, 10) AS date_iso,
               SUM(distance) AS distance_m
        FROM runs
        WHERE substr(date, 1, 10) BETWEEN ? AND ?
        GROUP BY substr(date, 1, 10)
        """,
        (start_iso, end_iso)
    )
    run_rows = rcur.fetchall()
    runs_conn.close()

    data = {}
    for row in training_rows:
        if not row["date_iso"]:
            continue
        data[row["date_iso"]] = {
            "date": row["date_iso"],
            "gym_tonnage": float(row["tonnage"] or 0),
            "run_km": 0.0,
        }
    for row in run_rows:
        if not row["date_iso"]:
            continue
        entry = data.get(row["date_iso"])
        if not entry:
            entry = {"date": row["date_iso"], "gym_tonnage": 0.0, "run_km": 0.0}
            data[row["date_iso"]] = entry
        entry["run_km"] = float(row["distance_m"] or 0) / 1000.0

    rows = sorted(data.values(), key=lambda r: r["date"])

    return jsonify({
        "ok": True,
        "days": days,
        "n": len(rows),
        "data": rows,
    })


@app.get("/api/dashboard/runs_detail")
def api_dashboard_runs_detail():
    conn = get_runs_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    last_row = cur.execute(
        """
        SELECT date, distance, pace, avg_hr, elevation_gain, moving_time
        FROM runs
        ORDER BY date DESC
        LIMIT 1
        """
    ).fetchone()

    if not last_row:
        conn.close()
        return jsonify({"ok": False, "error": "no_runs"}), 404

    prev_row = cur.execute(
        """
        SELECT date, distance, pace, avg_hr, elevation_gain, moving_time
        FROM runs
        WHERE date < ?
        ORDER BY date DESC
        LIMIT 1
        """,
        (last_row["date"],),
    ).fetchone()
    conn.close()

    def build_row(row):
        if not row:
            return None
        distance = row["distance"]
        pace = row["pace"]
        avg_hr = row["avg_hr"]
        elev = row["elevation_gain"]
        moving_time = row["moving_time"]
        trimp = None
        if moving_time and avg_hr:
            try:
                trimp = (float(moving_time) / 60.0) * (float(avg_hr) / 100.0)
            except Exception:
                trimp = None
        return {
            "date": row["date"],
            "distance_m": distance,
            "pace_s": pace,
            "avg_hr": avg_hr,
            "elev_m": elev,
            "moving_time_s": moving_time,
            "trimp": trimp,
        }

    last = build_row(last_row)
    prev = build_row(prev_row)

    hr_delta = None
    pace_delta = None
    trimp_delta = None
    pace_similar = False

    if last and prev:
        if last.get("avg_hr") is not None and prev.get("avg_hr") is not None:
            hr_delta = float(last["avg_hr"]) - float(prev["avg_hr"])
        if last.get("pace_s") is not None and prev.get("pace_s") is not None:
            pace_delta = float(last["pace_s"]) - float(prev["pace_s"])
            pace_similar = abs(pace_delta) <= 10
        if last.get("trimp") is not None and prev.get("trimp") is not None:
            trimp_delta = float(last["trimp"]) - float(prev["trimp"])

    return jsonify({
        "ok": True,
        "last": last,
        "prev": prev,
        "hr_delta": hr_delta,
        "pace_delta": pace_delta,
        "trimp_delta": trimp_delta,
        "pace_similar": pace_similar,
    })


@app.get("/api/dashboard/last_logs")
def api_dashboard_last_logs():
    out = {
        "training": None,
        "runs": None,
        "nutrition": None,
    }

