def _replacement_key(name: str) -> str:
    text = _norm_text(name)
    text = (text
            .replace("ä", "ae")
            .replace("ö", "oe")
            .replace("ü", "ue")
            .replace("ß", "ss"))
    return re.sub(r"[^a-z0-9]+", "", text)


_REPLACEMENT_MAP = {
    "bench": ["brustpresse", "chestpress"],
    "benchpress": ["brustpresse", "chestpress"],
    "bankdruecken": ["brustpresse", "chestpress"],
    "brustpresse": ["benchpress", "bankdruecken", "chestpress"],
    "latzug": ["pullups", "klimmzug", "klimmzuege", "pullup"],
    "pullups": ["latzug", "latzugmaschine"],
    "klimmzug": ["latzug"],
    "klimmzuege": ["latzug"],
    "ohp": ["schulterpresse", "shoulderpress", "overheadpress"],
    "overheadpress": ["schulterpresse", "shoulderpress", "ohp"],
    "schulterpresse": ["ohp", "overheadpress", "shoulderpress"],
}


def _replacement_candidates(name: str) -> list[str]:
    key = _replacement_key(name)
    return _REPLACEMENT_MAP.get(key, [])


def _previous_exercise_occurrences(cur: sqlite3.Cursor, *, name: str, variation: str, device: str,
                                   session_key: str, session_name: str, has_session_key: bool,
                                   current_date_iso: str, current_workout_id: int, limit: int = 2) -> list[dict]:
    name_norm = _norm_text(name)
    variation_norm = _norm_text(variation)
    device_norm = _norm_text(device)
    if not name_norm:
        return []

    where = ["LOWER(TRIM(e.name)) = ?"]
    params = [name_norm]
    if variation_norm:
        where.append("LOWER(TRIM(COALESCE(e.variation, ''))) = ?")
        params.append(variation_norm)
    if device_norm:
        where.append("LOWER(TRIM(COALESCE(e.device, ''))) = ?")
        params.append(device_norm)
    if has_session_key and session_key:
        where.append("w.session_key = ?")
        params.append(session_key)
    elif session_name:
        where.append("LOWER(TRIM(w.name)) = ?")
        params.append(_norm_text(session_name))

    where.append("(w.date_iso < ? OR (w.date_iso = ? AND w.id < ?))")
    params.extend([current_date_iso, current_date_iso, current_workout_id])

    sql = f"""
        SELECT e.id, w.id AS workout_id, w.date_iso, w.name AS workout_name
        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        WHERE {" AND ".join(where)}
        ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
        LIMIT {int(limit)}
    """
    rows = cur.execute(sql, params).fetchall()
    out = []
    for row in rows:
        ex_id = row["id"]
        sets = cur.execute("""
            SELECT set_number, reps, weight, rpe
            FROM sets
            WHERE exercise_id = ?
            ORDER BY set_number ASC, id ASC
        """, (ex_id,)).fetchall()
        out.append({
            "exercise_id": ex_id,
            "workout_id": row["workout_id"],
            "date_iso": row["date_iso"],
            "workout_name": row["workout_name"],
            "sets": [dict(s) for s in sets],
        })
    return out


def _previous_exercise_occurrences_with_fallback(
    cur: sqlite3.Cursor,
    *,
    name: str,
    variation: str,
    device: str,
    session_name: str,
    current_date_iso: str,
    current_workout_id: int,
    limit: int = 2,
) -> tuple[list[dict], str | None]:
    if session_name:
        same_session = _previous_exercise_occurrences(
            cur,
            name=name,
            variation=variation,
            device=device,
            session_key="",
            session_name=session_name,
            has_session_key=False,
            current_date_iso=current_date_iso,
            current_workout_id=current_workout_id,
            limit=limit,
        )
        if same_session:
            return same_session, "session_name"

    any_session = _previous_exercise_occurrences(
        cur,
        name=name,
        variation=variation,
        device=device,
        session_key="",
        session_name="",
        has_session_key=False,
        current_date_iso=current_date_iso,
        current_workout_id=current_workout_id,
        limit=limit,
    )
    if any_session:
        return any_session, "latest_any"
    return [], None


def _reference_set_from_sets(sets: list[dict]) -> dict | None:
    if not sets:
        return None
    candidates = []
    for idx, s in enumerate(sets):
        weight = s.get("weight")
        reps = s.get("reps")
        if weight is None or reps is None:
            continue
        candidates.append({
            "weight": float(weight),
            "reps": int(reps),
            "rpe": float(s["rpe"]) if s.get("rpe") is not None else None,
            "set_number": s.get("set_number"),
            "index": idx,
        })
    if not candidates:
        return None
    max_weight = max(c["weight"] for c in candidates)
    top_sets = [c for c in candidates if c["weight"] == max_weight]
    top_sets.sort(key=lambda c: (c["set_number"] if c["set_number"] is not None else 9999, c["index"]))
    return top_sets[0]


def _select_plan_day(plan: dict, workout_name: str, log_exercises: list[dict]):
    days = plan.get("base_week") or []
    if not isinstance(days, list) or not days:
        return None, {}

    workout_norm = _norm_text(workout_name or "")
    if workout_norm:
        for idx, day in enumerate(days):
            if _norm_text(day.get("session_name") or "") == workout_norm:
                return idx, day

    log_names = {ex["name_norm"] for ex in log_exercises if ex.get("name_norm")}
    log_patterns = {ex["pattern"] for ex in log_exercises if ex.get("pattern")}

    best_idx = 0
    best_match = -1
    best_ratio = -1.0
    for idx, day in enumerate(days):
        rows = day.get("strength_exercises") or []
        plan_rows = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            if _norm_text(r.get("exercise_name") or r.get("name") or ""):
                plan_rows.append(r)
        plan_count = len(plan_rows)
        match_count = 0
        for row in plan_rows:
            name_norm = _norm_text(row.get("exercise_name") or row.get("name") or "")
            if name_norm and name_norm in log_names:
                match_count += 1
                continue
            pattern = classify_pattern(row.get("exercise_name") or "", row.get("variation") or "")
            if pattern and pattern in log_patterns:
                match_count += 1
        ratio = (match_count / plan_count) if plan_count else 0.0
        if match_count > best_match or (match_count == best_match and ratio > best_ratio):
            best_match = match_count
            best_ratio = ratio
            best_idx = idx
    return best_idx, days[best_idx]


def _pick_best_log(candidates: list[dict]) -> dict:
    return max(candidates, key=lambda c: (len(c.get("sets") or []), c.get("id") or 0))


def _find_log_matches(plan_entry: dict, log_exercises: list[dict], matched_ids: set, allow_multi: bool):
    name_norm = plan_entry["name_norm"]
    variation_norm = plan_entry["variation_norm"]
    device_norm = plan_entry["device_norm"]
    pattern = plan_entry["pattern"]

    candidates = [ex for ex in log_exercises if ex.get("id") not in matched_ids]
    name_matches = [ex for ex in candidates if ex.get("name_norm") == name_norm]

    if device_norm:
        name_matches = [ex for ex in name_matches if ex.get("device_norm") == device_norm]
    if variation_norm:
        name_matches = [ex for ex in name_matches if ex.get("variation_norm") == variation_norm]

    if name_matches:
        if allow_multi:
            return name_matches
        return [_pick_best_log(name_matches)]

    if pattern:
        pattern_matches = [ex for ex in candidates if ex.get("pattern") == pattern]
        if device_norm:
            pattern_matches = [ex for ex in pattern_matches if ex.get("device_norm") == device_norm]
        if pattern_matches:
            return [_pick_best_log(pattern_matches)]

    return []


def _rep_stats(reps: list[int], reps_min: int | None, reps_max: int | None):
    if reps_min is None or reps_max is None or not reps:
        return None
    if reps_max < reps_min:
        reps_min, reps_max = reps_max, reps_min

    total = len(reps)
    hit = sum(1 for r in reps if reps_min <= r <= reps_max)
    below = sum(1 for r in reps if r < reps_min)
    above = sum(1 for r in reps if r > reps_max)
    ratio = (hit / total) if total else 0.0

    if ratio >= 0.6:
        label = "on"
    elif below >= above:
        label = "under"
    else:
        label = "over"

    span = reps_max - reps_min
    upper_cut = reps_max if span < 2 else reps_max - 1
    lower_cut = reps_min if span < 2 else reps_min + 1
    upper_bias = (sum(1 for r in reps if r >= upper_cut) / total) >= 0.6
    lower_bias = (sum(1 for r in reps if r <= lower_cut) / total) >= 0.6

    return {
        "label": label,
        "hit": hit,
        "total": total,
        "below": below,
        "above": above,
        "upper_bias": upper_bias,
        "lower_bias": lower_bias,
    }


def _rpe_label(avg_rpe, max_rpe, rpe_min, rpe_max):
    if avg_rpe is None or rpe_min is None or rpe_max is None:
        return None
    if avg_rpe < rpe_min and (max_rpe is None or max_rpe < rpe_min):
        return "under"
    if avg_rpe > rpe_max or (max_rpe is not None and max_rpe > rpe_max):
        return "over"
    return "on"


def _volume_label(planned_sets: int | None, done_sets: int):
    planned_sets = planned_sets or 0
    delta = done_sets - planned_sets
    if abs(delta) <= 1:
        return "on"
    return "over" if delta > 0 else "under"


def _exercise_suggestion(coverage, planned_sets, done_sets, rep_info, rpe_label):
    if coverage == "planned_missing":
        return "Nächstes mal einbauen."
    if coverage == "extra":
        return "Extra-Übung - optional reduzieren."

    planned_sets = planned_sets or 0
    delta = done_sets - planned_sets
    if delta >= 2:
        return "Nächstes mal 1 Satz weniger (Plan einhalten)."
    if delta <= -2:
        return "Nächstes mal 1 Satz mehr (Plan treffen)."

    if rep_info:
        if rep_info["upper_bias"] and (rpe_label in (None, "on", "under")):
            return "Nächstes mal mehr Gewicht."
        if rep_info["lower_bias"] and rpe_label == "over":
            return "Nächstes mal weniger Gewicht oder weniger Reps (Technik sauber)."
        if rep_info["label"] == "on" and (rpe_label in (None, "on", "under")):
            return "Gewicht halten und versuch nächste Einheit 1 Rep mehr."
        if rep_info["label"] == "under":
            return "Reps steigern."

    if rpe_label == "over":
        return "Technik priorisieren."
    return "Gewicht halten."


def _exercise_report(plan_row: dict, matched_logs: list[dict], coverage: str, history: dict | None = None, adjustments: dict | None = None):
    ex_name = (plan_row.get("exercise_name") or plan_row.get("name") or "").strip()
    plan_sets = _clean_int(plan_row.get("sets"))
    reps_min = _clean_int(plan_row.get("reps_min"))
    reps_max = _clean_int(plan_row.get("reps_max"))
    rpe_min = _clean_float(plan_row.get("rpe_min"))
    rpe_max = _clean_float(plan_row.get("rpe_max"))

    vol_factor = None
    rpe_cap = None
    if isinstance(adjustments, dict):
        try:
            vol_factor = float(adjustments.get("volume_factor")) if adjustments.get("volume_factor") is not None else None
        except Exception:
            vol_factor = None
        try:
            rpe_cap = float(adjustments.get("rpe_cap")) if adjustments.get("rpe_cap") is not None else None
        except Exception:
            rpe_cap = None
        if vol_factor is not None and not (0.2 <= vol_factor <= 1.4):
            vol_factor = None
        if rpe_cap is not None and not (5.0 <= rpe_cap <= 10.0):
            rpe_cap = None

    if plan_sets is not None and vol_factor is not None:
        plan_sets = int(round(plan_sets * vol_factor))
        if plan_sets < 0:
            plan_sets = 0
        if plan_sets == 0 and _clean_int(plan_row.get("sets")):
            plan_sets = 1

    if rpe_min is not None and rpe_max is None:
        rpe_max = rpe_min
    if rpe_max is not None and rpe_min is None:
        rpe_min = rpe_max
    if rpe_cap is not None:
        if rpe_min is not None:
            rpe_min = min(rpe_min, rpe_cap)
        if rpe_max is not None:
            rpe_max = min(rpe_max, rpe_cap)

    all_sets = []
    device = (plan_row.get("device") or "").strip()
    for ex in matched_logs:
        sets = ex.get("sets") or []
        if isinstance(sets, list):
            all_sets.extend(sets)
        if not device:
            device = (ex.get("device") or "").strip()

    reps = []
    rpes = []
    weights = []
    set_numbers = []
    seen_set_numbers = set()
    for idx, s in enumerate(all_sets):
        set_num = _clean_int(s.get("set_number"))
        if set_num is None or set_num <= 0 or set_num in seen_set_numbers:
            set_num = idx + 1
        seen_set_numbers.add(set_num)
        set_numbers.append(set_num)
        r = s.get("reps")
        if r is not None:
            try:
                reps.append(int(r))
            except Exception:
                reps.append(None)
        else:
            reps.append(None)
        w = s.get("weight")
        if w is not None:
            try:
                weights.append(float(w))
            except Exception:
                weights.append(None)
        else:
            weights.append(None)
        rpe = s.get("rpe")
        if rpe is not None:
            try:
                rpes.append(float(rpe))
            except Exception:
                rpes.append(None)
        else:
            rpes.append(None)

    done_sets = len(all_sets)
    rpe_vals = [r for r in rpes if r is not None]
    avg_rpe = _normalize_rpe_to_int(sum(rpe_vals) / len(rpe_vals)) if rpe_vals else None
    max_rpe = _normalize_rpe_to_int(max(rpe_vals)) if rpe_vals else None

    reps_vals = [r for r in reps if r is not None]
    rep_info = _rep_stats(reps_vals, reps_min, reps_max)
    total_reps = len(reps_vals)
    rep_range_hit = "0/0"
    if reps_min is not None and reps_max is not None:
        hit_reps = rep_info["hit"] if rep_info else 0
        rep_range_hit = f"{hit_reps}/{total_reps}" if total_reps else "0/0"
    elif total_reps:
        rep_range_hit = f"0/{total_reps}"

    rpe_target_hit = None
    if avg_rpe is not None and rpe_min is not None and rpe_max is not None:
        rpe_target_hit = (rpe_min <= avg_rpe <= rpe_max) and (max_rpe is None or max_rpe <= rpe_max)

    rpe_state = _rpe_label(avg_rpe, max_rpe, rpe_min, rpe_max)
    if rpe_cap is not None and avg_rpe is not None:
        rpe_state = "over" if ((max_rpe is not None and max_rpe > rpe_cap) or avg_rpe > rpe_cap) else "on"
        rpe_target_hit = (rpe_state != "over")
    volume_state = _volume_label(plan_sets, done_sets)
    rpe_missing = (rpe_min is not None or rpe_max is not None) and avg_rpe is None
    rep_label = rep_info["label"] if rep_info else None

    suggestion = _exercise_suggestion(
        coverage,
        plan_sets,
        done_sets,
        rep_info,
        rpe_state
    )

    done_block = {
        "sets": done_sets if done_sets is not None else 0,
        "reps": reps if isinstance(reps, list) else [],
        "weights": weights if isinstance(weights, list) else [],
        "rpes": rpes if isinstance(rpes, list) else [],
        "set_numbers": set_numbers if isinstance(set_numbers, list) else [],
        "avg_rpe": avg_rpe,
        "max_rpe": max_rpe,
        "rep_range_hit": rep_range_hit or "0/0",
        "rpe_target_hit": rpe_target_hit,
    }

    report = {
        "name": ex_name,
        "device": device or None,
        "coverage": coverage,
        "planned": {
            "sets": plan_sets or 0,
            "reps": _format_range(reps_min, reps_max),
            "rpe": _format_range(rpe_min, rpe_max),
        },
        "done": done_block,
        "labels": {
            "volume": volume_state,
            "reps": rep_label,
            "rpe": rpe_state,
        },
        "suggestion": suggestion,
        "_meta": {
            "volume_delta": done_sets - (plan_sets or 0),
            "rpe_missing": rpe_missing,
        }
    }
    if isinstance(history, dict) and history:
        report["history"] = history
    return report


def _build_exercise_reports(plan_rows: list[dict], log_exercises: list[dict], history_map: dict | None = None, debug_matches: list | None = None, adjustments: dict | None = None):
    name_counts = Counter()
    for row in plan_rows:
        if not isinstance(row, dict):
            continue
        name_norm = _norm_text(row.get("exercise_name") or row.get("name") or "")
        if name_norm:
            name_counts[name_norm] += 1

    matched_ids = set()
    reports = []

    for row in plan_rows:
        if not isinstance(row, dict):
            continue
        ex_name = (row.get("exercise_name") or row.get("name") or "").strip()
        if not ex_name:
            continue

        plan_entry = {
            "name_norm": _norm_text(ex_name),
            "variation_norm": _norm_text(row.get("variation") or ""),
            "device_norm": _norm_text(row.get("device") or ""),
            "pattern": classify_pattern(ex_name, row.get("variation") or ""),
        }

        allow_multi = name_counts.get(plan_entry["name_norm"]) == 1 and not plan_entry["variation_norm"]
        matches = _find_log_matches(plan_entry, log_exercises, matched_ids, allow_multi)
        if plan_entry["device_norm"]:
            if plan_entry["variation_norm"]:
                history_key = f"{plan_entry['name_norm']}||{plan_entry['variation_norm']}||{plan_entry['device_norm']}"
            else:
                history_key = f"{plan_entry['name_norm']}||*||{plan_entry['device_norm']}"
        else:
            if plan_entry["variation_norm"]:
                history_key = f"{plan_entry['name_norm']}||{plan_entry['variation_norm']}"
            else:
                history_key = f"{plan_entry['name_norm']}||*"
        history = history_map.get(history_key) if isinstance(history_map, dict) else None
        if matches:
            for m in matches:
                matched_ids.add(m.get("id"))
            if debug_matches is not None:
                debug_matches.append({
                    "plan_exercise": ex_name,
                    "matched_ids": [m.get("id") for m in matches if m.get("id") is not None]
                })
            report = _exercise_report(row, matches, "planned_done", adjustments=adjustments)
            if debug_matches is not None:
                report["_debug_ids"] = [m.get("id") for m in matches if m.get("id") is not None]
            reports.append(report)
        else:
            if debug_matches is not None:
                debug_matches.append({
                    "plan_exercise": ex_name,
                    "matched_ids": []
                })
            report = _exercise_report(row, [], "planned_missing", history=history, adjustments=adjustments)
            if debug_matches is not None:
                report["_debug_ids"] = []
            reports.append(report)

    for log in log_exercises:
        if log.get("id") in matched_ids:
            continue
        report = _exercise_report(
            {"exercise_name": log.get("name") or "", "sets": 0},
            [log],
            "extra",
            adjustments=adjustments
        )
        if debug_matches is not None:
            report["_debug_ids"] = [log.get("id")] if log.get("id") is not None else []
        reports.append(report)

    return reports


def _session_flags_and_status(reports: list[dict]):
    planned_done = [r for r in reports if r.get("coverage") == "planned_done"]
    planned_total = len(planned_done) + sum(1 for r in reports if r.get("coverage") == "planned_missing")
    missing = sum(1 for r in reports if r.get("coverage") == "planned_missing")
    extra = sum(1 for r in reports if r.get("coverage") == "extra")
    reps_off = sum(1 for r in planned_done if r.get("labels", {}).get("reps") in ("under", "over"))
    rpe_over = sum(1 for r in planned_done if r.get("labels", {}).get("rpe") == "over")
    rpe_missing = sum(1 for r in planned_done if r.get("_meta", {}).get("rpe_missing"))
    volume_over = sum(1 for r in planned_done if r.get("_meta", {}).get("volume_delta", 0) >= 2)
    volume_under = sum(1 for r in planned_done if r.get("_meta", {}).get("volume_delta", 0) <= -2)

    flags = []
    if missing:
        flags.append("Übungen fehlen")
    if extra:
        flags.append("Extra-Übungen")
    if volume_over:
        flags.append("Volumen über Plan")
    if volume_under:
        flags.append("Volumen drunter")
    if rpe_over:
        flags.append("RPE zu hoch")
    if rpe_missing:
        flags.append("RPE fehlt")
    if reps_off:
        flags.append("Reps daneben")

    if not flags:
        flags = ["Plan getroffen"]

    issue_score = volume_under + rpe_over + reps_off
    missing_ratio = (missing / planned_total) if planned_total else 0.0
    hard_missing = (missing >= 3) or (missing >= 2 and missing_ratio >= 0.6)
    hard_overall = issue_score >= 5

    if hard_missing or hard_overall:
        status = "red"
    elif missing or extra or volume_under or rpe_over or reps_off or rpe_missing:
        status = "yellow"
    else:
        status = "green"

    summary_parts = []
    if rpe_missing:
        summary_parts.append("RPE nicht geloggt")
    if missing >= 2:
        summary_parts.append("mehrere geplante Übungen fehlen")
    elif missing == 1:
        summary_parts.append("eine geplante Übung fehlt")
    elif volume_over or volume_under or rpe_over:
        summary_parts.append("Volumen/RPE weichen ab")
    elif reps_off:
        summary_parts.append("Reps weichen ab")
    elif extra:
        summary_parts.append("Extra-Übungen geloggt")

    if summary_parts:
        summary = "; ".join(summary_parts)
        if not summary.endswith("."):
            summary += "."
    else:
        summary = "Plan gut getroffen."

    return status, summary, flags[:5]


def _normalize_done(report: dict):
    done = report.get("done")
    if not isinstance(done, dict):
        done = {}
    sets = done.get("sets")
    reps = done.get("reps")
    weights = done.get("weights")
    rpes = done.get("rpes")
    set_numbers = done.get("set_numbers")
    rep_range_hit = done.get("rep_range_hit")
    report["done"] = {
        "sets": sets if isinstance(sets, int) else 0,
        "reps": reps if isinstance(reps, list) else [],
        "weights": weights if isinstance(weights, list) else [],
        "rpes": rpes if isinstance(rpes, list) else [],
        "set_numbers": set_numbers if isinstance(set_numbers, list) else [],
        "avg_rpe": done.get("avg_rpe"),
        "max_rpe": done.get("max_rpe"),
        "rep_range_hit": rep_range_hit if isinstance(rep_range_hit, str) else "0/0",
        "rpe_target_hit": done.get("rpe_target_hit"),
    }
    return report


def build_plan_check_for_workout(workout_id: int, *, debug: bool = False):
    plan_row = _get_active_plan_row()
    if not plan_row:
        return None
    plan = plan_row_to_dict(plan_row)

    workout, exercises, sets_by_exercise = _fetch_workout_with_sets(workout_id)
    if not workout:
        return None

    kienzl_adjustments = None
    try:
        from kienzl import kienzl as _kienzl
        wday = workout.get("date_iso") or None
        if wday:
            kienzl_adjustments = _kienzl.get_adjustments(wday)
    except Exception:
        kienzl_adjustments = None

    if debug:
        set_count = sum(len(v) for v in sets_by_exercise.values())
        print("PLAN_CHECK_DEBUG:", {
            "workout_id": workout_id,
            "sets_count": set_count,
            "exercise_ids": sorted([k for k in sets_by_exercise.keys() if k is not None]),
        })

    log_exercises = _build_log_exercises(exercises)
    plan_day = None
    plan_days = plan.get("base_week") or []
    workout_session_key = (workout.get("session_key") or "").strip()
    if workout_session_key:
        for idx, day in enumerate(plan_days):
            if not isinstance(day, dict):
                continue
            session_name = (day.get("session_name") or "").strip()
            display_name = session_name or f"Session {idx + 1}"
            if _session_key_from_day(idx, display_name) == workout_session_key:
                plan_day = day
                break
    if not plan_day:
        _, plan_day = _select_plan_day(plan, workout.get("name") or "", log_exercises)
    plan_rows = plan_day.get("strength_exercises") or []
    plan_targets = []
    for row in plan_rows:
        if not isinstance(row, dict):
            continue
        name = (row.get("exercise_name") or row.get("name") or "").strip()
        if name:
            plan_targets.append({
                "name": name,
                "variation": (row.get("variation") or "").strip(),
                "device": (row.get("device") or "").strip(),
            })
    history_map = _latest_exercise_history(plan_targets)

    debug_matches = [] if debug else None
    reports = _build_exercise_reports(plan_rows, log_exercises, history_map, debug_matches, adjustments=kienzl_adjustments)
    if debug and debug_matches is not None:
        for entry in debug_matches:
            print("PLAN_CHECK_MATCH:", entry)

    normalized = []
    for r in reports:
        normalized.append(_normalize_done(r))
    reports = normalized
    status, summary, flags = _session_flags_and_status(reports)

    for r in reports:
        if debug:
            done = r.get("done") or {}
            print("PLAN_CHECK_DONE:", {
                "name": r.get("name"),
                "exercise_ids": r.get("_debug_ids") or [],
                "computed_sets": done.get("sets"),
                "computed_reps_len": len(done.get("reps") or []),
                "avg_rpe": done.get("avg_rpe"),
                "max_rpe": done.get("max_rpe"),
                "rep_range_hit": done.get("rep_range_hit"),
            })
        r.pop("_meta", None)
        r.pop("_debug_ids", None)

    return {
        "version": PLAN_CHECK_VERSION,
        "workout_id": workout_id,
        "plan_id": plan.get("id"),
        "status": status,
        "summary": summary,
        "flags": flags,
        "exercises": reports,
        "adjustments": {
            "mode": (kienzl_adjustments or {}).get("mode"),
            "intensity_factor": (kienzl_adjustments or {}).get("intensity_factor"),
            "volume_factor": (kienzl_adjustments or {}).get("volume_factor"),
            "rpe_cap": (kienzl_adjustments or {}).get("rpe_cap"),
        } if kienzl_adjustments else None,
        "adjustments_source": "kienzl_daily" if kienzl_adjustments else None,
    }


def save_plan_check_report(report: dict):
    if not report:
        return None
    conn = get_training_db()
    cur = conn.cursor()
    now = datetime.utcnow().isoformat()
    cur.execute("""
        INSERT INTO plan_checks (
            workout_id, plan_id, status, summary, flags_json, payload, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(workout_id) DO UPDATE SET
            plan_id = excluded.plan_id,
            status = excluded.status,
            summary = excluded.summary,
            flags_json = excluded.flags_json,
            payload = excluded.payload,
            updated_at = excluded.updated_at
    """, (
        report.get("workout_id"),
        report.get("plan_id"),
        report.get("status"),
        report.get("summary"),
        json.dumps(report.get("flags") or [], ensure_ascii=False),
        json.dumps(report, ensure_ascii=False),
        now,
        now
    ))
    conn.commit()
    conn.close()
    return report


def load_plan_check_report(workout_id: int):
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    row = conn.execute("""
        SELECT payload
        FROM plan_checks
        WHERE workout_id = ?
    """, (workout_id,)).fetchone()
    conn.close()
    if not row:
        return None
    try:
        return json.loads(row["payload"])
    except Exception:
        return None


def _normalize_name_key(value: Any) -> str:
    txt = str(value or "").strip().lower()
    txt = re.sub(r"\s+", " ", txt)
    return txt


def _ensure_training_pr_notice_schema(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS training_pr_notice (
            workout_id INTEGER NOT NULL,
            exercise_name TEXT NOT NULL,
            e1rm_sent REAL NOT NULL,
            sent_at TEXT NOT NULL,
            message_id INTEGER,
            PRIMARY KEY (workout_id, exercise_name)
        )
        """
    )


def _active_plan_exercise_name_keys() -> set[str]:
    record = _get_active_gym_plan_record()
    if not isinstance(record, dict):
        return set()
    plan_json = record.get("plan_json") if isinstance(record.get("plan_json"), dict) else {}
    out: set[str] = set()

    def collect(value: Any) -> None:
        if isinstance(value, list):
            for item in value:
                collect(item)
            return
        if not isinstance(value, dict):
            return
        kind = str(value.get("kind") or "").strip().lower()
        exercise_name = (
            value.get("name")
            if kind == "exercise"
            else value.get("display_name")
            if kind == "ref_block"
            else value.get("exercise_name")
        )
        key = _normalize_name_key(exercise_name)
        if key:
            out.add(key)
        for child_key in ("days", "base_week", "sequence", "events", "items", "strength_exercises", "exercises"):
            child = value.get(child_key)
            if isinstance(child, (list, dict)):
                collect(child)

    collect(plan_json)
    return out


def _format_de_1(v: float) -> str:
    try:
        return f"{float(v):.1f}".replace(".", ",")
    except Exception:
        return "-"


def _notify_plan_e1rm_prs(workout_id: int) -> None:
    planned_keys = _active_plan_exercise_name_keys()
    if not planned_keys:
        return

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        _ensure_training_pr_notice_schema(conn)
        rows = conn.execute(
            """
            SELECT e.name AS exercise_name,
                   MAX(s.weight * (1.0 + (s.reps / 30.0))) AS e1rm_now
            FROM exercises e
            JOIN sets s ON s.exercise_id = e.id
            WHERE e.workout_id = ?
              AND s.weight IS NOT NULL
              AND s.reps IS NOT NULL
              AND s.weight > 0
              AND s.reps > 0
            GROUP BY e.name
            """,
            (int(workout_id),),
        ).fetchall()

        for row in rows:
            ex_name = str(row["exercise_name"] or "").strip()
            if not ex_name:
                continue
            name_key = _normalize_name_key(ex_name)
            if name_key not in planned_keys:
                continue
            e1rm_now = float(row["e1rm_now"] or 0.0)
            if e1rm_now <= 0:
                continue

            sent_row = conn.execute(
                """
                SELECT e1rm_sent
                FROM training_pr_notice
                WHERE workout_id = ? AND exercise_name = ?
                LIMIT 1
                """,
                (int(workout_id), ex_name),
            ).fetchone()
            if sent_row and float(sent_row["e1rm_sent"] or 0.0) >= (e1rm_now - 0.05):
                continue

            prev_row = conn.execute(
                """
                SELECT MAX(s.weight * (1.0 + (s.reps / 30.0))) AS e1rm_prev
                FROM exercises e
                JOIN sets s ON s.exercise_id = e.id
                WHERE LOWER(TRIM(e.name)) = ?
                  AND e.workout_id <> ?
                  AND s.weight IS NOT NULL
                  AND s.reps IS NOT NULL
                  AND s.weight > 0
                  AND s.reps > 0
                """,
                (name_key, int(workout_id)),
            ).fetchone()
            e1rm_prev = float(prev_row["e1rm_prev"] or 0.0) if prev_row and prev_row["e1rm_prev"] is not None else None
            if e1rm_prev is None or e1rm_now <= (e1rm_prev + 0.05):
                continue

            top_set = conn.execute(
                """
                SELECT s.weight AS weight, s.reps AS reps
                FROM exercises e
                JOIN sets s ON s.exercise_id = e.id
                WHERE e.workout_id = ?
                  AND LOWER(TRIM(e.name)) = ?
                  AND s.weight IS NOT NULL
                  AND s.reps IS NOT NULL
                  AND s.weight > 0
                  AND s.reps > 0
                ORDER BY (s.weight * (1.0 + (s.reps / 30.0))) DESC, s.weight DESC, s.reps DESC
                LIMIT 1
                """,
                (int(workout_id), name_key),
            ).fetchone()
            weight_txt = _format_de_1(float(top_set["weight"])) if top_set and top_set["weight"] is not None else "-"
            reps_txt = str(int(top_set["reps"])) if top_set and top_set["reps"] is not None else "-"
            delta = e1rm_now - e1rm_prev
            text = (
                f"PR 🚀 {ex_name}\n"
                f"Neues e1RM: {_format_de_1(e1rm_now)} kg (+{_format_de_1(delta)})\n"
                f"Top-Set: {reps_txt} x {weight_txt}kg"
            )
            sent = send_ntfy_notification(
                text,
                title="LIVA · Training PR",
                priority=4,
                tags="trophy,muscle",
            )
            message_id = None
            if not sent.get("ok") or not sent.get("sent"):
                continue

            conn.execute(
                """
                INSERT INTO training_pr_notice (workout_id, exercise_name, e1rm_sent, sent_at, message_id)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(workout_id, exercise_name) DO UPDATE SET
                    e1rm_sent = excluded.e1rm_sent,
                    sent_at = excluded.sent_at,
                    message_id = excluded.message_id
                """,
                (
                    int(workout_id),
                    ex_name,
                    float(e1rm_now),
                    datetime.utcnow().isoformat(),
                    message_id,
                ),
            )
        conn.commit()
    finally:
        conn.close()


