def _training_import_plan_day(date_iso: str | None, session_name: str | None, exercises: list[dict] | None) -> dict:
    try:
        plan, _source = _active_plan_for_decision(bool(_get_core_mode_enabled()))
    except Exception:
        app.logger.exception("training_import_plan_lookup_failed")
        plan = None
    if not isinstance(plan, dict):
        return {}

    base_week = plan.get("base_week") or []
    if not isinstance(base_week, list) or not base_week:
        return {}

    session_norm = _norm_text(session_name or "")
    if session_norm:
        for day in base_week:
            if not isinstance(day, dict):
                continue
            if _norm_text(day.get("session_name") or "") == session_norm:
                return day

    try:
        weekday_idx = datetime.strptime(date_iso or "", "%Y-%m-%d").weekday()
    except Exception:
        weekday_idx = None
    if weekday_idx is not None:
        day_aliases = {
            0: {"mo", "montag", "monday"},
            1: {"di", "dienstag", "tuesday"},
            2: {"mi", "mittwoch", "wednesday"},
            3: {"do", "donnerstag", "thursday"},
            4: {"fr", "freitag", "friday"},
            5: {"sa", "samstag", "saturday"},
            6: {"so", "sonntag", "sunday"},
        }
        for idx, day in enumerate(base_week):
            if not isinstance(day, dict):
                continue
            day_norm = _norm_text(day.get("day") or "")
            if day_norm in day_aliases.get(weekday_idx, set()) or idx == weekday_idx:
                if day.get("strength_exercises"):
                    return day

    log_exercises = []
    for ex in exercises or []:
        if not isinstance(ex, dict):
            continue
        name = (ex.get("name") or "").strip()
        if not name:
            continue
        log_exercises.append({
            "name": name,
            "name_norm": _norm_text(name),
            "variation_norm": _norm_text(ex.get("variation") or ""),
            "pattern": classify_pattern(name, ex.get("variation") or ""),
        })
    if log_exercises:
        try:
            _idx, day = _select_plan_day(plan, session_name or "", log_exercises)
            return day if isinstance(day, dict) else {}
        except Exception:
            app.logger.exception("training_import_plan_day_select_failed")
    return {}


def _training_plan_rows(day: dict) -> list[dict]:
    rows = day.get("strength_exercises") if isinstance(day, dict) else []
    out: list[dict] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        name = (row.get("exercise_name") or row.get("name") or "").strip()
        if not name:
            continue
        out.append({
            "name": name,
            "variation": (row.get("variation") or "").strip(),
            "device": (row.get("device") or "").strip(),
            "raw": row,
        })
    return out


def _training_exercise_catalog(conn: sqlite3.Connection, *, plan_rows: list[dict]) -> dict:
    names: dict[str, dict] = {}
    for idx, row in enumerate(plan_rows or []):
        key = _norm_text(row.get("name") or "")
        if not key:
            continue
        names.setdefault(key, {"name": row["name"], "source": "plan", "plan_index": idx})

    try:
        rows = conn.execute(
            """
            SELECT e.name AS name, COUNT(*) AS count, MAX(w.date_iso) AS last_date
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            WHERE TRIM(COALESCE(e.name, '')) <> ''
            GROUP BY LOWER(TRIM(e.name))
            ORDER BY count DESC, last_date DESC
            """
        ).fetchall()
    except Exception:
        rows = []

    for row in rows:
        name = (row["name"] or "").strip()
        key = _norm_text(name)
        if not key:
            continue
        names.setdefault(key, {"name": name, "source": "history", "plan_index": None})
    return {"names": names, "plan_rows": plan_rows or []}


def _training_alias_target(raw_name: str, catalog: dict) -> str:
    key = _norm_text(raw_name)
    alias = _TRAINING_NAME_ALIASES.get(key)
    if not alias:
        return ""
    alias_key = _norm_text(alias)
    entry = (catalog.get("names") or {}).get(alias_key)
    return entry["name"] if entry else alias


def _standardize_training_exercise_name(raw_name: str, catalog: dict) -> dict:
    raw = (raw_name or "").strip()
    key = _norm_text(raw)
    names = catalog.get("names") or {}
    if not key:
        return {"name": "", "confidence": "low", "source": "empty"}
    if key in names:
        return {"name": names[key]["name"], "confidence": "high", "source": names[key].get("source") or "exact"}

    alias = _training_alias_target(raw, catalog)
    if alias:
        return {"name": alias, "confidence": "medium", "source": "alias"}

    plan_keys = [
        _norm_text(r.get("name") or "")
        for r in catalog.get("plan_rows") or []
        if _norm_text(r.get("name") or "")
    ]
    plan_match = difflib.get_close_matches(key, plan_keys, n=1, cutoff=0.74)
    if plan_match:
        entry = names.get(plan_match[0])
        if entry:
            return {"name": entry["name"], "confidence": "medium", "source": "plan_fuzzy"}

    all_keys = list(names.keys())
    hist_match = difflib.get_close_matches(key, all_keys, n=1, cutoff=0.82)
    if hist_match:
        entry = names.get(hist_match[0])
        if entry:
            return {"name": entry["name"], "confidence": "medium", "source": "history_fuzzy"}

    return {"name": raw, "confidence": "low", "source": "raw"}


def _planned_variation_for_exercise(plan_rows: list[dict], exercise_name: str) -> str:
    key = _norm_text(exercise_name)
    for row in plan_rows or []:
        if _norm_text(row.get("name") or "") == key:
            return (row.get("variation") or "").strip()
    close = difflib.get_close_matches(key, [_norm_text(r.get("name") or "") for r in plan_rows or []], n=1, cutoff=0.86)
    if close:
        for row in plan_rows or []:
            if _norm_text(row.get("name") or "") == close[0]:
                return (row.get("variation") or "").strip()
    return ""


def _variation_weight_fit(
    conn: sqlite3.Connection,
    *,
    exercise_name: str,
    variation: str,
    target_weight: float | None,
    before_date: str,
) -> dict:
    if not variation:
        return {"fits": False, "reason": "no_planned_variation"}
    if target_weight is None or not math.isfinite(target_weight) or target_weight <= 0:
        return {"fits": True, "reason": "no_weight_anchor"}
    rows = conn.execute(
        """
        SELECT MAX(CASE WHEN s.weight IS NOT NULL THEN s.weight ELSE 0 END) AS max_weight
        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        LEFT JOIN sets s ON s.exercise_id = e.id
        WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
          AND LOWER(TRIM(COALESCE(e.variation, ''))) = LOWER(TRIM(?))
          AND w.date_iso <= ?
        GROUP BY e.id
        ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
        LIMIT 12
        """,
        (exercise_name, variation, before_date),
    ).fetchall()
    weights = []
    for row in rows:
        try:
            weight = float(row["max_weight"] or 0)
        except (TypeError, ValueError):
            continue
        if math.isfinite(weight) and weight > 0:
            weights.append(weight)
    med = _median(weights)
    if med is None:
        return {"fits": True, "reason": "planned_no_weight_history"}
    diff_ratio = abs(med - target_weight) / max(med, target_weight, 1.0)
    return {"fits": diff_ratio <= 0.25, "reason": "planned_weight_fit", "median_weight": med, "diff_ratio": diff_ratio}


def _standardize_training_variation(
    conn: sqlite3.Connection,
    *,
    exercise: dict,
    exercise_name: str,
    plan_rows: list[dict],
    date_iso: str,
) -> dict:
    raw_variation = (exercise.get("variation") or "").strip()
    if raw_variation and exercise.get("variation_user_locked"):
        return {"variation": raw_variation, "source": "user_locked", "confidence": "high"}

    weight_anchor = _variation_weight_anchor(exercise)
    planned = _planned_variation_for_exercise(plan_rows, exercise_name)
    plan_fit = _variation_weight_fit(
        conn,
        exercise_name=exercise_name,
        variation=planned,
        target_weight=weight_anchor,
        before_date=date_iso,
    ) if planned else {"fits": False, "reason": "no_planned_variation"}

    if planned and plan_fit.get("fits"):
        return {
            "variation": planned,
            "source": "active_plan",
            "confidence": "high" if weight_anchor else "medium",
            "planned_variation": planned,
            "planned_fit": plan_fit,
        }

    weight_pick = _variation_by_weight_similarity(
        conn,
        exercise_name=exercise_name,
        before_date=date_iso,
        target_weight=weight_anchor,
    )
    if weight_pick.get("variation") and (weight_pick.get("confidence") in {"high", "medium"} or not planned):
        return {
            "variation": weight_pick["variation"],
            "source": "weight_history",
            "confidence": weight_pick.get("confidence") or "medium",
            "planned_variation": planned,
            "planned_fit": plan_fit,
        }

    if raw_variation:
        return {"variation": raw_variation, "source": "raw", "confidence": "low"}

    hist = _variation_history_mode(conn, exercise_name=exercise_name, before_date=date_iso)
    if hist.get("mode") and (hist.get("share") or 0) >= 0.7 and (hist.get("count") or 0) >= 2:
        return {"variation": hist["mode"], "source": "history_mode", "confidence": "medium"}

    if planned:
        return {
            "variation": planned,
            "source": "active_plan_fallback",
            "confidence": "low",
            "planned_variation": planned,
            "planned_fit": plan_fit,
        }
    return {"variation": "", "source": "none", "confidence": "low"}


def _standardize_training_import_exercises(
    exercises: list,
    *,
    date_iso: str,
    session_name: str,
) -> list:
    if not isinstance(exercises, list):
        return []
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        plan_day = _training_import_plan_day(date_iso, session_name, exercises)
        plan_rows = _training_plan_rows(plan_day)
        catalog = _training_exercise_catalog(conn, plan_rows=plan_rows)
        normalized = []
        for item in exercises:
            if not isinstance(item, dict):
                continue
            ex = dict(item)
            raw_name = (ex.get("name") or ex.get("exercise") or ex.get("exercise_name") or "").strip()
            name_pick = _standardize_training_exercise_name(raw_name, catalog)
            ex["name"] = name_pick["name"]
            variation_pick = _standardize_training_variation(
                conn,
                exercise=ex,
                exercise_name=ex["name"],
                plan_rows=plan_rows,
                date_iso=date_iso,
            )
            if variation_pick.get("variation") or not (ex.get("variation") or "").strip():
                ex["variation"] = variation_pick.get("variation") or ""
            ex["normalization_meta"] = {
                "raw_name": raw_name,
                "name_source": name_pick.get("source"),
                "name_confidence": name_pick.get("confidence"),
                "variation_source": variation_pick.get("source"),
                "variation_confidence": variation_pick.get("confidence"),
                "planned_variation": variation_pick.get("planned_variation"),
            }
            normalized.append(ex)
        return normalized
    finally:
        conn.close()


@app.post("/api/training/import/normalize")
def api_training_import_normalize():
    payload = request.get_json(force=True) or {}
    raw_iso = payload.get("date_iso")
    try:
        date_iso = datetime.strptime(raw_iso, "%Y-%m-%d").strftime("%Y-%m-%d") if raw_iso else date.today().isoformat()
    except Exception:
        date_iso = date.today().isoformat()
    session_name = (payload.get("session_name") or "Training").strip()
    exercises = _standardize_training_import_exercises(
        payload.get("exercises") or [],
        date_iso=date_iso,
        session_name=session_name,
    )
    return jsonify({"date_iso": date_iso, "session_name": session_name, "exercises": exercises})


@app.get("/api/training/import/catalog")
def api_training_import_catalog():
    date_iso = (request.args.get("date_iso") or date.today().isoformat()).strip()
    session_name = (request.args.get("session_name") or "Training").strip()
    plan_day = _training_import_plan_day(date_iso, session_name, [])
    plan_rows = _training_plan_rows(plan_day)
    plan_names = {_norm_text(row.get("name") or ""): row for row in plan_rows}

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            """
            SELECT
                e.name AS name,
                e.variation AS variation,
                COUNT(*) AS count,
                MAX(w.date_iso) AS last_date
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            WHERE TRIM(COALESCE(e.name, '')) <> ''
            GROUP BY LOWER(TRIM(e.name)), LOWER(TRIM(COALESCE(e.variation, '')))
            ORDER BY LOWER(TRIM(e.name)), count DESC, last_date DESC
            """
        ).fetchall()
        by_name: dict[str, dict] = {}
        for row in rows:
            name = (row["name"] or "").strip()
            if not name:
                continue
            key = _norm_text(name)
            entry = by_name.setdefault(key, {
                "name": name,
                "is_in_active_plan": key in plan_names,
                "planned_variation": (plan_names.get(key) or {}).get("variation") or "",
                "variants": [],
                "count": 0,
                "last_date": None,
            })
            count = int(row["count"] or 0)
            entry["count"] += count
            if row["last_date"] and (entry["last_date"] is None or row["last_date"] > entry["last_date"]):
                entry["last_date"] = row["last_date"]
            variation = (row["variation"] or "").strip()
            if variation:
                entry["variants"].append({
                    "variation": variation,
                    "count": count,
                    "last_date": row["last_date"],
                })

        for key, row in plan_names.items():
            if not key:
                continue
            by_name.setdefault(key, {
                "name": row["name"],
                "is_in_active_plan": True,
                "planned_variation": row.get("variation") or "",
                "variants": [],
                "count": 0,
                "last_date": None,
            })

        exercises = sorted(
            by_name.values(),
            key=lambda item: (not item["is_in_active_plan"], -(item["count"] or 0), item["name"].lower()),
        )
        return jsonify({
            "date_iso": date_iso,
            "session_name": session_name,
            "exercises": exercises,
            "aliases": _TRAINING_NAME_ALIASES,
        })
    finally:
        conn.close()


