@app.route("/training/save", methods=["POST"])
def save_training():
    data = request.get_json(force=True)

    # =========================
    # DATE (BACKEND IS BOSS)
    # =========================
    workout_id = data.get("workout_id")

    raw_iso = data.get("date_iso")
    try:
        if raw_iso:
            date_iso = datetime.strptime(raw_iso, "%Y-%m-%d").strftime("%Y-%m-%d")
        else:
            date_iso = date.today().isoformat()
    except Exception:
        date_iso = date.today().isoformat()

    date_pretty = datetime.strptime(date_iso, "%Y-%m-%d").strftime("%d.%m.%y")

    # =========================
    # META
    # =========================
    session_name = (data.get("session_name") or "Training").strip()
    session_key = (data.get("session_key") or "").strip()
    session_notes = (data.get("session_notes") or "").strip()
    raw_import_text = (data.get("raw_import_text") or "").strip()
    plan_id_raw = data.get("plan_id") or data.get("template_id")
    plan_id = None
    if plan_id_raw:
        try:
            plan_id = int(plan_id_raw)
        except (ValueError, TypeError):
            plan_id = None
    exercises = _standardize_training_import_exercises(
        data.get("exercises", []),
        date_iso=date_iso,
        session_name=session_name,
    )
    if not raw_import_text and exercises:
        raw_import_text = normalized_training_text(exercises)

    conn = get_training_db()
    cur = conn.cursor()
    has_session_key = _column_exists(cur, "workouts", "session_key")

    try:
        cur.execute("BEGIN")

        # =========================
        # WORKOUT
        # =========================
        if workout_id:
            if has_session_key:
                cur.execute("""
                    UPDATE workouts
                    SET date = ?, date_iso = ?, name = ?, notes = ?, session_key = ?, raw_import_text = ?, plan_id = ?
                    WHERE id = ?
                """, (
                    date_pretty,
                    date_iso,
                    session_name,
                    session_notes,
                    session_key or None,
                    raw_import_text or None,
                    plan_id,
                    workout_id
                ))
            else:
                cur.execute("""
                    UPDATE workouts
                    SET date = ?, date_iso = ?, name = ?, notes = ?, raw_import_text = ?, plan_id = ?
                    WHERE id = ?
                """, (
                    date_pretty,
                    date_iso,
                    session_name,
                    session_notes,
                    raw_import_text or None,
                    plan_id,
                    workout_id
                ))

            # alte Übungen + Sets löschen
            cur.execute("""
                DELETE FROM sets
                WHERE exercise_id IN (
                    SELECT id FROM exercises WHERE workout_id = ?
                )
            """, (workout_id,))
            cur.execute("DELETE FROM exercises WHERE workout_id = ?", (workout_id,))

        else:
            if has_session_key:
                cur.execute("""
                    INSERT INTO workouts (date, date_iso, name, notes, session_key, raw_import_text, plan_id, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
                """, (
                    date_pretty,
                    date_iso,
                    session_name,
                    session_notes,
                    session_key or None,
                    raw_import_text or None,
                    plan_id
                ))
            else:
                cur.execute("""
                    INSERT INTO workouts (date, date_iso, name, notes, raw_import_text, plan_id, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
                """, (
                    date_pretty,
                    date_iso,
                    session_name,
                    session_notes,
                    raw_import_text or None,
                    plan_id
                ))
            workout_id = cur.lastrowid

        # =========================
        # EXERCISES + SETS
        # =========================
        for ex in exercises:
            name = (ex.get("name") or "").strip()
            raw  = (ex.get("variation") or "").strip()

            device, laterality = normalize_variation(raw)

            # ============================
            # DEFAULT
            # ============================
            if not laterality:
                laterality = "bilateral"

            # ============================
            # FIXE UNILATERALE ÜBUNGEN
            # ============================
            UNILATERAL_ALWAYS = {
                "Beinpresse",
                "Beinstrecker",
                "Rotator",
            }
            if name in UNILATERAL_ALWAYS:
                laterality = "unilateral"

            # ============================
            # GERÄTEABHÄNGIGE REGELN
            # ============================
            # Wadenheben an gym80 ist IMMER unilateral (ab jetzt Standard)
            if name == "Wadenheben" and device == "gym80":
                laterality = "unilateral"

            if name == "Seitheben" and device == "SZ":
                laterality = "unilateral"

            # ============================
            # ISO-HANTEL-LOGIK
            # ============================
            ISO_UNILATERAL = {
                "reversed Flys",
                "Katanas",
                "Carters",
            }
            if name in ISO_UNILATERAL:
                laterality = "unilateral"

            # ============================
            # PUSH DOWNS: NUR HIER SWITCHBAR
            # ============================
            # Ziel: device ist der Modus: unilat/bilat
            # laterality bleibt neutral (= bilateral), damit es sonst überall wie vorher bleibt.
            if name == "Pushdowns":
                # Falls du noch alte Logs/Inputs mit SZ hast: aus der damaligen Laterality ableiten
                if device == "SZ":
                    device = "unilat" if laterality == "unilateral" else "bilat"

                # Wenn jemand direkt unilat/bilat eingibt -> akzeptieren
                if device not in ("unilat", "bilat"):
                    # Fallback: aus erkannter Laterality ableiten (wichtig bei "unilat" ohne SZ im Raw-Text)
                    device = "unilat" if laterality == "unilateral" else "bilat"

                # laterality für Pushdowns immer neutral halten
                laterality = "bilateral"

            notes = merge_exercise_notes(ex.get("notes"), ex.get("sets") or [])

            if not name:
                continue

            cur.execute("""
                INSERT INTO exercises (
                    workout_id,
                    name,
                    variation,
                    device,
                    laterality,
                    canonical_exercise_id,
                    variation_id,
                    execution_mode,
                    notes,
                    created_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
            """, (
                workout_id,
                name,
                raw,
                device,
                laterality,
                str(ex.get("canonical_exercise_id") or ex.get("canonical_id") or name).strip(),
                str(ex.get("variation_id") or raw).strip(),
                str(ex.get("execution_mode") or "").strip(),
                notes
            ))

            ex_id = cur.lastrowid

            for set_idx, s in enumerate(ex.get("sets", [])):
                if s.get("weight") is None:
                    continue
                raw_rpe = s.get("rpe")
                rpe_val = _parse_float_or_none(raw_rpe)
                if DEBUG_SAVE_SETS:
                    print("SET_SAVE_IN:", {
                        "exercise_id": ex_id,
                        "workout_id": workout_id,
                        "reps": s.get("reps"),
                        "weight": s.get("weight"),
                        "rpe_raw": raw_rpe,
                        "rpe_norm": rpe_val,
                    })

                set_number = s.get("set_number") or s.get("order_index") or (set_idx + 1)
                cur.execute("""
                    INSERT INTO sets (
                        exercise_id, workout_id, set_number, set_slot, reps, weight, rpe,
                        is_warmup, is_working_set, intentional_deload, technique_set,
                        progression_excluded, progression_exclusion_reason, created_at
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
                """, (
                    ex_id,
                    workout_id,
                    set_number,
                    s.get("set_slot") or f"straight_{set_number}",
                    s.get("reps"),
                    float(s.get("weight")),
                    rpe_val,
                    s.get("is_warmup"),
                    s.get("is_working_set") if s.get("is_working_set") is not None else s.get("is_work_set"),
                    int(bool(s.get("intentional_deload"))),
                    int(bool(s.get("technique_set"))),
                    int(bool(s.get("progression_excluded"))),
                    (str(s.get("progression_exclusion_reason") or "").strip() or None),
                ))
                if DEBUG_SAVE_SETS:
                    set_id = cur.lastrowid
                    row = cur.execute("SELECT rpe FROM sets WHERE id = ?", (set_id,)).fetchone()
                    stored = row["rpe"] if row else None
                    if raw_rpe is not None and rpe_val is None:
                        print("RPE_PARSE_FAIL:", {"set_id": set_id, "rpe_raw": raw_rpe})
                    if rpe_val is not None and stored is None:
                        print("RPE_STORE_MISSING:", {"set_id": set_id, "rpe_norm": rpe_val})

        conn.commit()
        touch_last_update()

        try:
            report = build_plan_check_for_workout(workout_id)
            save_plan_check_report(report)
        except Exception as e:
            print("PLAN CHECK ERROR:", e)
        # PR alerts are emitted by the central inbox scanner. Keeping a single
        # sender prevents a web save and the scanner from notifying twice.

        invalidate_snapshot("training_snapshot")
        invalidate_snapshot_prefix("dashboard_snapshot:")
        invalidate_snapshot_prefix("today_snapshot:")
        invalidate_snapshot_prefix("next_session_snapshot:")
        _core_invalidate_dashboard_caches(date_iso)

    except Exception as e:
        conn.rollback()
        print("SAVE ERROR:", e)
        return jsonify(success=False), 500

    finally:
        conn.close()

    progress = None
    progress_conn = get_training_db()
    try:
        progress_conn.row_factory = sqlite3.Row
        progress = compute_session_progress(progress_conn, int(workout_id))
    finally:
        progress_conn.close()
    return jsonify(success=True, workout_id=workout_id, progress=progress)



