#   LOAD / DELETE WORKOUT
# ============================================================

@app.route("/api/workout/<int:workout_id>")
def load_workout(workout_id):
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    cur.execute("SELECT * FROM workouts WHERE id=?", (workout_id,))
    workout = cur.fetchone()

    # ❗ IMMER exercises mitsenden
    if not workout:
        conn.close()
        return jsonify(
            success=False,
            workout=None,
            exercises=[]
        )

    cur.execute("""
        SELECT * FROM exercises
        WHERE workout_id=?
        ORDER BY id
    """, (workout_id,))
    exercises_raw = cur.fetchall()

    exercises = []

    for ex in exercises_raw:
        cur.execute("""
            SELECT set_number, set_slot, reps, weight, rpe,
                   is_warmup, is_working_set, intentional_deload, technique_set,
                   progression_excluded, progression_exclusion_reason
            FROM sets
            WHERE exercise_id=?
            ORDER BY set_number
        """, (ex["id"],))

        sets = [dict(s) for s in cur.fetchall()]

        exercises.append({
            "id": ex["id"],
            "name": ex["name"],
            "variation": ex["variation"] or "",
            "device": ex["device"] or "",
            "laterality": ex["laterality"] or "",
            "canonical_exercise_id": ex["canonical_exercise_id"] or "",
            "variation_id": ex["variation_id"] or "",
            "execution_mode": ex["execution_mode"] or "",
            "notes": merge_exercise_notes(ex["notes"], sets),
            "sets": sets
        })

    workout_payload = dict(workout)
    normalized_text = normalized_training_text(exercises)
    if not str(workout_payload.get("raw_import_text") or "").strip():
        workout_payload["raw_import_text"] = normalized_text
        workout_payload["source_text_origin"] = "normalized_from_structured_data"
    else:
        workout_payload["source_text_origin"] = "persisted_raw_text"
    workout_payload["normalized_training_text"] = normalized_text
    reference_items = build_last_slot_reference_items(
        conn,
        date_iso=str(workout_payload.get("date_iso") or ""),
        session_name=str(workout_payload.get("name") or ""),
        exercises=exercises,
    )
    for item in reference_items:
        ex_idx = item.get("exercise_index")
        set_idx = item.get("set_index")
        if not isinstance(ex_idx, int) or not isinstance(set_idx, int):
            continue
        if ex_idx < 0 or ex_idx >= len(exercises):
            continue
        exercise_sets = exercises[ex_idx].get("sets") or []
        if set_idx < 0 or set_idx >= len(exercise_sets):
            continue
        exercise_sets[set_idx].update({
            "last_ref": item.get("ref"),
            "last_reason": item.get("reason"),
            "last_status": item.get("status"),
            "last_reason_code": item.get("reason_code"),
            "last_reason_text": item.get("reason_text"),
        })
    progress = compute_session_progress(conn, workout_id)
    conn.close()

    return jsonify(
        success=True,
        workout=workout_payload,
        exercises=exercises,
        progress=progress,
        rule_version=(progress or {}).get("rule_version"),
    )


@app.get("/api/training/plan_context")
def api_training_plan_context():
    plan_id_raw = request.args.get("plan_id")
    if not plan_id_raw:
        return jsonify({"ok": False, "error": "missing_plan_id"}), 400
    try:
        plan_id = int(plan_id_raw)
    except ValueError:
        return jsonify({"ok": False, "error": "invalid_plan_id"}), 400
    session_name = request.args.get("session_name")
    plan_context = load_plan_context(plan_id, session_name)
    if not plan_context:
        return jsonify({"ok": False, "error": "not_found"}), 404
    return jsonify({"ok": True, "plan_context": plan_context})


@app.get("/api/training/exercise_history")
def api_training_exercise_history():
    exercise_id = request.args.get("exercise_id")
    exercise_name = request.args.get("name")
    variation = (request.args.get("variation") or "").strip()

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        if exercise_id:
            try:
                exercise_id_val = int(exercise_id)
            except ValueError:
                return jsonify({"ok": False, "error": "invalid_exercise_id"}), 400
            row = conn.execute("SELECT name FROM exercises WHERE id = ?", (exercise_id_val,)).fetchone()
            if not row:
                return jsonify({"ok": False, "error": "not_found"}), 404
            exercise_name = row["name"]

        if not exercise_name:
            return jsonify({"ok": False, "error": "missing_exercise_name"}), 400

        snapshot = variation_history_snapshot(conn, exercise_name, variation)
        return jsonify({
            "ok": True,
            "exercise": exercise_name,
            "variation": variation,
            "history": snapshot["history"],
            "stats": snapshot["stats"],
            "typical_range": snapshot["typical_range"],
            "last_exposure": snapshot["last_exposure"],
        })
    finally:
        conn.close()


@app.post("/api/training/validate_draft")
def api_training_validate_draft():
    payload = request.get_json(force=True) or {}
    session_info = payload.get("session") or {}
    structured = payload.get("draft") or {}
    raw_text = payload.get("raw_text") or ""
    thresholds = payload.get("thresholds") or {}

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        result = validate_draft(
            conn,
            session_info=session_info,
            structured=structured,
            raw_text=raw_text,
            thresholds=thresholds,
        )
        return jsonify(result)
    finally:
        conn.close()


@app.get("/api/workout/<int:workout_id>/plan_check")
def api_workout_plan_check(workout_id):
    recompute = request.args.get("recompute") == "1"
    debug = recompute or os.getenv("LIVA_DEBUG_PLAN_CHECK", "0") == "1"
    report = None if recompute else load_plan_check_report(workout_id)
    if report and report.get("version") != PLAN_CHECK_VERSION:
        report = None
    if not report:
        report = build_plan_check_for_workout(workout_id, debug=debug)
        save_plan_check_report(report)
    if not report:
        return jsonify({"ok": False, "error": "not_found"}), 404
    return jsonify(report)



@app.route("/api/workout/delete/<int:workout_id>", methods=["DELETE"])
def delete_workout(workout_id):
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        workout = cur.execute(
            "SELECT id, date_iso, name FROM workouts WHERE id=?",
            (workout_id,),
        ).fetchone()
        if not workout:
            return jsonify(success=False, message="Training nicht gefunden."), 404

        set_count = cur.execute(
            "SELECT COUNT(*) AS c FROM sets WHERE workout_id=?",
            (workout_id,),
        ).fetchone()["c"]
        exercise_count = cur.execute(
            "SELECT COUNT(*) AS c FROM exercises WHERE workout_id=?",
            (workout_id,),
        ).fetchone()["c"]

        conn.execute("BEGIN")
        cur.execute("DELETE FROM training_pr_notice WHERE workout_id=?", (workout_id,))
        cur.execute("DELETE FROM plan_checks WHERE workout_id=?", (workout_id,))
        cur.execute("DELETE FROM sets WHERE workout_id=?", (workout_id,))
        cur.execute("DELETE FROM exercises WHERE workout_id=?", (workout_id,))
        cur.execute("DELETE FROM workouts WHERE id=?", (workout_id,))
        deleted_workouts = int(cur.rowcount or 0)
        conn.commit()

        touch_last_update()
        invalidate_snapshot("training_snapshot")
        invalidate_snapshot_prefix("dashboard_snapshot:")
        invalidate_snapshot_prefix("today_snapshot:")
        invalidate_snapshot_prefix("next_session_snapshot:")
        _core_invalidate_dashboard_caches(str(workout["date_iso"] or "")[:10])
        return jsonify(
            success=deleted_workouts > 0,
            workout_id=workout_id,
            deleted_workouts=deleted_workouts,
            deleted_exercises=int(exercise_count or 0),
            deleted_sets=int(set_count or 0),
            deleted_name=workout["name"],
            deleted_date_iso=workout["date_iso"],
        )
    except Exception as e:
        conn.rollback()
        return jsonify(success=False, message=f"Löschen fehlgeschlagen: {e}"), 500
    finally:
        conn.close()


