@app.route("/api/mvps_timeseries")
def api_mvps():
    conn = get_training_db()
    legacy = request.args.get("legacy") == "1"
    debug = request.args.get("debug") == "1"
    if legacy:
        rows = compute_mvps_timeseries(conn, debug=debug)
        conn.close()
        return jsonify(rows)
    version = (request.args.get("version") or "").strip().lower()
    if version in ("supercomp_v3", "v3"):
        components = request.args.get("components") == "1"
        markers = request.args.get("markers") == "1"
        payload = compute_supercomp_payload(conn, components=components, markers=markers, debug=debug)
    else:
        payload = compute_supercomp_v4_payload(conn, debug=debug)
    conn.close()
    return jsonify(payload)


@app.get("/api/training/response")
def api_training_response():
    start_iso = (request.args.get("start") or "").strip() or None
    end_iso = (request.args.get("end") or "").strip() or None
    for value, error in ((start_iso, "invalid_start_date"), (end_iso, "invalid_end_date")):
        if not value:
            continue
        try:
            date.fromisoformat(value[:10])
        except ValueError:
            return jsonify({"ok": False, "error": error}), 400
    if start_iso and end_iso and start_iso[:10] > end_iso[:10]:
        return jsonify({"ok": False, "error": "invalid_date_range"}), 400
    conn = get_training_db()
    try:
        payload = compute_training_response_payload(conn, end_iso=end_iso)
    finally:
        conn.close()
    days_raw = (request.args.get("days") or "all").strip().lower()
    if start_iso:
        range_start = start_iso[:10]
        dates = list(payload.get("dates") or [])
        start_index = next((index for index, value in enumerate(dates) if str(value)[:10] >= range_start), len(dates))
        visible_dates = dates[start_index:]
        visible_set = set(visible_dates)
        payload["dates"] = visible_dates
        for scope in (payload.get("scopes") or {}).values():
            for key in ("load", "performance", "performance_trend", "potential"):
                if isinstance(scope.get(key), list):
                    scope[key] = scope[key][start_index:]
            for key in ("load_details", "performance_details"):
                if isinstance(scope.get(key), dict):
                    scope[key] = {day: value for day, value in scope[key].items() if day in visible_set}
        payload.setdefault("meta", {})["range_days"] = len(visible_dates)
        payload["meta"]["range_start"] = range_start
        payload["meta"]["range_end"] = end_iso[:10] if end_iso else (visible_dates[-1] if visible_dates else None)
    elif days_raw != "all":
        days = _clamp_int(days_raw, 1, 3650, 180)
        dates = list(payload.get("dates") or [])
        if dates:
            range_end = date.fromisoformat(str(dates[-1])[:10])
            range_start = (range_end - timedelta(days=days - 1)).isoformat()
            start_index = next((index for index, value in enumerate(dates) if str(value)[:10] >= range_start), len(dates))
            visible_dates = dates[start_index:]
            visible_set = set(visible_dates)
            payload["dates"] = visible_dates
            for scope in (payload.get("scopes") or {}).values():
                for key in ("load", "performance", "performance_trend", "potential"):
                    if isinstance(scope.get(key), list):
                        scope[key] = scope[key][start_index:]
                for key in ("load_details", "performance_details"):
                    if isinstance(scope.get(key), dict):
                        scope[key] = {day: value for day, value in scope[key].items() if day in visible_set}
            payload.setdefault("meta", {})["range_days"] = days
            payload["meta"]["range_start"] = range_start
            payload["meta"]["range_end"] = visible_dates[-1] if visible_dates else None
    else:
        payload.setdefault("meta", {})["range_days"] = "all"
    return jsonify(payload)


@app.get("/api/training/last_exposure")
def api_training_last_exposure():
    name = (request.args.get("name") or "").strip()
    variation = (request.args.get("variation") or "").strip()
    before = (request.args.get("before") or "").strip()
    session_name = (request.args.get("session_name") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "missing_name"}), 400
    if not before:
        return jsonify({"ok": False, "error": "missing_before"}), 400

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            """
            SELECT e.id AS exercise_id, w.date_iso AS date_iso
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
              AND LOWER(TRIM(COALESCE(e.variation, ''))) = LOWER(TRIM(?))
              AND w.date_iso < ?
              AND (LOWER(TRIM(w.name)) = LOWER(TRIM(?)) OR ? = '')
            ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
            LIMIT 1
            """,
            (name, variation, before, session_name, session_name),
        ).fetchone()
        if not row:
            return jsonify({"ok": True, "sets": []})

        sets = conn.execute(
            """
            SELECT set_number, reps, weight, rpe
            FROM sets
            WHERE exercise_id = ?
            ORDER BY set_number
            """,
            (row["exercise_id"],),
        ).fetchall()
        return jsonify({
            "ok": True,
            "exercise_id": row["exercise_id"],
            "date_iso": row["date_iso"],
            "sets": [dict(s) for s in sets],
        })
    finally:
        conn.close()


def _select_last_exercise_row(
    conn: sqlite3.Connection,
    *,
    exercise_name: str,
    before_date: str,
    session_name: str | None,
) -> sqlite3.Row | None:
    name = exercise_name.strip()
    if not name or not before_date:
        return None
    session_name = (session_name or "").strip()
    params = [name, before_date]
    session_clause = ""
    if session_name:
        session_clause = "AND LOWER(TRIM(w.name)) = LOWER(TRIM(?))"
        params.append(session_name)
    row = conn.execute(
        f"""
        SELECT e.id AS exercise_id, e.variation AS variation, w.id AS workout_id, w.date_iso AS date_iso, w.name AS session_name
        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
          AND w.date_iso < ?
          {session_clause}
        ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
        LIMIT 1
        """,
        params,
    ).fetchone()
    return row


def _fetch_sets_for_exercise(conn: sqlite3.Connection, exercise_id: int) -> list[dict]:
    rows = conn.execute(
        """
        SELECT id, set_number, reps, weight, rpe
        FROM sets
        WHERE exercise_id = ?
        ORDER BY COALESCE(set_number, 0) ASC, id ASC
        """,
        (exercise_id,),
    ).fetchall()
    return [dict(r) for r in rows]

def row_get(row, key, default=None):
    if row is None:
        return default
    try:
        val = row[key]
        return default if val is None else val
    except Exception:
        return default


def _select_set_by_index(sets: list[dict], set_index: int) -> dict | None:
    if set_index < 0 or set_index >= len(sets):
        return None
    return sets[set_index]


def get_last_slot_reference(
    conn: sqlite3.Connection,
    *,
    date_iso: str,
    session_name: str,
    exercise_name: str,
    set_index: int,
    role: str | None = None,
    variation: str | None = None,
) -> dict:
    if not exercise_name or set_index is None:
        return {"ref": None, "reason": "none"}

    # Stage A/B: same session_name + exercise_name, slot match
    row = _select_last_exercise_row(
        conn,
        exercise_name=exercise_name,
        before_date=date_iso,
        session_name=session_name,
    )
    if row:
        sets = _fetch_sets_for_exercise(conn, row["exercise_id"])
        ref = _select_set_by_index(sets, set_index)
        if ref:
            reason = "slot_match"
            return {
                "ref": {
                    "reps": ref.get("reps"),
                    "weight": ref.get("weight"),
                    "rpe": ref.get("rpe"),
                    "set_id": ref.get("id"),
                    "set_number": ref.get("set_number"),
                    "exercise_id": row_get(row, "exercise_id"),
                    "workout_id": row_get(row, "workout_id"),
                    "date_iso": row_get(row, "date_iso", "") or "",
                    "session_name": row_get(row, "session_name", "") or "",
                    "variation": row_get(row, "variation", "") or "",
                },
                "reason": reason,
            }

    # Stage C: fallback to last session of same exercise name (any session_name)
    row_any = _select_last_exercise_row(
        conn,
        exercise_name=exercise_name,
        before_date=date_iso,
        session_name="",
    )
    if row_any:
        sets = _fetch_sets_for_exercise(conn, row_any["exercise_id"])
        ref = _select_set_by_index(sets, set_index)
        if ref:
            reason = "fallback_exercise_last"
            return {
                "ref": {
                    "reps": ref.get("reps"),
                    "weight": ref.get("weight"),
                    "rpe": ref.get("rpe"),
                    "set_id": ref.get("id"),
                    "set_number": ref.get("set_number"),
                    "exercise_id": row_get(row_any, "exercise_id"),
                    "workout_id": row_get(row_any, "workout_id"),
                    "date_iso": row_get(row_any, "date_iso", "") or "",
                    "session_name": row_get(row_any, "session_name", "") or "",
                    "variation": row_get(row_any, "variation", "") or "",
                },
                "reason": reason,
            }

    return {"ref": None, "reason": "none"}


def build_last_slot_reference_items(
    conn: sqlite3.Connection,
    *,
    date_iso: str,
    session_name: str,
    exercises: list[dict],
) -> list[dict]:
    """Build the set comparison payload shared by initial render and refreshes."""
    out: list[dict] = []
    for fallback_ex_idx, ex in enumerate(exercises):
        if not isinstance(ex, dict):
            continue
        ex_name = str(ex.get("exercise_name") or ex.get("name") or "").strip()
        ex_idx = ex.get("exercise_index", fallback_ex_idx)
        variation_default = str(ex.get("variation") or "").strip()
        sets = ex.get("sets") or []
        if not isinstance(sets, list):
            continue
        for fallback_set_idx, set_payload in enumerate(sets):
            if not isinstance(set_payload, dict):
                continue
            try:
                set_idx = int(set_payload.get("set_index", fallback_set_idx))
            except (TypeError, ValueError):
                continue
            role = str(set_payload.get("role") or "").strip()
            variation = str(set_payload.get("variation") or variation_default).strip()
            if bool(set_payload.get("progression_excluded")):
                out.append({
                    "exercise_name": ex_name,
                    "exercise_index": ex_idx,
                    "set_index": set_idx,
                    "ref": None,
                    "reason": "progression_excluded",
                    "status": None,
                    "comparable": False,
                    "progression_excluded": True,
                    "progression_exclusion_reason": str(
                        set_payload.get("progression_exclusion_reason") or ""
                    ).strip() or None,
                    "reason_code": "one_time_progression_exclusion",
                    "reason_text": str(
                        set_payload.get("progression_exclusion_reason")
                        or "Vom Coach einmalig als nicht vergleichbar markiert."
                    ).strip(),
                })
                continue
            ref_payload = get_last_slot_reference(
                conn,
                date_iso=date_iso,
                session_name=session_name,
                exercise_name=ex_name,
                set_index=set_idx,
                role=role,
                variation=variation,
            )
            item = {
                "exercise_name": ex_name,
                "exercise_index": ex_idx,
                "set_index": set_idx,
                "ref": ref_payload.get("ref"),
                "reason": ref_payload.get("reason"),
            }
            ref = ref_payload.get("ref")
            if isinstance(ref, dict):
                current = normalize_set_performance({
                    "exercise_name": ex_name,
                    "variation": variation,
                    "session_name": session_name,
                    "set_number": set_payload.get("set_number") if set_payload.get("set_number") is not None else set_idx + 1,
                    "weight": set_payload.get("weight"),
                    "reps": set_payload.get("reps"),
                    "rpe": set_payload.get("rpe"),
                    "tb_type": role if role in {"T", "B"} else None,
                    "tb_slot": set_idx + 1,
                }) or SetPerformance()
                reference = normalize_set_performance({
                    **ref,
                    "exercise_name": ex_name,
                    "variation": ref.get("variation") or variation,
                    "session_name": ref.get("session_name") or "",
                    "tb_type": role if role in {"T", "B"} else None,
                    "tb_slot": set_idx + 1,
                })
                comparison = compare_set_progress(
                    current,
                    reference,
                    match_level=str(ref_payload.get("reason") or "last_slot_reference"),
                )
                item.update({
                    "status": comparison.status,
                    "comparable": comparison.comparable,
                    "reason_code": comparison.reason_code,
                    "reason_text": comparison.reason_text,
                    "deltas": comparison.deltas,
                })
            out.append(item)
    return out


@app.post("/api/training/last-slot-references")
def api_training_last_slot_references():
    try:
        payload = request.get_json(force=True) or {}
        date_iso = (payload.get("date_iso") or "").strip()
        session_name = (payload.get("session_name") or "").strip()
        exercises = payload.get("exercises") or []
        if not date_iso:
            return jsonify({"ok": False, "error": "missing_date"}), 400
        if not isinstance(exercises, list):
            return jsonify({"ok": False, "error": "invalid_exercises"}), 400

        conn = get_training_db()
        conn.row_factory = sqlite3.Row
        try:
            out = build_last_slot_reference_items(
                conn,
                date_iso=date_iso,
                session_name=session_name,
                exercises=exercises,
            )
            return jsonify({"ok": True, "refs": out})
        finally:
            conn.close()
    except Exception as e:
        print("LAST_SLOT_ERROR:", e)
        print(traceback.format_exc())
        return jsonify({"ok": False, "error": str(e)}), 500


_variation_resolve_cache: dict[str, dict] = {}
_variation_resolve_cache_ts: dict[str, float] = {}
_variation_resolve_cache_ttl = 45.0


def _resolve_variation_cache_key(
    date_iso: str,
    session_name: str,
    exercise_name: str,
    role: str | None,
    weight_anchor: float | None,
) -> str:
    weight_key = ""
    if weight_anchor is not None and math.isfinite(weight_anchor):
        weight_key = f"{weight_anchor:.2f}"
    return (
        f"{date_iso}||{session_name.lower().strip()}||{exercise_name.lower().strip()}||"
        f"{(role or '').strip()}||{weight_key}"
    )


def _variation_history_mode(
    conn: sqlite3.Connection,
    *,
    exercise_name: str,
    before_date: str,
    limit: int = 10,
) -> dict:
    rows = conn.execute(
        """
        SELECT e.variation AS variation
        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
          AND w.date_iso <= ?
        ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
        LIMIT ?
        """,
        (exercise_name, before_date, limit),
    ).fetchall()
    variations = []
    for r in rows:
        v = (r["variation"] or "").strip()
        if v:
            variations.append(v)
    if not variations:
        return {"mode": "", "count": 0, "share": 0.0}
    normalized = [v.strip().lower() for v in variations]
    counts = Counter(normalized)
    mode_norm, mode_count = counts.most_common(1)[0]
    mode_value = ""
    for v in variations:
        if v.strip().lower() == mode_norm:
            mode_value = v
            break
    share = mode_count / max(len(normalized), 1)
    return {"mode": mode_value, "count": mode_count, "share": share}


def _variation_weight_anchor(payload: dict) -> float | None:
    sets = payload.get("sets")
    if not isinstance(sets, list):
        return None
    weights: list[float] = []
    for item in sets:
        if not isinstance(item, dict):
            continue
        raw = item.get("weight")
        if raw is None:
            continue
        try:
            w = float(raw)
        except (TypeError, ValueError):
            continue
        if math.isfinite(w) and w > 0:
            weights.append(w)
    if not weights:
        return None
    return max(weights)


def _median(values: list[float]) -> float | None:
    if not values:
        return None
    vals = sorted(values)
    n = len(vals)
    mid = n // 2
    if n % 2 == 1:
        return vals[mid]
    return (vals[mid - 1] + vals[mid]) / 2.0


def _variation_by_weight_similarity(
    conn: sqlite3.Connection,
    *,
    exercise_name: str,
    before_date: str,
    target_weight: float | None,
    limit_rows: int = 120,
    per_variation_cap: int = 8,
) -> dict:
    if target_weight is None or not math.isfinite(target_weight) or target_weight <= 0:
        return {"variation": "", "confidence": "low", "reason": "no_target_weight"}

    rows = conn.execute(
        """
        SELECT
            e.variation AS variation,
            MAX(CASE WHEN s.weight IS NOT NULL THEN s.weight ELSE 0 END) AS max_weight
        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        LEFT JOIN sets s ON s.exercise_id = e.id
        WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
          AND w.date_iso <= ?
          AND TRIM(COALESCE(e.variation, '')) <> ''
        GROUP BY e.id, e.variation, w.date_iso, w.id
        ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
        LIMIT ?
        """,
        (exercise_name, before_date, limit_rows),
    ).fetchall()

    if not rows:
        rows = conn.execute(
            """
            SELECT
                e.variation AS variation,
                MAX(CASE WHEN s.weight IS NOT NULL THEN s.weight ELSE 0 END) AS max_weight
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            LEFT JOIN sets s ON s.exercise_id = e.id
            WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
              AND TRIM(COALESCE(e.variation, '')) <> ''
            GROUP BY e.id, e.variation, w.date_iso, w.id
            ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
            LIMIT ?
            """,
            (exercise_name, limit_rows),
        ).fetchall()

    by_variation: dict[str, list[float]] = defaultdict(list)
    for row in rows:
        variation = (row["variation"] or "").strip()
        if not variation:
            continue
        try:
            max_weight = float(row["max_weight"] or 0)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(max_weight) or max_weight <= 0:
            continue
        if len(by_variation[variation]) >= per_variation_cap:
            continue
        by_variation[variation].append(max_weight)

    scored: list[dict] = []
    for variation, weights in by_variation.items():
        med = _median(weights)
        if med is None or med <= 0:
            continue
        diff_ratio = abs(med - target_weight) / max(med, target_weight, 1.0)
        scored.append(
            {
                "variation": variation,
                "count": len(weights),
                "median_weight": med,
                "diff_ratio": diff_ratio,
            }
        )

    if not scored:
        return {"variation": "", "confidence": "low", "reason": "no_weight_history"}

    scored.sort(key=lambda item: (item["diff_ratio"], -item["count"]))
    best = scored[0]
    second = scored[1] if len(scored) > 1 else None

    confidence = "low"
    if best["count"] >= 3 and best["diff_ratio"] <= 0.12:
        confidence = "high"
        if second is not None and (second["diff_ratio"] - best["diff_ratio"]) < 0.04:
            confidence = "medium"
    elif best["count"] >= 2 and best["diff_ratio"] <= 0.20:
        confidence = "medium"

    return {
        "variation": best["variation"],
        "confidence": confidence,
        "reason": "closest_weight",
    }


@app.post("/api/training/resolve-variation")
def api_training_resolve_variation():
    payload = request.get_json(force=True) or {}
    date_iso = (payload.get("date_iso") or "").strip()
    session_name = (payload.get("session_name") or "").strip()
    exercise_name = (payload.get("exercise_name") or "").strip()
    role = (payload.get("role") or "").strip()
    if not date_iso or not exercise_name:
        return jsonify({"variation": "", "confidence": "low", "source": "none", "note": None})

    weight_anchor = _variation_weight_anchor(payload)
    cache_key = _resolve_variation_cache_key(date_iso, session_name, exercise_name, role, weight_anchor)
    now_ts = time()
    if cache_key in _variation_resolve_cache:
        age = now_ts - _variation_resolve_cache_ts.get(cache_key, 0)
        if age <= _variation_resolve_cache_ttl:
            return jsonify(_variation_resolve_cache[cache_key])

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        weight_pick = _variation_by_weight_similarity(
            conn,
            exercise_name=exercise_name,
            before_date=date_iso,
            target_weight=weight_anchor,
        )
        hist = _variation_history_mode(conn, exercise_name=exercise_name, before_date=date_iso)
        mode = hist.get("mode") or ""
        mode_count = hist.get("count") or 0
        mode_share = hist.get("share") or 0.0
        response = {"variation": "", "confidence": "low", "source": "none", "note": None}

        if weight_pick.get("variation"):
            response = {
                "variation": weight_pick["variation"],
                "confidence": weight_pick.get("confidence") or "medium",
                "source": "weight_history",
                "note": None,
            }
        else:
            if mode and mode_share >= 0.7 and mode_count >= 2:
                response = {"variation": mode, "confidence": "medium", "source": "history", "note": None}
            else:
                response = {"variation": "", "confidence": "low", "source": "none", "note": None}
        _variation_resolve_cache[cache_key] = response
        _variation_resolve_cache_ts[cache_key] = now_ts
        return jsonify(response)
    finally:
        conn.close()


@app.route("/api/exercise_last_stats_strict")
def exercise_last_stats_strict():
    name = request.args.get("name", "").strip()
    variation = request.args.get("variation", "").strip()
    session_name = request.args.get("session_name", "").strip()
    date_iso = request.args.get("date_iso", "").strip()
    workout_id_param = request.args.get("workout_id", "").strip()
    sets_count_param = request.args.get("sets_count", "").strip()
    debug = os.getenv("LIVA_DEBUG_LAST_STATS", "0") == "1"

    if not name or not date_iso:
        return jsonify(found=False)

    name_norm = name.strip().lower()
    variation_norm = variation.strip().lower()
    session_norm = session_name.strip().lower()

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    exercise_id = None
    last_workout_id = None
    last_date_iso = None

    # ============================================================
    # LATEST EXERCISE OCCURRENCE (name + optional variation)
    # ============================================================
    cutoff_clause = "w.date_iso <= ?"
    cutoff_params = [date_iso]
    where_parts = [
        cutoff_clause,
        "LOWER(TRIM(e.name)) = ?",
        "LOWER(TRIM(COALESCE(e.variation, ''))) = ?",
    ]
    params = [*cutoff_params, name_norm, variation_norm]

    if session_norm:
        where_parts.append("LOWER(TRIM(w.name)) = ?")
        params.append(session_norm)

    workout_id = None
    if workout_id_param:
        try:
            workout_id = int(workout_id_param)
        except Exception:
            workout_id = None
    if workout_id is not None:
        where_parts.append("w.id != ?")
        params.append(workout_id)

    sets_count = None
    if sets_count_param:
        try:
            sets_count = int(sets_count_param)
        except Exception:
            sets_count = None

    where_sql = " AND ".join(where_parts)

    if sets_count is None:
        cur.execute(f"""
            SELECT e.id, w.id AS workout_id, w.date_iso
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            WHERE {where_sql}
            ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
            LIMIT 1
        """, params)
    else:
        cur.execute(f"""
            SELECT e.id, w.id AS workout_id, w.date_iso,
                   SUM(CASE WHEN s.weight IS NOT NULL THEN 1 ELSE 0 END) AS set_count
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            LEFT JOIN sets s ON s.exercise_id = e.id
            WHERE {where_sql}
            GROUP BY e.id, w.id, w.date_iso
            HAVING set_count = ?
            ORDER BY w.date_iso DESC, w.id DESC, e.id DESC
            LIMIT 1
        """, [*params, sets_count])
    row = cur.fetchone()
    if row:
        exercise_id = row["id"]
        last_workout_id = row["workout_id"]
        last_date_iso = row["date_iso"]

    # ============================================================
    # NICHTS GEFUNDEN
    # ============================================================
    if not exercise_id:
        conn.close()
        return jsonify(found=False)

    # ============================================================
    # SETS LADEN
    # ============================================================
    cur.execute("""
        SELECT reps, weight, rpe, set_number
        FROM sets
        WHERE exercise_id = ?
        ORDER BY set_number ASC, id ASC
    """, (exercise_id,))
    sets = cur.fetchall()

    conn.close()

    if not sets:
        return jsonify(found=False)

    # ============================================================
    # TEXT FORMATIEREN (exakt für dein JS)
    # ============================================================
    parts = []
    set_numbers = []
    for s in sets:
        if s["reps"] is None or s["weight"] is None:
            continue
        if s["set_number"] is not None:
            set_numbers.append(s["set_number"])

        txt = f"{int(s['reps'])} × {float(s['weight']):.1f}"
        if s["rpe"] is not None:
            txt += f" @ {float(s['rpe'])}"
        parts.append(txt)

    if not parts:
        return jsonify(found=False)

    payload = {
        "found": True,
        "text": "Zuletzt: " + " · ".join(parts)
    }
    if debug:
        payload["debug"] = {
            "workout_id": last_workout_id,
            "date_iso": last_date_iso,
            "sets_count": len(sets),
            "set_number_first": min(set_numbers) if set_numbers else None,
            "set_number_last": max(set_numbers) if set_numbers else None,
        }
        print("LAST_STATS_DEBUG:", payload["debug"])
    return jsonify(payload)



