@app.post("/api/remote/pc/wake")
@require_remote_access
def api_remote_pc_wake():
    wake_ts = _remote_mark_wake_attempt()
    wake_ok, wake_error = _remote_send_wake()
    if not wake_ok:
        status_code = 504 if wake_error == "wake_timeout" else 500
        app.logger.warning(
            "REMOTE wake api failed: host=%s interface=%s mac=%s error=%s",
            REMOTE_PC_HOST,
            REMOTE_PC_WAKE_INTERFACE,
            REMOTE_PC_WAKE_MAC,
            wake_error,
        )
        return jsonify(
            {
                "ok": False,
                "error": "wake_failed",
                "message": wake_error or "Wake-Befehl fehlgeschlagen.",
                "host": REMOTE_PC_HOST,
                "wake_interface": REMOTE_PC_WAKE_INTERFACE,
                "last_wake_attempt": _iso_utc(wake_ts),
            }
        ), status_code

    app.logger.info(
        "REMOTE wake api ok: host=%s interface=%s mac=%s wake_at=%s",
        REMOTE_PC_HOST,
        REMOTE_PC_WAKE_INTERFACE,
        REMOTE_PC_WAKE_MAC,
        _iso_utc(wake_ts),
    )
    invalidate_snapshot("remote_snapshot")
    return jsonify(
        {
            "ok": True,
            "status": "waking",
            "host": REMOTE_PC_HOST,
            "wake_interface": REMOTE_PC_WAKE_INTERFACE,
            "last_wake_attempt": _iso_utc(wake_ts),
            "checked_at": _iso_utc(_utc_now()),
        }
    )


