def api_remote_pc_status():
    payload = _remote_pc_status_payload()
    app.logger.info(
        "REMOTE status: status=%s host=%s rdp_open=%s host_reachable=%s listener_ping=%s wake_recent=%s checked_at=%s",
        payload.get("status"),
        payload.get("host"),
        payload.get("rdp_port_open"),
        payload.get("host_reachable"),
        payload.get("listener_ping"),
        _remote_recent_wake(),
        payload.get("checked_at"),
    )
    return jsonify(payload)


@app.post("/api/remote/pc/shutdown")
@require_remote_access
def api_remote_pc_shutdown():
    status_payload = _remote_pc_status_payload()
    if status_payload.get("status") == "offline":
        app.logger.info("REMOTE shutdown skipped: host=%s already offline", REMOTE_PC_HOST)
        return jsonify(
            {
                "ok": False,
                "code": "already_offline",
                "error": "already_offline",
                "message": "Windows-PC ist bereits offline.",
                "host": REMOTE_PC_HOST,
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 409

    if not REMOTE_PC_HTTP_TOKEN:
        app.logger.warning(
            "REMOTE shutdown blocked: token missing (expected env LIVA_REMOTE_PC_HTTP_TOKEN, host=%s)",
            REMOTE_PC_HOST,
        )
        return jsonify(
            {
                "ok": False,
                "code": "token_missing",
                "error": "token_missing",
                "message": "LIVA_REMOTE_PC_HTTP_TOKEN ist nicht gesetzt.",
                "host": REMOTE_PC_HOST,
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 400

    app.logger.info(
        "REMOTE shutdown start: url=%s",
        _remote_listener_log_url("/shutdown"),
    )
    ok, status_code, body_text = _remote_listener_call("/shutdown", timeout_seconds=2.2)
    if not ok:
        app.logger.warning(
            "REMOTE shutdown failed: url=%s error=%s",
            _remote_listener_log_url("/shutdown"),
            body_text,
        )
        return jsonify(
            {
                "ok": False,
                "code": "listener_unreachable",
                "error": "listener_unreachable",
                "message": f"Shutdown-Listener ist nicht erreichbar: {body_text}.",
                "host": REMOTE_PC_HOST,
                "control_port": REMOTE_PC_CONTROL_PORT,
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 503

    if status_code is None or not (200 <= int(status_code) < 300):
        app.logger.warning(
            "REMOTE shutdown bad status: url=%s http=%s body=%s",
            _remote_listener_log_url("/shutdown"),
            status_code,
            (body_text or "")[:240],
        )
        return jsonify(
            {
                "ok": False,
                "code": "shutdown_failed",
                "error": "shutdown_failed",
                "message": f"Shutdown-Listener antwortete mit HTTP {status_code}.",
                "host": REMOTE_PC_HOST,
                "control_port": REMOTE_PC_CONTROL_PORT,
                "listener_status_code": status_code,
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 502

    body_norm = (body_text or "").strip().lower()
    if "shutdown triggered" not in body_norm and "ok" not in body_norm:
        app.logger.warning(
            "REMOTE shutdown unexpected response: url=%s http=%s body=%s",
            _remote_listener_log_url("/shutdown"),
            status_code,
            (body_text or "")[:240],
        )
        return jsonify(
            {
                "ok": False,
                "code": "unexpected_response",
                "error": "unexpected_response",
                "message": "Shutdown-Listener lieferte keine erwartete Antwort.",
                "host": REMOTE_PC_HOST,
                "control_port": REMOTE_PC_CONTROL_PORT,
                "listener_status_code": status_code,
                "listener_body": (body_text or "")[:240],
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 502

    app.logger.info(
        "REMOTE shutdown ok: url=%s http=%s body=%s",
        _remote_listener_log_url("/shutdown"),
        status_code,
        (body_text or "")[:240],
    )
    invalidate_snapshot("remote_snapshot")
    return jsonify(
        {
            "ok": True,
            "code": "shutdown_triggered",
            "status": "shutting_down",
            "host": REMOTE_PC_HOST,
            "control_port": REMOTE_PC_CONTROL_PORT,
            "listener_status_code": status_code,
            "listener_body": (body_text or "")[:240],
            "checked_at": _iso_utc(_utc_now()),
        }
    )


def _remote_devices_payload() -> dict[str, Any]:
    from smart_home.config import GOVEE_DEVICES, TAPO_DEVICES, is_govee_enabled

    devices = []
    checked_at = _iso_utc(_utc_now())
    device_specs = [(str(device_name), "tapo") for device_name in TAPO_DEVICES]
    if is_govee_enabled():
        device_specs.extend((str(device_name), "govee") for device_name in GOVEE_DEVICES)
    live_states = _remote_fetch_live_device_states(device_specs)

    for device_name, cfg in TAPO_DEVICES.items():
        alias = str((cfg or {}).get("alias") or device_name)
        cached = _remote_device_get_cached_state(device_name) or {}
        live = live_states.get(str(device_name))
        live_is_on = _remote_device_live_is_on(live)
        if isinstance(live_is_on, bool):
            _remote_device_set_cached_state(device_name, is_on=live_is_on, reachable=True, error=None)
            cached = _remote_device_get_cached_state(device_name) or cached
        row = {
            "id": str(device_name),
            "alias": alias,
            "is_on": cached.get("is_on"),
            "reachable": bool(cached.get("reachable", True)),
            "updated_at": cached.get("updated_at"),
        }
        if isinstance(cached.get("last_brightness"), int):
            row["last_brightness"] = int(cached.get("last_brightness"))
        if isinstance(cached.get("pending_brightness"), int):
            row["pending_brightness"] = int(cached.get("pending_brightness"))
        if isinstance(cached.get("last_color"), dict):
            row["last_color"] = dict(cached.get("last_color"))
        if isinstance(cached.get("pending_color"), dict):
            row["pending_color"] = dict(cached.get("pending_color"))
        if cached.get("error"):
            row["error"] = str(cached.get("error"))
        devices.append(row)

    if is_govee_enabled():
        for device_name, cfg in GOVEE_DEVICES.items():
            alias = str((cfg or {}).get("alias") or device_name)
            cached = _remote_device_get_cached_state(device_name) or {}
            live = live_states.get(str(device_name))

            if isinstance(live, dict) and live.get("ok"):
                live_is_on = _remote_device_live_is_on(live)
                if isinstance(live_is_on, bool):
                    _remote_device_set_cached_state(device_name, is_on=live_is_on, reachable=True, error=None)
                extras: dict[str, Any] = {}
                if isinstance(live.get("brightness"), int):
                    extras["last_brightness"] = int(live.get("brightness"))
                if isinstance(live.get("color"), dict):
                    extras["last_color"] = dict(live.get("color"))
                if extras:
                    _remote_device_set_cached_extras(device_name, extras)
                cached = _remote_device_get_cached_state(device_name) or cached

            row = {
                "id": str(device_name),
                "alias": alias,
                "is_on": cached.get("is_on"),
                "reachable": bool(cached.get("reachable", True)),
                "updated_at": cached.get("updated_at"),
            }
            if isinstance(cached.get("last_brightness"), int):
                row["last_brightness"] = int(cached.get("last_brightness"))
            if isinstance(cached.get("pending_brightness"), int):
                row["pending_brightness"] = int(cached.get("pending_brightness"))
            if isinstance(cached.get("last_color"), dict):
                row["last_color"] = dict(cached.get("last_color"))
            if isinstance(cached.get("pending_color"), dict):
                row["pending_color"] = dict(cached.get("pending_color"))
            if cached.get("error"):
                row["error"] = str(cached.get("error"))
            devices.append(row)

    devices.sort(key=lambda d: d.get("alias", "").lower())
    return {"ok": True, "devices": devices, "checked_at": checked_at}


@app.get("/api/remote/devices")
@require_remote_access
def api_remote_devices():
    return jsonify(_remote_devices_payload())


def _build_remote_page_snapshot() -> dict[str, Any]:
    status_payload = _remote_pc_status_payload()
    devices_payload = _remote_devices_payload()
    return {
        "ok": True,
        "status": status_payload,
        "devices": (devices_payload or {}).get("devices") or [],
        "checked_at": (devices_payload or {}).get("checked_at") or status_payload.get("checked_at"),
        "partial": False,
    }


@app.get("/api/remote_snapshot")
@require_remote_access
def api_remote_snapshot():
    payload = get_snapshot(
        "remote_snapshot",
        builder=_build_remote_page_snapshot,
        ttl_seconds=_SNAPSHOT_TTLS["remote_snapshot"],
        allow_stale=True,
        background_refresh=True,
        meta={"route": "/api/remote_snapshot"},
    )
    return _snapshot_json_response(payload, max_age=3)


@app.post("/api/remote/devices/<device_name>/<action>")
@require_remote_access
def api_remote_device_action(device_name: str, action: str):
    from smart_home.config import GOVEE_DEVICES, TAPO_DEVICES, is_govee_enabled

    dev = (device_name or "").strip()
    act = (action or "").strip().lower()

    driver = None
    if dev in TAPO_DEVICES:
        driver = "tapo"
    elif is_govee_enabled() and dev in GOVEE_DEVICES:
        driver = "govee"
    else:
        return jsonify({"ok": False, "error": "device_not_found", "device": dev}), 404

    if act not in {"on", "off"}:
        return jsonify({"ok": False, "error": "invalid_action", "action": act}), 400

    try:
        if driver == "tapo":
            from smart_home.service import turn_off, turn_on
            if act == "on":
                result = turn_on(dev)
                _remote_device_set_cached_state(dev, is_on=True, reachable=True)
            else:
                result = turn_off(dev)
                _remote_device_set_cached_state(dev, is_on=False, reachable=True)
        else:
            if not is_govee_enabled():
                return jsonify({"ok": False, "error": "device_disabled", "device": dev, "driver": "govee"}), 409
            from smart_home.govee import set_brightness as govee_set_brightness
            from smart_home.govee import set_color_rgb as govee_set_color_rgb
            from smart_home.govee import turn_off, turn_on
            cached_before = _remote_device_get_cached_state(dev) or {}
            if act == "on":
                result = turn_on(dev)
                _remote_device_set_cached_state(dev, is_on=True, reachable=True)
                pending_brightness = cached_before.get("pending_brightness")
                pending_color = cached_before.get("pending_color")
                applied_brightness = None
                applied_color = None
                if isinstance(pending_brightness, int):
                    try:
                        govee_set_brightness(dev, int(pending_brightness))
                        applied_brightness = int(pending_brightness)
                    except Exception:
                        pass
                if isinstance(pending_color, dict):
                    try:
                        pr = int(pending_color.get("r"))
                        pg = int(pending_color.get("g"))
                        pb = int(pending_color.get("b"))
                        govee_set_color_rgb(dev, pr, pg, pb)
                        applied_color = {"r": max(0, min(255, pr)), "g": max(0, min(255, pg)), "b": max(0, min(255, pb))}
                    except Exception:
                        pass
                _remote_device_set_cached_extras(
                    dev,
                    {
                        "pending_brightness": None,
                        "pending_color": None,
                        "last_brightness": applied_brightness if isinstance(applied_brightness, int) else cached_before.get("last_brightness"),
                        "last_color": applied_color if isinstance(applied_color, dict) else cached_before.get("last_color"),
                    },
                )
            else:
                result = turn_off(dev)
                _remote_device_set_cached_state(dev, is_on=False, reachable=True)
    except Exception as exc:
        _remote_device_set_cached_state(dev, is_on=None, reachable=False, error=str(exc))
        return jsonify({
            "ok": False,
            "error": "switch_failed",
            "device": dev,
            "driver": driver,
            "action": act,
            "detail": str(exc),
        }), 502

    invalidate_snapshot("remote_snapshot")
    return jsonify({
        "ok": True,
        "device": dev,
        "driver": driver,
        "action": act,
        "result": result,
        "state": _remote_device_get_cached_state(dev),
        "checked_at": _iso_utc(_utc_now()),
    })


@app.post("/api/remote/devices/<device_name>/brightness")
@require_remote_access
def api_remote_device_brightness(device_name: str):
    from smart_home.config import GOVEE_DEVICES, is_govee_enabled

    dev = (device_name or "").strip()
    if not is_govee_enabled():
        return jsonify({"ok": False, "error": "device_disabled", "device": dev, "driver": "govee"}), 409
    if dev not in GOVEE_DEVICES:
        return jsonify({"ok": False, "error": "device_not_found", "device": dev}), 404

    payload = request.get_json(silent=True) or {}
    try:
        brightness = int(payload.get("brightness"))
    except Exception:
        return jsonify({"ok": False, "error": "invalid_brightness"}), 400
    if brightness < 1 or brightness > 100:
        return jsonify({"ok": False, "error": "invalid_brightness"}), 400

    current = _remote_device_get_cached_state(dev) or {}
    live_is_on: bool | None = None
    try:
        from smart_home.govee import get_state as govee_get_state
        live = govee_get_state(dev, timeout=0.45)
        if isinstance(live, dict) and isinstance(live.get("is_on"), bool):
            live_is_on = bool(live.get("is_on"))
            _remote_device_set_cached_state(dev, is_on=live_is_on, reachable=True, error=None)
            extras: dict[str, Any] = {}
            if isinstance(live.get("brightness"), int):
                extras["last_brightness"] = int(live.get("brightness"))
            if isinstance(live.get("color"), dict):
                extras["last_color"] = dict(live.get("color"))
            if extras:
                _remote_device_set_cached_extras(dev, extras)
            current = _remote_device_get_cached_state(dev) or current
    except Exception:
        live_is_on = None

    effective_on = live_is_on if isinstance(live_is_on, bool) else current.get("is_on")
    if effective_on is not True:
        _remote_device_set_cached_extras(dev, {"pending_brightness": brightness})
        return jsonify({
            "ok": True,
            "device": dev,
            "queued": True,
            "brightness": brightness,
            "message": "Gerät ist aus. Helligkeit wurde vorgemerkt und wird beim Einschalten angewendet.",
            "state": _remote_device_get_cached_state(dev),
            "checked_at": _iso_utc(_utc_now()),
        })

    try:
        from smart_home.govee import set_brightness
        result = set_brightness(dev, brightness)
        is_on_val = current.get("is_on")
        _remote_device_set_cached_state(
            dev,
            is_on=is_on_val if isinstance(is_on_val, bool) else None,
            reachable=True,
            error=None,
        )
        _remote_device_set_cached_extras(dev, {"last_brightness": brightness, "pending_brightness": None})
    except Exception as exc:
        _remote_device_set_cached_state(dev, is_on=None, reachable=False, error=str(exc))
        return jsonify({
            "ok": False,
            "error": "brightness_failed",
            "device": dev,
            "brightness": brightness,
            "detail": str(exc),
        }), 502

    invalidate_snapshot("remote_snapshot")
    return jsonify({
        "ok": True,
        "device": dev,
        "brightness": brightness,
        "result": result,
        "state": _remote_device_get_cached_state(dev),
        "checked_at": _iso_utc(_utc_now()),
    })


@app.post("/api/remote/devices/<device_name>/color")
@require_remote_access
def api_remote_device_color(device_name: str):
    from smart_home.config import GOVEE_DEVICES, is_govee_enabled

    dev = (device_name or "").strip()
    if not is_govee_enabled():
        return jsonify({"ok": False, "error": "device_disabled", "device": dev, "driver": "govee"}), 409
    if dev not in GOVEE_DEVICES:
        return jsonify({"ok": False, "error": "device_not_found", "device": dev}), 404

    payload = request.get_json(silent=True) or {}
    try:
        r = int(payload.get("r"))
        g = int(payload.get("g"))
        b = int(payload.get("b"))
    except Exception:
        return jsonify({"ok": False, "error": "invalid_rgb"}), 400

    if not (0 <= r <= 255 and 0 <= g <= 255 and 0 <= b <= 255):
        return jsonify({"ok": False, "error": "invalid_rgb"}), 400

    current = _remote_device_get_cached_state(dev) or {}
    live_is_on: bool | None = None
    try:
        from smart_home.govee import get_state as govee_get_state
        live = govee_get_state(dev, timeout=0.45)
        if isinstance(live, dict) and isinstance(live.get("is_on"), bool):
            live_is_on = bool(live.get("is_on"))
            _remote_device_set_cached_state(dev, is_on=live_is_on, reachable=True, error=None)
            extras: dict[str, Any] = {}
            if isinstance(live.get("brightness"), int):
                extras["last_brightness"] = int(live.get("brightness"))
            if isinstance(live.get("color"), dict):
                extras["last_color"] = dict(live.get("color"))
            if extras:
                _remote_device_set_cached_extras(dev, extras)
            current = _remote_device_get_cached_state(dev) or current
    except Exception:
        live_is_on = None

    effective_on = live_is_on if isinstance(live_is_on, bool) else current.get("is_on")
    if effective_on is not True:
        _remote_device_set_cached_extras(dev, {"pending_color": {"r": r, "g": g, "b": b}})
        return jsonify({
            "ok": True,
            "device": dev,
            "queued": True,
            "color": {"r": r, "g": g, "b": b},
            "message": "Gerät ist aus. Farbe wurde vorgemerkt und wird beim Einschalten angewendet.",
            "state": _remote_device_get_cached_state(dev),
            "checked_at": _iso_utc(_utc_now()),
        })

    try:
        from smart_home.govee import set_color_rgb
        result = set_color_rgb(dev, r, g, b)
        is_on_val = current.get("is_on")
        _remote_device_set_cached_state(
            dev,
            is_on=is_on_val if isinstance(is_on_val, bool) else None,
            reachable=True,
            error=None,
        )
        _remote_device_set_cached_extras(dev, {"last_color": {"r": r, "g": g, "b": b}, "pending_color": None})
    except Exception as exc:
        _remote_device_set_cached_state(dev, is_on=None, reachable=False, error=str(exc))
        return jsonify({
            "ok": False,
            "error": "color_failed",
            "device": dev,
            "r": r,
            "g": g,
            "b": b,
            "detail": str(exc),
        }), 502

    invalidate_snapshot("remote_snapshot")
    return jsonify({
        "ok": True,
        "device": dev,
        "color": {"r": r, "g": g, "b": b},
        "result": result,
        "state": _remote_device_get_cached_state(dev),
        "checked_at": _iso_utc(_utc_now()),
    })


@app.post("/api/remote/session/start")
@require_remote_access
def api_remote_session_start():
    now = _utc_now()
    _remote_sessions_cleanup(now)
    wake_ts = _remote_mark_wake_attempt()
    wake_ok, wake_error = _remote_send_wake()
    if not wake_ok:
        status_code = 504 if wake_error == "wake_timeout" else 500
        return jsonify(
            {
                "ok": False,
                "error": "wake_failed",
                "message": wake_error or "Wake-Befehl fehlgeschlagen.",
                "host": REMOTE_PC_HOST,
                "checked_at": _iso_utc(now),
            }
        ), status_code

    session_id = uuid.uuid4().hex
    with _remote_sessions_lock:
        _remote_sessions[session_id] = {
            "id": session_id,
            "created_at": now,
            "last_wake_attempt": wake_ts,
            "consumed": False,
        }

    return jsonify(
        {
            "ok": True,
            "session_id": session_id,
            "status": "booting",
            "host": REMOTE_PC_HOST,
            "shortcut_open_app": True,
            "checked_at": _iso_utc(now),
        }
    )


@app.get("/api/remote/session/<session_id>/status")
@require_remote_access
def api_remote_session_status(session_id: str):
    sid = (session_id or "").strip().lower()
    if not sid:
        return jsonify({"ok": False, "error": "session_id_missing"}), 400

    session_row = _remote_session_get(sid)
    if not session_row:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    payload = _remote_pc_status_payload()
    status = payload.get("status") or "offline"
    return jsonify(
        {
            "ok": True,
            "session_id": sid,
            "status": status,
            "host": REMOTE_PC_HOST,
            "rdp_port_open": bool(payload.get("rdp_port_open")),
            "checked_at": payload.get("checked_at"),
            "ready_to_open_remote_app": status == "ready",
            "consumed": bool(session_row.get("consumed")),
        }
    )


@app.post("/api/remote/session/<session_id>/consume")
@require_remote_access
def api_remote_session_consume(session_id: str):
    sid = (session_id or "").strip().lower()
    if not sid:
        return jsonify({"ok": False, "error": "session_id_missing"}), 400

    _remote_sessions_cleanup()
    with _remote_sessions_lock:
        session_row = _remote_sessions.get(sid)
        if not isinstance(session_row, dict):
            return jsonify({"ok": False, "error": "session_not_found"}), 404
        session_row["consumed"] = True
        session_row["consumed_at"] = _utc_now()
        _remote_sessions[sid] = session_row

    return jsonify(
        {
            "ok": True,
            "session_id": sid,
            "consumed": True,
            "checked_at": _iso_utc(_utc_now()),
        }
    )


_RUNS_SYNC_LOCK = threading.Lock()
_RUNS_SYNC_LAST_AT = 0.0
_RUNS_SYNC_MIN_INTERVAL_SECONDS = int(os.environ.get("LIVA_RUNS_SYNC_INTERVAL_SECONDS", "210"))


@app.route("/api/runs/sync", methods=["POST"])
@require_admin
def sync_runs():
    global _RUNS_SYNC_LAST_AT

    now = time()
    force = str(request.args.get("force") or "").strip().lower() in {"1", "true", "yes"}
    elapsed = now - _RUNS_SYNC_LAST_AT
    if not force and elapsed < _RUNS_SYNC_MIN_INTERVAL_SECONDS:
        return jsonify(
            {
                "success": True,
                "skipped": True,
                "reason": "throttled",
                "next_allowed_in_seconds": max(1, int(_RUNS_SYNC_MIN_INTERVAL_SECONDS - elapsed)),
                "checked_at": _iso_utc(_utc_now()),
            }
        )

    if not _RUNS_SYNC_LOCK.acquire(blocking=False):
        return jsonify(
            {
                "success": True,
                "skipped": True,
                "reason": "already_running",
                "checked_at": _iso_utc(_utc_now()),
            }
        )

    _RUNS_SYNC_LAST_AT = now
    try:
        sync_result = sync_garmin_to_database(blocking=False)
        if sync_result["skipped"]:
            return jsonify(
                {
                    "success": True,
                    "skipped": True,
                    "reason": sync_result["reason"],
                    "checked_at": _iso_utc(_utc_now()),
                }
            )
        invalidate_snapshot_prefix("dashboard_snapshot:")
        invalidate_snapshot_prefix("today_snapshot:")

        return jsonify(
            {
                "success": True,
                "skipped": False,
                "imported": sync_result["imported"],
                "checked_at": _iso_utc(_utc_now()),
            }
        )
    except GarminNotConfiguredError as exc:
        return jsonify(
            {
                "success": False,
                "error": {"code": "garmin_not_configured", "message": str(exc)},
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 503
    except Exception as exc:
        app.logger.exception("runs_sync_failed")
        return jsonify(
            {
                "success": False,
                "error": {
                    "code": "runs_sync_failed",
                    "message": str(exc),
                },
                "checked_at": _iso_utc(_utc_now()),
            }
        ), 500
    finally:
        _RUNS_SYNC_LOCK.release()

