def _active_plan_start_date_iso() -> str | None:
    """
    Best-effort: read start_date from the currently active plan.
    Falls back to parsing plan.data.meta.start_date because the DB column is optional/legacy.
    """
    row = _get_active_plan_row()
    if not row:
        return None

    try:
        start_date = row["start_date"]
        if isinstance(start_date, str) and start_date.strip():
            return start_date.strip()
    except Exception:
        pass

    try:
        data_raw = row["data"]
        if not isinstance(data_raw, str) or not data_raw.strip():
            return None
        data = json.loads(data_raw)
        meta = data.get("meta") if isinstance(data, dict) else None
        start_date = meta.get("start_date") if isinstance(meta, dict) else None
        if isinstance(start_date, str) and start_date.strip():
            return start_date.strip()
    except Exception:
        return None

    return None


def _export_default_range() -> tuple[date, date]:
    tz = ZoneInfo("Europe/Berlin")
    end_d = datetime.now(tz).date()

    start_iso = _active_plan_start_date_iso()
    start_d = _parse_iso(start_iso) if start_iso else None
    if not start_d:
        start_d = end_d - timedelta(days=30)
    return start_d, end_d


def _export_sort_key(record: dict):
    tz = ZoneInfo("Europe/Berlin")
    date_iso = (record.get("date") or "").strip()
    ts_iso = (record.get("ts") or "").strip()

    # primary: date (YYYY-MM-DD)
    if ts_iso:
        try:
            dt = datetime.fromisoformat(ts_iso)
        except Exception:
            dt = None
        if isinstance(dt, datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=tz)
            date_iso = dt.astimezone(tz).date().isoformat()
            time_key = dt.astimezone(tz).time()
            has_ts = 0
        else:
            time_key = datetime.min.time()
            has_ts = 1
    else:
        time_key = datetime.min.time()
        has_ts = 1

    if not date_iso:
        date_iso = "0001-01-01"

    type_key = str(record.get("type") or "")

    # deterministic fallback id:
    raw_id = (
        record.get("id")
        if record.get("id") is not None
        else record.get("session_id")
        if record.get("session_id") is not None
        else record.get("run_id")
        if record.get("run_id") is not None
        else ""
    )
    id_key = str(raw_id)

    # Spec (same date): timestamp if present -> else type -> else id
    # We choose a deterministic ordering for mixed "ts" vs date-only:
    # - ts records first (ordered by time), then date-only by type/id.
    return (date_iso, has_ts, time_key, type_key, id_key)


def export_records(start: date, end: date, include: list[str], limit: int = 3000) -> tuple[list[dict], bool]:
    tz = ZoneInfo("Europe/Berlin")
    include_set = {str(x).strip() for x in (include or []) if str(x).strip()}

    records: list[dict] = []

    start_iso = start.isoformat()
    end_iso = end.isoformat()

    # -----------------------------
    # HRV / HR (from HRV DB)
    # -----------------------------
    if "hrv_daily" in include_set or "hr_daily" in include_set:
        conn = get_hrv_db()
        conn.row_factory = sqlite3.Row
        cols = {row["name"] for row in conn.execute("PRAGMA table_info(hrv_measurements);").fetchall()}
        has_sickness_bool = "sickness_bool" in cols
        has_alcohol_bool = "alcohol_bool" in cols
        has_sickness_text = "sickness" in cols
        has_alcohol_text = "alcohol" in cols
        sickness_bool_expr = "sickness_bool" if has_sickness_bool else "0 AS sickness_bool"
        alcohol_bool_expr = "alcohol_bool" if has_alcohol_bool else "0 AS alcohol_bool"
        sickness_text_expr = "sickness" if has_sickness_text else "NULL AS sickness"
        alcohol_text_expr = "alcohol" if has_alcohol_text else "NULL AS alcohol"
        rows = conn.execute(
            f"""
            SELECT
              id,
              ts_measurement,
              hr,
              rmssd,
              sdnn,
              signal_quality,
              source_file,
              {sickness_bool_expr},
              {alcohol_bool_expr},
              {sickness_text_expr},
              {alcohol_text_expr}
            FROM hrv_measurements
            WHERE ts_measurement IS NOT NULL
              AND SUBSTR(ts_measurement, 1, 10) >= ?
              AND SUBSTR(ts_measurement, 1, 10) <= ?
            ORDER BY ts_measurement ASC, id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        conn.close()

        for r in rows:
            dt = _parse_hrv_timestamp(r["ts_measurement"])
            if not dt:
                continue
            dt_local = dt.astimezone(tz)
            ts_out = dt_local.replace(tzinfo=None).isoformat(timespec="seconds")
            is_sick = _export_flag_true(r["sickness_bool"], r["sickness"])
            has_alcohol = _export_flag_true(r["alcohol_bool"], r["alcohol"])
            hrv_flags: list[str] = []
            if is_sick:
                hrv_flags.append("sick")
            if has_alcohol:
                hrv_flags.append("alcohol")

            if "hrv_daily" in include_set:
                rec = {
                    "ts": ts_out,
                    "type": "hrv_daily",
                    "id": int(r["id"]),
                    "rmssd_ms": _to_optional_float(r["rmssd"]),
                    "sdnn_ms": _to_optional_float(r["sdnn"]),
                    "resting_hr_bpm": _to_optional_float(r["hr"]),
                    "signal_quality": (r["signal_quality"] if r["signal_quality"] is not None else None),
                    "source": (r["source_file"] if r["source_file"] is not None else None),
                }
                if hrv_flags:
                    rec["flags"] = hrv_flags
                records.append(rec)

            if "hr_daily" in include_set:
                records.append(
                    {
                        "ts": ts_out,
                        "type": "hr_daily",
                        "id": int(r["id"]),
                        "hr_bpm": _to_optional_float(r["hr"]),
                        "source": (r["source_file"] if r["source_file"] is not None else None),
                    }
                )

    # -----------------------------
    # Runs (Strava + manual)
    # -----------------------------
    if "run" in include_set:
        # Strava runs DB (distance is meters, pace is s/km, moving_time is seconds)
        runs_conn = get_runs_db()
        runs_conn.row_factory = sqlite3.Row
        run_rows = runs_conn.execute(
            """
            SELECT id, date, distance, moving_time, avg_speed, avg_hr, max_hr, elevation_gain, pace
            FROM runs
            WHERE date IS NOT NULL
              AND SUBSTR(date, 1, 10) >= ?
              AND SUBSTR(date, 1, 10) <= ?
            ORDER BY date ASC, id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        runs_conn.close()

        for r in run_rows:
            dt = _runs_parse_ts(r["date"])
            if not dt:
                continue
            dt_local = dt.astimezone(tz)
            ts_out = dt_local.replace(tzinfo=None).isoformat(timespec="seconds")

            dist_km = None
            if r["distance"] is not None:
                dist_km = _to_optional_float(r["distance"])
                if dist_km is not None:
                    dist_km = dist_km / 1000.0

            records.append(
                {
                    "ts": ts_out,
                    "type": "run",
                    "id": int(r["id"]),
                    "distance_km": dist_km,
                    "moving_time_s": int(r["moving_time"]) if r["moving_time"] is not None else None,
                    "avg_speed_m_s": _to_optional_float(r["avg_speed"]),
                    "pace_s_per_km": _to_optional_float(r["pace"]),
                    "avg_hr_bpm": _to_optional_float(r["avg_hr"]),
                    "max_hr_bpm": _to_optional_float(r["max_hr"]),
                    "elevation_gain_m": _to_optional_float(r["elevation_gain"]),
                    "source": "strava",
                }
            )

        # Manual runs inside training.sqlite3
        tr_conn = get_training_db()
        tr_conn.row_factory = sqlite3.Row
        tr_rows = tr_conn.execute(
            """
            SELECT id, date_iso, km, minutes
            FROM runs
            WHERE date_iso >= ? AND date_iso <= ?
            ORDER BY date_iso ASC, id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        tr_conn.close()

        for r in tr_rows:
            d = (r["date_iso"] or "").strip()
            if not d:
                continue
            records.append(
                {
                    "date": d,
                    "type": "run",
                    "id": int(r["id"]),
                    "distance_km": _to_optional_float(r["km"]),
                    "moving_time_s": int(float(r["minutes"]) * 60) if r["minutes"] is not None else None,
                    "source": "manual",
                }
            )

    # -----------------------------
    # Gym session summary
    # -----------------------------
    if "gym_session" in include_set:
        conn = get_training_db()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT
              w.id        AS session_id,
              w.date_iso  AS date_iso,
              w.name      AS title,
              w.session_key AS session_key,
              w.notes     AS notes,
              COUNT(s.id) AS set_count,
              SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage,
              AVG(CASE WHEN s.rpe IS NOT NULL THEN s.rpe END) AS avg_rpe
            FROM workouts w
            LEFT JOIN exercises e ON e.workout_id = w.id
            LEFT JOIN sets s ON s.exercise_id = e.id
            WHERE w.date_iso >= ? AND w.date_iso <= ?
            GROUP BY w.id
            ORDER BY w.date_iso ASC, w.id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        conn.close()

        for r in rows:
            d = (r["date_iso"] or "").strip()
            if not d:
                continue
            set_count = int(r["set_count"] or 0)
            tonnage = _to_optional_float(r["tonnage"])
            if set_count <= 0:
                tonnage = None

            records.append(
                {
                    "date": d,
                    "type": "gym_session",
                    "id": int(r["session_id"]),
                    "session_id": int(r["session_id"]),
                    "title": (r["title"] if r["title"] is not None else None),
                    "session_key": (r["session_key"] if r["session_key"] is not None else None),
                    "duration_s": None,  # not reliably stored; keep explicit null
                    "tonnage_kg": tonnage,
                    "set_count": set_count,
                    "avg_rpe": _to_optional_float(r["avg_rpe"]),
                    "notes": (r["notes"] if r["notes"] is not None else None),
                }
            )

    # -----------------------------
    # Gym raw sets
    # -----------------------------
    if "gym_set" in include_set:
        conn = get_training_db()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT
              s.id         AS set_id,
              w.id         AS session_id,
              w.date_iso   AS date_iso,
              e.id         AS exercise_id,
              e.name       AS exercise,
              e.device     AS device,
              e.laterality AS laterality,
              e.variation  AS variation,
              e.muscle_primary   AS muscle_primary,
              e.muscle_secondary AS muscle_secondary,
              s.set_number AS set_number,
              s.reps       AS reps,
              s.weight     AS weight,
              s.rpe        AS rpe
            FROM sets s
            JOIN exercises e ON e.id = s.exercise_id
            JOIN workouts  w ON w.id = e.workout_id
            WHERE w.date_iso >= ? AND w.date_iso <= ?
            ORDER BY w.date_iso ASC, w.id ASC, e.id ASC, COALESCE(s.set_number, 0) ASC, s.id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        conn.close()

        for r in rows:
            d = (r["date_iso"] or "").strip()
            if not d:
                continue
            records.append(
                {
                    "date": d,
                    "type": "gym_set",
                    "id": int(r["set_id"]),
                    "session_id": int(r["session_id"]),
                    "exercise_id": int(r["exercise_id"]) if r["exercise_id"] is not None else None,
                    "exercise": (r["exercise"] if r["exercise"] is not None else None),
                    "device": (r["device"] if r["device"] is not None else None),
                    "laterality": (r["laterality"] if r["laterality"] is not None else None),
                    "variation": (r["variation"] if r["variation"] is not None else None),
                    "muscle_primary": (r["muscle_primary"] if r["muscle_primary"] is not None else None),
                    "muscle_secondary": (r["muscle_secondary"] if r["muscle_secondary"] is not None else None),
                    "set_index": int(r["set_number"]) if r["set_number"] is not None else None,
                    "reps": int(r["reps"]) if r["reps"] is not None else None,
                    "weight_kg": _to_optional_float(r["weight"]),
                    "rpe": _to_optional_float(r["rpe"]),
                }
            )

    # -----------------------------
    # Weight
    # -----------------------------
    if "weight" in include_set:
        conn = get_nutrition_db()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT id, date_iso, weight_kg
            FROM weight_logs
            WHERE date_iso >= ? AND date_iso <= ?
            ORDER BY date_iso ASC, id ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        conn.close()

        for r in rows:
            d = (r["date_iso"] or "").strip()
            if not d:
                continue
            records.append(
                {
                    "date": d,
                    "type": "weight",
                    "id": int(r["id"]),
                    "weight_kg": _to_optional_float(r["weight_kg"]),
                }
            )

    # -----------------------------
    # Nutrition day
    # -----------------------------
    if "nutrition_day" in include_set:
        conn = get_nutrition_db()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            """
            SELECT date_iso, kcal, protein, carbs, fat
            FROM nutrition_daily
            WHERE date_iso >= ? AND date_iso <= ?
            ORDER BY date_iso ASC
            """,
            (start_iso, end_iso),
        ).fetchall()
        conn.close()

        for r in rows:
            d = (r["date_iso"] or "").strip()
            if not d:
                continue
            records.append(
                {
                    "date": d,
                    "type": "nutrition_day",
                    "id": d,
                    "kcal": int(r["kcal"]) if r["kcal"] is not None else None,
                    "protein_g": int(r["protein"]) if r["protein"] is not None else None,
                    "carbs_g": int(r["carbs"]) if r["carbs"] is not None else None,
                    "fat_g": int(r["fat"]) if r["fat"] is not None else None,
                }
            )

    # global chronological sort (cross-type)
    records.sort(key=_export_sort_key)

    truncated = False
    limit_n = _clamp_int(limit, 1, 20_000, 3000)
    if limit_n and len(records) > limit_n:
        truncated = True
        records = records[:limit_n]

    return records, truncated


def _compact_export_columns() -> dict[str, list[str]]:
    return {
        "hrv_daily": ["t", "id", "rmssd", "sdnn", "rhr", "q", "src", "flags"],
        "hr_daily": ["t", "id", "hr", "src"],
        "run": ["t", "id", "km", "dur_s", "pace_skm", "avg_hr", "max_hr", "elev_m", "src"],
        "gym_session": ["d", "sid", "title", "sets", "ton_kg", "avg_rpe", "key", "notes"],
        "gym_set": ["d", "sid", "eid", "ex", "var", "dev", "lat", "m1", "m2", "set", "reps", "kg", "rpe"],
        "weight": ["d", "id", "kg"],
        "nutrition_day": ["d", "kcal", "p", "c", "f"],
    }


def _export_flag_true(flag_bool, flag_text) -> bool:
    if flag_bool in (1, True):
        return True
    if flag_text is None:
        return False
    txt = str(flag_text).strip().lower()
    if not txt:
        return False
    if txt in {"0", "false", "no", "none", "nothing", "not sick"}:
        return False
    return True


def _compact_row_for_record(rec: dict) -> list[object]:
    t = str(rec.get("type") or "").strip()
    ts = rec.get("ts")
    d = rec.get("date")

    if t == "hrv_daily":
        return [ts, rec.get("id"), rec.get("rmssd_ms"), rec.get("sdnn_ms"), rec.get("resting_hr_bpm"), rec.get("signal_quality"), rec.get("source"), rec.get("flags")]
    if t == "hr_daily":
        return [ts, rec.get("id"), rec.get("hr_bpm"), rec.get("source")]
    if t == "run":
        return [
            ts or d,
            rec.get("id"),
            rec.get("distance_km"),
            rec.get("moving_time_s"),
            rec.get("pace_s_per_km"),
            rec.get("avg_hr_bpm"),
            rec.get("max_hr_bpm"),
            rec.get("elevation_gain_m"),
            rec.get("source"),
        ]
    if t == "gym_session":
        return [
            d,
            rec.get("session_id") if rec.get("session_id") is not None else rec.get("id"),
            rec.get("title"),
            rec.get("set_count"),
            rec.get("tonnage_kg"),
            rec.get("avg_rpe"),
            rec.get("session_key"),
            rec.get("notes"),
        ]
    if t == "gym_set":
        return [
            d,
            rec.get("session_id"),
            rec.get("exercise_id"),
            rec.get("exercise"),
            rec.get("variation"),
            rec.get("device"),
            rec.get("laterality"),
            rec.get("muscle_primary"),
            rec.get("muscle_secondary"),
            rec.get("set_index"),
            rec.get("reps"),
            rec.get("weight_kg"),
            rec.get("rpe"),
        ]
    if t == "weight":
        return [d, rec.get("id"), rec.get("weight_kg")]
    if t == "nutrition_day":
        return [d, rec.get("kcal"), rec.get("protein_g"), rec.get("carbs_g"), rec.get("fat_g")]
    return [ts or d, rec.get("id"), rec]


def _render_export_compact(*, start_d: date, end_d: date, include_items: list[str], records: list[dict], truncated: bool, limit_n: int) -> str:
    columns = _compact_export_columns()
    include_clean = [str(x).strip() for x in include_items if str(x).strip()]
    grouped: dict[str, list[dict[str, object]]] = {t: [] for t in include_clean}
    for rec in records:
        rtype = str(rec.get("type") or "").strip()
        if not rtype:
            continue
        row_values = _compact_row_for_record(rec)
        row_cols = columns.get(rtype, ["t", "id", "payload"])
        row_obj: dict[str, object] = {}
        for i, col in enumerate(row_cols):
            if i >= len(row_values):
                continue
            v = row_values[i]
            if v is None:
                continue
            row_obj[col] = v
        grouped.setdefault(rtype, []).append(row_obj)

    counts = {t: len(grouped.get(t) or []) for t in include_clean}
    out = {
        "meta": {
            "v": 3,
            "fmt": "ai_compact",
            "tz": "Europe/Berlin",
            "from": start_d.isoformat(),
            "to": end_d.isoformat(),
            "types": include_clean,
            "n": len(records),
            "by_type": counts,
            "limit": int(limit_n),
            "trunc": bool(truncated),
        },
        "data": {t: grouped.get(t, []) for t in include_clean},
    }
    return json.dumps(out, ensure_ascii=False, indent=2) + "\n"


@app.get("/api/export")
@require_master
def api_export():
    # allow query params OR JSON body
    body = request.get_json(silent=True) or {}

    fmt = (request.args.get("format") or body.get("format") or "ai_jsonl").strip().lower()
    if fmt not in ("ai_compact", "compact", "ai-json-compact", "ai_jsonl", "ai-jsonl", "jsonl", "ndjson"):
        return make_response("unsupported format", 400)

    start_raw = request.args.get("start_date") or body.get("start_date")
    end_raw = request.args.get("end_date") or body.get("end_date")

    # include can be: ?include=a,b,c OR ?include=a&include=b OR JSON list
    include_items: list[str] = []
    if request.args.getlist("include"):
        for it in request.args.getlist("include"):
            include_items.extend([x.strip() for x in str(it).split(",") if x.strip()])
    elif isinstance(body.get("include"), list):
        include_items = [str(x).strip() for x in body.get("include") if str(x).strip()]
    elif body.get("include"):
        include_items = [x.strip() for x in str(body.get("include")).split(",") if x.strip()]
    else:
        include_items = [x.strip() for x in str(request.args.get("include") or "").split(",") if x.strip()]

    if not include_items:
        return make_response("missing include (types)", 400)

    # keep export concise: HR is already part of hrv_daily via "rhr"
    if "hrv_daily" in include_items:
        include_items = [t for t in include_items if t != "hr_daily"]

    limit = request.args.get("limit") or body.get("limit") or 3000
    limit_n = _clamp_int(limit, 1, 20_000, 3000)

    default_start, default_end = _export_default_range()

    start_d = _parse_iso(start_raw) if start_raw else None
    end_d = _parse_iso(end_raw) if end_raw else None
    start_d = start_d or default_start
    end_d = end_d or default_end

    if start_d > end_d:
        return make_response("invalid range: start_date > end_date", 400)

    records, truncated = export_records(start_d, end_d, include_items, limit=limit_n)

    if fmt in ("ai_compact", "compact", "ai-json-compact"):
        out = _render_export_compact(
            start_d=start_d,
            end_d=end_d,
            include_items=include_items,
            records=records,
            truncated=truncated,
            limit_n=limit_n,
        )
        resp = make_response(out)
        resp.headers["Content-Type"] = "text/plain; charset=utf-8"
        return resp

    header = "\n".join(
        [
            "EXPORT_META",
            "timezone: Europe/Berlin",
            f"range: {start_d.isoformat()} -> {end_d.isoformat()}",
            f"included: {', '.join(include_items)}",
            f"record_count: {len(records)}",
            f"truncated: {'true' if truncated else 'false'}",
            "units: rmssd=ms, sdnn=ms, hr=bpm, weight=kg, distance=km, pace=s_per_km, time=s",
            "notes: null means missing, date is ISO-8601",
            "END_EXPORT_META",
        ]
    )

    lines = [json.dumps(r, ensure_ascii=False, separators=(",", ":")) for r in records]
    out = header + "\n"
    if lines:
        out += "\n".join(lines) + "\n"

    resp = make_response(out)
    resp.headers["Content-Type"] = "text/plain; charset=utf-8"
    return resp


