def _physique_update_payload(row: dict[str, Any]) -> dict[str, Any]:
    assets = row.get("assets") if isinstance(row.get("assets"), list) else []
    return {
        "id": row.get("id"),
        "source": row.get("source"),
        "note": row.get("note") or "",
        "weight_kg": row.get("weight_kg"),
        "view_label": row.get("view_label") or "",
        "pose_label": row.get("pose_label") or "",
        "captured_at": row.get("captured_at") or "",
        "created_at": row.get("created_at") or "",
        "assets": [
            {
                "id": asset.get("id"),
                "url": url_for("physique_asset_media", asset_name=asset.get("preview_name") or asset.get("asset_name")),
                "original_url": url_for("physique_asset_media", asset_name=asset.get("asset_name")),
                "asset_name": asset.get("asset_name"),
                "original_filename": asset.get("original_filename") or asset.get("asset_name"),
                "preview_name": asset.get("preview_name") or "",
                "mime_type": asset.get("mime_type") or "",
                "width": asset.get("width"),
                "height": asset.get("height"),
                "captured_at": asset.get("captured_at") or row.get("captured_at") or "",
                "captured_at_source": asset.get("captured_at_source") or "",
                "weight_kg": asset.get("weight_kg"),
                "weight_source": asset.get("weight_source") or "",
                "liked": bool(asset.get("liked")),
            }
            for asset in assets
            if asset.get("asset_name")
        ],
    }


