@app.post("/api/physique/updates")
@require_role("key")
@require_tailscale
def api_physique_upload():
    if not verify_csrf():
        return jsonify({"ok": False, "error": "csrf_invalid"}), 403
    files = request.files.getlist("photos")
    assets = []
    for file in files:
        if not file or not getattr(file, "filename", ""):
            continue
        mime_type = str(file.mimetype or "").strip().lower()
        if mime_type and not mime_type.startswith("image/"):
            continue
        content = file.read()
        if not content:
            continue
        assets.append(
            {
                "filename": file.filename,
                "mime_type": mime_type,
                "content": content,
            }
        )
    if not assets:
        return jsonify({"ok": False, "error": "missing_images"}), 400
    note = str(request.form.get("note") or "").strip()
    view_label = str(request.form.get("view_label") or "").strip()
    pose_label = str(request.form.get("pose_label") or "").strip()
    captured_at = str(request.form.get("captured_at") or "").strip()
    if captured_at:
        try:
            parsed = datetime.fromisoformat(captured_at)
            captured_at = parsed.astimezone().replace(microsecond=0).isoformat()
        except Exception:
            captured_at = ""
    weight_raw = str(request.form.get("weight_kg") or "").strip().replace(",", ".")
    weight_kg = None
    if weight_raw:
        try:
            weight_kg = float(weight_raw)
        except Exception:
            return jsonify({"ok": False, "error": "invalid_weight"}), 400
    row = create_physique_update(
        source="website",
        assets=assets,
        note=note,
        weight_kg=weight_kg,
        view_label=view_label,
        pose_label=pose_label,
        captured_at=captured_at,
    )
    payload_rows = list_physique_updates(limit=1)
    payload = _physique_update_payload(payload_rows[0]) if payload_rows else {"id": row.get("id")}
    return jsonify({"ok": True, "update": payload})


@app.patch("/api/physique/updates/<int:update_id>")
@require_role("key")
@require_tailscale
def api_physique_update_tags(update_id: int):
    if not verify_csrf():
        return jsonify({"ok": False, "error": "csrf_invalid"}), 403
    payload = request.get_json(silent=True) or {}
    kwargs: dict[str, Any] = {}
    if "view_label" in payload:
        kwargs["view_label"] = str(payload.get("view_label") or "").strip()
    if "pose_label" in payload:
        kwargs["pose_label"] = str(payload.get("pose_label") or "").strip()
    if "weight_kg" in payload:
        weight_raw = payload.get("weight_kg")
        weight_kg = None
        if weight_raw is not None and str(weight_raw).strip() != "":
            try:
                weight_kg = float(str(weight_raw).strip().replace(",", "."))
            except Exception:
                return jsonify({"ok": False, "error": "invalid_weight"}), 400
        kwargs["weight_kg"] = weight_kg
    if "captured_at" in payload:
        captured_at = str(payload.get("captured_at") or "").strip()
        if captured_at:
            try:
                parsed = datetime.fromisoformat(captured_at.replace("Z", "+00:00"))
                if parsed.tzinfo is None:
                    parsed = parsed.astimezone()
                captured_at = parsed.replace(microsecond=0).isoformat()
            except Exception:
                return jsonify({"ok": False, "error": "invalid_captured_at"}), 400
        kwargs["captured_at"] = captured_at or None
    row = update_physique_update_tags(
        int(update_id),
        **kwargs,
    )
    if not row:
        return jsonify({"ok": False, "error": "not_found"}), 404
    payload_row = _physique_update_payload({**row, "assets": []})
    return jsonify({"ok": True, "update": payload_row})


