@app.post("/api/settings")
@require_admin
def api_settings_update():
    payload = request.get_json(silent=True) or {}
    if "core_mode_enabled" in payload:
        raw = payload.get("core_mode_enabled")
        enabled = str(raw).strip().lower() in {"1", "true", "yes", "on"}
        _set_core_mode_enabled(enabled)
    if "autopilot_enabled" in payload:
        raw = payload.get("autopilot_enabled")
        enabled = str(raw).strip().lower() in {"1", "true", "yes", "on"}
        _set_core_mode_enabled(enabled)
    if "telegram_push_action" in payload:
        _apply_telegram_push_action(str(payload.get("telegram_push_action") or ""))
    if "telegram_push_mute" in payload:
        mode = str(payload.get("telegram_push_mute") or "").strip().lower()
        if mode in {"forever", "always", "permanent"}:
            _apply_telegram_push_action("mute_forever")
        elif mode in {"today", "heute"}:
            _apply_telegram_push_action("mute_today")
        elif mode in {"7d", "7days", "7_days", "week"}:
            _apply_telegram_push_action("mute_7d")
        elif mode in {"off", "none", "unmute", "on"}:
            _apply_telegram_push_action("unmute")
    if "telegram_meal_push_enabled" in payload:
        raw = payload.get("telegram_meal_push_enabled")
        if isinstance(raw, dict):
            for k, v in raw.items():
                try:
                    idx = int(str(k).strip())
                except Exception:
                    continue
                if idx < TELEGRAM_MEAL_PUSH_MIN_INDEX or idx > TELEGRAM_MEAL_PUSH_MAX_INDEX:
                    continue
                enabled = _parse_setting_bool(str(v), default=True)
                _set_telegram_meal_push_enabled(idx, enabled)
    return jsonify(ok=True, settings=_settings_payload())


@app.get("/api/next_session")
def api_next_session():
    day = (request.args.get("day") or "").strip() or date.today().isoformat()
    explain = str(request.args.get("explain") or "").strip().lower() in {"1", "true", "yes", "on"}
    force_refresh = str(request.args.get("refresh") or "").strip().lower() in {"1", "true", "yes", "on"}
    if os.environ.get("PYTEST_CURRENT_TEST"):
        payload = _build_next_session_snapshot(day, explain)
        status = int(payload.pop("status_code", 200) or 200)
        return jsonify(payload), status
    allow_async_fallback = not bool(app.testing)
    snapshot_key = f"next_session_snapshot:{day}:{1 if explain else 0}"
    try:
        builder = lambda: _build_next_session_snapshot(day, explain)
        meta = {"route": "/api/next_session", "day": day, "explain": explain}
        if force_refresh and allow_async_fallback:
            refresh_snapshot_async(
                snapshot_key,
                builder=builder,
                ttl_seconds=_SNAPSHOT_TTLS["next_session_snapshot"],
                meta={**meta, "forced_refresh": True},
            )
            payload = get_snapshot(
                snapshot_key,
                builder=builder,
                ttl_seconds=_SNAPSHOT_TTLS["next_session_snapshot"],
                allow_stale=True,
                background_refresh=False,
                meta=meta,
                fallback_payload=_next_session_snapshot_fallback(day),
            )
        else:
            if force_refresh:
                invalidate_snapshot(snapshot_key)
            payload = get_snapshot(
                snapshot_key,
                builder=builder,
                ttl_seconds=_SNAPSHOT_TTLS["next_session_snapshot"],
                allow_stale=True,
                background_refresh=(not force_refresh) and allow_async_fallback,
                meta=meta,
                fallback_payload=None if (force_refresh or not allow_async_fallback) else _next_session_snapshot_fallback(day),
            )
        record_timing(
            "next_session.snapshot",
            0.0,
            snapshot_hit=bool(payload.get("snapshot_hit")),
            stale=bool(payload.get("stale")),
            partial=bool(payload.get("partial")),
        )
        status = int(payload.pop("status_code", 200) or 200)
        return _snapshot_json_response(payload), status
    except Exception:
        app.logger.exception("api_next_session failed")
        return jsonify({
            "ok": False,
            "error": "next_session_failed",
            "selected_day_id": day,
            "week_days": [],
            "session": {"session_name": "Error", "session_key": "", "meta": {"autopilot": True}},
            "items": [],
            "summary": {"flags": ["ERROR"], "status": "red"},
        }), 500


