@app.post("/api/makros/settings")
def api_makros_settings_update():
    data = request.get_json(silent=True) or {}
    allowed = {"cut", "lean_bulk", "maintenance", "custom"}
    active_mode = data.get("active_mode")
    modes = data.get("modes") or {}
    if active_mode is not None and active_mode not in allowed:
        return jsonify(ok=False, error="invalid_mode", detail="Ungültiger Mode."), 400

    for mode, values in modes.items():
        if mode not in allowed:
            return jsonify(ok=False, error="invalid_mode", detail="Ungültiger Mode."), 400
        if not isinstance(values, dict):
            return jsonify(ok=False, error="invalid_payload", detail="Ungültige Mode-Daten."), 400
        kcal_target = _parse_float_or_none(values.get("kcal_target"))
        protein_target = _parse_float_or_none(values.get("protein_target"))
        carbs_target = _parse_float_or_none(values.get("carbs_target"))
        fat_target = _parse_float_or_none(values.get("fat_target"))
        green_tol = _parse_float_or_none(values.get("green_tol"))
        yellow_tol = _parse_float_or_none(values.get("yellow_tol"))
        green_low = _parse_float_or_none(values.get("green_low"))
        green_high = _parse_float_or_none(values.get("green_high"))
        yellow_low = _parse_float_or_none(values.get("yellow_low"))
        yellow_high = _parse_float_or_none(values.get("yellow_high"))
        if kcal_target is None or kcal_target <= 0:
            return jsonify(ok=False, error="invalid_target", detail="kcal_target muss > 0 sein."), 400
        for label, val in (("protein_target", protein_target), ("carbs_target", carbs_target), ("fat_target", fat_target)):
            if val is not None and val < 0:
                return jsonify(ok=False, error="invalid_target", detail=f"{label} muss >= 0 sein."), 400

        uses_bounds = any(v is not None for v in (green_low, green_high, yellow_low, yellow_high))
        if uses_bounds:
            if green_low is None or green_high is None or yellow_low is None or yellow_high is None:
                return jsonify(ok=False, error="invalid_bounds", detail="Alle Band-Grenzen (grün/gelb unten/oben) müssen gesetzt sein."), 400
            if green_low > kcal_target or green_high < kcal_target:
                return jsonify(ok=False, error="invalid_bounds", detail="Grün-Band muss das Ziel enthalten (green_low <= target <= green_high)."), 400
            if yellow_low > green_low or yellow_high < green_high:
                return jsonify(ok=False, error="invalid_bounds", detail="Gelb-Band muss Grün-Band enthalten (yellow_low <= green_low und yellow_high >= green_high)."), 400
            if yellow_low > kcal_target or yellow_high < kcal_target:
                return jsonify(ok=False, error="invalid_bounds", detail="Gelb-Band muss das Ziel enthalten."), 400
        else:
            if green_tol is None or green_tol < 0:
                return jsonify(ok=False, error="invalid_green_tol", detail="green_tolerance muss >= 0 sein."), 400
            if yellow_tol is None or yellow_tol < green_tol:
                return jsonify(ok=False, error="invalid_yellow_tol", detail="yellow_tolerance muss >= green_tolerance sein."), 400

    payload = {}
    if active_mode is not None:
        payload["active_mode"] = active_mode
    if modes:
        payload["modes"] = modes
    _write_nutrition_settings(payload)
    if active_mode:
        _set_active_nutrition_mode(active_mode)
    settings = _load_nutrition_settings()
    return jsonify(ok=True, settings={
        "active_mode": settings.get("active_mode"),
        "modes": settings.get("modes"),
    })


def _set_active_nutrition_mode(mode: str):
    conn = get_nutrition_db()
    _ensure_nutrition_mode_timeline(conn)
    settings = _load_nutrition_settings()
    _load_nutrition_mode_timeline(conn, settings)
    today = date.today().isoformat()
    cur = conn.cursor()
    last = cur.execute(
        """
        SELECT id, mode, start_date, end_date
        FROM nutrition_mode_timeline
        ORDER BY start_date DESC, id DESC
        LIMIT 1
        """
    ).fetchone()
    if last and last["mode"] == mode and last["end_date"] is None:
        conn.close()
        return
    if last and last["end_date"] is None:
        cur.execute(
            "UPDATE nutrition_mode_timeline SET end_date = date(?, '-1 day') WHERE id = ?",
            (today, last["id"]),
        )
    cur.execute(
        """
        INSERT INTO nutrition_mode_timeline (start_date, end_date, mode, target_kcal)
        VALUES (?, NULL, ?, NULL)
        """,
        (today, mode),
    )
    conn.commit()
    conn.close()


