@app.route("/api/settings/backup_status")
@require_master
def backup_status():
    last_ts = latest_backup_timestamp()
    if last_ts is None:
        return jsonify({"exists": False})

    def _git_backup_state() -> tuple[bool, str]:
        try:
            inside = subprocess.run(
                ["git", "rev-parse", "--is-inside-work-tree"],
                cwd="/opt/liva",
                capture_output=True,
                text=True,
                timeout=5,
            )
            if inside.returncode != 0 or inside.stdout.strip() != "true":
                return False, "Kein Git-Repo"
            origin = subprocess.run(
                ["git", "remote", "get-url", "origin"],
                cwd="/opt/liva",
                capture_output=True,
                text=True,
                timeout=5,
            )
            if origin.returncode != 0:
                return False, "Origin fehlt"
            return True, "Privates Repo aktuell"
        except Exception:
            return False, "Git-Status unbekannt"

    metadata = load_backup_metadata() or {}
    payload = metadata.get("payload") if isinstance(metadata, dict) else {}
    payload = payload if isinstance(payload, dict) else {}
    updated_at_raw = metadata.get("updated_at") if isinstance(metadata, dict) else None
    code_push = payload.get("code_push") if isinstance(payload.get("code_push"), dict) else {}
    sqlite_backup = payload.get("sqlite_backup") if isinstance(payload.get("sqlite_backup"), dict) else {}
    remote_sync = sqlite_backup.get("remote_sync") if isinstance(sqlite_backup.get("remote_sync"), dict) else {}
    targets = sqlite_backup.get("targets") if isinstance(sqlite_backup.get("targets"), dict) else {}
    target_errors = sqlite_backup.get("target_errors") if isinstance(sqlite_backup.get("target_errors"), dict) else {}
    usb_targets = {
        path: result for path, result in targets.items()
        if isinstance(path, str) and ("/mnt/" in path or "/media/" in path)
    }
    usb_ok = bool(usb_targets) and all(
        isinstance(result, dict) and all(str(value) == "ok" for value in result.values())
        for result in usb_targets.values()
    )
    usb_required = (os.getenv("LIVA_USB_BACKUP_REQUIRED") or "0").strip().lower() in {"1", "true", "yes", "on"}
    local_dropbox_target = next(
        (path for path in targets.keys() if isinstance(path, str) and "dropbox/Apps/Datenbanken" in path),
        "/var/lib/liva/dropbox/Apps/Datenbanken",
    )
    usb_error_detail = ""
    if not usb_ok and usb_targets:
        first_usb_error = next(
            (
                str(value)
                for path, result in usb_targets.items()
                if isinstance(result, dict)
                for value in result.values()
                if str(value) != "ok"
            ),
            "",
        )
        usb_error_detail = first_usb_error.replace("error:", "").strip() or "USB-Update fehlgeschlagen"
    github_ok_fallback, github_detail_fallback = _git_backup_state()
    code_push_status = str(code_push.get("status") or "") if code_push else ""
    github_ok = bool(code_push.get("ok")) and code_push_status in {"ok", "unchanged"} if code_push else github_ok_fallback
    if code_push:
        if github_ok:
            github_detail = "Quellcode-Snapshot aktuell"
        elif code_push_status == "skipped":
            github_detail = "Code-Backup deaktiviert"
        else:
            github_detail = str(code_push.get("reason") or code_push.get("step") or "Fehler")
    else:
        github_detail = github_detail_fallback
    dropbox_ok = bool(remote_sync.get("ok"))
    overall_ok = github_ok and dropbox_ok and (usb_ok or not usb_required)
    updated_at_ts = None
    if isinstance(updated_at_raw, str) and updated_at_raw.strip():
        try:
            updated_at_dt = datetime.fromisoformat(updated_at_raw.replace("Z", "+00:00"))
            updated_at_ts = updated_at_dt.timestamp()
        except Exception:
            updated_at_ts = None
    fresh_enough = bool(updated_at_ts and updated_at_ts >= (datetime.now(timezone.utc).timestamp() - 86400))
    recent_ok = overall_ok and fresh_enough
    return jsonify({
        "exists": True,
        "last_backup_ts": last_ts,
        "updated_at": updated_at_raw,
        "updated_at_ts": updated_at_ts,
        "summary": (
            "GitHub + Dropbox + USB ok"
            if overall_ok and usb_ok
            else ("GitHub + Dropbox ok; USB pruefen" if overall_ok else "Backup unvollstaendig")
        ),
        "recent_ok": recent_ok,
        "targets": {
            "github": {
                "label": "GitHub",
                "status": "ok" if github_ok else "error",
                "detail": github_detail,
            },
            "dropbox": {
                "label": "Dropbox",
                "status": "ok" if dropbox_ok else "error",
                "detail": "Apps/Datenbanken aktuell" if dropbox_ok else str(remote_sync.get("reason") or remote_sync.get("status") or "Fehler"),
                "path": local_dropbox_target,
            },
            "usb": {
                "label": "USB",
                "status": "ok" if usb_ok else ("error" if usb_required else "idle"),
                "detail": f"{len(usb_targets)} Ziel(e) aktuell" if usb_ok else ("Kein USB-Ziel erkannt" if not usb_targets else usb_error_detail),
                "errors": {path: target_errors.get(path, result) for path, result in usb_targets.items() if path in target_errors or not usb_ok},
            },
        },
    })



@app.get("/api/analysis/exercises")
def api_analysis_exercises():
    days = request.args.get("days", default=30, type=int)
    if not days or days < 1 or days > 365:
        days = 30

    start_iso = (request.args.get("start") or "").strip() or (date.today() - timedelta(days=days - 1)).isoformat()
    end_iso = (request.args.get("end") or "").strip() or None

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()

    cur.execute("""
        WITH all_ex AS (
            SELECT DISTINCT TRIM(name) AS name
            FROM exercises
            WHERE name IS NOT NULL AND TRIM(name) != ''
        ),
        freq AS (
            SELECT
                TRIM(e.name) AS name,
                COUNT(DISTINCT e.workout_id) AS sessions_30d,
                COUNT(s.id) AS sets_30d
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            LEFT JOIN sets s ON s.exercise_id = e.id
            WHERE e.name IS NOT NULL AND TRIM(e.name) != ''
              AND w.date_iso >= ?
              AND (? IS NULL OR substr(w.date_iso, 1, 10) <= ?)
            GROUP BY TRIM(e.name)
        ),
        last AS (
            SELECT
                TRIM(e.name) AS name,
                MAX(w.date_iso) AS last_date
            FROM exercises e
            JOIN workouts w ON w.id = e.workout_id
            WHERE e.name IS NOT NULL AND TRIM(e.name) != ''
            GROUP BY TRIM(e.name)
        )
        SELECT
            all_ex.name AS exercise,
            COALESCE(freq.sessions_30d, 0) AS sessions_30d,
            COALESCE(freq.sets_30d, 0)     AS sets_30d,
            last.last_date                  AS last_date
        FROM all_ex
        LEFT JOIN freq ON freq.name = all_ex.name
        LEFT JOIN last ON last.name = all_ex.name
        ORDER BY
            sessions_30d DESC,
            sets_30d DESC,
            last_date DESC,
            all_ex.name COLLATE NOCASE ASC;
    """, (start_iso, end_iso, end_iso))

    rows = cur.fetchall()
    conn.close()

    return jsonify([dict(r) for r in rows])


@app.route("/api/analysis/exercise_variants")
def api_exercise_variants():
    exercise = (request.args.get("exercise") or "").strip()
    if not exercise:
        return jsonify([])

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        days_raw = (request.args.get("days") or "all").strip().lower()
        start_iso = (request.args.get("start") or "").strip() or (None if days_raw == "all" else (date.today() - timedelta(days=_clamp_int(days_raw, 1, 3650, 180) - 1)).isoformat())
        end_iso = (request.args.get("end") or "").strip() or None
        rows = conn.execute("""
            WITH variants AS (
              SELECT
                CASE
                  WHEN LOWER(TRIM(e.name)) IN ('pushdown', 'pushdowns', 'beinpresse', 'beinstrecker', 'wadenheben') THEN
                    CASE
                      WHEN LOWER(COALESCE(e.variation, '')) LIKE '%unilat%' OR LOWER(COALESCE(e.variation, '')) LIKE '%unilateral%' THEN 'unilat'
                      WHEN LOWER(COALESCE(e.variation, '')) LIKE '%bilat%' OR LOWER(COALESCE(e.variation, '')) LIKE '%bilateral%' THEN 'bilat'
                      WHEN LOWER(TRIM(COALESCE(e.device, ''))) IN ('unilat', 'unilateral') THEN 'unilat'
                      WHEN LOWER(TRIM(COALESCE(e.device, ''))) IN ('bilat', 'bilateral') THEN 'bilat'
                      WHEN LOWER(TRIM(COALESCE(e.laterality, ''))) = 'unilateral' THEN 'unilat'
                      WHEN LOWER(TRIM(COALESCE(e.laterality, ''))) = 'bilateral' THEN 'bilat'
                      ELSE LOWER(TRIM(e.device))
                    END
                  ELSE
                    CASE
                      WHEN TRIM(COALESCE(e.device, '')) <> '' THEN TRIM(e.device)
                      WHEN TRIM(COALESCE(e.variation, '')) <> '' THEN TRIM(e.variation)
                      ELSE ''
                    END
                END AS device,
                substr(w.date_iso, 1, 10) AS date_iso
              FROM exercises e
              JOIN workouts w ON w.id = e.workout_id
              WHERE LOWER(TRIM(e.name)) = LOWER(TRIM(?))
                AND (? IS NULL OR substr(w.date_iso, 1, 10) >= ?)
                AND (? IS NULL OR substr(w.date_iso, 1, 10) <= ?)
            )
            SELECT device, MAX(date_iso) AS last_date
            FROM variants
            WHERE TRIM(device) <> ''
            GROUP BY device
            ORDER BY last_date DESC, device COLLATE NOCASE ASC;
        """, (exercise, start_iso, start_iso, end_iso, end_iso)).fetchall()
        return jsonify([
            {
                "device": r["device"],
                "last_date": r["last_date"],
            }
            for r in rows
        ])

    except Exception as e:
        print("❌ exercise_variants error:", e)
        return jsonify([]), 500
    finally:
        conn.close()





@app.route("/auswertung")
def auswertung_page():
    snapshot = get_snapshot(
        "training_snapshot",
        builder=_build_training_page_snapshot,
        ttl_seconds=_SNAPSHOT_TTLS["training_snapshot"],
        allow_stale=True,
        background_refresh=True,
        meta={"route": "/auswertung"},
        fallback_payload=_training_snapshot_fallback(),
    )
    analysis_ctx = snapshot.get("analysis_ctx") if isinstance(snapshot.get("analysis_ctx"), dict) else _training_analysis_context()

    rows = get_weight_logs(
        limit=None,
        date_from=_date_from_for_range(
            MAKROS_DEFAULT_TABLE_RANGE_DAYS,
            default_days=MAKROS_DEFAULT_TABLE_RANGE_DAYS,
        ),
    )

    timeline_mins = {"training": None, "ernaehrung": None}
    for area, db_getter, table_name in (
        ("training", get_training_db, "workouts"),
        ("ernaehrung", get_nutrition_db, "weight_logs"),
    ):
        conn = db_getter()
        try:
            row = conn.execute(
                f"SELECT MIN(substr(date_iso, 1, 10)) AS min_date FROM {table_name} WHERE date_iso IS NOT NULL"
            ).fetchone()
            if row:
                timeline_mins[area] = row["min_date"] if isinstance(row, sqlite3.Row) else row[0]
        finally:
            conn.close()
    available_timeline_mins = [value for value in timeline_mins.values() if value]
    timeline_mins["gesamt"] = min(available_timeline_mins) if available_timeline_mins else None

    return render_template(
        "auswertung.html",
        rows=rows,
        superk_dates=analysis_ctx["superk_dates"],
        superk_values=analysis_ctx["superk_values"],
        exercises=analysis_ctx["exercises"],
        timeline_mins=timeline_mins,
        active_page="auswertung",
    )


@app.route("/analyse")
def analyse_page():
    return redirect(url_for("auswertung_page"))

def _training_analysis_context() -> dict:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row

    mvps_data = compute_mvps_timeseries(conn)

    superk_dates = [d["date_iso"] for d in mvps_data]
    # robuster (falls trend/overall mal fehlt)
    superk_values = [((d.get("trend") or {}).get("overall")) for d in mvps_data]

    cutoff = (date.today() - timedelta(days=30)).isoformat()
    cur = conn.cursor()

    def table_exists(name: str) -> bool:
        cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (name,))
        return cur.fetchone() is not None

    def column_exists(table: str, col: str) -> bool:
        cur.execute(f"PRAGMA table_info({table})")
        return any(r["name"] == col for r in cur.fetchall())

    # ✅ Übungsliste: nach Häufigkeit (letzte 30 Tage) sortiert
    #    -> zählt "Workouts, in denen Übung vorkam" (nicht Sets), damit’s fair bleibt.
    try:
        if table_exists("workouts") and column_exists("exercises", "workout_id"):
            cur.execute("""
                SELECT name
                FROM (
                    SELECT DISTINCT e.name AS name, w.date_iso AS date_iso
                    FROM exercises e
                    JOIN workouts w ON w.id = e.workout_id
                    WHERE e.name IS NOT NULL AND TRIM(e.name) != ''
                )
                GROUP BY name
                ORDER BY
                    SUM(CASE WHEN date_iso >= ? THEN 1 ELSE 0 END) DESC,
                    MAX(date_iso) DESC,
                    name COLLATE NOCASE
            """, (cutoff,))
        elif column_exists("exercises", "date_iso"):
            cur.execute("""
                SELECT name
                FROM (
                    SELECT DISTINCT name, date_iso
                    FROM exercises
                    WHERE name IS NOT NULL AND TRIM(name) != '' AND date_iso IS NOT NULL
                )
                GROUP BY name
                ORDER BY
                    SUM(CASE WHEN date_iso >= ? THEN 1 ELSE 0 END) DESC,
                    MAX(date_iso) DESC,
                    name COLLATE NOCASE
            """, (cutoff,))
        else:
            # Fallback: wenn wir nicht an ein Datum rankommen
            cur.execute("""
                SELECT DISTINCT name
                FROM exercises
                WHERE name IS NOT NULL AND TRIM(name) != ''
                ORDER BY name COLLATE NOCASE
            """)

        exercises = [r["name"] for r in cur.fetchall()]
    finally:
        conn.close()

    return {
        "superk_dates": superk_dates,
        "superk_values": superk_values,
        "exercises": exercises,
    }


def _build_training_page_snapshot() -> dict[str, Any]:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute("""
            SELECT 
                w.id,
                w.date,
                w.date_iso,
                w.name,
                w.session_key,
                COALESCE(SUM(s.reps * s.weight), 0) AS total_load,
                COUNT(s.id) AS total_sets
            FROM workouts w
            LEFT JOIN exercises e ON e.workout_id = w.id
            LEFT JOIN sets s ON s.exercise_id = e.id
            GROUP BY w.id
            ORDER BY w.date_iso DESC, w.id DESC
        """)
        workouts = [dict(r) for r in cur.fetchall()]
        progress_by_id = {
            int(payload["session_id"]): payload
            for payload in compute_progress_payloads(conn)
        }
        for workout in workouts:
            workout["progress"] = progress_by_id.get(int(workout["id"]))
    finally:
        conn.close()
    return {
        "ok": True,
        "workouts": workouts,
        "analysis_ctx": _training_analysis_context(),
        "partial": False,
    }


def _training_snapshot_fallback() -> dict[str, Any]:
    return {
        "ok": True,
        "workouts": [],
        "analysis_ctx": {
            "superk_dates": [],
            "superk_values": [],
            "exercises": [],
        },
        "partial": True,
        "loading": True,
    }


def _parse_analyse_default_progress_range(conn: sqlite3.Connection, raw_range: str | None) -> tuple[date, date]:
    today = date.today()
    default_start = today - timedelta(days=179)
    default_end = today

    raw = (raw_range or "").strip().lower()
    if not raw:
        try:
            row = conn.execute("SELECT MIN(substr(date_iso,1,10)) AS d FROM workouts").fetchone()
            min_iso = (row["d"] if row and row["d"] is not None else None) if isinstance(row, sqlite3.Row) else None
            if min_iso:
                return date.fromisoformat(str(min_iso)[:10]), default_end
        except Exception:
            pass
        return default_start, default_end

    if raw == "all":
        try:
            row = conn.execute("SELECT MIN(substr(date_iso,1,10)) AS d FROM workouts").fetchone()
            min_iso = (row["d"] if row and row["d"] is not None else None) if isinstance(row, sqlite3.Row) else None
            if min_iso:
                return date.fromisoformat(str(min_iso)[:10]), default_end
        except Exception:
            pass
        return default_start, default_end

    m = re.fullmatch(r"(\d+)\s*([dw])", raw)
    if m:
        n = max(1, int(m.group(1)))
        unit = m.group(2)
        days = n if unit == "d" else (n * 7)
        days = min(days, 3650)
        return (today - timedelta(days=days - 1)), default_end

    if raw.isdigit():
        n = max(1, min(3650, int(raw)))
        return (today - timedelta(days=n - 1)), default_end

    return default_start, default_end


@app.get("/api/analyse/default_progress")
def api_analyse_default_progress():
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        start_raw = (request.args.get("start") or "").strip()
        end_raw = (request.args.get("end") or "").strip()
        if start_raw and end_raw:
            start_d, end_d = date.fromisoformat(start_raw[:10]), date.fromisoformat(end_raw[:10])
        else:
            start_d, end_d = _parse_analyse_default_progress_range(conn, request.args.get("range"))
        tw_raw = request.args.get("trend_window_sessions", "6")
        try:
            trend_window_sessions = max(1, min(32, int(str(tw_raw).strip())))
        except Exception:
            trend_window_sessions = 6
        payload = compute_default_set_progress_series(
            conn,
            start_iso=start_d.isoformat(),
            end_iso=end_d.isoformat(),
            trend_window_sessions=trend_window_sessions,
            debug=(request.args.get("debug", "0").strip() in {"1", "true", "yes"}),
        )
        # The overall chart only consumes session-level aggregates.  Per-set
        # comparison details make this response several megabytes large and
        # delay JSON transfer/parsing without affecting the visualization.
        if request.args.get("debug", "0").strip() not in {"1", "true", "yes"}:
            for point in payload.get("points") or []:
                point.pop("set_comparisons", None)
                point.pop("unmatched_reasons", None)
        return jsonify(payload)
    except Exception as e:
        print("❌ analyse/default_progress error:", e)
        return jsonify(
            {
                "points": [],
                "meta": {
                    "mode": "session",
                    "trend_window_sessions": 6,
                    "rule_version": "progression_rules_v3",
                    "baseline_lookback_sessions": None,
                    "min_comparable_per_session": 1,
                    "coverage": None,
                    "low_comparable_sessions_count": 0,
                    "avg_comparable": None,
                    "plan_change_flag": False,
                },
            }
        ), 500
    finally:
        conn.close()


@app.route("/api/analysis/exercise_history")
def api_exercise_history():
    exercise = (request.args.get("exercise") or "").strip()
    device   = (request.args.get("device") or "").strip()

    if not exercise:
        return jsonify([])

    # ---- special mapping: some UIs send bilat/unilat via "device" (e.g. Pushdowns) ----
    dev_low = device.strip().lower()

    laterality = None
    device_arg = device

    if dev_low in ("bilat", "bilateral"):
        laterality = "bilateral"
        device_arg = None   # ignore device filter in this case
    elif dev_low in ("unilat", "unilateral"):
        laterality = "unilateral"
        device_arg = None

    # also accept explicit laterality param if you ever send it
    lat_raw = (request.args.get("laterality") or "").strip().lower()
    if lat_raw in ("bilat", "bilateral"):
        laterality = "bilateral"
    elif lat_raw in ("unilat", "unilateral"):
        laterality = "unilateral"
    elif lat_raw:
        laterality = lat_raw

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        days_raw = (request.args.get("days") or "all").strip().lower()
        start_iso = (request.args.get("start") or "").strip() or (None if days_raw == "all" else (date.today() - timedelta(days=_clamp_int(days_raw, 1, 3650, 180) - 1)).isoformat())
        end_iso = (request.args.get("end") or "").strip() or None
        data = get_exercise_history(
            conn,
            exercise=exercise,
            device=device_arg,        # None -> no device filter
            laterality=laterality,    # bilateral/unilateral -> correct split
            start_iso=start_iso,
            end_iso=end_iso,
        )
        return jsonify(data)
    finally:
        conn.close()



@app.route("/api/analysis/exercise_progress")
def api_exercise_progress():
    from analysis.training_analysis import compute_trend_from_history
    exercise = request.args.get("exercise", "").strip()
    device = request.args.get("device", "").strip()
    laterality = (request.args.get("laterality") or "").strip() or None

    if not exercise or not device:
        return jsonify({"status": "neutral", "trend": "neutral", "reason": "missing_params"})

    dev_low = device.lower()
    device_arg = device
    if dev_low in ("bilat", "bilateral"):
        laterality = "bilateral"
        device_arg = None
    elif dev_low in ("unilat", "unilateral"):
        laterality = "unilateral"
        device_arg = None

    conn = get_training_db()
    conn.row_factory = sqlite3.Row

    days_raw = (request.args.get("days") or "all").strip().lower()
    start_iso = (request.args.get("start") or "").strip() or (None if days_raw == "all" else (date.today() - timedelta(days=_clamp_int(days_raw, 1, 3650, 180) - 1)).isoformat())
    end_iso = (request.args.get("end") or "").strip() or None
    raw = get_exercise_history(conn, exercise, device_arg, laterality, start_iso=start_iso, end_iso=end_iso)
    conn.close()

    # sqlite row -> dict, nulls filtern
    def to_num(x):
        try:
            if x is None:
                return None
            return float(x)
        except Exception:
            return None

    history = []
    for r in (raw or []):
        try:
            d = dict(r)
        except Exception:
            d = r

        w = to_num(d.get("weight"))
        reps = to_num(d.get("reps"))
        if w is None or reps is None:
            continue

        d["weight"] = w
        d["reps"] = reps
        history.append(d)

    if len(history) < 2:
        return jsonify({
            "status": "neutral",
            "trend": "neutral",
            "reason": "not_enough_data"
        })

    prev = history[-2]
    last = history[-1]

    identity = {
        "exercise_name": exercise,
        "canonical_exercise": exercise,
        "device": device_arg or "",
        "variation": last.get("variation") or prev.get("variation") or "",
        "laterality": laterality or "bilateral",
    }
    comparison = compare_set_progress(
        normalize_set_performance({**last, **identity}) or SetPerformance(**identity),
        normalize_set_performance({**prev, **identity}),
        match_level="exercise_progress_history",
    )
    if comparison.status == "progress":
        status = "progress"
    elif comparison.status == "regress":
        status = "regress"
    else:
        status = "neutral"


    # TREND (4 Sessions)
    trend = compute_trend_from_history(history, lookback=4)

    return jsonify({
        "status": status,
        "trend": trend,
        "reason_code": comparison.reason_code,
        "reason_text": comparison.reason_text,
        "latest": last,
        "previous": prev
    })


@app.get("/api/analyse/trend_radar")
def api_analyse_trend_radar():
    tz = ZoneInfo("Europe/Berlin")

    def parse_days(name: str, default: int, lo: int = 3, hi: int = 365) -> int:
        raw = (request.args.get(name) or "").strip()
        if not raw:
            return default
        try:
            val = int(raw)
        except Exception:
            return default
        return max(lo, min(hi, val))

    days = parse_days("days", 28, lo=7, hi=180)
    baseline_days = parse_days("baseline_days", 28, lo=7, hi=365)
    trend_days = parse_days("trend_days", 7, lo=3, hi=90)

    end_raw = (request.args.get("end") or "").strip()
    end_date = datetime.now(tz).date()
    if end_raw:
        try:
            end_date = datetime.strptime(end_raw, "%Y-%m-%d").date()
        except Exception:
            end_date = datetime.now(tz).date()

    def fallback_payload() -> dict:
        dates = [(end_date - timedelta(days=days - 1) + timedelta(days=i)).isoformat() for i in range(days)]
        chips = []
        metrics = {}
        for key in METRICS_ORDER:
            chips.append({
                "key": key,
                "label": METRIC_META.get(key, {}).get("label", key.title()),
                "unit": METRIC_META.get(key, {}).get("unit", ""),
                "value_7d": None,
                "value_baseline": None,
                "delta_pct": None,
                "direction": "na",
                "note": "zu wenig Baseline",
                "missing": True,
                "baseline_ok": False,
            })
            metrics[key] = {
                "raw": [None for _ in dates],
                "index": [None for _ in dates],
                "index_daily": [None for _ in dates],
                "index_7d": [None for _ in dates],
                "band": {"low": 95.0, "high": 105.0},
                "baseline_mean": None,
                "baseline_ok": False,
                "chart_default": False if key == "cardio" else True,
            }
        return {
            "meta": {
                "end_date": end_date.isoformat(),
                "days": days,
                "baseline_days": baseline_days,
                "trend_days": trend_days,
                "timezone": "Europe/Berlin",
                "data_freshness": {
                    "weight_last": None,
                    "hrv_last": None,
                    "training_last": None,
                    "nutrition_last": None,
                    "cardio_last": None,
                },
            },
            "status": {
                "level": "yellow",
                "headline": "Trend Radar: zu wenig Daten",
                "reasons": [],
            },
            "chips": chips,
            "series": {
                "dates": dates,
                "metrics": metrics,
            },
            "flags": [],
        }

    tr_conn = None
    nu_conn = None
    hrv_conn = None
    runs_conn = None
    try:
        tr_conn = get_training_db()
        nu_conn = get_nutrition_db()
        hrv_conn = get_hrv_db()
        runs_conn = get_runs_db()
        payload = build_trend_radar_payload(
            tr_conn,
            nu_conn,
            hrv_conn,
            runs_conn,
            end_date=end_date,
            days=days,
            baseline_days=baseline_days,
            trend_days=trend_days,
        )
        return jsonify(payload)
    except Exception as e:
        print("❌ trend_radar error:", e)
        traceback.print_exc()
        return jsonify(fallback_payload())
    finally:
        for conn in (tr_conn, nu_conn, hrv_conn, runs_conn):
            try:
                if conn is not None:
                    conn.close()
            except Exception:
                pass


