def sanitize_plan_payload(data: dict):
    """
    Produces a valid plan object:
    - base_week always 7 items, each with required keys
    - weeks length == block_length with correct week numbering
    - meta always exists
    - ensure_row_ids applied at end
    """
    data = data or {}

    # base_week
    base_week = data.get("base_week") or []
    day_names = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]

    # normalize each existing day entry
    normed = []
    for i, d in enumerate(base_week[:7]):
        d = d or {}
        normed.append({
            "day": d.get("day") or day_names[i],
            "session_name": d.get("session_name") or "",
            "strength_exercises": d.get("strength_exercises") or [],
            "run_sessions": d.get("run_sessions") or [],
        })

    # pad to 7 days
    while len(normed) < 7:
        i = len(normed)
        normed.append({
            "day": day_names[i],
            "session_name": "",
            "strength_exercises": [],
            "run_sessions": [],
        })

    # block_length
    weeks_in = data.get("weeks") or []
    block_len = data.get("block_length")
    if block_len is None:
        block_len = len(weeks_in) if weeks_in else 4

    try:
        block_len = int(block_len)
    except Exception:
        block_len = 4
    block_len = max(1, min(block_len, 52))  # sane bounds

    # weeks
    if not weeks_in:
        weeks_in = (build_default_plan() or {}).get("weeks") or []

    weeks = []
    for w in weeks_in[:block_len]:
        w = w or {}
        weeks.append({
            "week": w.get("week"),  # overwritten below
            "strength_volume_factor": w.get("strength_volume_factor", 1.0),
            "run_volume_factor": w.get("run_volume_factor", 1.0),
            "deload": bool(w.get("deload", False)),
            "rpe_cap": w.get("rpe_cap", None),
            "week_note": w.get("week_note", ""),
        })

    # pad missing weeks up to block_len
    while len(weeks) < block_len:
        weeks.append({
            "week": None,
            "strength_volume_factor": 1.0,
            "run_volume_factor": 1.0,
            "deload": False,
            "rpe_cap": None,
            "week_note": "",
        })

    # enforce correct week numbering
    for idx, w in enumerate(weeks, start=1):
        w["week"] = idx

    meta = _clean_plan_meta(data.get("meta"), block_len)

    plan = {
        "name": (data.get("name") or "Neuer Split"),
        "block_length": block_len,
        "base_week": normed,
        "weeks": weeks,
        "meta": meta,
    }

    return ensure_row_ids(plan)


def _clean_plan_meta(meta, block_len: int | None = None):
    if not isinstance(meta, dict):
        meta = {}

    cleaned = dict(meta)

    def clean_date(val):
        if not isinstance(val, str):
            return None
        val = val.strip()
        try:
            return datetime.strptime(val, "%Y-%m-%d").date().isoformat()
        except Exception:
            return None

    def clean_int(val, min_val, max_val):
        try:
            num = int(val)
        except Exception:
            return None
        return max(min_val, min(max_val, num))

    start_date = clean_date(cleaned.get("start_date"))
    if start_date is not None:
        cleaned["start_date"] = start_date
    elif "start_date" in cleaned:
        cleaned["start_date"] = None

    total_weeks = clean_int(cleaned.get("total_weeks"), 1, 260)
    if total_weeks is not None:
        cleaned["total_weeks"] = total_weeks
    else:
        cleaned.setdefault("total_weeks", 8)

    block_length = clean_int(cleaned.get("block_length"), 1, 52)
    if block_length is not None:
        cleaned["block_length"] = block_length
    elif block_len is not None:
        cleaned["block_length"] = block_len

    week_override = clean_int(cleaned.get("week_override"), 1, (cleaned.get("total_weeks") or total_weeks or 260))
    cleaned["week_override"] = week_override

    week_type_override = cleaned.get("week_type_override")
    if isinstance(week_type_override, str):
        week_type_override = week_type_override.strip().lower()
    if week_type_override not in ("build", "deload", "overreach"):
        week_type_override = None
    cleaned["week_type_override"] = week_type_override

    if "rpe_cap_by_type" in cleaned and not isinstance(cleaned.get("rpe_cap_by_type"), dict):
        cleaned.pop("rpe_cap_by_type", None)
    if "volume_mult_by_type" in cleaned and not isinstance(cleaned.get("volume_mult_by_type"), dict):
        cleaned.pop("volume_mult_by_type", None)

    if "goal" not in cleaned:
        cleaned["goal"] = ""
    if "priorities" not in cleaned or not isinstance(cleaned.get("priorities"), list):
        cleaned["priorities"] = []

    return cleaned


def _ensure_plan_start_date(plan: dict, *, today_iso: str | None = None) -> bool:
    if not isinstance(plan, dict):
        return False
    meta = plan.get("meta")
    if not isinstance(meta, dict):
        meta = {}
        plan["meta"] = meta
    start_date = meta.get("start_date")
    if isinstance(start_date, str) and start_date.strip():
        return False
    meta["start_date"] = today_iso or date.today().isoformat()
    return True


def plan_row_to_dict(row):
    plan = plan_from_row(row)
    plan = ensure_row_ids(plan)
    return plan


DAY_ORDER = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"]


def _load_json_obj(raw: str | None) -> dict:
    try:
        data = json.loads(raw) if raw else {}
    except Exception:
        data = {}
    return data if isinstance(data, dict) else {}


def _load_gym_plan_json(raw: str | dict | None) -> dict:
    data = raw if isinstance(raw, dict) else _load_json_obj(raw)
    return _ensure_plan_shape(data)


def _normalize_gym_rules_json(raw: dict | None, weeks: int) -> dict:
    defaults = default_rules_json(weeks)
    active_week = "W1"
    merged = dict(defaults)
    if not isinstance(raw, dict):
        return {"active_week": active_week, "weeks": merged}

    nested_weeks = raw.get("weeks") if isinstance(raw.get("weeks"), dict) else None
    source = nested_weeks if isinstance(nested_weeks, dict) else raw
    for wk in defaults.keys():
        row = source.get(wk) if isinstance(source, dict) else None
        if isinstance(row, dict):
            merged[wk] = {**merged[wk], **row}
            if "cardio_factor" not in merged[wk]:
                merged[wk]["cardio_factor"] = merged[wk].get("run_factor", 1.0)

    aw = raw.get("active_week")
    if isinstance(aw, str) and aw in merged:
        active_week = aw
    return {"active_week": active_week, "weeks": merged}


def _row_to_gym_plan(row: sqlite3.Row) -> dict:
    plan_json = _load_gym_plan_json(row["plan_json"] if "plan_json" in row.keys() else None)
    rules_json = _normalize_gym_rules_json(_load_json_obj(row["rules_json"] if "rules_json" in row.keys() else None), int(plan_json.get("weeks") or 8))
    blocks_json = default_blocks_json()
    blocks_json.update(_load_json_obj(row["blocks_json"] if "blocks_json" in row.keys() else None))
    meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    title = (row["title"] or "").strip() if "title" in row.keys() else ""
    focus = (row["focus"] or "").strip() if "focus" in row.keys() else ""
    if title:
        meta["title"] = title
    if focus or "focus" not in meta:
        meta["focus"] = focus
    plan_json["meta"] = meta
    return {
        "id": row["id"],
        "name": title or meta.get("title") or "Gym Plan",
        "title": title or meta.get("title") or "Gym Plan",
        "focus": focus or meta.get("focus") or "",
        "meta": {"name": title or meta.get("title") or "Gym Plan", "focus": focus or meta.get("focus") or ""},
        "is_active": bool(row["is_active"]),
        "is_archived": bool(row["is_archived"]),
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
        "plan_json": plan_json,
        "rules_json": rules_json,
        "blocks_json": blocks_json,
    }


def _gym_plan_summary(plan_json: dict) -> dict:
    days = plan_json.get("days") if isinstance(plan_json.get("days"), list) else []
    sequence = plan_json.get("sequence") if isinstance(plan_json.get("sequence"), list) else []
    rolling = str(((plan_json.get("meta") or {}).get("mode")) or "").strip().lower() == "rolling_sequence"
    events = 0
    exercises = 0
    runs = 0
    rest = 0
    event_groups = [("sequence", sequence)] if rolling else [(day.get("day"), day.get("events") or []) for day in days if isinstance(day, dict)]
    for _group_name, group_events in event_groups:
        for event in group_events:
            if not isinstance(event, dict):
                continue
            events += 1
            kind = (event.get("kind") or "").strip().lower()
            if kind == "gym":
                exercises += sum(1 for item in (event.get("items") or []) if isinstance(item, dict) and item.get("kind") == "exercise")
            elif kind == "cardio" or kind in {"run", "ergo", "bike", "row", "swim"}:
                runs += 1
            elif kind == "rest":
                rest += 1
    return {
        "days": len(days),
        "events": events,
        "exercise_items": exercises,
        "run_events": runs,
        "rest_events": rest,
        "weeks": int(plan_json.get("weeks") or 8),
    }


def _gym_plan_cycle_status(plan_json: dict, rules_json: dict, *, today: date | None = None) -> dict:
    meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    periodization_enabled = bool(meta.get("periodization_enabled"))
    weeks_total = int(meta.get("total_weeks") or plan_json.get("weeks") or 8)
    weeks_total = max(1, min(260, weeks_total))
    week_label = "W1"
    week_current = 1
    phase_label = "BUILD"
    start_date = meta.get("start_date")
    loop_cycle = bool(meta.get("loop_cycle"))
    ref_today = today or date.today()

    week_override = meta.get("week_override")
    try:
        if week_override is not None and str(week_override).strip() != "":
            week_current = int(week_override)
        else:
            if isinstance(start_date, str) and start_date.strip():
                start_d = datetime.strptime(start_date.strip(), "%Y-%m-%d").date()
                # Align with dashboard logic:
                # week 1 starts on the first Monday on/after start_date.
                weekday = start_d.weekday()  # Mo=0..So=6
                week1_start = start_d if weekday == 0 else (start_d + timedelta(days=(7 - weekday)))
                if ref_today < week1_start:
                    week_current = 1
                else:
                    week_current = ((ref_today - week1_start).days // 7) + 1
            else:
                week_current = 1
    except Exception:
        week_current = 1
    if loop_cycle and week_current > 0:
        week_current = ((week_current - 1) % weeks_total) + 1
    else:
        week_current = max(1, min(weeks_total, week_current))
    week_label = f"W{week_current}"

    week_types = meta.get("week_types") if isinstance(meta.get("week_types"), dict) else {}
    if week_label in week_types and isinstance(week_types[week_label], str) and week_types[week_label].strip():
        phase_label = week_types[week_label].strip().upper()
    else:
        rules_weeks = rules_json.get("weeks") if isinstance(rules_json.get("weeks"), dict) else {}
        row = rules_weeks.get(week_label) if isinstance(rules_weeks.get(week_label), dict) else {}
        if isinstance(row.get("tag"), str) and row.get("tag", "").strip():
            phase_label = row["tag"].strip().upper()
        elif bool(row.get("deload")):
            phase_label = "DELOAD"
        else:
            # Smart fallback: week before deload is usually the overreach peak.
            next_label = f"W{min(weeks_total, week_current + 1)}"
            next_row = rules_weeks.get(next_label) if isinstance(rules_weeks.get(next_label), dict) else {}
            if week_current < weeks_total and bool(next_row.get("deload")):
                phase_label = "OVERREACH"
            else:
                phase_label = "BUILD"

    return {
        "week_current": week_current,
        "week_total": weeks_total,
        "week_label": week_label if periodization_enabled else "",
        "phase_label": phase_label if periodization_enabled else "",
        "display": (f"Woche {week_current}/{weeks_total} · {phase_label}" + (" · LOOP" if loop_cycle else "")) if periodization_enabled else "",
        "start_date": start_date if isinstance(start_date, str) else None,
        "loop_cycle": loop_cycle,
        "periodization_enabled": periodization_enabled,
    }


def _dashboard_plan_week_from_cycle(cycle: dict, plan_json: dict | None = None) -> dict | None:
    if not isinstance(cycle, dict) or cycle.get("week_current") is None:
        return None
    if cycle.get("periodization_enabled") is False:
        return None
    phase_label = _normalize_block_phase(cycle.get("phase_label"))
    week_type = {
        "BUILD": "build",
        "OVERREACH": "overreach",
        "DELOAD": "deload",
        "OFF": "off",
    }.get(phase_label, "build")
    week_current = int(cycle.get("week_current") or 1)
    total_weeks = int(cycle.get("week_total") or 1)
    meta = plan_json.get("meta") if isinstance(plan_json, dict) and isinstance(plan_json.get("meta"), dict) else {}
    block_length = meta.get("block_length") or total_weeks
    try:
        block_length = max(1, int(block_length))
    except Exception:
        block_length = total_weeks
    return {
        "week_current": week_current,
        "total_weeks": total_weeks,
        "block_length": block_length,
        "week_in_block": ((week_current - 1) % block_length) + 1,
        "week_type": week_type,
        "phase_label": phase_label,
    }


def _dashboard_plan_week_from_active_gym(*, today: date | None = None) -> dict | None:
    active_gym = _get_active_gym_plan_record()
    if not active_gym:
        return None
    plan_json = active_gym.get("plan_json") if isinstance(active_gym.get("plan_json"), dict) else {}
    rules_json = active_gym.get("rules_json") if isinstance(active_gym.get("rules_json"), dict) else {}
    cycle = _gym_plan_cycle_status(plan_json, rules_json, today=today)
    return _dashboard_plan_week_from_cycle(cycle, plan_json)


def _legacy_dashboard_plan_week(plan: dict | None, *, today: date | None = None) -> dict | None:
    if not plan:
        return None
    try:
        meta = plan.get("meta") or {}
        if not bool(meta.get("periodization_enabled")):
            return None
        start_date_iso = meta.get("start_date")
        if not start_date_iso:
            return None
        start_d = datetime.strptime(start_date_iso, "%Y-%m-%d").date()
        today_d = today or date.today()
        days = (today_d - start_d).days
        if days < 0:
            return None

        block_length = int(meta.get("block_length") or 4)
        total_weeks_raw = meta.get("total_weeks")
        try:
            total_weeks = int(total_weeks_raw) if total_weeks_raw is not None else None
        except Exception:
            total_weeks = None

        weekday = start_d.weekday()
        week1_start = start_d if weekday == 0 else (start_d + timedelta(days=(7 - weekday)))
        week_current = 1 if today_d < week1_start else ((today_d - week1_start).days // 7) + 1

        if meta.get("week_override") is not None:
            try:
                week_current = int(meta["week_override"])
            except Exception:
                pass

        week_in_block = ((week_current - 1) % block_length) + 1
        wto = meta.get("week_type_override")
        if wto:
            week_type = str(wto).strip().lower()
        elif week_in_block == block_length:
            week_type = "deload"
        elif week_in_block == (block_length - 1):
            week_type = "overreach"
        else:
            week_type = "build"

        phase_label = {
            "build": "BUILD",
            "overreach": "OVERREACH",
            "deload": "DELOAD",
        }.get(week_type, "")
        return {
            "week_current": week_current,
            "total_weeks": total_weeks,
            "block_length": block_length,
            "week_in_block": week_in_block,
            "week_type": week_type,
            "phase_label": phase_label,
        }
    except Exception:
        return None


