def _normalize_block_phase(raw: str | None) -> str:
    txt = str(raw or "").strip().upper()
    if txt in {"BUILD", "BASE"}:
        return "BUILD"
    if txt in {"OVERREACH", "INTENSIV", "PEAK"}:
        return "OVERREACH"
    if txt in {"DELOAD", "TAPER"}:
        return "DELOAD"
    return "OFF"


def _get_active_gym_plan_record() -> dict | None:
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        """
        SELECT id, title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at
        FROM gym_plans
        WHERE is_active = 1 AND is_archived = 0
        ORDER BY updated_at DESC, id DESC
        LIMIT 1
        """
    ).fetchone()
    conn.close()
    if not row:
        return None
    return _row_to_gym_plan(row)


def _block_status_phase_for_week(plan_json: dict, rules_json: dict, week_index: int, *, today: date) -> str:
    cloned = dict(plan_json or {})
    meta_src = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    meta = dict(meta_src)
    meta["week_override"] = int(week_index)
    cloned["meta"] = meta
    cycle = _gym_plan_cycle_status(cloned, rules_json, today=today)
    return _normalize_block_phase(cycle.get("phase_label"))


def _block_status_days_until_next_week(plan_json: dict, *, today: date) -> int | None:
    meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    start_date = meta.get("start_date")
    if not isinstance(start_date, str) or not start_date.strip():
        return None
    try:
        start_d = datetime.strptime(start_date.strip(), "%Y-%m-%d").date()
    except Exception:
        return None
    weekday = start_d.weekday()  # Mo=0..So=6
    week1_start = start_d if weekday == 0 else (start_d + timedelta(days=(7 - weekday)))
    if today < week1_start:
        return max(1, (week1_start - today).days)
    day_in_week = (today - week1_start).days % 7
    return 7 if day_in_week == 0 else (7 - day_in_week)


def _block_status_milestone_text(phase: str, cycle: dict, plan_json: dict, rules_json: dict, *, today: date) -> str:
    week_current = int(cycle.get("week_current") or 1)
    week_total = int(cycle.get("week_total") or 1)
    days_to_next = _block_status_days_until_next_week(plan_json, today=today)

    next_change_week = None
    next_change_phase = None
    for w in range(week_current + 1, week_total + 1):
        ph = _block_status_phase_for_week(plan_json, rules_json, w, today=today)
        if ph != phase:
            next_change_week = w
            next_change_phase = ph
            break

    if next_change_week and next_change_phase == "DELOAD":
        if days_to_next is not None and next_change_week == week_current + 1:
            return f"Woche {next_change_week} startet in {days_to_next} Tagen → Deload"
        return f"Woche {next_change_week} ist der nächste Deload."

    if phase == "DELOAD":
        if next_change_week:
            if days_to_next is not None and next_change_week == week_current + 1:
                return f"Woche {next_change_week} startet in {days_to_next} Tagen → Build"
            return f"Nächster Build in Woche {next_change_week}."
        return "Deload abschließen und den nächsten Build sauber ansetzen."

    if next_change_week and days_to_next is not None and next_change_week == week_current + 1:
        return f"Woche {next_change_week} startet in {days_to_next} Tagen."

    weeks_left = max(0, week_total - week_current)
    if weeks_left:
        return f"Blockabschluss in {weeks_left} Woche{'n' if weeks_left != 1 else ''}."
    return "Blockabschluss in dieser Woche."


def _block_status_days_until_deload(cycle: dict, plan_json: dict, rules_json: dict, *, today: date) -> int | None:
    week_current = int(cycle.get("week_current") or 1)
    week_total = int(cycle.get("week_total") or 1)
    if _normalize_block_phase(cycle.get("phase_label")) == "DELOAD":
        return 0

    next_deload_week = None
    for w in range(week_current + 1, week_total + 1):
        ph = _block_status_phase_for_week(plan_json, rules_json, w, today=today)
        if ph == "DELOAD":
            next_deload_week = w
            break
    if next_deload_week is None:
        return None

    days_to_next = _block_status_days_until_next_week(plan_json, today=today)
    if days_to_next is None:
        return None
    return days_to_next + max(0, (next_deload_week - week_current - 1)) * 7


def _block_status_expectation_text(phase: str, cycle: dict, plan_json: dict, rules_json: dict, *, today: date) -> str:
    week_current = int(cycle.get("week_current") or 1)
    week_total = int(cycle.get("week_total") or 1)
    days_to_deload = _block_status_days_until_deload(cycle, plan_json, rules_json, today=today)
    last_week_before_deload = (
        (days_to_deload is not None and days_to_deload <= 3)
        or (week_current == max(1, week_total - 1))
    )

    if phase == "DELOAD":
        return "Normal: stabilisieren, nicht pushen; Entlastung ist das Ziel."
    if phase == "OVERREACH":
        return "Normal: mehrere stabile Tage (=); vereinzelt leicht schlechter (↓) ist eingeplant."
    if last_week_before_deload:
        return "Normal: Viel '='; vereinzelte '↓' möglich. Ziel ist halten, nicht pushen."
    return "Normal: meist stabil (=); vereinzelt leicht besser (↑)."


def _block_status_last_week_before_deload(cycle: dict, plan_json: dict, rules_json: dict, *, today: date) -> tuple[bool, int | None]:
    week_current = int(cycle.get("week_current") or 1)
    week_total = int(cycle.get("week_total") or 1)
    days_to_deload = _block_status_days_until_deload(cycle, plan_json, rules_json, today=today)
    return (
        ((days_to_deload is not None and days_to_deload <= 3) or (week_current == max(1, week_total - 1))),
        days_to_deload,
    )


def _block_status_job_line(phase: str, *, last_week_before_deload: bool) -> str:
    if phase == "DELOAD":
        return "Job: Entlasten. Technik sauber halten."
    if phase == "OVERREACH" or last_week_before_deload:
        return "Job: Qualität halten. Kein Push mehr."
    if phase == "BUILD":
        return "Job: Qualität sauber steigern."
    return "Job: Plan wählen und aktivieren."


def _block_status_chip_expectation(phase: str, *, last_week_before_deload: bool) -> str:
    if phase == "DELOAD":
        return "Erwartung: ↗ / stabil"
    if phase == "OVERREACH" or last_week_before_deload:
        return "Erwartung: = / ↓ ok"
    return "Erwartung: stabil / leicht ↑"


def _block_status_chip_guardrail(week_row: dict) -> str:
    try:
        cap = float(week_row.get("rpe_cap")) if week_row.get("rpe_cap") is not None else None
    except Exception:
        cap = None
    if cap is not None:
        return f"Leitplanke: RPE ≤ {_fmt_num(cap)}"
    return "Leitplanke: Planvorgaben einhalten"




def _block_status_status_line(plan_name: str, cycle: dict, phase: str, *, days_to_deload: int | None) -> str:
    week_current = int(cycle.get("week_current") or 1)
    week_total = int(cycle.get("week_total") or 1)
    base = f"{plan_name} · Woche {week_current}/{week_total} · Phase {phase}"
    if phase == "DELOAD":
        return f"{base} → Deload läuft"
    if days_to_deload is not None and days_to_deload > 0:
        unit = "Tag" if int(days_to_deload) == 1 else "Tagen"
        return f"{base} → Deload in {days_to_deload} {unit}"
    return base


def _block_status_hrv_fit(*, phase: str, last_week_before_deload: bool) -> dict:
    expect = "stabil"
    if last_week_before_deload:
        expect = "↓ oder stabil"
    elif phase == "OVERREACH":
        expect = "↓"
    elif phase == "DELOAD":
        expect = "↗/stabil"

    try:
        conn = get_hrv_db()
        rows = conn.execute(
            """
            SELECT
                COALESCE(substr(date_utc, 1, 10), substr(ts_measurement, 1, 10)) AS day,
                rmssd,
                hr
            FROM hrv_measurements
            WHERE COALESCE(substr(date_utc, 1, 10), substr(ts_measurement, 1, 10)) >= date('now', '-35 days')
              AND rmssd IS NOT NULL
              AND hr IS NOT NULL
            ORDER BY day ASC, ts_measurement ASC
            """
        ).fetchall()
        conn.close()
    except Exception:
        rows = []

    by_day: dict[str, dict] = {}
    for row in rows:
        day = row["day"]
        if not day:
            continue
        by_day[day] = {"rmssd": _to_optional_float(row["rmssd"]), "hr": _to_optional_float(row["hr"])}
    points = [by_day[k] for k in sorted(by_day.keys()) if by_day[k].get("rmssd") is not None and by_day[k].get("hr") is not None]

    hrv_flags = _load_hrv_flags(days=5)
    sick = bool((hrv_flags or {}).get("sickness"))

    if len(points) < 6:
        return {
            "expected": expect,
            "observed": "keine Daten",
            "verdict": "neutral",
            "line": "HRV: keine Daten",
            "critical_cause": None,
        }

    rmssd_vals = [float(p["rmssd"]) for p in points]
    hr_vals = [float(p["hr"]) for p in points]
    recent_rmssd = _mean(rmssd_vals[-3:])
    base_rmssd = _mean(rmssd_vals[-17:-3]) if len(rmssd_vals) >= 10 else _mean(rmssd_vals[:-3])
    recent_rhr = _mean(hr_vals[-3:])
    base_rhr = _mean(hr_vals[-17:-3]) if len(hr_vals) >= 10 else _mean(hr_vals[:-3])

    rmssd_down = False
    rmssd_up = False
    if recent_rmssd is not None and base_rmssd not in (None, 0):
        ratio = recent_rmssd / base_rmssd
        rmssd_down = ratio <= 0.94
        rmssd_up = ratio >= 1.06

    rhr_high = False
    if recent_rhr is not None and base_rhr not in (None, 0):
        rhr_high = (recent_rhr - base_rhr) >= 4.0 or (recent_rhr / base_rhr) >= 1.06

    observed = "stabil"
    critical_cause = None
    if sick or rhr_high:
        observed = "↓ (krank/RHR↑)"
        critical_cause = "krank/RHR↑"
    elif rmssd_down and not rmssd_up:
        observed = "↓"
    elif rmssd_up and not rmssd_down:
        observed = "↑"
    else:
        last7 = rmssd_vals[-7:] if len(rmssd_vals) >= 7 else rmssd_vals
        if base_rmssd and len(last7) >= 5:
            signs = []
            for v in last7:
                if v >= base_rmssd * 1.05:
                    signs.append(1)
                elif v <= base_rmssd * 0.95:
                    signs.append(-1)
                else:
                    signs.append(0)
            non_zero = [s for s in signs if s != 0]
            flips = 0
            for i in range(1, len(non_zero)):
                if non_zero[i] != non_zero[i - 1]:
                    flips += 1
            sustained_low = sum(1 for v in last7[-4:] if base_rmssd and v <= base_rmssd * 0.94) >= 3
            if flips >= 2 and not sustained_low and not rhr_high and not sick:
                observed = "volatil"
            else:
                observed = "stabil"

    # Verdict is plan-fit only.
    verdict = "neutral"
    if expect == "↗/stabil":
        if observed.startswith("↓"):
            verdict = "kritisch"
        elif observed in {"↑", "stabil"}:
            verdict = "passt"
        else:
            verdict = "neutral"
    elif expect == "stabil":
        if observed in {"stabil", "↑"}:
            verdict = "passt"
        elif observed.startswith("↓"):
            verdict = "kritisch"
        else:
            verdict = "neutral"
    elif expect == "↓":
        if observed.startswith("↓"):
            verdict = "passt"
        elif observed in {"↑", "stabil"}:
            verdict = "kritisch"
        else:
            verdict = "neutral"
    elif expect == "↓ oder stabil":
        if observed.startswith("↓") or observed == "stabil":
            verdict = "passt"
        elif observed == "↑":
            verdict = "kritisch"
        else:
            verdict = "neutral"

    observed_for_line = observed
    if critical_cause:
        observed_for_line = f"↓ ({critical_cause})"
    line = f"HRV: Erwartet {expect} · Ist {observed_for_line} · {verdict}"
    return {
        "expected": expect,
        "observed": observed,
        "verdict": verdict,
        "line": line,
        "critical_cause": critical_cause,
    }


def _block_status_rules(template_rules: list[str], week_row: dict) -> list[str]:
    rules: list[str] = []
    cap = None
    try:
        cap = float(week_row.get("rpe_cap")) if week_row.get("rpe_cap") is not None else None
    except Exception:
        cap = None
    if cap is not None:
        rules.append(f"Topsätze nicht über RPE {_fmt_num(cap)}.")

    volume = None
    try:
        volume = float(week_row.get("strength_factor")) if week_row.get("strength_factor") is not None else None
    except Exception:
        volume = None
    if volume is not None and abs(volume - 1.0) >= 0.01:
        pct = int(round(volume * 100))
        if volume < 1.0:
            rules.append(f"Wochenvolumen bei {pct}% halten.")
        else:
            rules.append(f"Wochenvolumen bei {pct}% deckeln, keine Extras.")

    for rule in (template_rules or []):
        if len(rules) >= 3:
            break
        txt = str(rule or "").strip()
        if txt and txt not in rules:
            rules.append(txt)

    while len(rules) < 3:
        rules.append("Planvorgaben halten, keine Zusatz-Eskalation.")

    clipped: list[str] = []
    for rule in rules[:3]:
        txt = re.sub(r"\s+", " ", str(rule or "").strip())
        if len(txt) > 70:
            txt = txt[:69].rstrip() + "…"
        clipped.append(txt)
    return clipped


def _block_status_event_snapshot(legacy_plan_id: int | None, *, today: date) -> dict:
    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    try:
        since_dt = datetime.combine(today - timedelta(days=6), datetime.min.time(), tzinfo=timezone.utc)
        since_epoch = int(since_dt.timestamp())
        since_day_iso = (today - timedelta(days=6)).isoformat()
        override_rows = conn.execute(
            """
            SELECT LOWER(COALESCE(decision_type, '')) AS decision_type, user_override_bool
            FROM override_log
            WHERE ts >= ?
            """,
            (since_epoch,),
        ).fetchall()
        explicit_types = {
            "manual_override",
            "autopilot_override",
            "target_override",
            "volume_intensity_override",
            "skip_rest_override",
        }
        type_counts = {k: 0 for k in explicit_types}
        for row in override_rows:
            dt = str(row["decision_type"] or "").strip().lower()
            if dt in explicit_types:
                type_counts[dt] = int(type_counts.get(dt, 0) or 0) + 1
        override_count_7d = sum(type_counts.values())

        params: list[object] = []
        where = ""
        if legacy_plan_id is not None:
            where = "WHERE pc.plan_id = ?"
            params.append(int(legacy_plan_id))
        rows = conn.execute(
            f"""
            SELECT pc.payload, pc.flags_json, pc.status, w.date_iso, w.id AS workout_id
            FROM plan_checks pc
            JOIN workouts w ON w.id = pc.workout_id
            {where}
            ORDER BY w.date_iso DESC, w.id DESC
            LIMIT 3
            """,
            tuple(params),
        ).fetchall()

        rows_7d = conn.execute(
            f"""
            SELECT pc.payload, pc.flags_json, pc.status, w.date_iso, w.id AS workout_id
            FROM plan_checks pc
            JOIN workouts w ON w.id = pc.workout_id
            {("WHERE pc.plan_id = ? AND w.date_iso >= ?" if legacy_plan_id is not None else "WHERE w.date_iso >= ?")}
            ORDER BY w.date_iso DESC, w.id DESC
            LIMIT 42
            """,
            (int(legacy_plan_id), since_day_iso) if legacy_plan_id is not None else (since_day_iso,),
        ).fetchall()

        def _rpe_breach_from_payload(payload_obj: dict) -> float:
            if not isinstance(payload_obj, dict):
                return 0.0
            cap = None
            try:
                adj = payload_obj.get("adjustments") if isinstance(payload_obj.get("adjustments"), dict) else {}
                if adj.get("rpe_cap") is not None:
                    cap = float(adj.get("rpe_cap"))
            except Exception:
                cap = None

            max_done_rpe = None
            max_planned_rpe = None
            for ex in (payload_obj.get("exercises") or []):
                if not isinstance(ex, dict):
                    continue
                done = ex.get("done") if isinstance(ex.get("done"), dict) else {}
                try:
                    done_val = float(done.get("max_rpe")) if done.get("max_rpe") is not None else None
                except Exception:
                    done_val = None
                if done_val is not None:
                    max_done_rpe = done_val if max_done_rpe is None else max(max_done_rpe, done_val)

                planned = ex.get("planned") if isinstance(ex.get("planned"), dict) else {}
                planned_rpe_txt = str(planned.get("rpe") or "").strip()
                if planned_rpe_txt:
                    nums = []
                    for m in re.findall(r"\d+(?:\.\d+)?", planned_rpe_txt):
                        try:
                            nums.append(float(m))
                        except Exception:
                            continue
                    if nums:
                        pmax = max(nums)
                        max_planned_rpe = pmax if max_planned_rpe is None else max(max_planned_rpe, pmax)

            if cap is None:
                cap = max_planned_rpe
            if cap is None or max_done_rpe is None:
                return 0.0
            return max(0.0, float(max_done_rpe) - float(cap))

        recent_violations = 0
        rpe_cap_violations = 0
        rpe_cap_violations_7d = 0
        rpe_cap_max_breach = 0.0
        volume_over_violations = 0
        extra_violations = 0
        hard_outcomes: list[bool] = []
        volume_or_extra_seq: list[bool] = []
        for row in rows:
            flags = []
            try:
                parsed_flags = json.loads(row["flags_json"]) if row["flags_json"] else []
                if isinstance(parsed_flags, list):
                    flags = [str(x) for x in parsed_flags]
            except Exception:
                flags = []

            has_rpe_cap = any(f == "RPE zu hoch" for f in flags)
            has_volume_over = any(f in {"Volumen über Plan", "Volumen ueber Plan"} for f in flags)
            has_extra = any(f in {"Extra-Übungen", "Extra-Uebungen"} for f in flags)
            payload = {}
            try:
                payload = json.loads(row["payload"]) if row["payload"] else {}
            except Exception:
                payload = {}
            if not has_extra:
                exercises = payload.get("exercises") if isinstance(payload, dict) else []
                if isinstance(exercises, list):
                    has_extra = any(
                        isinstance(ex, dict) and str(ex.get("coverage") or "").strip().lower() == "extra"
                        for ex in exercises
                    )
            if has_rpe_cap:
                rpe_cap_max_breach = max(rpe_cap_max_breach, _rpe_breach_from_payload(payload))

            has_violation = has_rpe_cap or has_volume_over or has_extra
            if has_violation:
                recent_violations += 1
            if has_rpe_cap:
                rpe_cap_violations += 1
            if has_volume_over:
                volume_over_violations += 1
            if has_extra:
                extra_violations += 1
            hard_outcomes.append(bool(has_violation))
            volume_or_extra_seq.append(bool(has_volume_over or has_extra))

        escalated_two = len(hard_outcomes) >= 2 and hard_outcomes[0] and hard_outcomes[1]
        extra_volume_two_sessions = len(volume_or_extra_seq) >= 2 and volume_or_extra_seq[0] and volume_or_extra_seq[1]

        for row in rows_7d:
            flags = []
            try:
                parsed_flags = json.loads(row["flags_json"]) if row["flags_json"] else []
                if isinstance(parsed_flags, list):
                    flags = [str(x) for x in parsed_flags]
            except Exception:
                flags = []
            has_rpe_cap = any(f == "RPE zu hoch" for f in flags)
            if not has_rpe_cap:
                continue
            rpe_cap_violations_7d += 1
            try:
                payload = json.loads(row["payload"]) if row["payload"] else {}
            except Exception:
                payload = {}
            rpe_cap_max_breach = max(rpe_cap_max_breach, _rpe_breach_from_payload(payload))

        drift_reason = None
        if override_count_7d >= 3:
            auto_n = int(type_counts.get("autopilot_override", 0))
            target_n = int(type_counts.get("target_override", 0)) + int(type_counts.get("volume_intensity_override", 0))
            manual_n = int(type_counts.get("manual_override", 0)) + int(type_counts.get("skip_rest_override", 0))
            if auto_n >= max(target_n, manual_n):
                drift_reason = "Autopilot überstimmt"
            elif target_n >= max(auto_n, manual_n):
                drift_reason = "Targets übersteuert"
            elif manual_n > 0:
                drift_reason = "Overrides häufen sich"
            else:
                drift_reason = "Overrides häufen sich"
        elif (rpe_cap_violations_7d >= 2) or (rpe_cap_violations >= 2) or (rpe_cap_max_breach >= 0.5):
            drift_reason = "RPE-Cap wiederholt gebrochen"

        drift = drift_reason is not None
        return {
            "override_count_7d": override_count_7d,
            "override_by_type": type_counts,
            "recent_checks": len(rows),
            "recent_violations": recent_violations,
            "rpe_cap_violations": rpe_cap_violations,
            "rpe_cap_violations_7d": rpe_cap_violations_7d,
            "rpe_cap_max_breach": round(float(rpe_cap_max_breach), 2),
            "volume_over_violations": volume_over_violations,
            "extra_violations": extra_violations,
            "extra_volume_two_sessions": extra_volume_two_sessions,
            "escalated_two_sessions": escalated_two,
            "rule_break_detected": bool(rpe_cap_violations >= 1 or extra_volume_two_sessions or escalated_two or volume_over_violations >= 1),
            "drift_reason": drift_reason,
            "drift": drift,
        }
    except Exception:
        return {
            "override_count_7d": 0,
            "override_by_type": {},
            "recent_checks": 0,
            "recent_violations": 0,
            "rpe_cap_violations": 0,
            "rpe_cap_violations_7d": 0,
            "rpe_cap_max_breach": 0.0,
            "volume_over_violations": 0,
            "extra_violations": 0,
            "extra_volume_two_sessions": False,
            "escalated_two_sessions": False,
            "rule_break_detected": False,
            "drift_reason": None,
            "drift": False,
        }
    finally:
        conn.close()


def _gym_run_type_from_text(text: str) -> str:
    raw = (text or "").strip().lower()
    if not raw:
        return "z2"
    quality_tokens = ("threshold", "tempo", "interval", "intervals", "quality", "schwelle")
    return "threshold" if any(tok in raw for tok in quality_tokens) else "z2"


def _week_num_from_label(week_label: str | None) -> int | None:
    raw = str(week_label or "").strip().upper()
    m = re.fullmatch(r"W(\d{1,3})", raw)
    if not m:
        return None
    try:
        return int(m.group(1))
    except Exception:
        return None


def _parse_week_spec(spec: str) -> set[int]:
    nums = [int(x) for x in re.findall(r"\d+", str(spec or ""))]
    if not nums:
        return set()
    if len(nums) == 1:
        return {nums[0]}
    lo, hi = sorted((nums[0], nums[1]))
    return set(range(lo, hi + 1))


def _resolve_ref_block_line_for_week(item: dict, blocks_json: dict, target_week: int | None) -> str:
    if not isinstance(item, dict) or not isinstance(blocks_json, dict):
        return ""
    block_name = str(item.get("block_name") or "").strip()
    if not block_name:
        return ""
    rows = blocks_json.get(block_name)
    if not isinstance(rows, list) or not rows:
        return ""
    week_target = max(1, int(target_week or 1))
    block_day = str(item.get("block_day") or "").strip()
    display_name = str(item.get("display_name") or "").strip().lower()
    variation = str(item.get("variation") or "").strip().lower()

    def score_row(row: dict) -> int:
        score = 0
        if block_day and str(row.get("day") or "") == block_day:
            score += 2
        title = str(row.get("title") or "").lower()
        if display_name and display_name in title:
            score += 1
        if variation and variation in title:
            score += 1
        return score

    ordered_rows = sorted([r for r in rows if isinstance(r, dict)], key=score_row, reverse=True)
    for row in ordered_rows:
        for raw in (row.get("lines") or []):
            line = str(raw or "").strip().lstrip("-").strip()
            m = re.match(r"^Woche\s+([^:]+):\s*(.+)$", line, flags=re.IGNORECASE)
            if not m:
                continue
            if week_target in _parse_week_spec(m.group(1)):
                return m.group(2).strip()
    for row in ordered_rows:
        for raw in (row.get("lines") or []):
            line = str(raw or "").strip().lstrip("-").strip()
            if not line:
                continue
            m = re.match(r"^Woche\s+([^:]+):\s*(.+)$", line, flags=re.IGNORECASE)
            return (m.group(2).strip() if m else line)
    return ""


def _gym_event_to_legacy_strength(event: dict) -> list[dict]:
    out: list[dict] = []
    for item in (event.get("items") or []):
        if not isinstance(item, dict):
            continue
        kind = (item.get("kind") or "").strip().lower()
        if kind == "exercise":
            name = str(item.get("name") or "").strip()
            if not name:
                continue
            reps = item.get("reps") if isinstance(item.get("reps"), dict) else {}
            rmin = int(reps.get("min") or 0) if isinstance(reps, dict) else 0
            rmax = int(reps.get("max") or 0) if isinstance(reps, dict) else 0
            if rmin <= 0:
                rmin = 6
            if rmax <= 0:
                rmax = max(rmin, 10)
            if rmax < rmin:
                rmax = rmin
            sets = int(item.get("sets") or 0)
            if sets <= 0:
                sets = 3
            rpe_vals = []
            for v in (item.get("rpe_list") or []):
                try:
                    rpe_vals.append(float(v))
                except Exception:
                    pass
            out.append(
                {
                    "uid": uuid.uuid4().hex[:8],
                    "exercise_name": name,
                    "device": "",
                    "variation": str(item.get("variation") or "").strip(),
                    "sets": sets,
                    "reps_min": rmin,
                    "reps_max": rmax,
                    "rpe_min": min(rpe_vals) if rpe_vals else None,
                    "rpe_max": max(rpe_vals) if rpe_vals else None,
                    "notes": str(item.get("note") or "").strip(),
                }
            )
        elif kind == "ref_block":
            name = str(item.get("display_name") or "").strip()
            if not name:
                continue
            block_name = str(item.get("block_name") or "").strip()
            note = f'Block-Referenz: "{block_name}"' if block_name else "Block-Referenz"
            out.append(
                {
                    "uid": uuid.uuid4().hex[:8],
                    "exercise_name": name,
                    "device": "",
                    "variation": str(item.get("variation") or "").strip(),
                    "sets": 3,
                    "reps_min": 6,
                    "reps_max": 10,
                    "rpe_min": None,
                    "rpe_max": None,
                    "notes": note,
                }
            )
    return out


def _gym_event_to_legacy_run(event: dict, *, blocks_json: dict | None = None, target_week: int | None = None) -> list[dict]:
    title = str(event.get("title") or "").strip()
    details = []
    for item in (event.get("items") or []):
        if not isinstance(item, dict):
            continue
        kind = (item.get("kind") or "").strip().lower()
        if kind == "run_detail":
            txt = str(item.get("text") or "").strip()
            if txt:
                details.append(txt)
        elif kind == "ref_block":
            txt = _resolve_ref_block_line_for_week(item, blocks_json or {}, target_week)
            if txt:
                details.append(txt)
    merged = " · ".join([p for p in [title, *details] if p]).strip()
    run_type_source = " · ".join(details).strip() if details else merged
    run_type = _gym_run_type_from_text(run_type_source)
    amount_value = ""
    amount_unit = "min"
    pace = ""
    m_min = re.search(r"(\d{1,3})\s*min", merged, flags=re.IGNORECASE)
    if m_min:
        amount_value = m_min.group(1)
    m_pace = re.search(r"(\d{1,2}:\d{2})\s*/\s*km", merged, flags=re.IGNORECASE)
    if m_pace:
        pace = m_pace.group(1)
    return [
        {
            "uid": uuid.uuid4().hex[:8],
            "run_type": run_type,
            "amount_value": amount_value,
            "amount_unit": amount_unit,
            "pace": pace,
            "interval_reps": "",
            "interval_on": "",
            "interval_on_unit": "min",
            "interval_off": "",
            "interval_off_unit": "min",
            "notes": merged,
        }
    ]


def _legacy_plan_from_gym_record(record: dict) -> dict:
    plan_json = record.get("plan_json") if isinstance(record.get("plan_json"), dict) else {}
    rules_json = record.get("rules_json") if isinstance(record.get("rules_json"), dict) else {}
    blocks_json = record.get("blocks_json") if isinstance(record.get("blocks_json"), dict) else {}
    meta_src = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    title = str(record.get("title") or record.get("name") or "Gym Plan").strip() or "Gym Plan"
    focus = str(record.get("focus") or "").strip()
    target_week = _week_num_from_label(rules_json.get("active_week")) or 1

    endurance_kinds = {"run", "ergo", "bike", "row", "swim"}
    day_map = {d: [] for d in DAY_ORDER}
    for row in (plan_json.get("days") or []):
        if not isinstance(row, dict):
            continue
        d = str(row.get("day") or "").strip()
        if d in day_map and isinstance(row.get("events"), list):
            day_map[d] = row.get("events") or []

    base_week = []
    for day_name in DAY_ORDER:
        events = day_map.get(day_name) or []
        gym_events = [e for e in events if isinstance(e, dict) and (e.get("kind") or "").strip().lower() == "gym"]
        run_events = [
            e
            for e in events
            if isinstance(e, dict) and (e.get("kind") or "").strip().lower() in endurance_kinds
        ]

        strength_exercises = []
        for ev in gym_events:
            strength_exercises.extend(_gym_event_to_legacy_strength(ev))
        run_sessions = []
        for ev in run_events:
            run_sessions.extend(_gym_event_to_legacy_run(ev, blocks_json=blocks_json, target_week=target_week))

        session_name = ""
        if gym_events:
            first_title = str((gym_events[0] or {}).get("title") or "").strip()
            session_name = first_title or "Gym"

        base_week.append(
            {
                "day": day_name,
                "session_name": session_name,
                "strength_exercises": strength_exercises,
                "run_sessions": run_sessions,
            }
        )

    weeks_total = int(meta_src.get("total_weeks") or plan_json.get("weeks") or 8)
    weeks_total = max(1, min(260, weeks_total))
    rules_weeks = rules_json.get("weeks") if isinstance(rules_json.get("weeks"), dict) else {}
    weeks = []
    for i in range(1, weeks_total + 1):
        label = f"W{i}"
        row = rules_weeks.get(label) if isinstance(rules_weeks.get(label), dict) else {}
        try:
            strength_factor = float(row.get("strength_factor")) if row.get("strength_factor") is not None else 1.0
        except Exception:
            strength_factor = 1.0
        try:
            run_factor = float(row.get("run_factor")) if row.get("run_factor") is not None else 1.0
        except Exception:
            run_factor = 1.0
        try:
            rpe_cap = float(row.get("rpe_cap")) if row.get("rpe_cap") is not None else None
        except Exception:
            rpe_cap = None
        weeks.append(
            {
                "week": i,
                "strength_volume_factor": strength_factor,
                "run_volume_factor": run_factor,
                "deload": bool(row.get("deload")),
                "rpe_cap": rpe_cap,
                "week_note": str(row.get("tag") or "").strip(),
            }
        )

    meta = {
        "goal": focus,
        "priorities": [],
        "start_date": str(meta_src.get("start_date") or date.today().isoformat()),
        "total_weeks": weeks_total,
        "block_length": int(meta_src.get("block_length") or 4),
        "week_override": meta_src.get("week_override"),
        "week_type_override": meta_src.get("week_type_override"),
        "source": "gym_plan_mirror",
        "source_gym_plan_id": record.get("id"),
        "source_gym_plan_title": title,
        "synced_at": datetime.utcnow().isoformat(),
    }

    legacy = {
        "name": title,
        "block_length": int(meta.get("block_length") or 4),
        "base_week": base_week,
        "weeks": weeks,
        "meta": meta,
    }
    return sanitize_plan_payload(legacy)


def _sync_active_legacy_plan_from_gym_record(record: dict) -> int | None:
    if not isinstance(record, dict):
        return None
    legacy = _legacy_plan_from_gym_record(record)
    gym_plan_id = record.get("id")
    rules_json = record.get("rules_json") if isinstance(record.get("rules_json"), dict) else {}
    now = datetime.utcnow().isoformat()
    meta = legacy.get("meta") if isinstance(legacy.get("meta"), dict) else {}
    weeks_list = legacy.get("weeks") if isinstance(legacy.get("weeks"), list) else []
    try:
        total_weeks = int(meta.get("total_weeks") or 0)
    except Exception:
        total_weeks = 0
    if total_weeks <= 0:
        total_weeks = len(weeks_list) if weeks_list else 8
    total_weeks = max(1, min(260, total_weeks))

    week_override = None
    active_week = str(rules_json.get("active_week") or "").strip().upper()
    m_aw = re.fullmatch(r"W(\d{1,3})", active_week)
    if m_aw:
        try:
            week_override = int(m_aw.group(1))
        except Exception:
            week_override = None
    if week_override is not None:
        week_override = max(1, min(total_weeks, week_override))

    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("BEGIN")
    try:
        mirror_id = None
        rows = cur.execute("SELECT id, data FROM plans ORDER BY updated_at DESC, id DESC").fetchall()
        for row in rows:
            try:
                parsed = json.loads(row["data"]) if row["data"] else {}
            except Exception:
                parsed = {}
            meta = parsed.get("meta") if isinstance(parsed, dict) and isinstance(parsed.get("meta"), dict) else {}
            if meta.get("source") == "gym_plan_mirror" and str(meta.get("source_gym_plan_id")) == str(gym_plan_id):
                mirror_id = int(row["id"])
                break

        cur.execute("UPDATE plans SET is_active = 0")
        payload_json = json.dumps(legacy, ensure_ascii=False)
        block_length = int(legacy.get("block_length") or 4)
        if mirror_id is None:
            cur.execute(
                """
                INSERT INTO plans (name, data, block_length, is_active, created_at, updated_at, total_weeks, week_override)
                VALUES (?, ?, ?, 1, ?, ?, ?, ?)
                """,
                (legacy.get("name") or "Gym Plan", payload_json, block_length, now, now, total_weeks, week_override),
            )
            mirror_id = int(cur.lastrowid)
        else:
            cur.execute(
                """
                UPDATE plans
                SET name = ?, data = ?, block_length = ?, is_active = 1, updated_at = ?, total_weeks = ?, week_override = ?
                WHERE id = ?
                """,
                (legacy.get("name") or "Gym Plan", payload_json, block_length, now, total_weeks, week_override, mirror_id),
            )
        conn.commit()
    except Exception:
        conn.rollback()
        conn.close()
        raise
    conn.close()
    return mirror_id


def _mark_gym_plan_core_change_seen(plan_id: int, item_id: str) -> tuple[bool, dict[str, Any] | None]:
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        """
        SELECT id, title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at
        FROM gym_plans
        WHERE id = ?
        LIMIT 1
        """,
        (int(plan_id),),
    ).fetchone()
    if not row:
        conn.close()
        return False, None
    try:
        plan_json = _load_gym_plan_json(row["plan_json"] if "plan_json" in row.keys() else None)
    except Exception:
        conn.close()
        return False, None
    days = plan_json.get("days") if isinstance(plan_json.get("days"), list) else []
    changed = False
    payload: dict[str, Any] | None = None
    now = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    target_id = str(item_id or "").strip()
    for day in days:
        if not isinstance(day, dict):
            continue
        for event in (day.get("events") or []):
            if not isinstance(event, dict):
                continue
            for item in (event.get("items") or []):
                if not isinstance(item, dict):
                    continue
                if str(item.get("id") or "").strip() != target_id:
                    continue
                core_change = item.get("core_change") if isinstance(item.get("core_change"), dict) else None
                if not core_change:
                    conn.close()
                    return False, None
                core_change["seen"] = True
                core_change["seen_at"] = now
                item["core_change"] = core_change
                payload = {
                    "item_id": target_id,
                    "day": str(day.get("day") or "").strip(),
                    "session_title": str(event.get("title") or "").strip(),
                    "exercise_name": str(item.get("name") or "").strip(),
                    "core_change": core_change,
                }
                changed = True
                break
            if changed:
                break
        if changed:
            break
    if not changed:
        conn.close()
        return False, None
    plan_json["base_week"] = {
        str(day.get("day") or ""): list(day.get("events") or [])
        for day in days
        if isinstance(day, dict)
    }
    conn.execute(
        "UPDATE gym_plans SET plan_json = ?, updated_at = ? WHERE id = ?",
        (json.dumps(plan_json, ensure_ascii=False), now, int(plan_id)),
    )
    conn.commit()
    conn.close()
    try:
        record = _row_to_gym_plan(row)
        record["plan_json"] = plan_json
        mirror_id = _sync_active_legacy_plan_from_gym_record(record) if bool(row["is_active"]) else None
        if mirror_id:
            _autopilot_clear_week_cache()
    except Exception:
        app.logger.exception("gym_plan_core_change_seen_sync_failed")
    return True, payload


