@app.get("/api/gym_plans")
def api_list_gym_plans():
    include_archived = (request.args.get("include_archived") or "0").strip() in {"1", "true", "yes"}
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    if include_archived:
        rows = conn.execute(
            """
            SELECT id, title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at
            FROM gym_plans
            ORDER BY is_active DESC, is_archived ASC, updated_at DESC
            """
        ).fetchall()
    else:
        rows = conn.execute(
            """
            SELECT id, title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at
            FROM gym_plans
            WHERE is_archived = 0
            ORDER BY is_active DESC, updated_at DESC
            """
        ).fetchall()
    conn.close()

    out = []
    for row in rows:
        record = _row_to_gym_plan(row)
        cycle = _gym_plan_cycle_status(record["plan_json"], record.get("rules_json") if isinstance(record.get("rules_json"), dict) else {})
        out.append(
            {
                "id": record["id"],
                "name": record["title"],
                "title": record["title"],
                "focus": record["focus"],
                "is_active": record["is_active"],
                "is_archived": record["is_archived"],
                "created_at": record["created_at"],
                "updated_at": record["updated_at"],
                "summary": _gym_plan_summary(record["plan_json"]),
                "cycle": cycle,
            }
        )
    return jsonify({"ok": True, "plans": out})


@app.post("/api/gym_plans")
def api_create_gym_plan():
    payload = request.get_json(silent=True) or {}
    title = str(payload.get("title") or "Neuer Gym-Plan").strip() or "Neuer Gym-Plan"
    focus = str(payload.get("focus") or "").strip()
    plan_json_raw = payload.get("plan_json") if isinstance(payload.get("plan_json"), dict) else default_gym_plan_json()
    plan_json = _load_gym_plan_json(plan_json_raw)
    rules_json = _normalize_gym_rules_json(payload.get("rules_json") if isinstance(payload.get("rules_json"), dict) else None, int(plan_json.get("weeks") or 8))
    blocks_json = default_blocks_json()
    if isinstance(payload.get("blocks_json"), dict):
        blocks_json.update(payload["blocks_json"])
    meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    meta["title"] = title
    meta["focus"] = focus
    meta["updated_at"] = datetime.utcnow().isoformat()
    plan_json["meta"] = meta
    set_active = payload.get("set_active", True) is True

    now = datetime.utcnow().isoformat()
    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("BEGIN")
    try:
        if set_active:
            cur.execute("UPDATE gym_plans SET is_active = 0")
        cur.execute(
            """
            INSERT INTO gym_plans (title, focus, plan_json, rules_json, blocks_json, is_active, is_archived, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?)
            """,
            (
                title,
                focus,
                json.dumps(plan_json, ensure_ascii=False),
                json.dumps(rules_json, ensure_ascii=False),
                json.dumps(blocks_json, ensure_ascii=False),
                1 if set_active else 0,
                now,
                now,
            ),
        )
        new_id = cur.lastrowid
        conn.commit()
    except Exception as exc:
        conn.rollback()
        conn.close()
        return jsonify({"ok": False, "error": "create_failed", "detail": str(exc)}), 500
    conn.close()
    if set_active:
        try:
            mirror_id = _sync_active_legacy_plan_from_gym_record(
                {
                    "id": new_id,
                    "title": title,
                    "name": title,
                    "focus": focus,
                    "plan_json": plan_json,
                    "rules_json": rules_json,
                    "blocks_json": blocks_json,
                }
            )
            if mirror_id:
                _autopilot_clear_week_cache()
        except Exception:
            app.logger.exception("gym_plan_sync_on_create_failed")

    return jsonify(
        {
            "ok": True,
            "id": new_id,
            "title": title,
            "focus": focus,
            "is_active": set_active,
            "is_archived": False,
            "updated_at": now,
            "plan_json": plan_json,
            "rules_json": rules_json,
            "blocks_json": blocks_json,
        }
    ), 201


