@app.post("/api/gym_plans/<int:plan_id>/archive")
def api_archive_gym_plan(plan_id: int):
    conn = get_plans_db()
    cur = conn.cursor()
    now = datetime.utcnow().isoformat()
    payload = request.get_json(silent=True) or {}
    archive_flag = payload.get("archive")
    if archive_flag is None:
        archive_flag = True
    archive_val = 1 if bool(archive_flag) else 0
    cur.execute("BEGIN")
    try:
        row = cur.execute("SELECT id FROM gym_plans WHERE id = ? LIMIT 1", (plan_id,)).fetchone()
        if not row:
            conn.rollback()
            conn.close()
            return jsonify({"ok": False, "error": "not_found", "detail": "Gym-Plan nicht gefunden."}), 404
        cur.execute("UPDATE gym_plans SET is_archived = ?, is_active = CASE WHEN ? = 1 THEN 0 ELSE is_active END, updated_at = ? WHERE id = ?", (archive_val, archive_val, now, plan_id))
        conn.commit()
    except Exception as exc:
        conn.rollback()
        conn.close()
        return jsonify({"ok": False, "error": "archive_failed", "detail": str(exc)}), 500
    conn.close()
    return jsonify({"ok": True, "id": plan_id, "is_archived": bool(archive_val), "updated_at": now})


