@app.post("/api/gym_plans/<int:plan_id>/import_dsl")
def api_import_gym_plan_dsl(plan_id: int):
    payload = request.get_json(silent=True) or {}
    text = payload.get("text")
    if text is None:
        text = payload.get("dsl")
    if not isinstance(text, str):
        return jsonify({"ok": False, "error": "invalid_request", "detail": "Feld 'text' muss ein String sein."}), 400

    conn = get_plans_db()
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        "SELECT id, title, focus, plan_json, rules_json, blocks_json FROM gym_plans WHERE id = ? LIMIT 1",
        (plan_id,),
    ).fetchone()
    if not row:
        conn.close()
        return jsonify({"ok": False, "error": "not_found", "detail": "Gym-Plan nicht gefunden."}), 404

    known = {str(x).strip() for x in EXERCISE_NAME_SUGGESTIONS if str(x).strip()}
    parsed = parse_gym_plan_dsl(text, known_exercises=known)
    plan_json = parsed["plan_json"]
    blocks_json = parsed.get("blocks_json") or _load_json_obj(row["blocks_json"])
    parsed_rules_json = parsed.get("rules_json") if isinstance(parsed.get("rules_json"), dict) else None
    if parsed_rules_json is not None:
        rules_json = _normalize_gym_rules_json(parsed_rules_json, int(plan_json.get("weeks") or 8))
    else:
        rules_json = _normalize_gym_rules_json(_load_json_obj(row["rules_json"]), int(plan_json.get("weeks") or 8))
    title = str(row["title"] or "").strip() or plan_json.get("meta", {}).get("title") or "Gym Plan"
    focus = str(row["focus"] or "").strip() or plan_json.get("meta", {}).get("focus") or ""
    meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
    now = datetime.utcnow().isoformat()
    meta["title"] = title
    meta["focus"] = focus
    meta["updated_at"] = now
    plan_json["meta"] = meta

    try:
        conn.execute(
            "UPDATE gym_plans SET plan_json = ?, blocks_json = ?, rules_json = ?, updated_at = ? WHERE id = ?",
            (
                json.dumps(plan_json, ensure_ascii=False),
                json.dumps(blocks_json, ensure_ascii=False),
                json.dumps(rules_json, ensure_ascii=False),
                now,
                plan_id,
            ),
        )
        conn.commit()
    except Exception as exc:
        conn.close()
        return jsonify({"ok": False, "error": "import_failed", "detail": str(exc)}), 500
    conn.close()

    return jsonify(
        {
            "ok": True,
            "id": plan_id,
            "updated_at": now,
            "plan_json": plan_json,
            "blocks_json": blocks_json,
            "rules_json": rules_json,
            "warnings": parsed["warnings"],
        }
    )


