@app.post("/api/gym_plans/coach_summary")
def api_gym_plans_coach_summary():
    payload = request.get_json(silent=True) or {}
    plan_json = payload.get("plan_json")
    blocks_json = payload.get("blocks_json") if isinstance(payload.get("blocks_json"), dict) else {}
    week = str(payload.get("week") or "W1")
    if not isinstance(plan_json, dict):
        return jsonify({"ok": False, "error": "invalid_request", "detail": "Feld 'plan_json' muss ein Objekt sein."}), 400
    rules_json = _normalize_gym_rules_json(payload.get("rules_json") if isinstance(payload.get("rules_json"), dict) else None, int(plan_json.get("weeks") or 8))
    plan_for_week = apply_week_rules_to_plan(plan_json, rules_json.get("weeks"), week)
    plan_mode = str(((plan_for_week.get("meta") or {}).get("mode")) or "fixed_week").strip().lower()
    rolling_pattern = ((plan_for_week.get("meta") or {}).get("rolling_week_pattern")) or {}

    exercise_map = combined_mapping()
    muscle_sets: dict[str, float] = {}
    grouped_sets: dict[str, float] = {}
    part_to_group = {
        "front_delts": "shoulders",
        "side_delts": "shoulders",
        "rear_delts": "shoulders",
        "chest": "chest",
        "lats": "back",
        "upper_back": "back",
        "traps": "back",
        "lower_back": "back",
        "biceps": "biceps",
        "brachialis": "biceps",
        "triceps": "triceps",
        "quads": "quads",
        "hamstrings": "hamstrings",
        "calves": "calves",
        "core": "core",
        "hip_flexors": "core",
    }

    keyword_groups = [
        ("quads", ["squat", "squats", "beinpresse", "beinstrecker", "leg extension", "hack squat", "split squat", "lunge"]),
        ("hamstrings", ["rdl", "deadlift", "beinbeuger", "leg curl", "hamstring"]),
        ("calves", ["waden", "calf"]),
        ("core", ["crunch", "plank", "situp", "sit-up", "core", "hanging leg raise"]),
        ("chest", ["bench", "bank", "brust", "fly", "chest press", "presse"]),
        ("back", ["latzug", "row", "rows", "rudern", "pullup", "pull-up", "pull up", "highrow"]),
        ("shoulders", ["seitheben", "ohp", "shoulder", "upright row", "rear delt", "reverse fly"]),
        ("biceps", ["curl", "preacher", "bayesian", "bayesians"]),
        ("triceps", ["pushdown", "french press", "trizeps", "dip", "katanas", "katana"]),
    ]

    def infer_group_from_name(name: str) -> str | None:
        text = (name or "").strip().lower()
        if not text:
            return None
        for grp, keywords in keyword_groups:
            if any(k in text for k in keywords):
                return grp
        return None

    def parse_week_spec(spec: str) -> set[int]:
        nums = [int(x) for x in re.findall(r"\d+", str(spec or ""))]
        if not nums:
            return set()
        if len(nums) == 1:
            return {nums[0]}
        lo, hi = sorted((nums[0], nums[1]))
        return set(range(lo, hi + 1))

    def resolve_block_line_for_week(item: dict, week_label: str) -> str:
        block_name = str(item.get("block_name") or "").strip()
        if not block_name:
            return ""
        rows = blocks_json.get(block_name)
        if not isinstance(rows, list) or not rows:
            return ""
        target_week = int(re.sub(r"[^0-9]", "", str(week_label or "1")) or "1")
        block_day = str(item.get("block_day") or "").strip()
        display_name = str(item.get("display_name") or "").strip().lower()
        variation = str(item.get("variation") or "").strip().lower()

        def score_row(row: dict) -> int:
            score = 0
            if block_day and str(row.get("day") or "") == block_day:
                score += 2
            title = str(row.get("title") or "").lower()
            if display_name and display_name in title:
                score += 1
            if variation and variation in title:
                score += 1
            return score

        ordered_rows = sorted([r for r in rows if isinstance(r, dict)], key=score_row, reverse=True)
        for row in ordered_rows:
            lines = row.get("lines") if isinstance(row.get("lines"), list) else []
            for raw in lines:
                line = str(raw or "").strip().lstrip("-").strip()
                m = re.match(r"^Woche\s+([^:]+):\s*(.+)$", line, flags=re.IGNORECASE)
                if not m:
                    continue
                if target_week in parse_week_spec(m.group(1)):
                    return m.group(2).strip()
        for row in ordered_rows:
            lines = row.get("lines") if isinstance(row.get("lines"), list) else []
            for raw in lines:
                line = str(raw or "").strip().lstrip("-").strip()
                if line:
                    m = re.match(r"^Woche\s+([^:]+):\s*(.+)$", line, flags=re.IGNORECASE)
                    return (m.group(2).strip() if m else line)
        return ""

    def extract_sets_from_text(text: str) -> float:
        vals = [int(x) for x in re.findall(r"(\d+)\s*x", str(text or ""), flags=re.IGNORECASE)]
        return float(sum(vals)) if vals else 0.0

    def add_sets_to_groups(ex_name: str, sets: float):
        if sets <= 0:
            return
        mapping = exercise_map.get(ex_name) if isinstance(exercise_map.get(ex_name), dict) else {}
        if not mapping:
            inferred = infer_group_from_name(ex_name)
            if inferred:
                grouped_sets[inferred] = grouped_sets.get(inferred, 0.0) + sets
            else:
                muscle_sets["unmapped"] = muscle_sets.get("unmapped", 0.0) + sets
            return
        for muscle, weight in mapping.items():
            try:
                w = float(weight)
            except Exception:
                continue
            val = sets * w
            muscle_sets[muscle] = muscle_sets.get(muscle, 0.0) + val
            grp = part_to_group.get(str(muscle))
            if grp:
                grouped_sets[grp] = grouped_sets.get(grp, 0.0) + val

    def expected_training_days_per_week() -> float:
        weights = {"train": 1.0, "optional": 0.5, "rest": 0.0}
        total = 0.0
        for day in ("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"):
            status = str(rolling_pattern.get(day) or "").strip().lower()
            total += weights.get(status, weights.get({"Mo": "train", "Di": "optional", "Mi": "train", "Do": "rest", "Fr": "train", "Sa": "optional", "So": "rest"}[day], 0.0))
        return total

    def sequence_training_slots() -> int:
        slots = 0
        for event in plan_for_week.get("sequence") or []:
            kind = str(event.get("kind") or "").strip().lower()
            if kind == "gym" or kind == "cardio":
                slots += 1
        return slots

    total_sets = 0.0
    event_groups = []
    if plan_mode == "rolling_sequence":
        event_groups = [("sequence", plan_for_week.get("sequence") or [])]
    else:
        event_groups = [(day.get("day"), day.get("events") or []) for day in (plan_for_week.get("days") or [])]
    for _group_name, group_events in event_groups:
        for event in group_events:
            if (event.get("kind") or "").lower() != "gym":
                continue
            for item in event.get("items") or []:
                kind = str(item.get("kind") or "")
                if kind not in {"exercise", "ref_block"}:
                    continue
                if kind == "exercise":
                    name = str(item.get("name") or "").strip().lower()
                    sets = float(item.get("sets") or 0)
                else:
                    name = str(item.get("display_name") or item.get("name") or "").strip().lower()
                    line = resolve_block_line_for_week(item, week)
                    sets = extract_sets_from_text(line)
                if sets <= 0:
                    continue
                total_sets += sets
                add_sets_to_groups(name, sets)

    estimated_weekly_days = 0.0
    sequence_slots = 0
    rotation_factor = 1.0
    if plan_mode == "rolling_sequence":
        estimated_weekly_days = expected_training_days_per_week()
        sequence_slots = sequence_training_slots()
        rotation_factor = (estimated_weekly_days / sequence_slots) if sequence_slots > 0 else 0.0
        total_sets *= rotation_factor
        for key, value in list(grouped_sets.items()):
            grouped_sets[key] = float(value or 0.0) * rotation_factor
        for key, value in list(muscle_sets.items()):
            muscle_sets[key] = float(value or 0.0) * rotation_factor

    group_specs = [
        {"key": "shoulders", "label": "Schultern", "parts": ["front_delts", "side_delts", "rear_delts"], "min": 10.0, "max": 14.0, "too_high": 16.0},
        {"key": "chest", "label": "Brust", "parts": ["chest"], "min": 8.0, "max": 12.0, "too_high": 14.0},
        {"key": "back", "label": "Rücken", "parts": ["lats", "upper_back", "traps", "lower_back"], "min": 10.0, "max": 16.0, "too_high": 18.0},
        {"key": "biceps", "label": "Bizeps", "parts": ["biceps", "brachialis"], "min": 8.0, "max": 12.0, "too_high": 14.0},
        {"key": "triceps", "label": "Trizeps", "parts": ["triceps"], "min": 8.0, "max": 12.0, "too_high": 14.0},
        {"key": "quads", "label": "Quads", "parts": ["quads"], "min": 6.0, "max": 10.0, "too_high": 12.0},
        {"key": "hamstrings", "label": "Hamstrings", "parts": ["hamstrings"], "min": 6.0, "max": 10.0, "too_high": 12.0},
        {"key": "calves", "label": "Waden", "parts": ["calves"], "min": 4.0, "max": 8.0, "too_high": 10.0},
        {"key": "core", "label": "Core", "parts": ["core", "hip_flexors"], "min": 2.0, "max": 6.0, "too_high": 8.0},
    ]

    warnings = validate_plan_against_rules(plan_for_week, rules_json.get("weeks"), week)
    enriched = []
    for spec in group_specs:
        sets_val = float(grouped_sets.get(spec["key"], 0.0) or 0.0)
        status = "ok"
        if sets_val < spec["min"]:
            status = "low"
            warnings.append(
                {
                    "kind": "low_group_volume",
                    "message": f"{spec['label']} niedrig ({sets_val:.1f} Sets, Ziel {spec['min']:.0f}-{spec['max']:.0f}).",
                    "path": f"group:{spec['key']}",
                }
            )
        elif sets_val > spec["too_high"]:
            status = "high"
            warnings.append(
                {
                    "kind": "high_group_volume",
                    "message": f"{spec['label']} hoch ({sets_val:.1f} Sets, ab ~{spec['too_high']:.0f}+ zu viel).",
                    "path": f"group:{spec['key']}",
                }
            )
        enriched.append(
            {
                "key": spec["key"],
                "label": spec["label"],
                "sets": round(sets_val, 2),
                "status": status,
                "target_min": spec["min"],
                "target_max": spec["max"],
                "warn_min": max(0.0, spec["min"] - 1.0),
                "warn_max": spec["max"] + 2.0,
            }
        )

    unmapped_sets = float(muscle_sets.get("unmapped", 0.0) or 0.0)
    if unmapped_sets > 0:
        warnings.append(
            {
                "kind": "unmapped_exercises",
                "message": f"{unmapped_sets:.1f} Sets konnten keiner Muskelgruppe zugeordnet werden.",
                "path": "group:unmapped",
            }
        )

    return jsonify(
        {
            "ok": True,
            "muscle_sets": enriched,
            "warnings": warnings,
            "totals": {
                "total_sets": round(total_sets, 2),
                "muscle_groups": len(enriched),
                "mode": "rolling_sequence" if plan_mode == "rolling_sequence" else "fixed_week",
                "expected_training_days_per_week": round(estimated_weekly_days, 2) if plan_mode == "rolling_sequence" else None,
                "sequence_slots": sequence_slots if plan_mode == "rolling_sequence" else None,
                "rotation_factor": round(rotation_factor, 4) if plan_mode == "rolling_sequence" else None,
            },
        }
    )

@app.get("/api/plans")
def api_list_plans():
    conn = get_plans_db()
    rows = conn.execute("SELECT * FROM plans ORDER BY is_active DESC, updated_at DESC").fetchall()
    conn.close()

    out = []
    for r in rows:
        plan = plan_row_to_dict(r)
        summary = summarize_plan(plan)
        out.append({
            "id": plan["id"],
            "name": plan["name"],
            "is_active": plan["is_active"],
            "block_length": plan["block_length"],
            "meta": plan.get("meta") if isinstance(plan.get("meta"), dict) else {},
            "summary": summary,
            "updated_at": plan.get("updated_at"),
        })
    return jsonify(out)


@app.post("/api/plans")
def api_create_plan():
    payload = request.get_json(silent=True) or {}

    # default behavior: new plan becomes active unless explicitly set_active=false
    set_active = payload.get("set_active", True)

    base = payload if payload else (build_default_plan() or {})
    plan = sanitize_plan_payload(base)
    now = datetime.utcnow().isoformat()
    if set_active:
        _ensure_plan_start_date(plan, today_iso=date.today().isoformat())

    conn = get_plans_db()
    cur = conn.cursor()
    cur.execute("BEGIN")

    try:
        if set_active:
            cur.execute("UPDATE plans SET is_active = 0")

        cur.execute("""
            INSERT INTO plans (name, data, block_length, is_active, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (
            plan["name"],
            json.dumps(plan, ensure_ascii=False),
            plan["block_length"],
            1 if set_active else 0,
            now,
            now
        ))
        plan_id = cur.lastrowid
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"error": "create_failed", "detail": str(e)}), 500

    conn.close()
    if set_active:
        try:
            _autopilot_clear_week_cache()
        except Exception:
            pass

    plan["id"] = plan_id
    plan["is_active"] = 1 if set_active else 0
    plan["created_at"] = now
    plan["updated_at"] = now
    return jsonify(plan), 201


@app.get("/api/plans/<int:plan_id>")
def api_get_plan(plan_id):
    row = get_plan_row(plan_id)
    if not row:
        return jsonify({"error": "Plan nicht gefunden"}), 404
    plan = plan_row_to_dict(row)
    return jsonify(plan)


@app.put("/api/plans/<int:plan_id>")
def api_update_plan(plan_id):
    row = get_plan_row(plan_id)
    if not row:
        return jsonify({"error": "Plan nicht gefunden"}), 404

    existing = plan_row_to_dict(row)
    payload = request.get_json(silent=True) or {}

    # MERGE: only overwrite provided keys
    merged = dict(existing)
    for k in ("name", "block_length", "base_week", "weeks", "meta"):
        if k in payload:
            if k == "meta" and isinstance(payload.get("meta"), dict):
                current_meta = merged.get("meta") if isinstance(merged.get("meta"), dict) else {}
                merged["meta"] = {**current_meta, **payload.get("meta")}
            else:
                merged[k] = payload.get(k)

    plan = sanitize_plan_payload(merged)
    plan["id"] = plan_id

    invalidate_plan_cache(plan_id)
    now = datetime.utcnow().isoformat()

    # handle optional set_active in update
    set_active = payload.get("set_active", None)
    if set_active is True:
        _ensure_plan_start_date(plan, today_iso=date.today().isoformat())

    conn = get_plans_db()
    cur = conn.cursor()
    cur.execute("BEGIN")

    try:
        if set_active is True:
            cur.execute("UPDATE plans SET is_active = 0")
            cur.execute("UPDATE plans SET is_active = 1 WHERE id = ?", (plan_id,))
        elif set_active is False:
            cur.execute("UPDATE plans SET is_active = 0 WHERE id = ?", (plan_id,))
        cur.execute("""
            UPDATE plans
            SET name = ?, data = ?, block_length = ?, updated_at = ?
            WHERE id = ?
        """, (
            plan["name"],
            json.dumps(plan, ensure_ascii=False),
            plan["block_length"],
            now,
            plan_id
        ))
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"error": "update_failed", "detail": str(e)}), 500

    conn.close()
    if set_active is True:
        try:
            _autopilot_clear_week_cache()
        except Exception:
            pass

    plan["updated_at"] = now
    # preserve is_active from DB if you store it inside plan dict; else pull from existing
    plan["is_active"] = existing.get("is_active", 0) if set_active is None else (1 if set_active else 0)
    return jsonify(plan)


