def api_delete_plan(plan_id):
    conn = get_plans_db()
    cur = conn.cursor()
    cur.execute("BEGIN")
    try:
        cur.execute("DELETE FROM plans WHERE id = ?", (plan_id,))
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"error": "delete_failed", "detail": str(e)}), 500
    conn.close()
    try:
        _autopilot_clear_week_cache()
    except Exception:
        pass
    return jsonify({"ok": True})


@app.post("/api/plans/<int:plan_id>/duplicate")
def api_duplicate_plan(plan_id):
    row = get_plan_row(plan_id)
    if not row:
        return jsonify({"error": "Plan nicht gefunden"}), 404

    plan = plan_row_to_dict(row)
    plan["name"] = f"{plan.get('name','Plan')} (Kopie)"
    plan["is_active"] = 0

    if not isinstance(plan.get("meta"), dict):
        plan["meta"] = {"goal": "", "priorities": []}
    plan["meta"]["version"] = int(plan["meta"].get("version", 1)) + 1

    now = datetime.utcnow().isoformat()

    conn = get_plans_db()
    cur = conn.cursor()
    cur.execute("BEGIN")

    try:
        cur.execute("""
            INSERT INTO plans (name, data, block_length, is_active, created_at, updated_at)
            VALUES (?, ?, ?, 0, ?, ?)
        """, (
            plan["name"],
            json.dumps(plan, ensure_ascii=False),
            plan["block_length"],
            now,
            now
        ))
        new_id = cur.lastrowid
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"error": "duplicate_failed", "detail": str(e)}), 500

    conn.close()

    plan["id"] = new_id
    plan["created_at"] = now
    plan["updated_at"] = now
    return jsonify(plan)


@app.post("/api/plans/<int:plan_id>/set_active")
def api_set_active(plan_id):
    now = datetime.utcnow().isoformat()
    conn = get_plans_db()
    cur = conn.cursor()

    cur.execute("SELECT id, data FROM plans WHERE id = ?", (plan_id,))
    row = cur.fetchone()
    if not row:
        conn.close()
        return jsonify({"error": "Plan nicht gefunden"}), 404

    updated_data = None
    try:
        plan = json.loads(row["data"]) if row["data"] else {}
        if isinstance(plan, dict):
            if _ensure_plan_start_date(plan, today_iso=date.today().isoformat()):
                updated_data = json.dumps(plan, ensure_ascii=False)
    except Exception:
        updated_data = None

    cur.execute("BEGIN")
    try:
        cur.execute("UPDATE plans SET is_active = CASE WHEN id=? THEN 1 ELSE 0 END", (plan_id,))
        # bump updated_at for the activated plan (nice for sorting + UI)
        cur.execute("UPDATE plans SET updated_at = ? WHERE id = ?", (now, plan_id))
        if updated_data:
            cur.execute("UPDATE plans SET data = ? WHERE id = ?", (updated_data, plan_id))
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"error": "set_active_failed", "detail": str(e)}), 500

    conn.close()
    return jsonify({"ok": True})



