def plan_rows_for_export(plan: dict, week_index: int):
    planned = compute_planned_week(plan, week_index)
    rows = []

    day_names = [d.get("day") or idx for idx, d in enumerate(plan.get("base_week", []))]
    for d in planned["day_details"]:
        day_label = day_names[d["day_index"]] if d["day_index"] < len(day_names) else d["day_index"]

        for row in d.get("strength_rows", []):
            rows.append({
                "day": day_label,
                "week": week_index + 1,
                "type": "strength",
                "name": row.get("exercise_name"),
                "device": row.get("device"),
                "sets": row.get("sets"),
                "reps_min": row.get("reps_min"),
                "reps_max": row.get("reps_max"),
                "rpe_min": row.get("rpe_min"),
                "rpe_max": row.get("rpe_max"),
                "amount_value": "",
                "amount_unit": "",
                "notes": row.get("notes")
            })

        for run in d.get("runs", []):
            rows.append({
                "day": day_label,
                "week": week_index + 1,
                "type": "run",
                "name": run.get("run_type"),
                "device": "",
                "sets": "",
                "reps_min": "",
                "reps_max": "",
                "rpe_min": "",
                "rpe_max": "",
                "amount_value": run.get("amount_value"),
                "amount_unit": run.get("amount_unit"),
                "notes": run.get("notes"),
            })

    return rows


@app.post("/api/plans/<int:plan_id>/export")
def api_export_plan(plan_id):
    # allow query params OR JSON body
    body = request.get_json(silent=True) or {}

    fmt = (request.args.get("format") or body.get("format") or "pdf").strip().lower()
    week = int((request.args.get("week") or body.get("week") or "1")) - 1

    row = get_plan_row(plan_id)
    if not row:
        return jsonify({"error": "Plan nicht gefunden"}), 404

    plan = plan_row_to_dict(row)
    week = max(0, min(week, plan["block_length"] - 1))
    rows = plan_rows_for_export(plan, week)

    if fmt != "pdf":
        return jsonify({"error": "Nur PDF Export unterstützt"}), 400

    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.pdfgen import canvas
    except Exception:
        return jsonify({"error": "reportlab nicht installiert"}), 400

    mem = io.BytesIO()
    c = canvas.Canvas(mem, pagesize=A4)
    w, h = A4

    y = h - 40
    c.setFont("Helvetica-Bold", 14)
    c.drawString(40, y, f"Plan Export – {plan.get('name')} – Woche {week+1}")
    y -= 24
    c.setFont("Helvetica", 10)

    for r in rows:
        line = (
            f"{r['day']}: {r['type']} {r['name']} "
            f"Sets:{r['sets']} Reps:{r['reps_min']}-{r['reps_max']} "
            f"RPE:{r['rpe_min']} "
            f"{r['amount_value']}{r['amount_unit']} "
            f"{r['notes'] or ''}"
        )
        c.drawString(40, y, line[:120])
        y -= 14
        if y < 40:
            c.showPage()
            y = h - 40
            c.setFont("Helvetica", 10)

    c.showPage()
    c.save()
    mem.seek(0)

    return send_file(
        mem,
        mimetype="application/pdf",
        as_attachment=True,
        download_name=f"plan_{plan_id}_w{week+1}.pdf"
    )


