@app.get("/api/analysis/raw_sets")
def api_analysis_raw_sets():
    """
    Returns raw joined set rows with IDs.
    Query params:
      exercise (optional), device (optional), laterality (optional), variation (optional),
      days (optional), from (optional), to (optional),
      limit (default 200, max 5000), offset (default 0),
      order=asc|desc (default asc),
      strict=1|0 (default 1)
    """
    exercise   = (request.args.get("exercise") or "").strip()
    device     = (request.args.get("device") or "").strip()
    laterality = (request.args.get("laterality") or "").strip()
    variation  = (request.args.get("variation") or "").strip()

    strict = (request.args.get("strict") or "1").strip() != "0"

    days   = request.args.get("days", default=None, type=int)
    d_from = _parse_iso(request.args.get("from"))
    d_to   = _parse_iso(request.args.get("to"))

    if days and not d_from and not d_to:
        d_from = date.today() - timedelta(days=max(1, days))
        d_to   = date.today()

    limit  = _clamp_int(request.args.get("limit"), 1, 5000, 200)
    offset = _clamp_int(request.args.get("offset"), 0, 10_000_000, 0)

    order = (request.args.get("order") or "asc").lower()
    order = "DESC" if order == "desc" else "ASC"

    where = ["w.date_iso IS NOT NULL"]
    params = []

    if d_from:
        where.append("w.date_iso >= ?")
        params.append(d_from.isoformat())
    if d_to:
        where.append("w.date_iso <= ?")
        params.append(d_to.isoformat())

    # STRICT filters (default): exact match (NOCASE) to avoid mixing variants
    if exercise:
        if strict:
            where.append("TRIM(e.name) = TRIM(?) COLLATE NOCASE")
            params.append(exercise)
        else:
            where.append("TRIM(e.name) LIKE '%' || TRIM(?) || '%' COLLATE NOCASE")
            params.append(exercise)

    if device:
        if strict:
            where.append("TRIM(COALESCE(e.device,'')) = TRIM(?) COLLATE NOCASE")
            params.append(device)
        else:
            where.append("TRIM(COALESCE(e.device,'')) LIKE '%' || TRIM(?) || '%' COLLATE NOCASE")
            params.append(device)

    if laterality:
        where.append("TRIM(COALESCE(e.laterality,'')) = TRIM(?) COLLATE NOCASE")
        params.append(laterality)

    # variation = raw string field you store; useful if you want "exact original input"
    if variation:
        if strict:
            where.append("TRIM(COALESCE(e.variation,'')) = TRIM(?) COLLATE NOCASE")
            params.append(variation)
        else:
            where.append("TRIM(COALESCE(e.variation,'')) LIKE '%' || TRIM(?) || '%' COLLATE NOCASE")
            params.append(variation)

    sql = f"""
        SELECT
            s.id            AS set_id,
            e.id            AS exercise_id,
            w.id            AS workout_id,

            w.date_iso      AS date_iso,
            w.name          AS session_name,
            w.notes         AS session_notes,

            e.name          AS exercise,
            e.device        AS device,
            e.laterality    AS laterality,
            e.variation     AS variation,
            e.notes         AS exercise_notes,

            s.set_number    AS set_number,
            s.reps          AS reps,
            s.weight        AS weight,
            s.rpe           AS rpe,

            (s.weight * s.reps) AS tonnage,
            (CASE
                WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL AND s.weight > 0 AND s.reps > 0
                THEN (s.weight * (1.0 + (s.reps / 30.0)))
                ELSE NULL
             END) AS e1rm

        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts  w ON w.id = e.workout_id

        WHERE {" AND ".join(where)}
        ORDER BY w.date_iso {order}, w.id {order}, e.id {order}, COALESCE(s.set_number, 0) {order}, s.id {order}
        LIMIT ? OFFSET ?
    """

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    rows = conn.execute(sql, params + [limit, offset]).fetchall()
    conn.close()

    return jsonify([dict(r) for r in rows])

@app.get("/api/analysis/top_sets")
def api_analysis_top_sets():
    """
    Returns best set per workout-session for a given exercise key.
    Params: exercise (required), device (optional), laterality (optional), days (default 180),
            metric=e1rm|weight (default e1rm), limit (max 5000), strict=1|0 (default 1)
    """
    exercise   = (request.args.get("exercise") or "").strip()
    device     = (request.args.get("device") or "").strip()
    laterality = (request.args.get("laterality") or "").strip()
    metric     = (request.args.get("metric") or "e1rm").strip().lower()
    strict     = (request.args.get("strict") or "1").strip() != "0"

    if not exercise:
        return jsonify({"ok": False, "error": "missing_exercise"}), 400

    days  = _clamp_int(request.args.get("days"), 1, 3650, 180)
    limit = _clamp_int(request.args.get("limit"), 1, 5000, 5000)
    start = (date.today() - timedelta(days=days)).isoformat()

    where = ["w.date_iso >= ?"]
    params = [start]

    if strict:
        where.append("TRIM(e.name) = TRIM(?) COLLATE NOCASE")
    else:
        where.append("TRIM(e.name) LIKE '%' || TRIM(?) || '%' COLLATE NOCASE")
    params.append(exercise)

    if device:
        where.append("TRIM(COALESCE(e.device,'')) = TRIM(?) COLLATE NOCASE")
        params.append(device)

    if laterality:
        where.append("TRIM(COALESCE(e.laterality,'')) = TRIM(?) COLLATE NOCASE")
        params.append(laterality)

    # score for ranking
    score_expr = """
        CASE
          WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL AND s.weight > 0 AND s.reps > 0
          THEN (s.weight * (1.0 + (s.reps / 30.0)))
          ELSE NULL
        END
    """
    if metric == "weight":
        score_expr = "s.weight"

    # Window function: pick best set per workout_id for that exercise key
    sql = f"""
      WITH ranked AS (
        SELECT
          s.id         AS set_id,
          e.id         AS exercise_id,
          w.id         AS workout_id,
          w.date_iso   AS date_iso,
          w.name       AS session_name,

          e.name       AS exercise,
          e.device     AS device,
          e.laterality AS laterality,
          e.variation  AS variation,

          s.set_number AS set_number,
          s.reps       AS reps,
          s.weight     AS weight,
          s.rpe        AS rpe,

          (s.weight * s.reps) AS tonnage,
          ({score_expr})      AS score,

          ROW_NUMBER() OVER (
            PARTITION BY w.id
            ORDER BY ({score_expr}) DESC, s.weight DESC, s.reps DESC, s.id DESC
          ) AS rn
        FROM sets s
        JOIN exercises e ON e.id = s.exercise_id
        JOIN workouts  w ON w.id = e.workout_id
        WHERE {" AND ".join(where)}
      )
      SELECT *
      FROM ranked
      WHERE rn = 1
      ORDER BY date_iso ASC, workout_id ASC
      LIMIT ?
    """

    conn = get_training_db()
    conn.row_factory = sqlite3.Row
    rows = conn.execute(sql, params + [limit]).fetchall()
    conn.close()

    return jsonify([dict(r) for r in rows])

@app.get("/api/analysis/workout_raw")
def api_analysis_workout_raw():
    workout_id = request.args.get("workout_id", type=int)
    if not workout_id:
        return jsonify({"ok": False, "error": "missing_workout_id"}), 400

    conn = get_training_db()
    conn.row_factory = sqlite3.Row

    w = conn.execute("SELECT * FROM workouts WHERE id = ?", (workout_id,)).fetchone()
    if not w:
        conn.close()
        return jsonify({"ok": False, "error": "not_found"}), 404

    rows = conn.execute("""
        SELECT
          s.id AS set_id,
          e.id AS exercise_id,
          w.id AS workout_id,
          w.date_iso,
          w.name AS session_name,

          e.name AS exercise,
          e.device,
          e.laterality,
          e.variation,

          s.set_number,
          s.reps,
          s.weight,
          s.rpe,
          (s.weight * s.reps) AS tonnage,
          (CASE
            WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL AND s.weight > 0 AND s.reps > 0
            THEN (s.weight * (1.0 + (s.reps / 30.0)))
            ELSE NULL
          END) AS e1rm

        FROM exercises e
        JOIN workouts w ON w.id = e.workout_id
        LEFT JOIN sets s ON s.exercise_id = e.id
        WHERE w.id = ?
        ORDER BY e.id ASC, COALESCE(s.set_number, 0) ASC, s.id ASC
    """, (workout_id,)).fetchall()

    conn.close()

    return jsonify({
        "ok": True,
        "workout": dict(w),
        "rows": [dict(r) for r in rows]
    })


@app.get("/api/analysis/exercise_frequency")
def api_exercise_frequency():
    days = _clamp_int(request.args.get("days"), 1, 3650, 240)
    start = (request.args.get("start") or "").strip() or (date.today() - timedelta(days=days)).isoformat()
    end = (request.args.get("end") or "").strip() or None

    sql = """
      SELECT
        TRIM(e.name) AS exercise,
        TRIM(COALESCE(e.device,'')) AS device,
        TRIM(COALESCE(e.laterality,'')) AS laterality,
        COUNT(s.id) AS n_sets,
        MIN(w.date_iso) AS first_date,
        MAX(w.date_iso) AS last_date
      FROM sets s
      JOIN exercises e ON e.id = s.exercise_id
      JOIN workouts  w ON w.id = e.workout_id
      WHERE w.date_iso >= ?
        AND (? IS NULL OR substr(w.date_iso, 1, 10) <= ?)
      GROUP BY TRIM(e.name), TRIM(COALESCE(e.device,'')), TRIM(COALESCE(e.laterality,''))
      ORDER BY n_sets DESC
      LIMIT 200
    """
    conn = get_training_db(); conn.row_factory = sqlite3.Row
    rows = conn.execute(sql, (start, end, end)).fetchall()
    conn.close()
    return jsonify([dict(r) for r in rows])

@app.get("/api/analysis/training_weekly_summary")
def api_training_weekly_summary():
    days = _clamp_int(request.args.get("days"), 1, 3650, 240)
    start = (date.today() - timedelta(days=days)).isoformat()

    sql = """
      SELECT
        strftime('%Y-%W', date(w.date_iso)) AS week,
        MIN(w.date_iso) AS week_start,
        MAX(w.date_iso) AS week_end,
        COUNT(s.id) AS sets_count,
        SUM(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL THEN s.weight*s.reps ELSE 0 END) AS tonnage_sum,
        AVG(CASE WHEN s.rpe IS NOT NULL THEN s.rpe END) AS rpe_avg,
        MAX(CASE WHEN s.weight IS NOT NULL AND s.reps IS NOT NULL AND s.weight>0 AND s.reps>0
            THEN (s.weight * (1.0 + (s.reps/30.0))) END) AS e1rm_max
      FROM sets s
      JOIN exercises e ON e.id = s.exercise_id
      JOIN workouts  w ON w.id = e.workout_id
      WHERE w.date_iso >= ?
      GROUP BY strftime('%Y-%W', date(w.date_iso))
      ORDER BY strftime('%Y-%W', date(w.date_iso)) ASC
    """
    conn = get_training_db(); conn.row_factory = sqlite3.Row
    rows = conn.execute(sql, (start,)).fetchall()
    conn.close()
    return jsonify([dict(r) for r in rows])




